/**
 * Groundwork v2 — app.js
 * Talks to Flask REST API at /api/*
 * All DOM IDs match index.html exactly.
 */
'use strict';

// ─── API ──────────────────────────────────────────────────────────────────────
const _GW_AUTH_HEADER = () => ({ 'X-GW-Token': window.GW_SESSION_TOKEN || '' });

// 403 self-heal — the server mints a fresh session token on every restart.
// If this page was loaded before a restart (or replayed from browser cache),
// its token is stale and every API call 403s. Recover by re-fetching the page
// fresh, extracting the current token, and retrying the request once.
// Security note: any local process can already GET / and read the token from
// the HTML, so re-extracting it here does not weaken the auth model.
let _gwTokenRefresh = null; // in-flight refresh — dedupes concurrent 403s
async function _gwRefreshToken() {
  if (!_gwTokenRefresh) {
    _gwTokenRefresh = (async () => {
      try {
        const html = await (await fetch('/', { cache: 'no-store' })).text();
        const m = html.match(/GW_SESSION_TOKEN="([a-f0-9]{64})"/);
        if (m) { window.GW_SESSION_TOKEN = m[1]; return true; }
      } catch (_) { /* server unreachable — fall through */ }
      return false;
    })().finally(() => { _gwTokenRefresh = null; });
  }
  return _gwTokenRefresh;
}

async function _gwFetch(path, opts = {}, _retried = false) {
  const r = await fetch(path, {
    ...opts,
    headers: { ...(opts.headers || {}), ..._GW_AUTH_HEADER() },
  });
  if (r.status === 403 && !_retried && await _gwRefreshToken()) {
    return _gwFetch(path, opts, true);
  }
  return r;
}

const API = {
  async get(path) {
    const r = await _gwFetch(path);
    if (!r.ok) throw new Error(`${r.status} ${path}`);
    const j = await r.json();
    return j.data !== undefined ? j.data : j;
  },
  async post(path, body = {}) {
    const r = await _gwFetch(path, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body),
    });
    const j = await r.json();
    if (!r.ok) throw new Error(j.error || `${r.status} ${path}`);
    return j.data !== undefined ? j.data : j;
  },
  async patch(path, body = {}) {
    const r = await _gwFetch(path, {
      method: 'PATCH',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body),
    });
    const j = await r.json();
    if (!r.ok) throw new Error(j.error || `${r.status} ${path}`);
    return j.data !== undefined ? j.data : j;
  },
  async put(path, body = {}) {
    const r = await _gwFetch(path, {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body),
    });
    const j = await r.json();
    if (!r.ok) throw new Error(j.error || `${r.status} ${path}`);
    return j.data !== undefined ? j.data : j;
  },
  async delete(path) {
    const r = await _gwFetch(path, { method: 'DELETE' });
    const j = await r.json();
    if (!r.ok) throw new Error(j.error || `${r.status} ${path}`);
    return j;
  },
};

// ─── Formatting ───────────────────────────────────────────────────────────────
function fmt(n) {
  if (n == null || isNaN(n)) return '$0.00';
  return new Intl.NumberFormat('en-US', {
    style: 'currency', currency: 'USD',
    minimumFractionDigits: 2, maximumFractionDigits: 2,
  }).format(n);
}
function fmtD(n) {
  return new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(n || 0);
}
function fmtDate(s) {
  if (!s) return '';
  const d = new Date(s + 'T00:00:00');
  return d.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
}
function today() { return new Date().toISOString().slice(0, 10); }
function g(id) { return document.getElementById(id); }
function setText(id, v) { const e = g(id); if (e) e.textContent = v; }


// Open a link in the user's normal system browser rather than navigating the
// app window away from Groundwork (the desktop window has no back button).
function openExternal(url) {
  if (window.pywebview?.api?.open_external) {
    window.pywebview.api.open_external(url);
  } else {
    window.open(url, '_blank');
  }
}

// ─── Global flags (set during boot from bootstrap data) ───────────────────────
let _aiEnabled     = true;   // updated by restoreFromBootstrap
let _saveTimer     = null;   // debounce timer for scheduleSave()

// ── Global error handler — catches ALL uncaught JS errors and promise rejections
// Writes to _gwErrorLog (last 20). Visible in Settings → Debug. Surfaces a
// subtle indicator in the topbar so errors are never silently swallowed.
const _gwErrorLog = [];
function _gwLogError(msg, source, line, col, err) {
  const entry = {
    ts:    new Date().toISOString(),
    msg:   String(msg || '').slice(0, 300),
    src:   (source || '').replace(/.*\//, ''),
    line,  col,
    stack: err?.stack ? err.stack.split('\n').slice(0,4).join(' | ') : '',
  };
  _gwErrorLog.unshift(entry);
  if (_gwErrorLog.length > 20) _gwErrorLog.pop();
  const ind = document.getElementById('gwErrorIndicator');
  if (ind) {
    ind.style.display  = '';
    ind.title          = entry.msg;
    ind.textContent    = `⚠ ${_gwErrorLog.length}`;
  }
}
window.onerror = (msg, src, line, col, err) => { _gwLogError(msg, src, line, col, err); return false; };
window.addEventListener('unhandledrejection', e => {
  _gwLogError(e.reason?.message || String(e.reason), 'promise', 0, 0, e.reason);
});

// Logging catch helpers — replace silent `.catch(() => {})`, which marks a
// rejection as handled and therefore BYPASSES the unhandledrejection net
// above. _gwErr logs with the enclosing function as context; _gwErrVal logs
// and returns a fallback value for read paths.
const _gwErr = (ctx) => (e) =>
  _gwLogError(`${ctx}: ${e?.message || e}`, 'catch', 0, 0, e);
const _gwErrVal = (ctx, val) => (e) => {
  _gwLogError(`${ctx}: ${e?.message || e}`, 'catch', 0, 0, e);
  return val;
};

// ─── App state ────────────────────────────────────────────────────────────────
const S = {
  // Core data
  transactions: [],
  incomes:      [],   // [{name, amount}]
  expenses:     [],   // [{cat, name, amount}]
  categories:   [],   // [{id, name, icon, color, parent_id, is_system, sort_order}] — mirrors the Category DB table; the only source of truth for "what categories exist". See loadCategories().
  accounts:     [],   // [{id, name, type, institution, balance, transaction_count}] — mirrors the Account DB table; the only source of truth for "what accounts exist". See loadAccounts().
  debtCards:    [],
  debtIdCounter:0,
  achievements:     new Set(),
  achievementDates: null,   // { id: iso_date_string } — loaded from DB lazily
  bybItems:     [],
  netWorth:     { savings:0, investments:0, cash:0, homeValue:0, mortgage:0 },

  // UI state
  period:       'mtd',
  debtMethod:   'avalanche',
  dfmActive:    false,
  dfmSavingsCut:5,

  // Debt calc output
  lastSchedule: null,
  lastCards:    null,
  _interestSaved: 0,  // accumulated interest saved vs minimums — used by interest_slayer progress

  // Strategy streak tracking
  strategyStreak: { method: null, months: 0 },
  paymentStreak:  0,

  // User display preferences
  prefs: {
    payoffDisplayMode: 'countdown', // 'countdown' | 'progress'
  },

  // Unified financial intelligence profile — built on every boot from all data
  profile: null,

  // Life stage flags — loaded from app_settings on boot
  lifeStage: {
    pslfAccounts:   {},     // { debtCardId: true } — loans on income-based forgiveness
    commissionMode: false,  // irregular/commission income — disables monthly failure flags
    payFrequency:   null,      // 'weekly'|'biweekly'|'semimonthly'|'monthly'|'irregular', or null = unanswered (never assumed)
    pensions:       [],     // [{ id, name, monthlyBenefit, retirementAge }]
  },
};
const GW_VERSION = '20261008-d25'; // must match server.py GW_VERSION


// ═══════════════════════════════════════════════════════════════════════════════
// CATEGORY HIERARCHY HELPERS
// ── All category logic goes through these functions ────────────────────────────
//
// S.categories is a flat array of {id, name, type, color, icon, parent_id, ...}
// These helpers build the tree, resolve children, and provide rollup logic.
// Rule: Transactions always have CHILD categories. Parents are display-only.
// ═══════════════════════════════════════════════════════════════════════════════

// Build a map of parent_id → [child categories] from S.categories


// Get all child category NAMES for a given parent name
// Returns [] if parent has no children or doesn't exist
function _catChildren(parentName) {
  const parent = (S.categories || []).find(c => c.name === parentName && !c.parent_id);
  if (!parent) return [];
  return (S.categories || [])
    .filter(c => c.parent_id === parent.id)
    .map(c => c.name);
}

// Get all child category IDs for a given parent name
function _catChildIds(parentName) {
  const parent = (S.categories || []).find(c => c.name === parentName && !c.parent_id);
  if (!parent) return [];
  return (S.categories || [])
    .filter(c => c.parent_id === parent.id)
    .map(c => c.id);
}

// Get parent name for a given category name
// Returns the name itself if it's already a parent (or null if not found)
// Canonical "is this real spending?" test. A transfer (money moving between the
// user's own accounts — Home Banking transfer, ATM withdrawal, savings move) is
// NOT spending; counting it inflated the dashboard's spent total, projected
// spend, the donut, and What Changed (field-caught: a $5,000 transfer read as
// "Over budget $12,651"). Debit + not a Transfer-category row. Used everywhere
// the dashboard sums spending.
function _isSpend(t) {
  if (!t || t.type !== 'debit') return false;
  const parent = _catParentName(t.category) || t.category;
  return parent !== 'Transfer';
}

// The credit-side mirror of _isSpend: money that actually arrived from outside,
// not an internal move between the user's own accounts. Any ratio built from
// gross credits and gross debits needs both sides filtered the same way, or the
// transfers inflate the numerator and denominator by different amounts.
function _isEarn(t) {
  if (!t || t.type !== 'credit') return false;
  const parent = _catParentName(t.category) || t.category;
  return parent !== 'Transfer';
}

function _catParentName(catName) {  const cat = (S.categories || []).find(c => c.name === catName);
  if (!cat) return catName;
  if (!cat.parent_id) return catName;  // already a parent
  const parent = (S.categories || []).find(c => c.id === cat.parent_id);
  return parent ? parent.name : catName;
}

// Get the category object by name
function _catByName(name) {
  return (S.categories || []).find(c => c.name === name) || null;
}

// Is this category a parent (has children)?
function _catIsParent(catName) {
  const cat = _catByName(catName);
  if (!cat) return false;
  return (S.categories || []).some(c => c.parent_id === cat.id);
}

// Is this category a child (has a parent)?
function _catIsChild(catName) {
  const cat = _catByName(catName);
  return cat ? !!cat.parent_id : false;
}

// Get all parent categories (top-level, enabled)
function _catParents(type = 'expense') {
  return (S.categories || [])
    .filter(c => !c.parent_id && (type === 'all' || c.type === type) && c.is_enabled !== false)
    .sort((a, b) => (a.sort_order || 0) - (b.sort_order || 0));
}

// Get children of a parent, sorted
function _catChildrenOf(parentName) {
  const parent = _catByName(parentName);
  if (!parent) return [];
  return (S.categories || [])
    .filter(c => c.parent_id === parent.id && c.is_enabled !== false)
    .sort((a, b) => (a.sort_order || 0) - (b.sort_order || 0));
}

// Build full tree [{parent, children:[]}] for rendering
function _catTree(type = 'expense') {
  return _catParents(type).map(parent => ({
    parent,
    children: _catChildrenOf(parent.name),
  }));
}

// Sum all debit transactions in a given month for a category.
// If the category is a PARENT, sums all its children.
// If it's a CHILD, sums only that child's transactions.
// This is the core budget spent-so-far function.
function _catSpentInMonth(catName, monthKey) {
  if (!catName || !monthKey) return 0;
  if (!S.transactions || !S.transactions.length) return 0;
  const txns = S.transactions.filter(t =>
    t.type === 'debit' && (t.date || '').startsWith(monthKey)
  );

  const cat = _catByName(catName);
  if (!cat) return 0;

  if (_catIsParent(catName)) {
    // Roll up all children
    const childIds = _catChildIds(catName);
    // Also include transactions directly on the parent (legacy)
    return txns
      .filter(t => t.category_id === cat.id || childIds.includes(t.category_id))
      .reduce((s, t) => s + t.amount, 0);
  } else {
    // Child category — exact match
    return txns
      .filter(t => t.category_id === cat.id)
      .reduce((s, t) => s + t.amount, 0);
  }
}

// 6-month average for a category (parent or child)
function _catSixMonthAvg(catName) {
  const now    = new Date();
  const months = [];
  for (let i = 1; i <= 6; i++) {
    const d = new Date(now.getFullYear(), now.getMonth() - i, 1);
    months.push(`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`);
  }
  const totals = months
    .map(mo => _catSpentInMonth(catName, mo))
    .filter(v => v > 0);
  if (!totals.length) return null;
  return Math.round(totals.reduce((a, b) => a + b, 0) / totals.length);
}

// Get category color by name (falls back to parent color)
function _catColor(catName) {
  const cat = _catByName(catName);
  if (!cat) return '#6b7280';
  if (cat.color) return cat.color;
  if (cat.parent_id) {
    const parent = (S.categories || []).find(c => c.id === cat.parent_id);
    return parent?.color || '#6b7280';
  }
  return '#6b7280';
}

// Group spending by parent category for a month (for donut chart, reports)
// Returns [{name, amount, children:[{name, amount}]}]


// ── Unified Financial Intelligence Layer ──────────────────────────────────────
// buildFinancialProfile() assembles everything the app knows into S.profile.
// Runs on every boot. Every AI prompt, dashboard indicator, and projection
// consumes from this single object — nothing is siloed.

// ── B6d: Seasonal pattern detection ──────────────────────────────────────────
// Reads debt_balance_history to detect months where balances historically
// increase (spending spikes). Requires ≥6 months of real history.
// Blueprint: flag if upcoming month shows ≥$100 avg balance increase vs current.
// Returns { flags: [{month, avgIncrease, cardName, note}], hasEnoughHistory }
function _calcSeasonalPatterns() {
  const result = { flags: [], hasEnoughHistory: false };
  const hasHistory = Object.values(_debtHistoryCache).some(h => h.length >= 6);
  if (!hasHistory) return result;

  const nextMonth = (() => {
    const d = new Date();
    d.setMonth(d.getMonth() + 1);
    return String(d.getMonth() + 1).padStart(2, '0'); // '01' through '12'
  })();

  const cards = _activeDebtCards();
  let anyEnough = false;

  cards.forEach(card => {
    const history = (_debtHistoryCache[String(card._dbId)] || []).slice().reverse(); // oldest→newest
    if (history.length < 6) return;
    anyEnough = true;

    // Group snapshots by month-of-year (MM)
    const byMonthOfYear = {};
    history.forEach((snap, i) => {
      if (i === 0) return; // need previous month to compute delta
      const mo = snap.month.slice(5, 7); // 'MM'
      const prevBal = history[i - 1].balance;
      const delta   = snap.balance - prevBal; // positive = balance went UP (bad)
      if (!byMonthOfYear[mo]) byMonthOfYear[mo] = [];
      byMonthOfYear[mo].push(delta);
    });

    // Check the upcoming month
    const deltas = byMonthOfYear[nextMonth];
    if (!deltas || deltas.length < 2) return; // need at least 2 data points

    const avgDelta = deltas.reduce((s, d) => s + d, 0) / deltas.length;
    if (avgDelta >= 100) {
      // Balance has historically increased ≥$100 in this month
      result.flags.push({
        cardId:      card.id,
        cardName:    card.name,
        month:       nextMonth,
        avgIncrease: Math.round(avgDelta),
        dataPoints:  deltas.length,
        note: `${card.name} balance has averaged +${fmt ? fmt(avgDelta) : '$' + Math.round(avgDelta)} in this month historically`,
      });
    }
  });

  result.hasEnoughHistory = anyEnough;
  return result;
}

async function buildFinancialProfile() {
  try {
    // Fetch supplementary data not in S state
    const [nwRes, sbRes] = await Promise.all([
      API.get('/api/net-worth/snapshots?months=24').catch(_gwErrVal('buildFinancialProfile', { data: [] })),
      API.get('/api/budget/plan').catch(_gwErrVal('buildFinancialProfile', { data: null })),
    ]);
    const nwSnapshots = (nwRes.data || []).filter(r => !r.without_figures);   // item 38: never a $0 from no figures
    const sbMonths    = (sbRes.data?.months || []);

    S.profile = {
      income:   _calcIncomeIntelligence(),
      spending: _calcSpendingIntelligence(),
      debt:     _calcDebtIntelligence(),
      behavior: _calcBehavioralProfile(sbMonths),
      netWorth: _calcNetWorthTrajectory(nwSnapshots),
      seasonal: _calcSeasonalPatterns(),
      builtAt:  new Date().toISOString(),
    };
  } catch(e) {
    // Profile failure is non-fatal — app works without it, just without intelligence
    S.profile = null;
  }
}

// ── Helper: group transactions by YYYY-MM ─────────────────────────────────────
function _groupByMonth(txns) {
  const map = {};
  txns.forEach(t => {
    const key = (t.date || '').slice(0, 7);
    if (!key) return;
    if (!map[key]) map[key] = [];
    map[key].push(t);
  });
  return map;
}

// ── Helper: last N calendar months as YYYY-MM strings ─────────────────────────
function _lastNMonths(n) {
  const months = [];
  const d = new Date();
  for (let i = 1; i <= n; i++) {
    const m = new Date(d.getFullYear(), d.getMonth() - i, 1);
    months.push(`${m.getFullYear()}-${String(m.getMonth()+1).padStart(2,'0')}`);
  }
  return months;
}

// ── Income intelligence ───────────────────────────────────────────────────────
function _calcIncomeIntelligence() {
  const incomeTxns = S.transactions.filter(t =>
    t.type === 'credit' && t.amount > 0 &&
    /(income|salary|paycheck|direct.deposit|payroll|wages)/i.test(t.category || t.description || '')
  );

  const byMonth = _groupByMonth(incomeTxns);
  const months3  = _lastNMonths(3);
  const months6  = _lastNMonths(6);
  const months12 = _lastNMonths(12);

  const monthlyTotal = mo => (byMonth[mo] || []).reduce((s,t) => s+t.amount, 0);

  // d21 (issue-5 breadcrumb): average over months that actually HAVE income,
  // not a fixed 3/6/12. Dividing 4 months of pay by 6 under-reported income —
  // and in the onboarding Snapshot that's the very first number a user sees.
  // A month with zero detected income (gap/parsing miss) shouldn't drag the
  // average down either; only count months with real deposits.
  const avgOver = window => {
    const totals = window.map(monthlyTotal).filter(v => v > 0);
    return totals.length ? totals.reduce((s,v) => s+v, 0) / totals.length : 0;
  };
  const avg3  = avgOver(months3);
  const avg6  = avgOver(months6);
  const avg12 = avgOver(months12);

  // Fall back to budget income if no transaction income detected
  const budgetIncome = S.incomes.reduce((s,i) => s+i.amount, 0);
  const effectiveAvg = avg6 > 0 ? avg6 : budgetIncome;

  // Coefficient of variation → variable income flag
  const amounts6 = months6.map(monthlyTotal).filter(v => v > 0);
  let cv = 0;
  if (amounts6.length >= 3) {
    const mean = amounts6.reduce((s,v) => s+v, 0) / amounts6.length;
    const variance = amounts6.reduce((s,v) => s+Math.pow(v-mean,2), 0) / amounts6.length;
    cv = mean > 0 ? Math.sqrt(variance) / mean : 0;
  }

  // Year-over-year trend
  const recentHalf = months6.reduce((s,m) => s+monthlyTotal(m), 0) / 6;
  const olderHalf  = months12.slice(6).reduce((s,m) => s+monthlyTotal(m), 0) / 6;
  const trend = olderHalf > 0
    ? (recentHalf - olderHalf) / olderHalf
    : 0;

  // Seasonal low months (historically below average)
  const seasonalMap = {};
  months12.forEach(mo => {
    const monthNum = parseInt(mo.split('-')[1]) - 1;
    const total = monthlyTotal(mo);
    if (!seasonalMap[monthNum]) seasonalMap[monthNum] = [];
    seasonalMap[monthNum].push(total);
  });

  return {
    avg3:          Math.round(avg3),
    avg6:          Math.round(avg6),
    avg12:         Math.round(avg12),
    effectiveAvg:  Math.round(effectiveAvg),
    budgetIncome,
    variabilityCV: Math.round(cv * 100) / 100,
    isVariable:    cv > 0.25,
    trendPct:      Math.round(trend * 100),
    trendDir:      trend > 0.05 ? 'growing' : trend < -0.05 ? 'declining' : 'flat',
  };
}

// ── Spending intelligence ─────────────────────────────────────────────────────
function _calcSpendingIntelligence() {
  // Exclude transfers (ATM withdrawals, account-to-account moves) — they are
  // not spending, so they must not appear in category trends or growth alerts
  // ("ATM trending +229%" was a transfer leaking into the trend calc, d21).
  const debitTxns = S.transactions.filter(t => _isSpend(t) && t.amount > 0);
  const byMonth   = _groupByMonth(debitTxns);
  const months3   = _lastNMonths(3);
  const months6   = _lastNMonths(6);

  // Per-category averages and trends — grouped by PARENT category for rollup
  // Child categories roll up to their parent so reports show top-level spending
  //
  // d21 (tester screenshot: "Rent jumped 97%"): the old trend divided the
  // 6-month window sum by a fixed 6 even when transaction history was
  // shorter — constant rent with only 3 months of data computed
  // avg6 = rent/2 → "+100% growth" out of thin air. Trends now compare two
  // DISJOINT windows (most recent 3 complete months vs the prior 3), each
  // averaged over only the months that actually have data, and require at
  // least 2 months of baseline. No baseline → no trend — the profile says
  // nothing rather than inventing a pattern.
  const firstDataMonth = debitTxns.reduce((min, t) => {
    const m = (t.date || '').slice(0, 7);
    return m && (!min || m < min) ? m : min;
  }, null);
  const recentWin = months6.slice(0, 3).filter(m => firstDataMonth && m >= firstDataMonth);
  const priorWin  = months6.slice(3, 6).filter(m => firstDataMonth && m >= firstDataMonth);
  const trendComputable = recentWin.length >= 2 && priorWin.length >= 2;

  const allCats = [...new Set(debitTxns.map(t => {
    // Map child category back to parent name for grouping
    return _catParentName(t.category) || t.category;
  }).filter(Boolean))];
  const categoryData = {};

  allCats.forEach(cat => {
    // Get spending using hierarchy-aware function (includes all children)
    const dataMonths6 = months6.filter(m => firstDataMonth && m >= firstDataMonth);
    const avg3 = recentWin.length
      ? recentWin.reduce((s,m) => s + _catSpentInMonth(cat, m), 0) / recentWin.length : 0;
    const avg6 = dataMonths6.length
      ? dataMonths6.reduce((s,m) => s + _catSpentInMonth(cat, m), 0) / dataMonths6.length : 0;
    if (avg6 < 1) return; // skip empty categories
    let trend = 0, dir = 'insufficient', priorAvg = 0;
    if (trendComputable) {
      priorAvg = priorWin.reduce((s,m) => s + _catSpentInMonth(cat, m), 0) / priorWin.length;
      if (priorAvg > 0) {
        trend = (avg3 - priorAvg) / priorAvg;
        dir   = trend > 0.10 ? 'growing' : trend < -0.10 ? 'shrinking' : 'flat';
      }
    }
    categoryData[cat] = {
      avg3:     Math.round(avg3),
      avg6:     Math.round(avg6),
      priorAvg: Math.round(priorAvg),
      trend:    Math.round(trend * 100),
      dir,
    };
  });

  // Top 5 categories by 6-month average
  const topCategories = Object.entries(categoryData)
    .sort((a,b) => b[1].avg6 - a[1].avg6)
    .slice(0, 5)
    .map(([cat, data]) => ({ category: cat, ...data }));

  // Growing categories (potential alerts for dashboard). d21 (field: "Rent
  // trending +6619%"): a percentage off a near-zero prior baseline is
  // mathematically real but meaningless — $3 → $200 is "+6567%". Require the
  // PRIOR window to have had real spending too (priorAvg >= $40), so we only
  // flag categories that were already material and grew, not ones appearing for
  // the first time. Also cap what we're willing to call a percentage.
  const growingCategories = Object.entries(categoryData)
    .filter(([,d]) => d.dir === 'growing' && d.trend > 25 && d.trend <= 300 && d.avg6 > 50 && (d.priorAvg || 0) >= 40)
    .sort((a,b) => b[1].trend - a[1].trend)
    .map(([cat, data]) => ({ category: cat, trendPct: data.trend, avg6: data.avg6 }));

  // Subscription candidates: merchants appearing monthly at consistent amounts
  const merchantFreq = {};
  debitTxns.forEach(t => {
    const merchant = (t.description || '').trim().toLowerCase().slice(0, 30);
    if (!merchant) return;
    if (!merchantFreq[merchant]) merchantFreq[merchant] = { amounts: [], months: new Set() };
    merchantFreq[merchant].amounts.push(t.amount);
    merchantFreq[merchant].months.add((t.date||'').slice(0,7));
  });

  const subscriptionCandidates = Object.entries(merchantFreq)
    .filter(([, v]) => v.months.size >= 2)
    .map(([merchant, v]) => {
      const sorted = [...v.amounts].sort((a,b)=>a-b);
      const median = sorted[Math.floor(sorted.length/2)];
      const variance = v.amounts.reduce((s,a) => s+Math.pow(a-median,2), 0) / v.amounts.length;
      const isConsistent = Math.sqrt(variance) / median < 0.05; // <5% variance = fixed price
      return { merchant, amount: median, monthsActive: v.months.size, isConsistent };
    })
    .filter(s => s.isConsistent && s.amount > 1 && s.amount < 500)
    .sort((a,b) => b.monthsActive - a.monthsActive)
    .slice(0, 15);

  return {
    categoryData,
    topCategories,
    growingCategories,
    subscriptionCandidates,
  };
}

// ── Debt intelligence ─────────────────────────────────────────────────────────
function _calcDebtIntelligence() {
  const cards     = _activeDebtCards();
  const totalDebt = cards.reduce((s,c) => s+(_cardBal(c)), 0);
  const beginDebt = S.debtCards.reduce((s,c) => s+(parseFloat(c.beginBal)||0), 0);
  const eliminated = Math.max(0, beginDebt - totalDebt);
  const pctPaid    = beginDebt > 0 ? (eliminated / beginDebt) * 100 : 0;

  // ── B6c: Use real historian data when available ───────────────────────────
  // _debtHistoryCache is populated by _budgetLoadDebtHistory() and auto-written
  // by B6b on every import. Each entry: { month, balance, payment, min_payment,
  // apr, interest_charged, statement_period_end }
  const hasHistory = Object.values(_debtHistoryCache).some(h => h.length > 0);

  let avgMonthlyPayment     = 0;
  let actualInterestPaid    = 0;
  let hasRealInterest       = false;
  let monthsOfHistory       = 0;
  let actualBalanceReduction = 0; // real balance delta from history
  // ── Interpretation layer (d21, tester-caught) ─────────────────────────────
  // Three concepts must never be conflated downstream: balance (what's owed),
  // payments (what money moved), principal reduction (what actually dropped).
  // The reconciliation verdict is computed HERE, before any narrator sees the
  // numbers — "$2,390/mo of payments" + "eliminated $0" once reached the AI
  // as two unreconciled facts and it novelized the gap ("principal sits").
  let reconciliation = null;

  if (hasHistory) {
    // Aggregate across all active cards
    const allMonthPayments  = {};  // { 'YYYY-MM': totalPayment }
    const allMonthInterest  = {};  // { 'YYYY-MM': totalInterest }
    const firstBalances     = {};  // card._dbId → oldest snapshot balance
    const latestBalances    = {};  // card._dbId → newest snapshot balance

    cards.forEach(card => {
      const history = (_debtHistoryCache[String(card._dbId)] || []).slice().reverse(); // oldest→newest
      if (!history.length) return;

      firstBalances[card._dbId]  = history[0].balance;
      latestBalances[card._dbId] = history[history.length - 1].balance;

      history.forEach(snap => {
        if (snap.payment > 0) {
          allMonthPayments[snap.month] = (allMonthPayments[snap.month] || 0) + snap.payment;
        }
        if (snap.interest_charged != null && snap.interest_charged > 0) {
          allMonthInterest[snap.month] = (allMonthInterest[snap.month] || 0) + snap.interest_charged;
          hasRealInterest = true;
        }
      });
    });

    // Average monthly payment across all months with data (last 3 months for recency)
    const allMonths     = Object.keys(allMonthPayments).sort();
    monthsOfHistory     = allMonths.length;
    const recent3       = allMonths.slice(-3);
    const recentTotal   = recent3.reduce((s, mo) => s + (allMonthPayments[mo] || 0), 0);
    avgMonthlyPayment   = recent3.length > 0 ? recentTotal / recent3.length : 0;

    // Total interest from real interest_charged field
    if (hasRealInterest) {
      actualInterestPaid = Object.values(allMonthInterest).reduce((s, v) => s + v, 0);
    } else {
      // Estimate from payment - balance_reduction per month across all cards
      cards.forEach(card => {
        const history = (_debtHistoryCache[String(card._dbId)] || []).slice().reverse();
        for (let i = 1; i < history.length; i++) {
          const balDrop = history[i-1].balance - history[i].balance;
          const pmt     = history[i].payment || 0;
          if (pmt > 0 && balDrop < pmt) actualInterestPaid += Math.max(0, pmt - balDrop);
        }
      });
    }

    // Actual balance reduction from history (more accurate than beginBal - currentBal
    // because beginBal is manually entered and may be wrong)
    const totalFirst  = Object.values(firstBalances).reduce((s,v) => s+v, 0);
    const totalLatest = Object.values(latestBalances).reduce((s,v) => s+v, 0);
    actualBalanceReduction = Math.max(0, totalFirst - totalLatest);

    // Reconciliation verdict: payments vs what balances actually did. The gap
    // is interest + fees + new charges — a computed fact, not a judgment.
    const paidTotal = Object.values(allMonthPayments).reduce((s,v) => s+v, 0);
    if (monthsOfHistory >= 2 && paidTotal > 0) {
      reconciliation = {
        paidTotal:        Math.round(paidTotal),
        balanceReduction: Math.round(totalFirst - totalLatest),   // can be negative: debt grew — still a fact
        gap:              Math.round(paidTotal - (totalFirst - totalLatest)),
      };
    }

  } else {
    // Fallback: approximate from debt-keyword transactions (pre-B6b — no
    // historian data yet). IMPORTANT (d21): this is keyword-matched SPENDING
    // ("payment"/"loan"/etc. in category or description) — it can include
    // transfers, payoffs, new charges, and non-debt bills. It is NOT verified
    // against balances and must never be labeled "debt payments" or converted
    // into a progress/pace claim downstream.
    const debtPaymentTxns = S.transactions.filter(t =>
      t.type === 'debit' &&
      /(debt|loan|payment|credit.card|mortgage|student)/i.test(t.category || t.description || '')
    );
    const months3 = _lastNMonths(3);
    const recentPayments = months3.reduce((s, mo) => {
      const moTxns = debtPaymentTxns.filter(t => (t.date||'').startsWith(mo));
      return s + moTxns.reduce((ss,t) => ss+t.amount, 0);
    }, 0);
    avgMonthlyPayment = recentPayments / 3;

    // Estimated interest (rough: daily rate × 30 × months elapsed)
    monthsOfHistory   = beginDebt > 0 && eliminated > 0
      ? Math.round(eliminated / Math.max(avgMonthlyPayment, 100))
      : 0;
    const dailyRate   = typeof calcDailyInterest === 'function' ? calcDailyInterest() : 0;
    actualInterestPaid = Math.round(dailyRate * 30 * monthsOfHistory);
  }

  // ── Pace vs projection ────────────────────────────────────────────────────
  // How fast is the balance actually moving vs how fast it needs to move?
  // BUG FIX (July 8): _simulatePayoff() returns null when the committed
  // budget can't cover minimum payments — "no valid payoff exists." The old
  // `projResult?.months || 0` silently coerced that null to 0 months, which
  // zeroed requiredMonthlyReduction and let paceRatio default to 1 — so the
  // exact scenario where the budget can't cover minimums was being reported
  // as 'on_track'. Same class as the four BYB fixes on July 6. Now the null
  // is carried through explicitly as payoffImpossible: pace is forced to
  // 'behind', and projectedPayoffMonths is null instead of a fake 0.
  const _simAvailable = typeof _simulatePayoff === 'function';
  const projResult  = _simAvailable ? _simulatePayoff(0) : null;
  const payoffImpossible = _simAvailable && projResult === null && totalDebt > 0;
  const monthsRemaining          = payoffImpossible ? null : (projResult?.months || 0);
  const minimumPayments          = cards.reduce((s,c) => s+(parseFloat(c.minimum)||0), 0);
  const requiredMonthlyReduction = monthsRemaining > 0 ? totalDebt / monthsRemaining : 0;

  // Use real balance reduction rate from history when available. d21: the old
  // fallback fabricated "reduction" as (keyword spend − minimums) — mislabeled
  // spending as progress, which is where "111% ahead of plan" alongside
  // "eliminated $0" came from. Pace now requires verified balance movement;
  // without it, pace is honestly unknown.
  const actualMonthlyReduction = (hasHistory && actualBalanceReduction > 0 && monthsOfHistory > 0)
    ? actualBalanceReduction / monthsOfHistory
    : null;

  // d21 pace rebuild (field: "116% ahead of schedule"): the rate-ratio pace
  // (actualMonthlyReduction / requiredMonthlyReduction) was structurally
  // misleading — totalDebt/monthsRemaining flat-averages a non-linear
  // amortization, so users in the acceleration phase read hugely "ahead"
  // while exactly on plan, and no "original plan" appeared anywhere in the
  // formula. Pace is now SCHEDULE MONTHS from _gwDateMovement(): first-
  // snapshot plan vs today's plan, same engine both ends — the identical
  // number Distance Traveled reports, read from the same substrate helper.
  const _mv = hasHistory ? _gwDateMovement() : { computable: false };
  const paceMonths = _mv.computable ? _mv.monthsDelta : null;
  const paceStatus = payoffImpossible ? 'behind'
    : paceMonths === null ? 'unknown'
    : paceMonths >= 1 ? 'ahead'
    : paceMonths <= -1 ? 'behind'
    : 'on_track';
  const pacePct = 0;   // retired — kept so stale consumers render nothing rather than crash

  // ── Data-quality verdict (d21) ────────────────────────────────────────────
  // Can the balances be trusted as current? Computed here — never left for
  // the AI to diagnose. Three signals:
  //   unverified: no balance history at all (balances are whatever was typed)
  //   stale:      history exists but the newest snapshot is >2 months old
  //   anomalous:  payments recorded but balances did not decrease at all
  let newestSnapshotMonth = '';
  Object.values(_debtHistoryCache || {}).forEach(rows => {
    (rows || []).forEach(h => { if (h.month && h.month > newestSnapshotMonth) newestSnapshotMonth = h.month; });
  });
  const _cutoff = (() => { const d = new Date(); d.setMonth(d.getMonth() - 2); return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`; })();
  const balancesStale      = hasHistory && newestSnapshotMonth < _cutoff;
  const balancesUnverified = !hasHistory;
  const reconAnomaly       = !!(reconciliation && reconciliation.paidTotal > 0 && reconciliation.balanceReduction <= 0);

  const allClearNow = !_activeDebtCards().some(c => _cardBal(c) > 0);

  // ── Next milestone (d21, tester: "a 10/10 report answers why should I
  // care") ── Computed as a business rule, never narrated ad hoc — the AI
  // inventing milestones would put different goalposts in different reports.
  // Priority order:
  //   1. Total balances returning below the starting line (the tester's exact
  //      case: a card retired, yet totals still above where they began — this
  //      milestone EXPLAINS the "0% of original debt" state instead of letting
  //      it read as failure)
  //   2. The next debt cleared, from the same strategy engine as everything else
  let nextMilestone = null;
  if (!payoffImpossible && !allClearNow) {
    if (beginDebt > 0 && totalDebt > beginDebt) {
      nextMilestone = `Total balances dropping back below your starting point (${fmt(beginDebt)}) — ${fmt(totalDebt - beginDebt)} to go. From there, "paid down" starts counting.`;
    } else {
      const method = S.debtMethod === 'snowball' ? 'snowball' : 'avalanche';
      const sim = _simulatePayoffStrategy(S.debtCards, _getMonthlyBudget(), method);
      if (sim && sim.firstClearedName && sim.firstClearedMonth > 0) {
        // firstClearedMonth is a month COUNTER from the sim, not a label
        const _md = new Date(); _md.setDate(1); _md.setMonth(_md.getMonth() + sim.firstClearedMonth);
        const _mdLabel = _md.toLocaleDateString('en-US', { month: 'long', year: 'numeric' });
        nextMilestone = `${sim.firstClearedName} fully paid — projected ${_mdLabel} at the current budget. Its minimum payment frees up every month after that.`;
      }
    }
  }

  return {
    totalDebt:             Math.round(totalDebt),
    beginDebt:             Math.round(beginDebt),
    eliminated:            Math.round(eliminated),
    pctPaid:               Math.round(pctPaid),
    avgMonthlyPayment:     Math.round(avgMonthlyPayment),
    paceStatus,
    pacePct,
    paceMonths,                    // d21: signed schedule months from _gwDateMovement — the honest pace
    interestSaved:         Math.round(S._interestSaved || 0),
    estimatedInterestPaid: Math.round(actualInterestPaid),
    hasRealInterest,               // true = from interest_charged field, false = estimated
    monthsOfHistory,               // how many months of real data back this
    hasHistory,                    // d21: false = avgMonthlyPayment is keyword-matched spend, unverified
    actualBalanceReduction: Math.round(actualBalanceReduction),
    reconciliation,                // d21: {paidTotal, balanceReduction, gap} | null — computed BEFORE narration
    nextMilestone,                 // d21: computed milestone verdict — the AI relays it, never invents one
    balancesUnverified,            // d21: no history — balances are as-typed, not confirmed
    balancesStale,                 // d21: history exists but stopped >2 months ago
    reconAnomaly,                  // d21: payments recorded, balances did not decrease
    lastSnapshotMonth: newestSnapshotMonth || null,
    projectedPayoffMonths: monthsRemaining,   // null when payoffImpossible — never a fake 0
    payoffImpossible,              // true = committed budget can't cover minimum payments
  };
}

// ── Behavioral profile ────────────────────────────────────────────────────────
function _calcBehavioralProfile(sbMonths) {
  const last12 = _lastNMonths(12);
  let greenCount = 0;
  const categoryOverages = {};

  if (sbMonths && sbMonths.length > 0) {
    const recentMonths = sbMonths.filter(m =>
      last12.includes((m.month_key || '').slice(0,7))
    );
    greenCount = recentMonths.filter(m => !m.is_over).length;
  } else {
    // Approximate green months from spending vs income
    const budgetIncome = S.incomes.reduce((s,i) => s+i.amount, 0);
    last12.forEach(mo => {
      const spent = S.transactions
        .filter(t => t.type==='debit' && (t.date||'').startsWith(mo))
        .reduce((s,t) => s+t.amount, 0);
      if (budgetIncome > 0 && spent < budgetIncome) greenCount++;
    });
  }

  // Most consistent overage category — computed from transactions directly
  // (S.profile is null while being built, so we can't reference it here)
  const budgetByCategory = {};
  S.expenses.forEach(e => { budgetByCategory[e.cat || e.name] = e.amount; });

  const months3 = _lastNMonths(3);
  const catSpend3 = {};
  S.transactions
    .filter(t => t.type === 'debit' && months3.some(mo => (t.date||'').startsWith(mo)))
    .forEach(t => {
      const cat = t.category || 'Other';
      catSpend3[cat] = (catSpend3[cat] || 0) + t.amount;
    });

  // Average over 3 months, compare to budget
  Object.entries(catSpend3).forEach(([cat, total]) => {
    const avg    = total / 3;
    const budget = budgetByCategory[cat] || 0;
    if (budget > 0 && avg > budget) categoryOverages[cat] = avg - budget;
  });
  const topOverage = Object.entries(categoryOverages).sort((a,b) => b[1]-a[1])[0];
  const worstCategory = topOverage ? topOverage[0] : null;

  // Item 39 (Rob 2026-10-05): the "engaged / occasional / passive" label that stood here - a guess about the
  // person from how many transactions they had - is removed. Nothing read it, and a sparse record can mean many
  // things; "passive" is not one Groundwork can see.

  // Best performing month — which calendar month is historically greenest
  const monthGreenCount = {};
  _lastNMonths(24).forEach(mo => {
    const monthNum = parseInt(mo.split('-')[1]) - 1;
    const budgetInc = S.incomes.reduce((s,i) => s+i.amount, 0);
    const spent = S.transactions
      .filter(t => t.type==='debit' && (t.date||'').startsWith(mo))
      .reduce((s,t) => s+t.amount, 0);
    if (!monthGreenCount[monthNum]) monthGreenCount[monthNum] = { green:0, total:0 };
    monthGreenCount[monthNum].total++;
    if (budgetInc > 0 && spent < budgetInc) monthGreenCount[monthNum].green++;
  });
  const bestMonth = Object.entries(monthGreenCount)
    .filter(([,v]) => v.total >= 2)
    .sort((a,b) => (b[1].green/b[1].total) - (a[1].green/a[1].total))[0];
  const bestPerformingMonth = bestMonth ? parseInt(bestMonth[0]) : null;

  return {
    greenMonths12:        greenCount,
    greenMonthRate:       Math.round((greenCount / 12) * 100),
    currentStreak:        _streakFromData().current,
    peakStreak:           _streakFromData().peak,
    mostOverageCategory:  worstCategory,
    bestPerformingMonth,
  };
}

// ── Net worth trajectory ──────────────────────────────────────────────────────
function _calcNetWorthTrajectory(snapshots) {
  if (!snapshots || snapshots.length < 2) {
    return { monthlyDelta: 0, trend: 'unknown', projectionLine: [] };
  }

  // Sort oldest first
  const sorted = [...snapshots].sort((a,b) =>
    (a.snapshot_date||a.date||'').localeCompare(b.snapshot_date||b.date||'')
  );

  const first = sorted[0];
  const last  = sorted[sorted.length-1];
  const firstNW = parseFloat(first.net_worth || first.netWorth || 0);
  const lastNW  = parseFloat(last.net_worth  || last.netWorth  || 0);
  const months  = sorted.length - 1;
  const monthlyDelta = months > 0 ? (lastNW - firstNW) / months : 0;

  // Trend
  const trend = monthlyDelta > 100 ? 'improving'
    : monthlyDelta < -100 ? 'declining'
    : 'flat';

  // Months until current NW reaches zero (if currently negative)
  const monthsToZero = lastNW < 0 && monthlyDelta > 0
    ? Math.ceil(Math.abs(lastNW) / monthlyDelta)
    : null;

  // 24-month projection line
  const projectionLine = [];
  for (let i = 1; i <= 24; i++) {
    const d = new Date();
    d.setMonth(d.getMonth() + i);
    projectionLine.push({
      month: `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`,
      projected: Math.round(lastNW + (monthlyDelta * i)),
    });
  }

  return {
    currentNW:    Math.round(lastNW),
    firstNW:      Math.round(firstNW),
    monthlyDelta: Math.round(monthlyDelta),
    annualizedRate: Math.round(monthlyDelta * 12),
    trend,
    monthsToZero,
    snapshotCount: sorted.length,
    projectionLine,
  };
}

// ─────────────────────────────────────────────────────────────────────────────
function scheduleSave() {
  clearTimeout(_saveTimer);
  setSaveDot('saving');
  _saveTimer = setTimeout(doSave, 1500);
}

async function doSave() {
  try {
    await API.post('/api/save', buildSnapshot());
    setSaveDot('saved');
  } catch(e) {
    setSaveDot('error');
  }
}

function setSaveDot(state) {
  // No-op — save indicator removed in Phase 8.
  // All writes go directly to DB; the snapshot is a backup layer only.
}

function buildSnapshot() {
  return {
    incomes:           S.incomes,
    expenses:          S.expenses,
    debtCardRows:      S.debtCards,
    transactions:      S.transactions,
    earnedAchievements:[...S.achievements],
    dfmActive:         S.dfmActive,
    dfmSettings:       { savingsCut: S.dfmSavingsCut },
    savingsPct:        parseInt(g('settingsSavingsPct')?.value || 10),
    monthlyBudget:     _getMonthlyBudget() || 1500,   // 1500 = app default, same coercion boot applies
    bybItems:          S.bybItems,
    netWorth:          S.netWorth,
    savedAt:           new Date().toISOString(),
  };
}

// ── Error log viewer ─────────────────────────────────────────────────────────
function showGwErrors() {
  if (!_gwErrorLog.length) return;
  const existing = document.getElementById('gwErrorModal');
  if (existing) existing.remove();
  const rows = _gwErrorLog.map(e => `
    <div style="border-bottom:1px solid var(--steel);padding:8px 0;font-size:12px">
      <div style="display:flex;justify-content:space-between;margin-bottom:3px">
        <span style="font-family:var(--font-mono);color:var(--ember);font-size:11px">${e.src}:${e.line}</span>
        <span style="color:var(--slate-2);font-size:10px">${e.ts.slice(11,19)}</span>
      </div>
      <div style="color:var(--ink);word-break:break-word">${esc(e.msg)}</div>
      ${e.stack ? `<div style="font-family:var(--font-mono);font-size:10px;color:var(--slate-2);white-space:pre-wrap;word-break:break-all;margin-top:3px">${esc(e.stack)}</div>` : ''}
    </div>`).join('');
  const modal = document.createElement('div');
  modal.id        = 'gwErrorModal';
  modal.className = 'modal-overlay';
  modal.innerHTML = `
    <div class="modal" style="max-width:560px;max-height:80vh;overflow-y:auto">
      <div class="modal-header">
        <div class="modal-title" style="color:var(--ember)">⚠ Error log (${_gwErrorLog.length})</div>
        <button class="modal-close" onclick="document.getElementById('gwErrorModal').remove()">×</button>
      </div>
      <div class="modal-body" style="padding:16px">
        <div style="font-size:12px;color:var(--slate);margin-bottom:12px">
          Caught JS errors this session. Copy and share when reporting bugs.
        </div>
        ${rows}
        <div style="margin-top:14px;display:flex;gap:8px">
          <button class="btn btn-secondary btn-sm" onclick="
            navigator.clipboard?.writeText(JSON.stringify(_gwErrorLog,null,2))
              .then(()=>showToast('Copied','Error log copied','success')).catch(_gwErr('copyErrorLog'))">
            Copy to clipboard
          </button>
          <button class="btn btn-ghost btn-sm" onclick="
            _gwErrorLog.length=0;
            const i=document.getElementById('gwErrorIndicator'); if(i) i.style.display='none';
            document.getElementById('gwErrorModal').remove()">
            Clear
          </button>
        </div>
      </div>
    </div>`;
  document.body.appendChild(modal);
}


// ── Auto-import polling ───────────────────────────────────────────────────────
// The Downloads watcher in launch.py queues detected bank files on the server;
// we poll /pending and offer to import. Polling only runs when the import
// modal is closed, because /pending pops the item — we don't want to consume
// a file while the user is mid-import on another.
let _autoImportPollTimer = null;
let _autoImportCtx = null;
let _autoImportFastUntil = 0;   // while a bank window is in use, check every few seconds

function _startAutoImportPolling() {
  if (_autoImportPollTimer) return;
  let last = 0;
  const poll = async () => {
    try {
      if (!g('importModal')?.classList.contains('hidden')) return; // busy
      if (document.getElementById('autoImportPrompt')) return;     // already offering
      const item = await API.get('/api/auto-import/pending');
      if (item && item.filename && (item.content || item.kind === 'statement')) _offerAutoImport(item);
    } catch (e) { /* transient — next tick */ }
  };
  // One 3 s tick: poll every tick while a bank window was opened in the last
  // half hour (the user is downloading and waiting for Groundwork to notice -
  // they should never have to go looking), every 45 s otherwise.
  _autoImportPollTimer = setInterval(() => {
    const now = Date.now();
    if (now < _autoImportFastUntil || now - last >= 45000) { last = now; poll(); }
  }, 3000);
  setTimeout(poll, 3000); // first check shortly after boot
}

function _offerAutoImport(item) {
  _autoImportCtx = item;
  const el = document.createElement('div');
  el.id = 'autoImportPrompt';
  el.style.cssText = `
    position:fixed;bottom:24px;left:50%;transform:translateX(-50%);
    background:var(--paper);border:1px solid var(--steel);
    border-left:3px solid var(--sky);
    border-radius:var(--r-lg);box-shadow:var(--shadow-md);
    padding:14px 18px;max-width:480px;width:calc(100vw - 48px);
    z-index:200;display:flex;flex-direction:column;gap:10px;
    animation:slideUp .18s ease;`;
  el.innerHTML = `
    <div style="font-size:13px;color:var(--ink);line-height:1.5">
      ${item.kind === 'statement'
        ? `📄 Statement downloaded: <b style="font-weight:600">${esc(item.filename)}</b>. Open it to review?`
        : `📥 <b style="font-weight:600">${esc(item.filename)}</b> just finished downloading.
      Import it into Groundwork?`}
    </div>
    <div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap">
      <button onclick="_acceptAutoImport()"
        style="font-size:12px;font-family:inherit;background:var(--sky);color:#fff;
               border:none;border-radius:var(--r-md);padding:6px 14px;cursor:pointer;
               font-weight:500">
        ${item.kind === 'statement' ? 'Open statement' : 'Import now'}
      </button>
      <button onclick="document.getElementById('autoImportPrompt')?.remove()"
        style="font-size:12px;font-family:inherit;background:none;
               border:1px solid var(--steel-2);border-radius:var(--r-md);
               padding:6px 14px;cursor:pointer;color:var(--ink)">
        Not this file
      </button>
    </div>`;
  document.body.appendChild(el);
  // Sticks around 60s — a download prompt shouldn't vanish while the user
  // is still looking at their browser.
  setTimeout(() => {
    if (document.getElementById('autoImportPrompt') === el) el.remove();
  }, 60000);
}

async function _acceptAutoImport() {
  document.getElementById('autoImportPrompt')?.remove();
  const item = _autoImportCtx;
  if (!item) return;
  if (item.kind === 'statement') {
    // Only now - after the user said yes - are the statement's bytes read, and
    // they go to the same import flow a manual upload takes (F7).
    try {
      const r = await _gwFetch('/api/auto-import/statement', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ path: item.path }),
      });
      if (!r.ok) throw new Error(r.status === 404 ? 'It is no longer in your Downloads folder.' : 'It could not be read.');
      const blob = await r.blob();
      const pdf  = new File([blob], item.filename, { type: 'application/pdf' });
      _importOriginPending = { path: item.path, sha256: await _sha256Hex(blob) };
      showImportModal();
      handleImportFile({ target: { files: [pdf] } });
    } catch(e) {
      showToast('Could not open the statement', e.message || '', 'warning');
    }
    return;
  }
  const file = new File([item.content], item.filename, { type: 'text/plain' });
  // The page's File is rebuilt from decoded text; the watcher's hash is of the
  // raw bytes on disk, which is what identifies the download.
  _importOriginPending = { path: item.path, sha256: item.sha256 || null };
  showImportModal();
  handleImportFile({ target: { files: [file] } });
}

// ── Update popup (Phase 2) ────────────────────────────────────────────────────
// Asks the local server (which asks the website, cached) whether a newer
// build exists. Shows a standard modal; "Remind me later" lasts the session,
// so it reappears on next launch — right behavior for updates. Download opens
// the SYSTEM browser via the pywebview bridge, not the embedded webview.
// Never shown while first-run onboarding is on screen.
let _updateDismissed = false;
let _updateCtx = null;

async function _checkForUpdates() {
  try {
    const u = await API.get('/api/update-check');
    if (!u || !u.update_available || _updateDismissed) return;
    if (document.getElementById('updateModal')) return;
    // A brand-new install is mid-onboarding and already current — don't
    // stack a second overlay on top of the welcome flow.
    const ob = document.getElementById('onboardingOverlay');
    if (ob && !ob.classList.contains('hidden')) return;
    _updateCtx = u;
    const el = document.createElement('div');
    el.id = 'updateModal';
    el.className = 'modal-overlay';
    el.innerHTML = `
      <div class="modal" style="max-width:420px">
        <div class="modal-header">
          <div class="modal-title">Update available</div>
          <button class="modal-close" onclick="_dismissUpdateModal()">×</button>
        </div>
        <div class="modal-body">
          <p style="color:var(--ink);line-height:1.6;margin:0 0 6px">
            Groundwork <b style="font-family:var(--font-mono)">${esc(u.latest)}</b> is ready to download.
            You're on <span style="font-family:var(--font-mono)">${esc(u.current)}</span>.
          </p>
          ${u.notes ? `<p style="color:var(--slate);line-height:1.6;margin:0">${esc(u.notes)}</p>` : ''}
        </div>
        <div class="modal-footer">
          <button class="btn btn-secondary" onclick="_dismissUpdateModal()">Remind me later</button>
          <button onclick="window.pywebview?.api?.open_external('https://groundworkfinance.app/changelog') || window.open('https://groundworkfinance.app/changelog','_blank')"
            style="font-size:12px;font-family:inherit;background:none;border:none;
                   color:var(--slate-2);cursor:pointer;padding:6px 4px;
                   text-decoration:underline">
            What changed
          </button>
          <button class="btn btn-primary" onclick="_openUpdateDownload()">Download update</button>
        </div>
      </div>`;
    document.body.appendChild(el);
  } catch (e) { _gwErr('_checkForUpdates')(e); }
}

function _openUpdateDownload() {
  const url = _updateCtx?.url;
  if (!url) return;
  if (window.pywebview?.api?.open_external) {
    window.pywebview.api.open_external(url);   // system browser
  } else {
    window.open(url, '_blank');                // dev fallback
  }
  _dismissUpdateModal();
}

function _dismissUpdateModal() {
  _updateDismissed = true;
  document.getElementById('updateModal')?.remove();
}

// ── Server heartbeat ──────────────────────────────────────────────────────────
// Pings /api/health every 60s. Detects server restarts + version mismatches.
let _heartbeatTimer = null;
let _gwSessionId    = '';

function _startHeartbeat() {
  if (_heartbeatTimer) return;
  _heartbeatTimer = setInterval(async () => {
    try {
      const r = await fetch('/api/health', { headers: _GW_AUTH_HEADER() });
      const d = await r.json();
      if (d.platform) window._gwServerPlatform = d.platform + (d.py_version ? ' / Python ' + d.py_version : '');
      if (!_gwSessionId) { _gwSessionId = d.session_id || ''; return; }
      if (d.session_id && d.session_id !== _gwSessionId) {
        // Server restarted — reload to get fresh token
        clearInterval(_heartbeatTimer);
        showToast('Groundwork restarted', 'Reloading…', 'info');
        setTimeout(() => window.location.reload(), 1500);
      }
    } catch(e) {
      // Transient — server may be mid-restart. The next tick (or the API
      // layer's 403 self-heal) will recover; stay quiet.
    }
  }, 60000);
}

// ─── Beta feedback system ─────────────────────────────────────────────────────
// Print-only by design. Groundwork does not compose, send, email or copy this
// report: it renders exactly what the preview shows and hands that to the print
// dialog. If the user prints to PDF and mails it, that is their own act on their
// own data, and not a crossing Groundwork initiated.
//
// The previous version opened a mailto: with the server log appended *after* the
// preview had rendered, so the panel labelled "Report preview" did not show the
// report that left. See gw 2.0/HEALTH_TRUST_BOUNDARY.md, findings F2 and F5.

// Three states, deliberately. `null` = not yet determined, 'unavailable' = we
// tried and could not read it, [] = we read it and there was nothing. Collapsing
// the last two would report "we never looked" as "there is nothing" - gap 4's
// contradicted/not_evaluated tie, arriving in a different place.
let _gwFeedbackServerLog = null;

function _gwGetOSInfo() {
  if (window._gwServerPlatform) return window._gwServerPlatform;
  const ua = navigator.userAgent;
  if (ua.includes('Win'))   return 'Windows';
  if (ua.includes('Mac'))   return 'macOS';
  if (ua.includes('Linux')) return 'Linux';
  return 'Unknown OS';
}

function _gwBuildReport(userDescription) {
  const now     = new Date().toISOString().replace('T',' ').slice(0,19);
  const version = typeof GW_VERSION !== 'undefined' ? GW_VERSION : 'unknown';
  const os      = _gwGetOSInfo();
  const SEP     = '─'.repeat(40);
  const errorLines = (_gwErrorLog || []).length
    ? (_gwErrorLog||[]).map(e => '['+e.ts.slice(11,19)+'] '+e.src+':'+e.line+' — '+e.msg+(e.stack?'\n  '+e.stack:'')).join('\n')
    : '(no errors in log)';
  const serverLines =
      _gwFeedbackServerLog === null          ? '(not yet read)'
    : _gwFeedbackServerLog === 'unavailable' ? '(server log could not be read - not included)'
    : _gwFeedbackServerLog.length            ? _gwFeedbackServerLog.join('\n')
    :                                          '(no recent server warnings or errors)';
  return [
    'GROUNDWORK BUG REPORT', SEP,
    'Version : ' + version, 'OS      : ' + os, 'Date    : ' + now, '',
    'What happened:', userDescription ? userDescription.trim() : '(no description)',
    '', 'Browser error log:', errorLines,
    '', 'Server log (recent warnings and errors):', serverLines,
    '', SEP,
  ].join('\n');
}

// One builder, one preview, one printed artefact. Everything that will appear on
// the page appears here first — that equality is the whole point of the redesign.
function _gwRefreshFeedbackPreview() {
  const preview = document.getElementById('gwFeedbackPreview');
  if (!preview) return;
  preview.textContent = _gwBuildReport(
    document.getElementById('gwFeedbackDesc')?.value || '');
}

function openFeedbackModal() {
  const existing = document.getElementById('gwFeedbackModal');
  if (existing) existing.remove();
  const modal = document.createElement('div');
  modal.id = 'gwFeedbackModal';
  modal.className = 'modal-overlay';
  modal.innerHTML = `
    <div class="modal" style="max-width:520px">
      <div class="modal-header">
        <div class="modal-title">Report a problem</div>
        <button class="modal-close" onclick="document.getElementById('gwFeedbackModal').remove()">×</button>
      </div>
      <div class="modal-body" style="padding:20px">
        <div class="field" style="margin-bottom:16px">
          <label style="font-size:12px;font-weight:600;color:var(--slate);display:block;margin-bottom:6px">What were you doing when this happened?</label>
          <textarea id="gwFeedbackDesc" rows="4" placeholder="e.g. I tapped the Lease button on a debt card and nothing changed…"
            style="width:100%;padding:10px;border:1px solid var(--steel);border-radius:var(--r-md);font-size:13px;font-family:var(--font-body);resize:vertical;background:var(--paper);color:var(--ink)"></textarea>
        </div>
        <div style="background:var(--mist);border:1px solid var(--steel);border-radius:var(--r-md);padding:12px;margin-bottom:16px">
          <div style="font-size:11px;font-weight:600;color:var(--slate);margin-bottom:6px;text-transform:uppercase;letter-spacing:.06em">Report preview</div>
          <pre id="gwFeedbackPreview" style="font-size:11px;font-family:var(--font-mono);color:var(--slate);white-space:pre-wrap;word-break:break-word;margin:0;max-height:140px;overflow-y:auto"></pre>
        </div>
        <div id="gwFeedbackNote" style="font-size:11px;color:var(--slate-2);margin-bottom:16px">Groundwork sends nothing. This preview is the complete report, and printing is the only action offered — what you do with the printout is yours.</div>
        <div style="display:flex;gap:8px;flex-wrap:wrap">
          <button id="gwFeedbackPrintBtn" class="btn btn-primary" onclick="_gwPrintFeedback()" disabled style="flex:1;min-width:140px;opacity:.5">Preparing report...</button>
          <button class="btn btn-ghost" onclick="document.getElementById('gwFeedbackModal').remove()">Close</button>
        </div>
      </div>
    </div>`;
  document.body.appendChild(modal);
  const desc = document.getElementById('gwFeedbackDesc');
  desc?.addEventListener('input', _gwRefreshFeedbackPreview);

  // Fetched into the preview, never appended afterwards.
  _gwFeedbackServerLog = null;
  _gwRefreshFeedbackPreview();
  Promise.resolve(API.get('/api/debug/log-tail'))
    .then(t => { _gwFeedbackServerLog = (t?.log || [])
                   .filter(l => / (WARNING|ERROR|CRITICAL) /.test(l)).slice(-8); })
    .catch(e => { _gwFeedbackServerLog = 'unavailable';
                  _gwErr('openFeedbackModal logTail')(e); })
    .then(() => { _gwRefreshFeedbackPreview(); _gwSetPrintEnabled(true); });

  setTimeout(() => desc?.focus(), 50);
}

// Deny by default, fail closed: the action that puts the report on a page is
// refused while any part of it is still undetermined, rather than printing a
// page with a hole in it and letting the reader decide what the hole meant.
function _gwSetPrintEnabled(on) {
  const b = document.getElementById('gwFeedbackPrintBtn');
  if (!b) return;
  b.disabled      = !on;
  b.style.opacity = on ? '' : '.5';
  b.textContent   = on ? 'Print report' : 'Preparing report...';
}

function _gwPrintFeedback() {
  if (_gwFeedbackServerLog === null) return;   // content not yet determined
  _gwRefreshFeedbackPreview();
  window.print();
}
async function bootFromDB() {
  /**
   * Primary boot path — loads all app state from the DB.
   * Fetches bootstrap + all transactions in parallel for a single
   * conceptual "boot round trip." Replaces the old snapshot pattern.
   */
  const [bootstrapRes, txnRes] = await Promise.all([
    API.get('/api/settings/bootstrap'),
    API.get('/api/transactions?per_page=5000').catch(_gwErrVal('bootFromDB', { data: [] })),
  ]);
  const data = bootstrapRes.data || bootstrapRes;
  if (!data) throw new Error('Empty bootstrap response');
  restoreFromBootstrap(data);

  // Populate S.transactions from DB — this was missing from the DB-first boot path
  const txnPayload = txnRes.data || txnRes;
  S.transactions = Array.isArray(txnPayload)
    ? txnPayload
    : (txnPayload?.items || txnPayload?.transactions || []);

  // Categories — the single source of truth for every category picker in the
  // app (Ledger filter/recategorize, Budget rows, import rules, recurring
  // items, Settings). Awaited here so nothing downstream renders against an
  // empty list.
  await loadCategories();

  // Accounts — same pattern, single source of truth for every account
  // picker (Ledger filter/edit, Add modal, import).
  await loadAccounts();

  // Import intelligence (category map + rules) is now parsed directly from
  // the bootstrap settings payload above in restoreFromBootstrap() — no
  // separate fetch needed on the main boot path (see loadImportIntelligence()
  // for the offline-fallback path, which doesn't go through bootstrap).
  // Load rollover category settings
  loadRolloverSettings().catch(_gwErr('bootFromDB'));
  _loadSchedulerPrefs();
  // Load recurring transactions and post any that are due this month.
  // Awaited so the first dashboard/ledger render already includes anything
  // auto-posted here — previously this ran fire-and-forget and could lose
  // the race against showView('dashboard'), silently missing the post
  // until the next reload.
  await loadRecurringItems().then(() => postDueRecurringTransactions()).catch(_gwErr('bootFromDB'));
  // Auto-record a net worth snapshot for this month if one doesn't exist yet
  // (idempotent — server skips if already taken). Awaited and placed before
  // buildFinancialProfile() so a freshly-created snapshot is already
  // reflected in this same boot's net-worth trajectory/pace calculation,
  // instead of lagging a full reload behind.
  await autoSnapshotNetWorthIfDue();
  // Build the unified financial profile from all loaded data — awaited so
  // the dashboard's first render already has S.profile (spending trends,
  // debt pace, etc.) instead of flashing empty and never re-rendering.
  await buildFinancialProfile().catch(_gwErr('bootFromDB'));
}

function restoreFromBootstrap(data) {
  if (!data) return;

  // ── Incomes & expenses ────────────────────────────────────────────────
  S.incomes  = (data.incomes  || []).map(i => ({ id: i.id, name: i.name, amount: i.amount }));
  S.expenses = (data.expenses || []).map(e => ({ id: e.id, cat: e.cat || 'Other', name: e.name, amount: e.amount,
    // This month's figure and where it came from (the server decides; nothing here writes it - M1/M2).
    month_amount: e.month_amount, month_source: e.month_source, month_why: e.month_why, month_from: e.month_from,
    month_for: e.month_for }));

  // ── Debt cards ────────────────────────────────────────────────────────
  S.debtCards = [];
  document.getElementById('cardList')?.replaceChildren();
  (data.debts || []).forEach(d => {
    addCard(d.name, d.begin_balance, d.start_date, d.interest_rate,
            d.minimum_payment, d.current_balance, d.due_day, d.id,
            !!d.paid_off_at,   // was hardcoded false — every restart silently un-retired paid cards (d21 fix)
            '',
            d.debt_type || 'credit',
            d.linked_account_id    || null,
            d.calculated_balance   ?? null,
            d.credit_limit         ?? null,
            d.end_date             || '',
            d.linked_txn_count     ?? null);
    S.debtCards[S.debtCards.length - 1].paidOffAt = d.paid_off_at || null;
    Object.assign(S.debtCards[S.debtCards.length - 1], {   // V2
      rateSource: d.interest_rate_source || null, minSource: d.minimum_payment_source || null,
      statementAsOf: d.statement_as_of || null });
  });

  // ── Achievements ──────────────────────────────────────────────────────
  S.achievements = new Set(data.earnedAchievements || []);

  // ── BYB items ─────────────────────────────────────────────────────────
  S.bybItems = (data.bybItems || []).map(b => ({
    id: b.id, _dbId: b.id, type: b.type, name: b.name,
    category: b.category, monthly: b.monthly, replacing: b.replacing || null,
  }));

  // ── Net worth — includes retirement accounts (Phase 11) ──────────────
  const nwData = data.netWorth || {};
  S.netWorth = {
    savings:       nwData.savings       || 0,
    investments:   nwData.investments   || 0,
    cash:          nwData.cash          || 0,
    // BUG FIX (July 6): homeValue/mortgage were only ever read from
    // nwData (the dedicated server-side netWorth structure), with no
    // fallback — unlike retirement401k/retirementIRA below, which already
    // had this same safety net. updateNetWorth() correctly SAVES both
    // fields to /api/settings (home_value, mortgage_balance) every time,
    // but nothing ever read them back from there — confirmed by grepping
    // the whole file for "home_value" and finding exactly one occurrence,
    // the save call itself. Result: homeValue silently reset to 0 on every
    // reboot regardless of what was saved. Adding the same fallback
    // pattern already proven for retirement fields.
    homeValue:     nwData.homeValue     || parseFloat(data.prefs?.home_value||0)||0,
    mortgage:      nwData.mortgage      || parseFloat(data.prefs?.mortgage_balance||0)||0,
    retirement401k:nwData.retirement401k|| parseFloat(data.prefs?.retirement_401k||0)||0,
    retirementIRA: nwData.retirementIRA || parseFloat(data.prefs?.retirement_ira||0)||0,
  };

  // ── Preferences ───────────────────────────────────────────────────────
  const prefs     = data.prefs || {};
  S.dfmActive     = !!prefs.dfmActive;
  S.dfmSavingsCut = prefs.dfmSavingsCut || 5;
  S.debtMethod    = prefs.debtMethod    || 'avalanche';
  S.proactiveDial = prefs.proactiveDial || 'normal';
  try {
    S.strategyStreak = typeof prefs.strategyStreak === 'string'
      ? JSON.parse(prefs.strategyStreak)
      : { method: S.debtMethod, months: prefs.strategyStreak || 0 };
  } catch(e) { S.strategyStreak = { method: S.debtMethod, months: 0 }; }
  S.paymentStreak = prefs.paymentStreak || 0;

  // Apply to UI inputs
  // BUG FIX (July 6): mb was only ever written into the DOM input field
  // below, never kept as app state. That field lives inside <div
  // id="view-debt"> — only mounted while actually on the Debt Payoff
  // page. Every other function that needs the user's real monthly debt
  // budget (_simulatePayoff, called from Dashboard, Before You Buy, and
  // Reports) reads g('monthlyBudget')?.value directly, which silently
  // evaluates to 0 from anywhere else. Confirmed in the field: the Debt
  // Payoff Report showed a different, later payoff date than the Debt
  // Payoff page itself. Storing it as S.monthlyBudget gives every other
  // function a real value to fall back to regardless of which page is
  // currently mounted.
  const mb = prefs.monthlyBudget || 1500;
  S.monthlyBudget = mb;
  if (g('monthlyBudget'))         g('monthlyBudget').value         = mb;
  if (g('settingsMonthlyBudget')) g('settingsMonthlyBudget').value = mb;
  if (prefs.savingsPct && g('settingsSavingsPct')) g('settingsSavingsPct').value = prefs.savingsPct;
  g('btnAvalanche')?.classList.toggle('active', S.debtMethod === 'avalanche');
  g('btnSnowball')?.classList.toggle('active',  S.debtMethod === 'snowball');
  if (g('strategyHelpIcon')) g('strategyHelpIcon').innerHTML = helpIcon(S.debtMethod === 'snowball' ? 'snowball' : 'avalanche');

  // Display preferences
  if (!S.prefs) S.prefs = {};
  S.prefs.payoffDisplayMode = prefs.payoff_display_mode || 'countdown';

  // AI settings (avoids second round trip)
  if (data.settings) {
    _aiEnabled     = data.settings['ai_enabled'] !== 'false';
    S.prefs        = S.prefs || {};
    S.prefs.aiEnabled = _aiEnabled;
    // AI is local-only (CLOUD_AI_REMOVAL.md): no provider, no key.
    _cloudAiRemovedNotice(data.settings['cloud_ai_removed_notice']);
    // One notice at a time: the Ollama one waits a launch if the cloud one is showing now.
    const _cloudPending = data.settings['cloud_ai_removed_notice'] && data.settings['cloud_ai_removed_notice'] !== 'shown';
    if (!_cloudPending) _ollamaNotice();
    S.homeState     = data.settings['home_state']     || '';
    updateAIFeatureVisibility();

    // ── Life stage flags ────────────────────────────────────────────────
    const s = data.settings;
    try { S.lifeStage.pslfAccounts   = JSON.parse(s.pslf_accounts_json   || '{}'); } catch(e) { _gwErr('restoreFromBootstrap')(e); }
    try { S.lifeStage.debtTypes      = JSON.parse(s.debt_types_json      || '{}'); } catch(e) { _gwErr('restoreFromBootstrap')(e); }
    try { S.lifeStage.pensions       = JSON.parse(s.pension_json         || '[]'); } catch(e) { _gwErr('restoreFromBootstrap')(e); }
    S.lifeStage.commissionMode = s.commission_mode  === 'true';
    S.lifeStage.payFrequency   = s.pay_frequency    || null;   // unanswered stays unanswered (ONBOARDING_REVISIT.md O6)

    // Import intelligence (category map + categorization rules) — read straight
    // from the bootstrap payload instead of a second /api/settings round trip.
    // Previously loadImportIntelligence() fetched this separately and
    // unawaited, leaving a race window right after boot where _importRules/
    // _categoryMap were still empty — silently skipping auto-categorization
    // on a CSV import done right after opening the app.
    try { _categoryMap = JSON.parse(s.category_map_json || '{}'); } catch(e) { _categoryMap = {}; }
    try { _importRules = JSON.parse(s.import_rules_json || '[]'); } catch(e) { _importRules = []; }

    // Sound preference (default on)
    if (s.sound_enabled !== undefined) {
      S.prefs.soundEnabled = s.sound_enabled !== 'false';
    }
    const soundToggle = g('settingsSoundEnabled');
    if (soundToggle) {
      soundToggle.checked = S.prefs.soundEnabled !== false;
      const track = g('soundEnabledTrack');
      if (track) track.style.background = soundToggle.checked ? 'var(--pine)' : '';
    }

    // Household mode
    S_household.enabled     = s.household_mode   === 'true';
    S_household.user1Name   = s.household_user1  || '';
    S_household.user2Name   = s.household_user2  || '';

    // Apply UI toggles
    const commToggle = g('settingsCommissionMode');
    if (commToggle) commToggle.checked = S.lifeStage.commissionMode;
    const payFreqSel = g('settingsPayFrequency');
    if (payFreqSel) payFreqSel.value = S.lifeStage.payFrequency;
  }
}

async function loadSnapshot() {
  /** Offline fallback — loads from snapshot or localStorage. */
  try {
    const data = await API.get('/api/load');
    if (data) _restoreFromSnapshot(data);
    return;
  } catch(e) { /* server down */ }
  try {
    const raw = localStorage.getItem('gw2');
    if (raw) _restoreFromSnapshot(JSON.parse(raw));
  } catch(e) { _gwErr('loadSnapshot')(e); }
}

function _restoreFromSnapshot(d) {
  /** Legacy snapshot restore — offline fallback only. */
  if (!d) return;
  S.transactions  = d.transactions  || [];
  S.incomes       = d.incomes       || [];
  S.expenses      = d.expenses      || [];
  S.dfmActive     = !!d.dfmActive;
  S.dfmSavingsCut = d.dfmSettings?.savingsCut || 5;
  S.bybItems      = d.bybItems      || [];
  // HARDENING (July 8): default shape now matches the real S.netWorth shape —
  // retirement401k/retirementIRA were the exact two fields bug #13 (July 6)
  // was about; a mismatched default here is where that class of bug hides.
  S.netWorth      = d.netWorth      || { savings:0, investments:0, cash:0,
                                         homeValue:0, mortgage:0,
                                         retirement401k:0, retirementIRA:0 };
  if (d.earnedAchievements) S.achievements = new Set(d.earnedAchievements);
  S.debtCards = [];
  document.getElementById('cardList')?.replaceChildren();
  // Bootstrap sends 'debts' — each item uses server field names (snake_case).
  // addCard() uses camelCase legacy names. Map them explicitly here.
  const debtRows = d.debtCardRows || d.debts || [];
  debtRows.forEach(c => {
    addCard(
      c.name,
      c.beginBal   ?? c.begin_balance   ?? '',   // V6: unknown stays blank, not 0
      c.startDate  ?? c.start_date      ?? '',
      c.rate       ?? c.interest_rate   ?? '',
      c.minimum    ?? c.minimum_payment ?? '',
      c.currentBal ?? c.current_balance ?? c.begin_balance ?? '',
      c.dueDay     ?? c.due_day         ?? null,
      c._dbId      ?? c.id,
      c.paidInFull ?? !!c.paid_off_at,
      c.context    ?? '',
      c.debtType   ?? 'credit',
      c.linked_account_id  ?? null,
      c.calculated_balance ?? null,
      c.credit_limit       ?? null,
      c.endDate    ?? c.end_date        ?? '',
      c.linkedTxnCount ?? c.linked_txn_count ?? null
    );
    S.debtCards[S.debtCards.length - 1].paidOffAt = c.paidOffAt ?? c.paid_off_at ?? null;
    Object.assign(S.debtCards[S.debtCards.length - 1], {   // V2
      rateSource: c.rateSource ?? c.interest_rate_source ?? null,
      minSource: c.minSource ?? c.minimum_payment_source ?? null,
      statementAsOf: c.statementAsOf ?? c.statement_as_of ?? null });
  });
  if (d.savingsPct    && g('settingsSavingsPct'))    g('settingsSavingsPct').value    = d.savingsPct;
  // HARDENING (July 8): the legacy path wrote the DOM fields but never set
  // S.monthlyBudget — leaving _getMonthlyBudget()'s state fallback undefined
  // in offline mode. Same 1500 default coercion the bootstrap path applies.
  S.monthlyBudget = parseFloat(d.monthlyBudget) || 1500;
  if (d.monthlyBudget && g('settingsMonthlyBudget')) g('settingsMonthlyBudget').value = d.monthlyBudget;
  if (d.monthlyBudget && g('monthlyBudget'))         g('monthlyBudget').value         = d.monthlyBudget;
}


