// Shows a render error directly in the page (prepended to the view), so it's
// visible even when devtools/console access isn't available.
function _showViewError(name, e) {
  const el = g(`view-${name}`);
  if (!el) return;
  const box = document.createElement('div');
  box.style.cssText = 'padding:16px;margin-bottom:16px;font-family:monospace;font-size:12px;'
    + 'color:#dc2626;background:#fff;border:2px solid #dc2626;border-radius:8px;'
    + 'white-space:pre-wrap;word-break:break-word';
  box.innerHTML = `<strong>Render error in ${name}:</strong><br><br>${e?.message || e}<br><br>`
    + `<span style="color:#666">${(e?.stack || '').slice(0, 500)}</span>`;
  el.prepend(box);
}

function showView(name) {
  // Backward compat: tracker is now the Month Tracker tab inside the Debt page
  if (name === 'tracker') {
    showView('debt');
    setTimeout(() => _debtShowTab('tracker'), 50);
    return;
  }
  document.querySelectorAll('.view').forEach(v => v.classList.remove('active'));
  document.querySelectorAll('.nav-item').forEach(n => n.classList.remove('active'));
  g(`view-${name}`)?.classList.add('active');
  document.querySelector(`[data-view="${name}"]`)?.classList.add('active');
  setText('topbarTitle', VIEW_LABELS[name] || name);

  // Cancel investment auto-refresh when leaving that view
  if (name !== 'investments') clearAutoRefresh();

  // Lazy init each view
  if (name === 'dashboard') renderDashboard();
  if (name === 'ledger')    { renderLedger(); updateLedgerStats(); renderRecentWin('ledger','ledgerRecentWin'); loadRecurringDetection(); }
  if (name === 'budget')    { renderBudget(); renderRecentWin('budget','budgetRecentWin'); loadSinkingFunds(); renderSubscriptionAudit();
                              // Historian: user opened the budget page (a navigation, not
                              // a re-render — renderBudget() is called directly elsewhere).
                              API.post('/api/historian/engagement', { event: 'budget_reviewed' }).catch(_gwErr('budget_reviewed')); }
  if (name === 'debt')      { try { _renderCardList(); calculate(); renderDebtAchievements(); renderRecentWin('debt','debtRecentWin'); renderLoanFlags(); _debtShowTab(_debtActiveTab); loadPendingDrafts(); } catch(e) { _gwLogError('debt',e); } }
  if (name === 'byb')       renderBYB();
  if (name === 'investments') { try { initInvestments();      } catch(e) { console.error('Investments render:', e); _showViewError(name, e); } }
  if (name === 'networth')  { renderNetWorth(); renderPensionList(); _retirementToolsExpanded = false; const s = g('retirementToolsSection'); if(s) s.style.display='none'; const ch = g('retirementToolsChevron'); if(ch) ch.style.transform=''; }
  if (name === 'trophy')    { try { renderTrophyRoom();   } catch(e) { console.error('Trophy render:', e); _showViewError(name, e); } }
  if (name === 'settings')  { try { renderSettings();     } catch(e) { console.error('Settings render:', e); _showViewError(name, e); } }
  if (name === 'trip')      { try { renderTripPlanner();  } catch(e) { console.error('Trip render:', e); _showViewError(name, e); } }
  if (name === 'gifts')     { try { renderGiftBudget();   } catch(e) { console.error('Gift Budget render:', e); _showViewError(name, e); } }
  if (name === 'reports')   { try { renderReportCenter(); } catch(e) { console.error('Reports render:', e); _showViewError(name, e); } }

  // Catch day-rollover for sessions left open across midnight — idempotent
  // (postDueRecurringTransactions skips anything already posted this month)
  // and self-refreshes whatever it touches, so this is safe to fire on every
  // navigation without re-rendering the view we just built above.
  if (['dashboard','ledger','budget'].includes(name)) {
    postDueRecurringTransactions().catch(_gwErr('showView'));
  }

  // First-visit banners (Layer 2)
  if (typeof FIRST_VISIT_BANNERS !== 'undefined' && FIRST_VISIT_BANNERS[name]) {
    setTimeout(() => renderFirstVisitBanner(name), 60);
  }
  // Close any open help card on navigation
  if (typeof closeHelpCard === 'function') closeHelpCard();
}

