// ── Column resize ──────────────────────────────────────────────────────
// The 6 resize handles in #ledgerColHead set CSS vars on the .ledger card,
// which both the col-head grid and every row grid read from. Widths are
// saved to localStorage so the user's tweaks persist across sessions —
// nothing's worse than having to re-resize columns every time you open
// the app.
const LEDGER_COL_WIDTHS_KEY = 'gw2_ledgerColWidths';
const _LEDGER_COL_CONFIG = {
  icon:     { var: '--c-icon',     min: 36  },
  date:     { var: '--c-date',     min: 80  },
  desc:     { var: '--c-desc',     min: 180 },  // dragged in pixels, then stored as px
  account:  { var: '--c-account',  min: 100 },
  category: { var: '--c-category', min: 100 },
  amount:   { var: '--c-amount',   min: 90  },
};

function _restoreLedgerColWidths() {
  const card = g('ledgerCard');
  if (!card) return;
  try {
    const saved = JSON.parse(localStorage.getItem(LEDGER_COL_WIDTHS_KEY) || 'null');
    if (!saved) return;
    for (const col of Object.keys(_LEDGER_COL_CONFIG)) {
      if (saved[col]) card.style.setProperty(_LEDGER_COL_CONFIG[col].var, saved[col]);
    }
  } catch(e) { /* corrupt — ignore */ }
}

function _persistLedgerColWidth(col, valuePx) {
  try {
    const saved = JSON.parse(localStorage.getItem(LEDGER_COL_WIDTHS_KEY) || '{}');
    saved[col] = valuePx + 'px';
    localStorage.setItem(LEDGER_COL_WIDTHS_KEY, JSON.stringify(saved));
  } catch(e) { /* localStorage unavailable */ }
}

// Wired once, via delegation, so handles work even after re-renders that
// would otherwise need rebinding. The header isn't re-rendered (only the
// body is) but delegation is the safer pattern in case that ever changes.
function _initLedgerColResize() {
  if (_initLedgerColResize._wired) return;
  _initLedgerColResize._wired = true;

  document.addEventListener('mousedown', (e) => {
    const handle = e.target.closest('.col-resize');
    if (!handle) return;
    const col = handle.dataset.col;
    const cfg = _LEDGER_COL_CONFIG[col];
    if (!cfg) return;

    e.preventDefault();
    const card = g('ledgerCard');
    if (!card) return;
    handle.classList.add('resizing');

    // Use the column header's actual rendered width as the starting point
    // — works whether the column is currently sized by a px value or 1fr.
    const ch = handle.parentElement;
    const startWidth = ch.getBoundingClientRect().width;
    const startX = e.clientX;

    function onMove(ev) {
      const newW = Math.max(cfg.min, Math.round(startWidth + (ev.clientX - startX)));
      card.style.setProperty(cfg.var, newW + 'px');
    }
    function onUp(ev) {
      document.removeEventListener('mousemove', onMove);
      document.removeEventListener('mouseup', onUp);
      handle.classList.remove('resizing');
      document.body.style.cursor = '';
      document.body.style.userSelect = '';
      const newW = Math.max(cfg.min, Math.round(startWidth + (ev.clientX - startX)));
      _persistLedgerColWidth(col, newW);
    }
    document.body.style.cursor = 'col-resize';
    document.body.style.userSelect = 'none';
    document.addEventListener('mousemove', onMove);
    document.addEventListener('mouseup', onUp);
  });

  // Don't let a click on the resize handle bubble up to the column header
  // (which has its own click handler for sorting).
  document.addEventListener('click', (e) => {
    if (e.target.closest('.col-resize')) e.stopPropagation();
  }, true);
}

// Debounced search — renderLedger does a full filter + normalize + innerHTML
// rebuild of every matching transaction; running it per keystroke makes typing
// laggy on large ledgers. 180ms trailing debounce.
let _ledgerShowAll = false;        // Phase 3 row cap — per-filter
let _ledgerLastFilterSig = '';
let _ledgerSearchTimer = null;
function ledgerSearchInput() {
  clearTimeout(_ledgerSearchTimer);
  _ledgerSearchTimer = setTimeout(renderLedger, 180);
}

function renderLedger() {
  const body     = g('ledgerBody');
  const countEl  = g('ledgerCount');
  if (!body) return;

  let txns = _ledgerHasActiveFilter() ? S.transactions.slice() : _ledgerTxnsForSelectedMonth();

  // Filters
  const search = (g('ledgerSearch')?.value||'').toLowerCase();
  const cat    = g('ledgerCatFilter')?.value||'';
  const type   = g('ledgerTypeFilter')?.value||'';
  const acct   = g('ledgerAccountFilter')?.value||'';

  // Search: check merchant (canonical clean name) first, then description,
  // then category. Normalize special chars so "at&t" matches "AT&T",
  // "att", "at & t" — the & is the common failure case.
  if (search) {
    const normalize = s => (s||'').toLowerCase()
      .replace(/&/g, 'and')      // at&t → atand t; also accept "and" version
      .replace(/[^a-z0-9 ]/g, ' ')
      .replace(/\s+/g, ' ')
      .trim();
    const normSearch = normalize(search);
    // Also try the raw search for exact-match users who type the & themselves
    const rawSearch  = search.toLowerCase();
    txns = txns.filter(t => {
      const merchant = normalize(t.merchant || '');
      const desc     = normalize(t.description || '');
      const cat      = (t.category||'').toLowerCase();
      return merchant.includes(normSearch)
          || desc.includes(normSearch)
          || cat.includes(normSearch)
          || (t.merchant||'').toLowerCase().includes(rawSearch)
          || (t.description||'').toLowerCase().includes(rawSearch);
    });
  }
  if (cat) {
    // If filtering by a parent category, include all its child categories
    const children = _catChildren(cat);
    if (children.length > 0) {
      const allNames = [cat, ...children];
      txns = txns.filter(t => allNames.includes(t.category));
    } else {
      txns = txns.filter(t => t.category === cat);
    }
  }
  if (type)   txns = txns.filter(t => t.type === type);
  if (acct)   txns = txns.filter(t => t.account === acct);
  if (_ledgerShowUnclearedOnly) txns = txns.filter(t => !t.cleared);

  _saveLedgerFilters({ search, cat, type, acct });

  // Keep the month label/arrows in sync with whatever just changed the
  // visible rows — search, the uncleared toggle, and the (hidden-shim)
  // category/type filters all call renderLedger() directly without also
  // calling updateLedgerStats(), which is where this used to live exclusively.
  // Called here (before any early return below) so it never goes stale.
  _renderLedgerMonthSwitcher();

  // Sort. _ledgerSortDir of -1 means descending (newest/largest first),
  // +1 means ascending. The comparator returns negative when a should
  // come before b, so for descending: a>b → -1, a<b → +1.
  txns.sort((a,b) => {
    let va = a[_ledgerSortCol], vb = b[_ledgerSortCol];
    if (_ledgerSortCol==='amount'){va=+va;vb=+vb;}
    return va<vb ? -_ledgerSortDir : va>vb ? _ledgerSortDir : 0;
  });

  // Sort-mark on column headers
  document.querySelectorAll('#ledgerColHead .ch.sortable').forEach(ch => {
    const col = ch.dataset.sort;
    const mark = ch.querySelector('.sort-mark');
    if (!mark) return;
    if (col === _ledgerSortCol) {
      ch.classList.add('sort-active');
      mark.textContent = _ledgerSortDir < 0 ? '↓' : '↑';
    } else {
      ch.classList.remove('sort-active');
      mark.textContent = '';
    }
  });

  if (countEl) countEl.textContent = `${txns.length} transaction${txns.length!==1?'s':''}`;

  if (!txns.length) {
    const filtered = _ledgerHasActiveFilter();
    body.innerHTML = filtered
      ? `<div class="ledger-empty"><div class="icon">🔍</div>
          <div class="title">No transactions found</div>
          <div class="sub">Try adjusting your filters, or import some transactions.</div></div>`
      : `<div class="ledger-empty"><div class="icon">📭</div>
          <div class="title">No transactions in ${_ledgerMonthLabel(_ledgerMonthKey)}</div>
          <div class="sub">Use the arrows above to browse other months, or add one here.</div></div>`;
    return;
  }

  // Sorting by date is the natural case where day-grouping makes sense.
  // For other sort modes (description/amount) the day-grouping logic still
  // works — it groups whatever order the txns are currently in — but the
  // group order may look unusual. That's deliberate: respect the user's
  // chosen sort, don't override it.
  const groups = [];                   // [{ key, label, txns }]
  const byKey = new Map();
  for (const t of txns) {
    const k = (t.date || '').slice(0,10);
    if (!byKey.has(k)) {
      const g = { key:k, label:_dayHeadLabel(k), txns:[] };
      byKey.set(k, g);
      groups.push(g);
    }
    byKey.get(k).txns.push(t);
  }

  // ── Row cap (Phase 3) ─────────────────────────────────────────────────────
  // Rendering every matching row builds multi-MB innerHTML on big ledgers.
  // Cap at ~300 transactions, cutting at day boundaries so a day is never
  // split. "Show all" lifts the cap for the current filter only — changing
  // any filter re-arms it.
  const LEDGER_ROW_CAP = 300;
  const filterSig = [search, g('ledgerAccountFilter')?.value, g('ledgerCatFilter')?.value,
                     g('ledgerTypeFilter')?.value, _ledgerRange, _ledgerMonthKey].join('|');
  if (filterSig !== _ledgerLastFilterSig) { _ledgerShowAll = false; _ledgerLastFilterSig = filterSig; }

  const totalTxns = txns.length;
  let shownGroups = groups, shownTxns = totalTxns;
  if (!_ledgerShowAll && totalTxns > LEDGER_ROW_CAP) {
    shownGroups = []; shownTxns = 0;
    for (const grp of groups) {
      shownGroups.push(grp);
      shownTxns += grp.txns.length;
      if (shownTxns >= LEDGER_ROW_CAP) break;
    }
  }

  body.innerHTML = shownGroups.map(grp => {
    const collapsed = _ledgerCollapsedDays.has(grp.key);
    const sum = grp.txns.reduce((s,t) => s + (t.type==='credit' ? t.amount : -t.amount), 0);
    const sumStr = (sum>=0?'+':'') + fmt(sum);
    const cls = sum>=0 ? 'pos' : 'neg';
    return `<div class="day-group${collapsed?' collapsed':''}">
      <div class="day-head" onclick="toggleLedgerDay('${grp.key}')">
        <span class="dh-toggle">▾</span>
        <span class="dh-date">${grp.label}</span>
        <span class="dh-meta">${grp.txns.length} transaction${grp.txns.length!==1?'s':''}</span>
        <span class="dh-spacer"></span>
        <span class="dh-net ${cls}">${sumStr}</span>
      </div>
      <div class="day-rows">${grp.txns.map(t => _ledgerRowHTML(t)).join('')}</div>
    </div>`;
  }).join('') + (shownTxns < totalTxns
    ? `<div style="text-align:center;padding:16px">
         <div style="font-size:12px;color:var(--slate);margin-bottom:8px">
           Showing the most recent ${shownTxns} of ${totalTxns} transactions</div>
         <button class="btn btn-sm btn-secondary" onclick="_ledgerShowAll=true;renderLedger()">
           Show all ${totalTxns}</button>
       </div>`
    : '');

  // After re-render, if a row was mid-bloom, restore the bloom for it.
  if (_ledgerEditingId != null) {
    const row = body.querySelector(`.row[data-id="${_ledgerEditingId}"]`);
    if (row) _openEditBloom(row);
  }
}

// "Wed, June 18" — day-head label format. Uses the local timezone parsing
// pattern below so a YYYY-MM-DD string doesn't shift a day on UTC→local.
function _dayHeadLabel(yyyymmdd) {
  if (!yyyymmdd) return '—';
  const [y,m,d] = yyyymmdd.split('-').map(Number);
  if (!y) return yyyymmdd;
  const dt = new Date(y, (m||1)-1, d||1);
  return dt.toLocaleDateString('en-US', { weekday:'short', month:'long', day:'numeric' });
}

// Canonical category buckets — fallback slugs for names that don't yet
// exist in S.categories. Once a category is defined in Settings with its
// own color and icon, that wins. This list is only for the cold-start case.
// CP6 (this session) — added groceries/coffee/fastfood/phone/streaming +
// the mid-value backlog (travel/charity/childcare/fees/taxes/auto/home/
// beauty/fitness/education), so they get sensible defaults the first time
// a user creates a category with one of these names.
const _CAT_CANONICAL = [
  'income','refund','savings','transfer','debt','housing','utilities','phone','streaming','subscription','subscriptions',
  'food','restaurant','fastfood','coffee','groceries',
  'transportation','transport','gas','auto','autoservice',
  'personal','shopping','entertainment','hobby','hobbies',
  'healthcare','health','petcare','pet','insurance','childcare',
  'travel','charity','beauty','fitness','education','fees','taxes','homeservices',
  'other',
];

function _catSlug(name) {
  const raw = (name||'other').toLowerCase().replace(/[^a-z]/g,'') || 'other';
  if (_CAT_CANONICAL.includes(raw)) return raw;
  let best = '';
  for (const c of _CAT_CANONICAL) {
    if (raw.startsWith(c) && c.length > best.length) best = c;
  }
  return best || 'other';
}

// Resolve a category name to {color, icon} by reading the user-configured
// values from S.categories (Settings → Categories → color + icon picker).
// This is the loop: whatever the user picks in Settings shows up in the
// Ledger, Budget, Dashboard, Reports — anywhere a category is drawn.
//
// `color` is a hex string. `icon` is an icon-slug name that maps to a
// custom SVG in _CAT_ICONS (the SVG library below). Emoji is no longer
// used here — the SVG renderer takes over via _renderCatIcon().
//
// Color palette philosophy (extended this session):
//   Original 9 families: orange, blue, purple, violet, cyan, pink, pine,
//   ember, slate — each tied to a semantic role.
//   New 4 families added: amber (warm yellow for coffee/travel), teal
//   (between pine and cyan for fitness/auto-service), rose (between pink
//   and ember for beauty/charity), sienna (earthy brown for petcare/
//   childcare). 13 distinct colors is the practical ceiling at 7px dot
//   size — beyond that they blur together. Within a family, subcategories
//   share the color (food/groceries/fastfood all orange; phone/streaming
//   both cyan), distinguished by their icon, not their dot.
const _CAT_FALLBACK = {
  // Food family — orange (sub-cats share color, differ by icon)
  food:           { color:'#f97316', icon:'burger' },
  restaurant:     { color:'#f97316', icon:'cutlery' },
  fastfood:       { color:'#f97316', icon:'takeout' },
  groceries:      { color:'#f97316', icon:'cart-fill' },
  coffee:         { color:'#d97706', icon:'coffee' },        // amber — warm but distinct

  // Transport family — blue
  transportation: { color:'#3b82f6', icon:'car' },
  transport:      { color:'#3b82f6', icon:'car' },
  gas:            { color:'#3b82f6', icon:'gas-pump' },
  auto:           { color:'#3b82f6', icon:'car' },
  autoservice:    { color:'#0d9488', icon:'wrench' },        // teal — distinct from gas/car

  // Home / utilities — purple housing, cyan utils, cyan w/ icon for phone/streaming
  housing:        { color:'#a855f7', icon:'home' },
  homeservices:   { color:'#a855f7', icon:'home-wrench' },
  utilities:      { color:'#06b6d4', icon:'bolt' },
  phone:          { color:'#06b6d4', icon:'phone' },
  streaming:      { color:'#ec4899', icon:'play' },          // pink (with entertainment)

  // Shopping/personal — violet
  personal:       { color:'#8b5cf6', icon:'bag' },
  shopping:       { color:'#8b5cf6', icon:'cart' },

  // Entertainment — pink
  entertainment:  { color:'#ec4899', icon:'film' },
  hobby:          { color:'#e11d48', icon:'train' },         // rose — distinct from passive entertainment
  hobbies:        { color:'#e11d48', icon:'train' },

  // Income / savings — pine. Refund is income's return-trip sibling.
  income:         { color:'#16a34a', icon:'dollar' },
  refund:         { color:'#16a34a', icon:'dollar-arrow' },
  savings:        { color:'#16a34a', icon:'piggy' },

  // Healthcare / pets / debt — red family, but split: petcare uses sienna
  healthcare:     { color:'#dc2626', icon:'nurse-cap' },
  health:         { color:'#dc2626', icon:'nurse-cap' },
  debt:           { color:'#dc2626', icon:'credit-card' },
  petcare:        { color:'#92400e', icon:'paw' },           // sienna — earthy
  pet:            { color:'#92400e', icon:'paw' },
  childcare:      { color:'#92400e', icon:'baby' },          // sienna

  // Insurance — cyan, parallel to utilities
  insurance:      { color:'#0891b2', icon:'umbrella' },

  // Recurring — infinity sign signals "ongoing, no end"
  subscription:   { color:'#ec4899', icon:'infinity' },      // pink, family with streaming
  subscriptions:  { color:'#ec4899', icon:'infinity' },

  // Mid-value backlog
  travel:         { color:'#d97706', icon:'plane' },         // amber — wanderlust gold
  charity:        { color:'#e11d48', icon:'heart' },         // rose
  beauty:         { color:'#e11d48', icon:'scissors' },      // rose
  fitness:        { color:'#0d9488', icon:'dumbbell' },      // teal
  education:      { color:'#d97706', icon:'cap' },           // amber
  fees:           { color:'#94a3b8', icon:'receipt' },       // slate — quiet/dull intentionally
  taxes:          { color:'#94a3b8', icon:'document' },      // slate

  // Transfers / fallback
  transfer:       { color:'#94a3b8', icon:'arrows' },
  other:          { color:'#94a3b8', icon:'dot' },
};

