  if (/\bnationwide\s+pet\b|\bpetco\b|\bchewy\b|\bbanfield\b|\bvet (clinic|hospital|services)\b|\bveterinary\b|\bpetsmart\b|\bpet supplies\b|\bflying fur pets\b/.test(d)) return 'Pet Food / Supplies';
