function clientCategorize(desc, mcc) {
  // Item 55 C4: a code that names a leaf wins; a code that names Other lets the words decide
  if (mcc && CLIENT_MCC_CATEGORY_MAP[mcc] && CLIENT_MCC_CATEGORY_MAP[mcc] !== 'Other') return CLIENT_MCC_CATEGORY_MAP[mcc];
  return clientAutoCategory(desc);
}

const _CARD_TXN_SUFFIX_RE = /Date\s+(\d{2})\/(\d{2})\/(\d{2})\s+\d{6}\s+(\d{3,4})\s+Card\s+(\d{4})\s*$/;
const _CARD_ONLY_SUFFIX_RE = /Card\s+(\d{4})\s*$/;
const _DESC_PREFIX_RE = /^(?:Recurring\s+)?(?:Withdrawal|Deposit)\s+(?:CHECK CARD TRAN\s+|POS\s+#\d+\s+|at ATM\s+#\d+\s+|Adjustment Credit Voucher\s+)?/i;

function parseRichDescription(description='') {
  const desc = description.trim();
  const result = {};
  let remainder = desc;

  const m = desc.match(_CARD_TXN_SUFFIX_RE);
  if (m) {
    const [, mm, dd, yy, mcc, card] = m;
    result.true_date  = `20${yy}-${mm}-${dd}`;
    result.mcc        = mcc;
    result.card_last4 = card;
    remainder = desc.slice(0, m.index).trim();
  } else {
    const m2 = desc.match(_CARD_ONLY_SUFFIX_RE);
    if (m2) {
      result.card_last4 = m2[1];
      remainder = desc.slice(0, m2.index).trim();
    }
  }

  remainder = remainder.replace(_DESC_PREFIX_RE, '').trim();
  result.merchant = remainder || desc;
  return result;
}

function esc(s='') {
  return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/\x22/g,'&quot;');
}

// ─── DB write helpers (Phase 0B) ─────────────────────────────────────────────
// These functions sync in-memory S.* state to the database.
// Called alongside scheduleSave() so both the snapshot and DB stay consistent
// during the 0B→0C transition period.

// A budget row's amount for THIS month (BUDGET_MONTH_AMOUNT.md M1/M2): what the server sent as month_amount (a
// followed estimate, when it has a figure) or else the saved amount. Read-only: every write path sends e.amount, the
// saved figure, and nothing ever sends month_amount.
function _rowMonth(e) {
  const m = e && e.month_amount;
  return (m === null || m === undefined) ? (parseFloat(e && e.amount) || 0) : m;
}

async function _syncBudgetItemsToDb(type, items) {
  // Simple replace strategy: fetch existing IDs, delete removed ones, upsert remaining.
  // Budget lists are small (<20 items) so this is safe and avoids complex diffing.
  try {
    const existing = await API.get('/api/budget/items');
    const existingOfType = (Array.isArray(existing) ? existing : (existing.data||[]))
      .filter(i => i.type === type);
    const existingIds = new Set(existingOfType.map(i => i.id));
    const keepIds     = new Set(items.filter(i => i.id).map(i => i.id));

    // Delete removed items
    for (const id of existingIds) {
      if (!keepIds.has(id)) {
        await API.delete(`/api/budget/items/${id}`).catch(_gwErr('_syncBudgetItemsToDb'));
      }
    }

    // Upsert each item — if it has an id and exists, update; otherwise create
    for (const item of items) {
      // BudgetItem.category is a plain string column on the server (not a
      // category_id FK) — previously this sent `category_id`, a key the
      // server never read, so every budget line's category silently saved
      // as blank. category falls back to the item's name (the existing
      // convention — see line ~393/1453) so Budget vs Actual matching keeps
      // working even for ad-hoc rows that never had an explicit category.
      const payload = { type, name: item.name, amount: item.amount,
                        category: item.cat || item.name || '' };
      if (item.id && existingIds.has(item.id)) {
        await API.patch(`/api/budget/items/${item.id}`, payload).catch(_gwErr('_syncBudgetItemsToDb'));
      } else {
        const res = await API.post('/api/budget/items', payload).catch(_gwErrVal('_syncBudgetItemsToDb', null));
        // Stamp the DB id back onto the row so future syncs can update instead of create
        if (res?.id || res?.data?.id) {
          const dbId = res.id || res.data.id;
          const rows = document.querySelectorAll(
            `#${type === 'income' ? 'income' : 'expense'}Rows .budget-row`
          );
          for (const row of rows) {
            const inp = row.querySelector('input');
            if (inp && inp.value.trim() === item.name && !row.dataset.dbId) {
              row.dataset.dbId = dbId;
              break;
            }
          }
        }
      }
    }
  } catch(e) {
    // Non-fatal — snapshot still saves
    console.warn('Budget DB sync failed:', e.message);
  }
}

// ── Where a debt figure came from (V2) ──────────────────────────────────────
function _figureSourceLabel(source, statementAsOf) {
  if (source === 'statement') {
    const d = statementAsOf ? new Date(statementAsOf + 'T00:00:00') : null;
    return d && !isNaN(d) ? `from your ${d.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' })} statement` : 'from your statement';
  }
  if (source === 'user')       return 'you entered';
  if (source === 'calculated') return 'calculated by Groundwork';
  return '';
}
// "APR 22.9% (you entered) → 24.9% from this statement" — only for figures that changed.
function _statementFigureChanges(rec) {
  const was = s => s === 'user' ? ' (you entered)' : s === 'calculated' ? ' (calculated)' : '';
  const parts = [];
  if (rec.interest_rate != null && rec.previous_interest_rate != null
      && Math.abs(rec.interest_rate - rec.previous_interest_rate) > 1e-9)
    parts.push(`APR ${rec.previous_interest_rate}%${was(rec.previous_interest_rate_source)} → ${rec.interest_rate}%`);
  if (rec.minimum_payment != null && rec.previous_minimum_payment != null
      && Math.abs(rec.minimum_payment - rec.previous_minimum_payment) > 1e-9)
    parts.push(`minimum ${fmt(rec.previous_minimum_payment)}${was(rec.previous_minimum_payment_source)} → ${fmt(rec.minimum_payment)}`);
  return parts.length ? `From this statement: ${parts.join('; ')}` : '';
}

// ── The mortgage Net Worth counts, and where it lives (V9) ──────────────────
// Net Worth used to count a mortgage twice: assets held home *equity* (value
// minus mortgage) while liabilities added the mortgage again - so a $300,000
// home with a $187,000 mortgage came out at -$74,000 instead of +$113,000. And
// since V3 a mortgage can also be a debt on the Debt page, which Net Worth adds
// to its own mortgage field. Now assets hold the full home value, liabilities
// hold the mortgage once, and a Mortgage-type debt wins: while one exists, Net
// Worth uses its balance and the Net Worth field is not counted again. A
// mortgage entered as a plain Loan can't be recognised, so the field says so.
function _nwMortgageInfo(typedMortgage) {
  const typed = typedMortgage != null ? (parseFloat(typedMortgage) || 0) : (parseFloat(S.netWorth?.mortgage) || 0);
  const onDebtPage = S.debtCards.filter(c => !c.paidInFull && (c.debtType || 'credit') === 'mortgage' && _cardBal(c) > 0);
  if (onDebtPage.length) {
    return { amount: onDebtPage.reduce((s, c) => s + _cardBal(c), 0), fromDebtPage: true,
             counted: 0,   // already inside the Debt page's total
             names: onDebtPage.map(c => c.name || 'Mortgage') };
  }
  return { amount: typed, fromDebtPage: false, counted: typed, names: [] };
}

// ── Which plan a payoff month belongs to (V4) ───────────────────────────────
// A debt's payoff month depends on every other debt, the strategy and the payoff
// budget - it belongs to a scenario, not to the debt. The row's date comes from
// the same engine run as the debt-free date (rollover included), and wherever
// a month is shown the scenario is named with it.
function _planName() { return S.debtMethod === 'snowball' ? 'snowball' : 'avalanche'; }
function _planScenario() {
  const n = S.debtCards.filter(c => !c.paidInFull && _cardBal(c) > 0).length;
  return `your ${_planName()} plan: ${fmt(_getMonthlyBudget())}/mo across ${n} debt${n === 1 ? '' : 's'}`;
}
// The month (from now) this debt clears in the plan, or null. The engine keys its
// per-debt results by name, so two debts sharing a name get no date rather than
// possibly each other's.
function _planClearedMonth(c, plan) {
  if (!plan || !plan.clearedAt) return null;
  const name = c.name || 'Card';
  const same = S.debtCards.filter(d => !d.paidInFull && _cardBal(d) > 0 && (d.name || 'Card') === name);
  if (same.length !== 1) return null;
  const hit = plan.clearedAt[name];
  return hit && hit.month > 0 ? hit.month : null;
}

// ── Mortgage payments: principal & interest vs the rest (V3) ────────────────
// A mortgage payment usually includes escrow (property tax, insurance), PMI or
// fees, which leave the account but never reduce what's owed. With a balance,
// APR and maturity date, principal & interest is calculated the way the
// extra-payment tool already does it (exact for a fixed-rate, fully amortizing
// loan); projections use that. Without them, the whole payment is used, as
// before, and the page says so. Budgets and debt-to-income keep the whole
// payment - it's what actually leaves the account. Mirrors _mortgage_split in
// server.py.
function _monthsUntil(endDate) {
  if (!endDate) return 0;
  const e = new Date(endDate + 'T00:00:00');
  if (isNaN(e)) return 0;
  const t = new Date();
  return (e.getFullYear() - t.getFullYear()) * 12 + (e.getMonth() - t.getMonth());
}
function _mortgageSplit(c) {
  if (!c || (c.debtType || 'credit') !== 'mortgage') return null;
  const pay = _numOrNull(c.minimum), apr = _numOrNull(c.rate), bal = _cardBal(c);
  const months = _monthsUntil(c.endDate);
  if (pay === null) return { known: false };
  if (!(bal > 0) || apr === null || months < 1) return { known: false, payment: pay };
  const pi = _mortgageAmortMonthly(bal, apr, months);
  if (!(pi > 0) || pi >= pay) return { known: true, payment: pay, pi: pay, other: 0 };
  return { known: true, payment: pay, pi: Math.round(pi * 100) / 100,
           other: Math.round((pay - pi) * 100) / 100 };
}
// The part of a debt's payment that goes to principal & interest.
function _payoffPayment(c) {
  const s = _mortgageSplit(c);
  return s && s.known ? s.pi : (parseFloat(c && c.minimum) || 0);
}
function _nonPrincipalPart(c) {
  const s = _mortgageSplit(c);
  return s && s.known ? s.other : 0;
}
function _mortgageSplitHTML(c) {
  const s = _mortgageSplit(c);
  if (!s) return '';
  const box = t => `<div style="grid-column:1/-1;font-size:12px;line-height:1.55;color:var(--slate);margin-top:4px">${t}</div>`;
  if (!s.known) {
    return box(`Add the balance, APR and payoff / maturity date so Groundwork can separate principal &amp; interest from escrow. Until then, projections assume the whole payment reduces what you owe, which projects payoff early if part of it is escrow.`);
  }
  if (!(s.other > 0)) {
    return box(`Going by the balance, APR and maturity date, all of your ${fmt(s.payment)} payment goes to principal &amp; interest.`);
  }
  return box(`Of your ${fmt(s.payment)} payment, about <strong style="font-family:var(--font-mono);font-weight:500">${fmt(s.pi)}</strong> is principal &amp; interest, worked out from the balance, APR and maturity date as for a fixed-rate loan. The other <strong style="font-family:var(--font-mono);font-weight:500">${fmt(s.other)}</strong> likely covers escrow (property tax, insurance), PMI or fees; it doesn't reduce what you owe. Payoff projections use ${fmt(s.pi)}.`);
}

// ── Unknown debt figures (V6) ───────────────────────────────────────────────
function _isBlank(v) {
  return v === null || v === undefined || (typeof v === 'string' && v.trim() === '')
      || (typeof v === 'number' && isNaN(v));
}
function _numOrNull(v) {
  if (_isBlank(v)) return null;
  const n = parseFloat(v);
  return isNaN(n) ? null : n;
}
// What an active debt is missing. A lease has no balance or APR by design, so
// only its payment can be missing.
function _debtUnknowns(c) {
  if (!c || c.paidInFull) return [];
  const lease = (c.debtType || 'credit') === 'lease';
  const out = [];
  if (!lease && _isBlank(c.rate)) out.push('APR');
  if (!lease && _isBlank(c.currentBal) && _isBlank(c.beginBal)) out.push('balance');
  if ((c.debtType || 'credit') === 'mortgage' && _isBlank(c.endDate)) out.push('maturity date');   // V3
  if (_isBlank(c.minimum)) out.push(lease ? 'payment' : 'minimum payment');
  return out;
}
// One sentence for any projection that used a missing figure: which figures,
// and what the projection did in their place. '' when nothing is missing.
function _debtAssumptionNote(cards) {
  const missing = (cards || []).map(c => [c, _debtUnknowns(c)]).filter(([, u]) => u.length);
  if (!missing.length) return '';
  const list = missing.map(([c, u]) => `${esc(c.name || 'a card')}'s ${u.join(' and ')}`).join('; ');
  return `Not entered: ${list}. Projections treat a missing APR as 0% and a missing minimum as an estimate, and leave out a missing balance${
    missing.some(([, u]) => u.includes('maturity date')) ? '; a mortgage without a maturity date is assumed to put its whole payment toward what you owe' : ''}.`;
}

async function _syncDebtToDb(card) {
  // Upsert a single debt card to the DB.
  try {
    const payload = {
      name:               card.name,
      // V6: a field left blank is sent as null (unknown), never as 0 — 0% and
      // $0 are real values, and a zero written for "not entered" can't be told
      // apart from one afterwards.
      begin_balance:      _numOrNull(card.beginBal),
      current_balance:    (_isBlank(card.currentBal) && _isBlank(card.beginBal))
                            ? null : _cardBal(card),   // 0 is a real balance — never fall back to beginBal
      interest_rate:      _numOrNull(card.rate),
      minimum_payment:    _numOrNull(card.minimum),
      // V2: the server records these only when the value actually changes.
      interest_rate_source:   card.rateSource === 'calculated' ? 'calculated' : 'user',
      minimum_payment_source: card.minSource  === 'calculated' ? 'calculated' : 'user',
      due_day:            card.dueDay ? parseInt(card.dueDay) : null,
      start_date:         card.startDate || null,
      end_date:           card.endDate   || null,
      linked_account_id:  card.linkedAccountId || null,
      debt_type:          card.debtType || 'credit',
      // d21: this field was missing entirely — paidInFull lived only in memory
      // and every restart silently un-retired paid cards. Date doubles as the
      // flag (null = not paid) and the "paid · March 2026" label.
      paid_off_at:        card.paidInFull
                            ? (card.paidOffAt || new Date().toISOString().slice(0,10))
                            : null,
    };
    if (card._dbId) {
      const res = await API.patch(`/api/debt/${card._dbId}`, payload).catch(_gwErrVal('_syncDebtToDb', null));
      // After a link change, the server returns a fresh calculated_balance.
      // Update the card's local state so the cross-check renders correctly
      // without a full page reload.
      if (res?.calculated_balance !== undefined) {
        card.calculatedBalance = res.calculated_balance;
        card.linkedTxnCount   = res.linked_txn_count ?? null;
        _renderCardList();
      }
    } else {
      const res = await API.post('/api/debt', payload).catch(_gwErrVal('_syncDebtToDb', null));
      if (res?.id || res?.data?.id) {
        card._dbId = res.id || res.data.id;
        card.calculatedBalance = res.calculated_balance ?? null;
        card.linkedTxnCount   = res.linked_txn_count ?? null;
        _renderCardList();
      }
    }
  } catch(e) {
    console.warn('Debt DB sync failed:', e.message);
  }
}

async function _deleteDebtFromDb(dbId) {
  if (!dbId) return;
  await API.delete(`/api/debt/${dbId}`).catch(_gwErr('_deleteDebtFromDb'));
}

async function _syncAchievementToDb(id, section) {
  // Award an achievement in the DB. Idempotent.
  await API.post('/api/achievements', {
    achievement_id: id,
    section: section || 'general',
  }).catch(_gwErr('_syncAchievementToDb'));
}


async function _syncBYBItemToDb(item) {
  // Add a BYB item to the DB. Returns the DB id.
  // The wizard (_bybCommit) always computes decision/dti/payoff-impact —
  // these used to get silently dropped here (server had no columns for
  // them either), which made every saved item render as "walked away"
  // regardless of the real choice. See BYBItem's docstring in
  // core/database.py.
  try {
    const res = await API.post('/api/byb', {
      type:               item.type,
      name:               item.name,
      category:           item.category,
      monthly:            item.monthly,
      replacing:          item.replacing || null,
      replacing_name:     item.replacing_name || null,
      replacing_id:       item.replacing_id ?? null,
      decision:           item.decision ?? null,
      dti_before:         item.dti_before,
      dti_after:          item.dti_after,
      payoff_impact:      item.payoff_impact,
      whats_left_before:  item.whats_left_before,
      whats_left_after:   item.whats_left_after,
    });
    const d = res?.data || res;
    return d?.id || null;
  } catch(e) {
    console.warn('BYB DB sync failed:', e.message);
    return null;
  }
}

async function _deleteBYBItemFromDb(dbId) {
  if (!dbId) return;
  await API.delete(`/api/byb/${dbId}`).catch(_gwErr('_deleteBYBItemFromDb'));
}


// ─── Budget ──────────────────────────────────────────────────────────────

// Sum of minimum payments across debts that aren't paid off — the "required"
// debt obligation each month, shrinking automatically as debts get eliminated.


// ── Budget month state ────────────────────────────────────────────────────────
// Tracks which month the Budget page is showing. Initialized to current month.
// Format: 'YYYY-MM'
// Current month's scheduler target card id — set in renderBudget, read in _budgetRenderDebtRow
let _budgetSchedulerTargetId = null;

// CFPB guidance URL for the can't-pay shortfall banner (Budget Blueprint §19.9).
// U.S. government page — stable. Update this constant if CFPB ever changes the URL.
const CFPB_CANT_PAY_URL = 'https://www.consumerfinance.gov/ask-cfpb/what-should-i-do-if-i-cant-pay-my-credit-card-bills-en-1697/';

let _budgetMonthKey = (() => {
  const n = new Date();
  return `${n.getFullYear()}-${String(n.getMonth()+1).padStart(2,'0')}`;
})();

function _budgetMonthLabel(key) {
  if (!key) return '—';
  const [y, m] = key.split('-').map(Number);
  return new Date(y, m-1, 1).toLocaleDateString('en-US', { month:'long', year:'numeric' });
}

function budgetMonthStep(delta) {
  const [y, m] = _budgetMonthKey.split('-').map(Number);
  const d = new Date(y, m-1+delta, 1);
  _budgetMonthKey = `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;
  renderBudget();
}

// ── Budget-CP0: Strip, reframe, rebuild the spine ─────────────────────────────
// Blueprint §16 CP0 deliverable:
//   - No dead UI (sbState, savings slider, check-in, reset, streaks)
//   - Single forward spine: Income → Expenses → Debt → What's Left
//   - Pamphlet Standard: Playfair title, page-head with period switcher
//   - Bloom-pattern editing on all rows
//   - Per-debt commitment rows with basic bloom
//   - Static What's Left card with realism sentence
// CP1 adds: live spend from imports. CP2 adds: projections.


// ── Grouped expense rendering ─────────────────────────────────────────────────
// Groups expense rows by parent category with collapsible headers.
// Shows a parent total row + progress bar, then child rows underneath.

function _budgetRenderGroupedExpenses() {
  const cont = g('budgetExpenseRows');
  if (!cont) return;

  if (S.expenses.length === 0) return; // empty state already handled

  // If categories not yet loaded, fall back to simple list render
  if (!S.categories || S.categories.length === 0) {
    S.expenses.forEach((exp, idx) => _budgetRenderExpenseRow(exp, idx));
    return;
  }

  // Group expenses by parent category
  const groups = {};   // parentName → [expenses with index]
  const noGroup = [];  // expenses with no matching parent

  S.expenses.forEach((exp, idx) => {
    const catName = exp.cat || exp.name || 'Other';
    const parentName = _catIsChild(catName) ? _catParentName(catName) : catName;
    const hasChildren = _catIsParent(catName);

    if (hasChildren || _catIsChild(catName)) {
      if (!groups[parentName]) groups[parentName] = [];
      groups[parentName].push({ exp, idx });
    } else {
      noGroup.push({ exp, idx });
    }
  });

  // Render ungrouped first (simple expenses with no parent/child)
  noGroup.forEach(({ exp, idx }) => _budgetRenderExpenseRow(exp, idx));

  // Render grouped expenses with collapsible parent headers
  Object.entries(groups).forEach(([parentName, items]) => {
    const totalBudget = items.reduce((s, { exp }) => s + (parseFloat(exp.amount) || 0), 0);
    const totalSpent  = _catSpentInMonth(parentName, _budgetMonthKey);
    const pct = totalBudget > 0 ? Math.min(150, Math.round((totalSpent / totalBudget) * 100)) : 0;
    const barColor = pct >= 100 ? 'var(--ember)' : pct >= 85 ? 'var(--gold)' : 'var(--pine)';
    // d21: was `parentCat?.icon || 'folder'` passed raw into _renderCatIcon,
    // which bypassed _categoryStyle's unknown-slug guard. Insurance is seeded
    // with icon='shield' — a slug the SVG library doesn't have — so the group
    // header printed the literal word "shield". _categoryStyle swaps unknown
    // saved icons for the canonical fallback (umbrella, for insurance).
    const pcs   = _categoryStyle(parentName);
    const color = pcs.color;
    const isExpanded = !_budgetCollapsedGroups.has(parentName);

    // Group header row
    const header = document.createElement('div');
    header.className = 'budget-group-header';
    header.dataset.group = parentName;
    header.style.cssText = `
      padding:10px 0 8px;
      border-bottom:${isExpanded ? '0' : '1px solid var(--steel)'};
      cursor:pointer;
      user-select:none;
    `;
    header.innerHTML = `
      <div style="display:flex;align-items:center;gap:10px">
        <span style="font-size:16px;width:28px;text-align:center;color:${color}">
          ${_renderCatIcon(pcs.icon, color, 16)}
        </span>
        <div style="flex:1;min-width:0">
          <div style="display:flex;align-items:baseline;justify-content:space-between;gap:8px;margin-bottom:4px">
            <span style="font-size:13px;font-weight:600;color:var(--ink)">${esc(parentName)}</span>
            <div style="display:flex;gap:10px;align-items:baseline;flex-shrink:0">
              ${totalSpent > 0 ? `<span style="font-family:var(--font-mono);font-size:11px;color:var(--slate)">${fmt(totalSpent)} spent</span>` : ''}
              <span style="font-family:var(--font-mono);font-size:13px;color:var(--ink)">${fmt(totalBudget)}</span>
              <span style="font-size:11px;color:var(--slate-2)">${isExpanded ? '▴' : '▾'} ${items.length}</span>
            </div>
          </div>
          ${totalBudget > 0 ? `
          <div style="height:3px;background:var(--steel);border-radius:2px;overflow:hidden">
            <div style="height:100%;width:${Math.min(100,pct)}%;background:${barColor};border-radius:2px;transition:width .4s"></div>
          </div>` : ''}
        </div>
      </div>
    `;
    header.onclick = () => _budgetToggleGroup(parentName);
    cont.appendChild(header);

    // Child expense rows (collapsible)
    const childCont = document.createElement('div');
    childCont.className = 'budget-group-children';
    childCont.dataset.groupChildren = parentName;
    childCont.style.cssText = `
      padding-left:38px;
      display:${isExpanded ? 'block' : 'none'};
      border-bottom:1px solid var(--steel);
      padding-bottom:4px;
    `;
    cont.appendChild(childCont);

    // Render child rows into child container
    const savedCont = g('budgetExpenseRows');
    // Temporarily swap container for child rows
    items.forEach(({ exp, idx }) => {
      const row = _buildBudgetExpenseRowEl(exp, idx);
      row.style.paddingLeft = '0';
      row.style.borderBottom = '0.5px solid var(--steel-2)';
      childCont.appendChild(row);
    });
  });
}

// Set of collapsed group names (persists during session)
const _budgetCollapsedGroups = new Set();

function _budgetToggleGroup(parentName) {
  if (_budgetCollapsedGroups.has(parentName)) {
    _budgetCollapsedGroups.delete(parentName);
  } else {
    _budgetCollapsedGroups.add(parentName);
  }
  // Re-render just the group — find header and children
  const cont = g('budgetExpenseRows');
  if (!cont) return;
  const header = cont.querySelector(`[data-group="${parentName}"]`);
  const children = cont.querySelector(`[data-group-children="${parentName}"]`);
  if (!header || !children) return;

  const isExpanded = !_budgetCollapsedGroups.has(parentName);
  const chevron = header.querySelector('.group-chevron');
  if (chevron) chevron.textContent = isExpanded ? '▴' : '▾';
  children.style.display = isExpanded ? 'block' : 'none';
  header.style.borderBottom = isExpanded ? '0' : '1px solid var(--steel)';
}

// Build a single expense row element (extracted from _budgetRenderExpenseRow)
function _buildBudgetExpenseRowEl(exp, idx) {
  const cs      = _categoryStyle(exp.cat || exp.name || 'Other');
  const budget  = parseFloat(exp.amount) || 0;
  const catName = exp.cat || exp.name || 'Other';
  const proj    = _budgetProjection(catName, budget);
  const spent   = proj ? proj.spent : _budgetSpentForCat(catName);
  const barPct  = budget > 0 ? Math.min(150, Math.round((proj ? proj.pct : spent / budget) * 100)) : 0;
  const barColor = barPct >= 100 ? 'var(--ember)' : barPct >= 85 ? 'var(--gold)' : 'var(--pine)';

  let projLabel = '';
  if (proj) {
    const trendIcon = proj.trending === 'over' ? '↑' : proj.trending === 'warn' ? '↗' : '';
    const trendClr  = proj.trending === 'over' ? 'var(--ember)' : proj.trending === 'warn' ? 'var(--gold)' : 'var(--pine)';
    projLabel = `<span style="font-family:var(--font-mono);font-size:11px;color:${trendClr}">${trendIcon} ${fmt(proj.projected)} proj.</span>`;
  }

  const row = document.createElement('div');
  row.className = 'ledger-row';
  row.dataset.expenseIdx = idx;
  row.style.cssText = 'padding:8px 0;border-bottom:0.5px solid var(--steel-2);cursor:pointer';
  const iconBg     = _catTint(cs.color);
  const iconBorder = _catTintBorder(cs.color);
  row.innerHTML = `
    <div style="display:flex;align-items:center;gap:10px">
      <div><div class="cat-icon" style="background:${iconBg};border-color:${iconBorder};color:${cs.color};width:24px;height:24px;font-size:12px">${_renderCatIcon(cs.icon, cs.color, 14)}</div></div>
      <div style="flex:1;min-width:0">
        <div style="display:flex;align-items:baseline;justify-content:space-between;gap:8px;margin-bottom:4px">
          <span style="font-size:12px;font-weight:500;color:var(--ink)">${esc(exp.name||catName)}</span>
          <div style="display:flex;gap:8px;align-items:baseline;flex-shrink:0">
            ${spent > 0 ? `<span style="font-family:var(--font-mono);font-size:11px;color:var(--slate)">${fmt(spent)}</span>` : ''}
            ${projLabel}
            <span style="font-family:var(--font-mono);font-size:12px;color:var(--ink)">${fmt(budget)}</span>
          </div>
        </div>
        ${budget > 0 ? `
        <div style="height:3px;background:var(--steel);border-radius:2px;overflow:hidden">
          <div style="height:100%;width:${Math.min(100,barPct)}%;background:${barColor};border-radius:2px"></div>
        </div>` : ''}
        ${_utilityBenchmarkNote(catName)}
      </div>
    </div>
  `;
  row.onclick = () => _budgetOpenExpenseBloom(row, exp, idx);
  return row;
}

// ── Sinking Funds in Budget ───────────────────────────────────────────────────
// Shows sinking fund progress below expenses as a separate section.
// Monthly contribution counts toward "Out" in the budget header.
// Money sits in the user's checking/savings — Groundwork tracks it mentally.

async function _budgetRenderSinkingFundsSection() {
  // Check if sinking funds section exists in the budget template
  let section = g('budgetSinkingFundsCard');
  if (!section) {
    // Insert after the debt card
    const debtCard = g('budgetDebtCard');
    if (!debtCard) return;
    section = document.createElement('div');
    section.id = 'budgetSinkingFundsCard';
    section.className = 'card mb-4';
    debtCard.insertAdjacentElement('afterend', section);
  }

  const funds = (_sinkingFunds || []).filter(f => f.is_active !== false);

  if (!funds.length) {
    section.innerHTML = `
      <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:12px">
        <div>
          <div class="card-label" style="margin:0">Saving toward</div>
          <div style="font-size:12px;color:var(--slate);margin-top:3px">Sinking funds — Christmas, car repairs, vacation, anything annual.</div>
        </div>
        <button class="btn-add" style="margin:0" onclick="showView('budget');_budgetShowSinkingFundAdd()">+ Add fund</button>
      </div>
      <div style="font-size:12px;color:var(--slate);padding:8px 0">
        No sinking funds yet. Add one and the monthly contribution shows up here as a budget line.
      </div>`;
    return;
  }

  // Pace confidence, Historian-backed (mirrors net worth/investments) —
  // real contribution-vs-monthly_contribution variance over time.
  const confResults = await Promise.all(funds.map(f =>
    API.get(`/api/sinking-funds/${f.id}/confidence`).catch(() => ({confidence_pct: null}))
  ));

  const rows = funds.map((f, idx) => {
    const target  = parseFloat(f.target_amount) || 0;
    const saved   = parseFloat(f.current_amount) || 0;
    const contrib = parseFloat(f.monthly_contribution) || _sfMonthlyNeeded(f);
    const pct     = target > 0 ? Math.min(100, (saved / target) * 100) : 0;
    const filled  = saved >= target && target > 0;
    const barColor = filled ? 'var(--pine)' : pct >= 60 ? 'var(--pine)' : pct >= 30 ? 'var(--gold)' : 'var(--ember)';
    const conf     = confResults[idx];
    const confPct  = conf && conf.confidence_pct;
    const confBadge = (confPct != null)
      ? `<span style="font-size:10px;font-family:var(--font-mono);color:${confPct>=70?'var(--pine)':confPct>=40?'var(--gold)':'var(--ember)'}" title="${esc(conf.reasoning||'')}">${confPct}% on pace</span>`
      : '';

    let deadline = '';
    if (f.deadline) {
      const d     = new Date(f.deadline + 'T00:00:00');
      const today = new Date();
      const months = Math.max(0, (d.getFullYear()-today.getFullYear())*12+(d.getMonth()-today.getMonth()));
      deadline = months <= 1 ? `<span style="color:var(--ember)">Due soon</span>`
               : `due ${d.toLocaleDateString('en-US',{month:'short',year:'numeric'})}`;
    }

    return `
      <div data-fund-id="${f.id}" style="padding:10px 0;border-bottom:0.5px solid var(--steel-2)">
        <div style="display:flex;align-items:center;gap:10px">
          <div style="font-size:18px;width:28px;text-align:center">🎯</div>
          <div style="flex:1;min-width:0">
            <div style="display:flex;align-items:baseline;justify-content:space-between;gap:8px;margin-bottom:4px">
              <span style="font-size:13px;font-weight:500;color:var(--ink)">${esc(f.name)}</span>
              <div style="display:flex;gap:8px;align-items:baseline;flex-shrink:0">
                ${confBadge}
                <span style="font-family:var(--font-mono);font-size:11px;color:var(--slate)">${fmt(saved)} saved</span>
                <span style="font-family:var(--font-mono);font-size:13px;color:var(--pine)">${fmt(contrib)}/mo</span>
              </div>
            </div>
            <div style="height:4px;background:var(--steel);border-radius:2px;overflow:hidden;margin-bottom:3px">
              <div style="height:100%;width:${pct.toFixed(1)}%;background:${barColor};border-radius:2px;transition:width .4s"></div>
            </div>
            <div style="display:flex;justify-content:space-between;font-size:10px;color:var(--slate-2)">
              <span>${Math.round(pct)}% of ${fmt(target)} ${filled ? '✓ Funded' : ''}</span>
              <span>${deadline}</span>
            </div>
          </div>
        </div>
      </div>`;
  }).join('');

  const totalContrib = funds.reduce((s, f) => s + (parseFloat(f.monthly_contribution) || _sfMonthlyNeeded(f)), 0);

  section.innerHTML = `
    <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:12px">
      <div>
        <div class="card-label" style="margin:0">Saving toward</div>
        <div style="font-size:12px;color:var(--slate);margin-top:2px">
          ${fmt(totalContrib)}/month set aside across ${funds.length} fund${funds.length!==1?'s':''}
        </div>
      </div>
      <button class="btn-add" style="margin:0" onclick="_budgetShowSinkingFundAdd()">+ Add fund</button>
    </div>
    ${rows}`;

  _sfRenderAdvisorEntry(funds);
}

// Savings-goals advisor — mirrors _invRenderAdvisorEntry/_debtRenderAdvisorTab's
// one-time "Generate" entry point pattern, delegating to the shared
// _rcAnalyzeWithAI flow. dataLines only restate numbers already shown in
// the sinking-fund rows above.
let _sfAdvisorAICache = false;

function _sfRenderAdvisorEntry(funds) {
  const debtCard = g('budgetDebtCard');
  if (!debtCard) return;
  let card = g('budgetSavingsAdvisorCard');
  if (!funds.length) { card?.remove(); return; }
  if (!card) {
    card = document.createElement('div');
    card.id = 'budgetSavingsAdvisorCard';
    card.className = 'card mb-4';
    g('budgetSinkingFundsCard')?.insertAdjacentElement('afterend', card);
  }
  if (_sfAdvisorAICache || g('sfAdvisorAIEntry')) return;  // already generated or entry already shown

  card.innerHTML = `
    <div id="sfAdvisorAIEntry" style="display:flex;align-items:center;justify-content:space-between;gap:16px">
      <div>
        <div style="font-size:13px;font-weight:500;color:var(--ink)">Groundwork's savings-goals analysis</div>
        <div style="font-size:12px;color:var(--slate);margin-top:2px">AI-powered read of your sinking funds' pace toward their targets</div>
      </div>
      <button onclick="_sfLaunchAdvisorAI()"
        style="font-size:12px;padding:7px 16px;background:var(--pine);color:#fff;border:none;border-radius:var(--r-sm);cursor:pointer;white-space:nowrap;font-weight:500">
        ✦ Generate
      </button>
    </div>`;
}

async function _sfLaunchAdvisorAI() {
  g('sfAdvisorAIEntry')?.remove();
  const funds = (_sinkingFunds || []).filter(f => f.is_active !== false);
  if (!funds.length) return;

  const fundLines = funds.map(f => {
    const target  = parseFloat(f.target_amount) || 0;
    const saved   = parseFloat(f.current_amount) || 0;
    const contrib = parseFloat(f.monthly_contribution) || _sfMonthlyNeeded(f);
    const pct     = target > 0 ? Math.min(100, (saved/target)*100) : 0;
    return `${f.name}: ${fmt(saved)} of ${fmt(target)} (${pct.toFixed(0)}%), ${fmt(contrib)}/mo${f.deadline ? `, due ${f.deadline}` : ''}`;
  });

  const dataLines = [
    `Total set aside monthly: ${fmt(funds.reduce((s,f)=>s+(parseFloat(f.monthly_contribution)||_sfMonthlyNeeded(f)),0))}`,
    `Fund count: ${funds.length}`,
    '---',
    'FUNDS:',
    ...fundLines,
  ];

  const buildPrompt = (profileCtx, stageCtx) => [
    profileCtx || '',
    `SAVINGS GOALS PICTURE — ${new Date().toLocaleDateString('en-US',{month:'long',year:'numeric'})}`,
    '',
    dataLines.join('\n'),
    stageCtx?.stageNote || '',
    '',
    'Rules: Lead with the fund closest to its deadline or furthest behind, stated as a plain fact from the numbers above. Name dollar amounts. Never invent a number. 2-3 short paragraphs. No headers, no bullets.',
  ].filter(Boolean).join('\n').trim();

  const target = g('budgetSavingsAdvisorCard');
  if (target) {
    await _rcAnalyzeWithAI('savings_goals_advisor', dataLines, buildPrompt, target);
    _sfAdvisorAICache = true;
  }
}

function _sfMonthlyNeeded(fund) {
  if (!fund) return 0;
  const contrib = parseFloat(fund.monthly_contribution || fund.monthlyContrib) || 0;
  if (!fund.deadline) return contrib;
  const today   = new Date();
  const d       = new Date(fund.deadline + 'T00:00:00');
  const months  = Math.max(1, (d.getFullYear()-today.getFullYear())*12+(d.getMonth()-today.getMonth()));
  const target  = parseFloat(fund.target_amount || fund.target) || 0;
  const saved   = parseFloat(fund.current_amount || fund.balance) || 0;
  const remaining = Math.max(0, target - saved);
  return contrib || Math.ceil(remaining / months);
}

function _budgetShowSinkingFundAdd() {
  // Navigate to Budget page sinking funds tab
  showView('budget');
  setTimeout(() => {
    const addBtn = document.querySelector('[onclick*="addSinkingFund"], [onclick*="showAddSinkingFund"]');
    if (addBtn) addBtn.click();
    else showToast('Add a sinking fund', 'Go to Budget → Sinking Funds to add one', 'info');
  }, 100);
}


// Real utility-price benchmarks (natural gas $/MCF, electricity cents/kWh)
// for the Electric/Gas budget rows — mirrors the Trip Planner's Phase 5B
// exogenous-fact pattern: a distinct, labeled real-world figure beside the
// user's own budgeted number, never presented as their exact bill rate.
let _naturalGasPriceData = null;  // { price, period, area_name, live } from /api/utility/natural-gas-price
let _electricityPriceData = null; // { price, period, area_name, live } from /api/utility/electricity-price

async function _loadUtilityPrices() {
  if (_naturalGasPriceData || _electricityPriceData) return;  // already loaded this session
  try {
    const [ng, elec] = await Promise.all([
      API.get('/api/utility/natural-gas-price'),
      API.get('/api/utility/electricity-price'),
    ]);
    _naturalGasPriceData = ng;
    _electricityPriceData = elec;
  } catch (e) {
    _gwErr('_loadUtilityPrices')(e);
    return;
  }
  // Full re-render, not just _budgetRenderGroupedExpenses() — that function
  // appends into #budgetExpenseRows without clearing it first (it relies on
  // renderBudget()'s wholesale innerHTML replace having just emptied the
  // container), so calling it alone here would duplicate every row.
  if (g('budgetContent')) renderBudget();
  if (g('rcCatSelect')) _rcUpdateCategoryDeepDive();
}

// Renders the small "national/state average" line for the Electric and Gas
// rows specifically — '' for every other category. Dollars-and-cents only,
// clearly labeled as a benchmark, never a claim about the user's own rate.
// Shared by the Budget page's benchmark note and the Reports narratives —
// one source of truth for "is this category's cost driven by price, not
// usage" so a rising Electric/Gas/fuel bill isn't blamed on the user when
// the real cause is the commodity price itself.
function _utilityPriceContext(catName) {
  let data, unit, label, priceFmt;
  if (catName === 'Gas')          { data = _naturalGasPriceData; unit = '/MCF'; label = 'natural gas'; priceFmt = p => `$${p.toFixed(2)}/MCF`; }
  else if (catName === 'Electric') { data = _electricityPriceData; unit = 'kWh';  label = 'electricity'; priceFmt = p => `${p}¢/kWh`; }
  else if (catName === 'Gas / Fuel') { data = _gasPriceData; unit = '/gal'; label = 'gasoline'; priceFmt = p => `$${p.toFixed(2)}/gal`; }
  else return null;
  if (!data || !data.live) return null;
  return {
    label,
    areaLabel: data.area_name || 'U.S.',
    priceStr: priceFmt(data.price),
    period: data.period || '',
  };
}

function _utilityBenchmarkNote(catName) {
  const ctx = _utilityPriceContext(catName);
  if (!ctx) return '';
  return `<div style="margin-top:6px;font-size:10px;color:var(--slate-2)">
    ⛽ ${esc(ctx.areaLabel)} avg ${ctx.label} price${ctx.period ? ` (${esc(ctx.period)})` : ''}: <strong style="color:var(--slate)">${esc(ctx.priceStr)}</strong> · source: EIA
  </div>`;
}

// Plain-sentence version for AI report prompts — lets the model correctly
// attribute a cost swing to price vs. usage instead of guessing.
function _utilityPriceSentence(catName) {
  const ctx = _utilityPriceContext(catName);
  if (!ctx) return '';
  return `${ctx.areaLabel} avg ${ctx.label} price${ctx.period ? ` as of ${ctx.period}` : ''}: ${ctx.priceStr} (source: EIA) — a change here reflects market price, not the household's usage.`;
}

// Reports let the user drill into a PARENT category (e.g. "Utilities"),
// which rolls up children like Electric/Gas — so the direct name check in
// _utilityPriceContext alone would miss it. Returns the child category
// name(s), if any, that a price benchmark actually applies to for the
// category currently selected in a report.
function _utilityRelevantCategoryNames(catName) {
  if (_utilityPriceContext(catName)) return [catName];
  if (typeof _catIsParent === 'function' && _catIsParent(catName)) {
    return _catChildrenOf(catName).map(c => c.name).filter(n => _utilityPriceContext(n));
  }
  return [];
}

function renderBudget() {
  const cont = g('budgetContent');
  if (!cont) return;
  _loadUtilityPrices();

  const totalIncome = S.incomes.reduce((s,i) => s + i.amount, 0);
  const totalExpenses = S.expenses.reduce((s,e) => s + _rowMonth(e), 0);
  const _today = new Date().toISOString().slice(0, 10);
  const activeDebts = S.debtCards.filter(c => !c.paidInFull && !(c.endDate && c.endDate < _today));
  const totalDebt = activeDebts.reduce((s,c) => {
    const pmt = parseFloat(c.minimum) || 0;
    return s + pmt;
  }, 0);
  // totalSinking must be defined here — it's referenced in the template literal below
  const totalSinking = (_sinkingFunds || []).reduce((s,f) => s + (parseFloat(f.monthlyContrib)||0), 0);
  const totalOut = totalExpenses + totalDebt + totalSinking;
  const left = totalIncome - totalOut;

  cont.innerHTML = `
    <div class="ledger-page-head">
      <div>
        <h1>Budget</h1>
        <div class="sub" id="budgetSub">${_budgetMonthLabel(_budgetMonthKey)}</div>
      </div>
      <div class="ph-right">
        <div class="ledger-head-stat">
          <div class="lbl">Income</div>
          <div class="val pos" id="bhs-income">${totalIncome > 0 ? fmt(totalIncome) : '—'}</div>
        </div>
        <div class="ledger-head-stat">
          <div class="lbl">Out</div>
          <div class="val neg" id="bhs-out">${totalOut > 0 ? fmt(totalOut) : '—'}</div>
        </div>
        <div class="ledger-head-stat">
          <div class="lbl">Left</div>
          <div class="val ${left >= 0 ? 'pos' : 'neg'}" id="bhs-left">${totalIncome > 0 ? fmt(left) : '—'}</div>
        </div>
      </div>
    </div>

    <!-- Period switcher -->
    <div class="ledger-bar" style="margin-bottom:28px">
      <div class="ledger-bar-left">
        <div class="month-nav">
          <button class="month-arrow" onclick="budgetMonthStep(-1)" title="Previous month">‹</button>
          <span class="month-label" id="budgetMonthLabel">${_budgetMonthLabel(_budgetMonthKey)}</span>
          <button class="month-arrow" onclick="budgetMonthStep(1)" title="Next month">›</button>
        </div>
      </div>
    </div>

    <!-- INCOME SECTION -->
    <div class="card mb-4" id="budgetIncomeCard">
      <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:16px">
        <div class="card-label" style="margin:0">Income</div>
        <button class="btn-add" style="margin:0" onclick="_budgetAddIncomeBloom()">+ Add source</button>
      </div>
      <div id="budgetIncomeRows">
        ${S.incomes.length === 0 ? _budgetEmptyState('No income sources yet.', 'Add your take-home pay to get started.') : ''}
      </div>
      <div id="budgetIncomeLedgerNote" style="display:none;font-size:12px;color:var(--slate);margin-top:10px;font-family:var(--font-mono)"></div>
    </div>

    <!-- EXPENSES SECTION -->
    <div class="card mb-4" id="budgetExpensesCard">
      <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:16px">
        <div class="card-label" style="margin:0">Expenses</div>
        <button class="btn-add" style="margin:0" onclick="_budgetAddExpenseBloom()">+ Add expense</button>
      </div>
      <div id="budgetExpenseRows">
        ${S.expenses.length === 0 ? _budgetEmptyState('No expenses budgeted yet.', 'Add your fixed and variable monthly expenses.') : ''}
      </div>
      ${_budgetDataMonths() >= 3 ? `
      <div style="margin-top:12px;padding-top:10px;border-top:1px solid var(--steel)">
        <button class="btn btn-sm btn-ghost" onclick="_budgetPrefillFromHistory()" style="font-size:12px;color:var(--slate)">
          ↻ Pre-fill from my last 6 months →
        </button>
      </div>` : ''}
    </div>

    <!-- DEBT PAYMENTS SECTION -->
    <div class="card mb-4" id="budgetDebtCard">
      <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:${activeDebts.length ? 16 : 0}px">
        <div>
          <div class="card-label" style="margin:0">Debt Payments</div>
          ${activeDebts.length ? '' : '<div style="font-size:12px;color:var(--slate);margin-top:3px">Commitments this month.</div>'}
        </div>
        <button class="btn-add" style="margin:0" onclick="showView('debt')" title="Manage debt accounts in Debt Payoff">Manage debts ›</button>
      </div>
      <div id="budgetDebtRows">
        ${activeDebts.length === 0 ? _budgetEmptyState('No active debt accounts.', 'Add debt accounts in the Debt Payoff section.') : ''}
      </div>
      <!-- CP4: summary line + utilization + waterfall — populated after rows render -->
      <div id="budgetDebtSummary" style="display:none;margin-top:14px;padding-top:12px;border-top:1px solid var(--steel)"></div>
      <div id="budgetDebtWaterfall" style="display:none;margin-top:10px"></div>
    </div>

    <!-- WHAT'S LEFT CARD -->
    <div class="card" id="budgetWhatsLeftCard" style="border-color:${left >= 0 ? 'var(--pine-border)' : 'var(--ember-border)'};background:${left >= 0 ? 'var(--pine-bg)' : 'var(--ember-bg)'}">
      <div class="card-label" style="margin-bottom:16px;color:${left >= 0 ? 'var(--pine)' : 'var(--ember)'}">What's Left</div>
      <div style="display:flex;flex-direction:column;gap:10px">
        <div style="display:flex;justify-content:space-between;align-items:center;font-size:13px">
          <span style="color:var(--slate)">Income</span>
          <span style="font-family:var(--font-mono);color:var(--pine)" id="wl-income">${fmt(totalIncome)}</span>
        </div>
        <div style="display:flex;justify-content:space-between;align-items:center;font-size:13px">
          <span style="color:var(--slate)">Expenses</span>
          <span style="font-family:var(--font-mono);color:var(--ember)" id="wl-expenses">− ${fmt(totalExpenses)}</span>
        </div>
        <div style="display:flex;justify-content:space-between;align-items:center;font-size:13px">
          <span style="color:var(--slate)">Debt payments</span>
          <span style="font-family:var(--font-mono);color:var(--ember)" id="wl-debt">− ${fmt(totalDebt)}</span>
        </div>
        ${totalSinking > 0 ? `
        <div style="display:flex;justify-content:space-between;align-items:center;font-size:13px">
          <span style="color:var(--slate)">Sinking funds</span>
          <span style="font-family:var(--font-mono);color:var(--ember)" id="wl-sinking">− ${fmt(totalSinking)}</span>
        </div>` : '<div id="wl-sinking" style="display:none"></div>'}
        <div style="border-top:1px solid var(--steel);padding-top:12px;display:flex;justify-content:space-between;align-items:center">
          <span style="font-size:14px;font-weight:600;color:var(--ink)">Left to save or spend</span>
          <div style="text-align:right">
            <div style="font-family:var(--font-mono);font-size:18px;font-weight:600;color:var(--ink)" id="wl-left">${fmt(left)}</div>
            <div style="font-size:10px;color:var(--slate-2);margin-top:1px">planned</div>
          </div>
        </div>
        <!-- CP2: projected left — hidden until projection engine has data -->
        <div id="wl-left-projected" style="display:none;justify-content:space-between;align-items:center;padding-top:6px">
          <span style="font-size:12px;color:var(--slate)">Projected at this rate</span>
          <div style="text-align:right">
            <span class="wl-proj-val" style="font-family:var(--font-mono);font-size:15px;font-weight:600"></span>
          </div>
        </div>
      </div>
      <div id="budgetRealismSentence" style="margin-top:14px;font-size:12px;color:var(--slate);line-height:1.5"></div>
      <div id="budgetConsequence"     style="margin-top:6px;font-size:12px;color:var(--slate);line-height:1.5"></div>
      <!-- B0d: Two-scenario comparison (current payments vs. minimums-only) -->
      <div id="budgetTwoScenario"     style="margin-top:6px"></div>
    </div>

    <!-- Cross-link to Reports -->
    <div style="text-align:center;margin-top:20px;font-size:12px;color:var(--slate-2)">
      Want to see where the money actually went?
      <span onclick="showView('reports')"
        style="color:var(--slate);cursor:pointer;text-decoration:underline;text-underline-offset:2px">
        Monthly report and more →
      </span>
    </div>
  `;

  // Render income rows
  S.incomes.forEach((inc, idx) => _budgetRenderIncomeRow(inc, idx));

  // Render expense rows — grouped by parent category
  _budgetRenderGroupedExpenses();

  // Render debt commitment rows
  const _schedResult = _runScheduler(activeDebts);
  _budgetSchedulerTargetId = _schedResult?.targetCard?.id ?? null;
  activeDebts.forEach(card => _budgetRenderDebtRow(card));

  // Render sinking funds section
  _budgetRenderSinkingFundsSection();

  // A8: Paid-off cards — show a compact pine acknowledgment row in the Budget page.
  // These don't affect any calculations (filtered from activeDebts) but disappearing
  // silently feels like a bug. A quiet "Paid off" row lets the user see the win
  // and archive the card when she's ready.
  const paidCards = S.debtCards.filter(c => c.paidInFull);
  if (paidCards.length) {
    const cont = g('budgetDebtRows');
    if (cont) {
      paidCards.forEach(card => {
        const div = document.createElement('div');
        div.style.cssText = `display:flex;align-items:center;justify-content:space-between;
          padding:8px 12px;background:var(--pine-bg);border:1px solid var(--pine-border);
          border-radius:var(--r-sm);margin-bottom:4px`;
        const paidAt = card.paidInFull && typeof card.paidInFull === 'string'
          ? ` · ${card.paidInFull}` : '';
        div.innerHTML = `
          <div style="display:flex;align-items:center;gap:8px">
            <span style="color:var(--pine);font-size:13px">✓</span>
            <span style="font-family:'Playfair Display',Georgia,serif;font-style:italic;
                         font-size:13px;color:var(--pine)">${esc(card.name||'Card')}</span>
            <span style="font-family:var(--font-mono);font-size:11px;color:var(--pine);opacity:.7">
              Paid off${esc(paidAt)}
            </span>
          </div>
          <button onclick="confirmAction('Archive ${esc(card.name||'this card')}?',
            'It will be removed from your active list.',
            () => { removeCard(${card.id}); renderBudget(); }, 'Archive', false)"
            style="font-size:11px;color:var(--pine);background:none;border:none;
                   cursor:pointer;opacity:.7;text-decoration:underline;
                   text-underline-offset:2px">
            Archive
          </button>`;
        cont.appendChild(div);
      });
    }
  }
  // A7: CFPB shortfall banner — check before debt summary renders
  _budgetCheckShortfall(activeDebts);
  // CP4: load history then render summary (async — non-blocking)
  _budgetLoadDebtHistory().then(() => _budgetRenderDebtSummary(activeDebts));
  // What's Left card: planned + projected numbers + realism sentence
  _budgetUpdateWhatsLeft();
  // CP2: consequence sentence
  const conseqEl = g('budgetConsequence');
  if (conseqEl) conseqEl.textContent = _budgetConsequenceSentence();
  // Cross-check ledger income note
  _budgetUpdateLedgerIncomeNote();
  // Achievements (read-only display, kept from prior system)
  _budgetRenderAchievements();
}



// ── Budget helper: empty state ────────────────────────────────────────────────
function _budgetEmptyState(title, sub) {
  return `<div class="empty-state" style="padding:16px 0 4px">
    <div class="empty-state-title" style="font-size:13px">${esc(title)}</div>
    <div class="empty-state-sub">${esc(sub)}</div>
  </div>`;
}

// ── Budget helper: realism sentence ──────────────────────────────────────────
// Blueprint §10. Accepts pre-computed left+income so we can pass the
// projected numbers from _budgetUpdateWhatsLeft without double-calculating.
// ── A7: CFPB shortfall banner (Budget Blueprint §19.9) ────────────────────────
// When projected What's Left can't cover combined minimums, show a calm,
// non-alarming banner pointing to CFPB guidance. Tone: matter-of-fact.
// No red warnings. No judgment. Point to the people who can actually help.
function _budgetCheckShortfall(activeDebts) {
  const debtRowsEl = g('budgetDebtRows');
  if (!debtRowsEl) return;

  // Remove any existing shortfall banner
  g('budgetShortfallBanner')?.remove();

  if (!activeDebts.length) return;

  const totalIncome   = S.incomes.reduce((s,i) => s + i.amount, 0);
  if (totalIncome <= 0) return;

  const totalExpenses = S.expenses.reduce((s,e) => s + _rowMonth(e), 0);
  const totalMins     = activeDebts.reduce((s,c) => s + (parseFloat(c.minimum)||0), 0);
  const projExpenses  = S.expenses.reduce((sum, exp) => {
    const p = _budgetProjection(exp.cat || exp.name || 'Other', _rowMonth(exp));
    return sum + (p ? p.projected : _rowMonth(exp));
  }, 0);
  const leftProjected = totalIncome - projExpenses;

  if (leftProjected >= totalMins) return;  // enough to cover minimums — no banner

  const shortfall = Math.round(totalMins - leftProjected);
  const available = Math.round(Math.max(0, leftProjected));

  const banner = document.createElement('div');
  banner.id = 'budgetShortfallBanner';
  banner.style.cssText = 'margin-top:14px;padding:14px 16px;background:var(--mist);border:1px solid var(--steel);border-radius:var(--r-sm);font-size:13px;line-height:1.7';
  banner.innerHTML = `
    <div style="font-size:13px;color:var(--ink);margin-bottom:10px">
      Your projected expenses leave <strong style="font-family:var(--font-mono)">${fmt(available)}</strong>
      for debt this month, but your combined minimums total
      <strong style="font-family:var(--font-mono)">${fmt(totalMins)}</strong>.
      You're <strong style="font-family:var(--font-mono);color:var(--ember)">${fmt(shortfall)}</strong> short this month.
    </div>
    <div style="font-size:12px;color:var(--slate);margin-bottom:10px">
      This happens. Here's what the Consumer Financial Protection Bureau recommends:
    </div>
    <ol style="font-size:12px;color:var(--slate);margin:0 0 12px 18px;padding:0;line-height:1.8">
      <li>Add up income and expenses — look for costs to cut. Decide how much you can actually afford to pay.</li>
      <li>Call your credit card company — explain why you can't pay the minimum and how much you can pay. Many will work with you.</li>
      <li>Consider nonprofit credit counseling — they can help manage money and negotiate with creditors.</li>
      <li>Watch out for for-profit debt settlement companies — they often charge upfront fees and can make things worse.</li>
    </ol>
    <a href="${CFPB_CANT_PAY_URL}" onclick="openExternal('${CFPB_CANT_PAY_URL}');return false;"
      style="font-size:12px;color:var(--pine);text-decoration:underline;text-underline-offset:2px;cursor:pointer">
      What to do when you can't pay your credit card bills (CFPB) →
    </a>
  `;

  // Insert below the debt rows, before the summary
  const summaryEl = g('budgetDebtSummary');
  if (summaryEl) {
    debtRowsEl.closest('.card')?.insertBefore(banner, summaryEl);
  } else {
    debtRowsEl.after(banner);
  }
}

function _budgetUpdateRealismSentence(left, totalIncome) {
  const el = g('budgetRealismSentence');
  if (!el) return;
  // Recalculate if called without arguments (e.g. from renderBudget directly)
  if (left === undefined) {
    const _tod = new Date().toISOString().slice(0, 10);
    totalIncome = S.incomes.reduce((s,i) => s + i.amount, 0);
    const activeDebts = S.debtCards.filter(c => !c.paidInFull && !(c.endDate && c.endDate < _tod));
    const totalDebt   = activeDebts.reduce((s,c) => s + (parseFloat(c.minimum)||0), 0);
    const totalExpenses = S.expenses.reduce((s,e) => s + _rowMonth(e), 0);
    left = totalIncome - totalExpenses - totalDebt;
  }
  if (!totalIncome || totalIncome <= 0) { el.textContent = ''; return; }
  const pct = Math.round((left / totalIncome) * 100);
  if (left < 0) {
    el.style.color = 'var(--ember)';
    el.textContent = `Plan overspends by ${fmt(Math.abs(left))}. Trim an expense or reduce a commitment.`;
  } else if (pct >= 20) {
    el.style.color = 'var(--pine)';
    el.textContent = `Saving ${pct}% of income. Solid cushion.`;
  } else if (pct >= 10) {
    el.style.color = 'var(--slate)';
    el.textContent = `Saving ${pct}% of income. Aim for 15–20%.`;
  } else {
    el.style.color = 'var(--gold)';
    el.textContent = `Saving ${pct}% of income. Prioritize debt paydown to free cash.`;
  }
}

// ── Budget helper: ledger income cross-check note ─────────────────────────────
function _budgetUpdateLedgerIncomeNote() {
  const el = g('budgetIncomeLedgerNote');
  if (!el) return;
  const ledgerIncome = S.transactions
    .filter(t => t.type === 'credit' &&
                 (t.category === 'Income' || (t.category||'').toLowerCase().includes('income')) &&
                 (t.date||'').startsWith(_budgetMonthKey))
    .reduce((s,t) => s + t.amount, 0);
  if (ledgerIncome > 0) {
    el.style.display = 'block';
    el.textContent = `Ledger shows ${fmt(ledgerIncome)} in income imported this month.`;
  } else {
    el.style.display = 'none';
  }
}

// ── Budget helper: update What's Left card (CP1+CP2) ─────────────────────────
// Blueprint §10: two numbers — planned (what the budget says) and projected
// (what imports suggest will actually happen). Planned in ink. Projected in
// pine when under, ember when over.
function _budgetUpdateWhatsLeft() {
  const totalIncome   = S.incomes.reduce((s,i) => s + i.amount, 0);
  const totalExpenses = S.expenses.reduce((s,e) => s + _rowMonth(e), 0);
  const today         = new Date().toISOString().slice(0, 10); // YYYY-MM-DD
  const activeDebts   = S.debtCards.filter(c => !c.paidInFull && !(c.endDate && c.endDate < today));
  const totalDebt     = activeDebts.reduce((s,c) => s + (parseFloat(c.minimum)||0), 0);
  // Sinking fund monthly contributions count as committed spending
  const totalSinking  = (_sinkingFunds || []).reduce((s,f) => s + (parseFloat(f.monthlyContrib)||0), 0);
  const totalOut      = totalExpenses + totalDebt + totalSinking;
  const leftPlanned   = totalIncome - totalOut;

  // CP2: sum projected spend across all expense categories that have projections
  const projExpenses = S.expenses.reduce((sum, exp) => {
    const p = _budgetProjection(exp.cat || exp.name || 'Other', _rowMonth(exp));
    return sum + (p ? p.projected : _rowMonth(exp));
  }, 0);
  const leftProjected   = totalIncome - projExpenses - totalDebt - totalSinking;
  const hasProjection   = S.expenses.some(exp =>
    _budgetProjection(exp.cat || exp.name || 'Other', _rowMonth(exp)) !== null
  );

  // Card border/bg follows projected when available, planned otherwise
  const leftForStyle = hasProjection ? leftProjected : leftPlanned;
  const wlCard = g('budgetWhatsLeftCard');
  if (wlCard) {
    wlCard.style.borderColor = leftForStyle >= 0 ? 'var(--pine-border)' : 'var(--ember-border)';
    wlCard.style.background  = leftForStyle >= 0 ? 'var(--pine-bg)'     : 'var(--ember-bg)';
    const lbl = wlCard.querySelector('.card-label');
    if (lbl) lbl.style.color = leftForStyle >= 0 ? 'var(--pine)' : 'var(--ember)';
  }

  setText('wl-income',   fmt(totalIncome));
  setText('wl-expenses', `− ${fmt(totalExpenses)}`);
  setText('wl-debt',     `− ${fmt(totalDebt)}`);
  // Update sinking funds row visibility (re-render writes it in the template;
  // _budgetUpdateWhatsLeft is also called in place, so update it directly)
  const wlSinking = g('wl-sinking');
  if (wlSinking) {
    if (totalSinking > 0) {
      wlSinking.textContent = `− ${fmt(totalSinking)}`;
      wlSinking.style.display = '';
      const wlRow = wlSinking.closest('div');
      if (wlRow) wlRow.style.display = '';
    } else {
      const wlRow = wlSinking.closest('div');
      if (wlRow) wlRow.style.display = 'none';
    }
  }

  // Planned left (always shown, always in ink)
  const leftEl = g('wl-left');
  if (leftEl) {
    leftEl.textContent = fmt(leftPlanned);
    leftEl.style.color = 'var(--ink)';
  }

  // Projected left (only shown when projection engine has data)
  const projEl = g('wl-left-projected');
  if (projEl) {
    if (hasProjection) {
      projEl.style.display = 'flex';
      const valEl = projEl.querySelector('.wl-proj-val');
      if (valEl) {
        valEl.textContent = fmt(leftProjected);
        valEl.style.color = leftProjected >= 0 ? 'var(--pine)' : 'var(--ember)';
      }
    } else {
      projEl.style.display = 'none';
    }
  }

  // Header stats — use projected when available
  const leftForHeader = hasProjection ? leftProjected : leftPlanned;
  setText('bhs-income', totalIncome > 0 ? fmt(totalIncome) : '—');
  setText('bhs-out',    totalOut > 0    ? fmt(hasProjection ? projExpenses + totalDebt + totalSinking : totalOut) : '—');
  const bhsLeft = g('bhs-left');
  if (bhsLeft) {
    bhsLeft.textContent = totalIncome > 0 ? fmt(leftForHeader) : '—';
    bhsLeft.className   = `val ${leftForHeader >= 0 ? 'pos' : 'neg'}`;
  }

  _budgetUpdateRealismSentence(hasProjection ? leftProjected : leftPlanned, totalIncome);
  if (totalIncome > 0 && totalExpenses > 0) awardAchievement('eyes_open');
  // B0d: two-scenario comparison (current payments vs. minimums-only)
  const twoScenEl = g('budgetTwoScenario');
  if (twoScenEl) {
    const _tod2 = new Date().toISOString().slice(0, 10);
    const activeDebts = S.debtCards.filter(c => !c.paidInFull && !(c.endDate && c.endDate < _tod2));
    twoScenEl.innerHTML = _budgetTwoScenarioComparison(activeDebts);
  }
  renderDashboard();
}

// ── Budget achievements (read-only shelf) ─────────────────────────────────────
function _budgetRenderAchievements() {
  // achievements shelf is no longer rendered inside renderBudget HTML.
  // Kept as a no-op for any callers that still reference the old name.
}
// Keep old name as alias for legacy call sites outside this block


// ── Income bloom ──────────────────────────────────────────────────────────────
function _budgetRenderIncomeRow(inc, idx) {
  const cont = g('budgetIncomeRows');
  if (!cont) return;

  // Clear empty state if needed
  const emptyEl = cont.querySelector('.empty-state');
  if (emptyEl) emptyEl.remove();

  const cs = _categoryStyle('Income');  // use the real Income category style (pine dollar icon)
  const iconBg     = _catTint(cs.color);
  const iconBorder = _catTintBorder(cs.color);
  const row = document.createElement('div');
  row.className = 'ledger-row';
  row.dataset.incomeIdx = idx;
  row.style.cssText = 'display:flex;align-items:center;gap:10px;padding:10px 0;border-bottom:1px solid var(--steel);cursor:pointer';
  row.innerHTML = `
    <div><div class="cat-icon" style="background:${iconBg};border-color:${iconBorder};color:${cs.color}">${_renderCatIcon(cs.icon, cs.color, 18)}</div></div>
    <div style="flex:1;min-width:0">
      <div style="font-size:13px;font-weight:500;color:var(--ink)">${esc(inc.name||'Income source')}</div>
      <div style="font-size:11px;color:var(--slate)">${esc(inc.type||'Payroll')}</div>
    </div>
    <div style="font-family:var(--font-mono);font-size:14px;color:var(--pine);flex-shrink:0">${fmt(inc.amount)}</div>
  `;
  row.onclick = () => _budgetOpenIncomeBloom(row, inc, idx);
  cont.appendChild(row);
}

function _budgetAddIncomeBloom() {
  const cont = g('budgetIncomeRows');
  if (!cont) return;
  _budgetCloseAllBlooms();
  const emptyEl = cont.querySelector('.empty-state');
  if (emptyEl) emptyEl.remove();
  const bloom = _budgetBuildIncomeBloom({ name:'', amount:'', type:'salary' }, -1);
  cont.appendChild(bloom);
  bloom.querySelector('input')?.focus();
}

function _budgetOpenIncomeBloom(row, inc, idx) {
  _budgetCloseAllBlooms();
  const bloom = _budgetBuildIncomeBloom(inc, idx);
  row.replaceWith(bloom);
  bloom.querySelector('input')?.focus();
}

function _budgetBuildIncomeBloom(inc, idx) {
  const bloom = document.createElement('div');
  bloom.className = 'budget-bloom';
  bloom.dataset.bloomType = 'income';
  bloom.dataset.incomeIdx = idx;
  bloom.style.cssText = 'border-left:3px solid var(--pine);background:var(--pine-bg);padding:14px 16px;border-radius:var(--r-sm);margin:4px 0';
  bloom.innerHTML = `
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:10px">
      <div class="field" style="margin:0">
        <label style="font-size:11px;font-weight:600;letter-spacing:.06em;text-transform:uppercase;color:var(--slate);display:block;margin-bottom:4px">Source name</label>
        <input type="text" class="bloom-name" placeholder="e.g. City of Millbrook — Payroll"
          value="${esc(inc.name||'')}"
          style="width:100%;font-size:13px;border:1px solid var(--steel);border-radius:var(--r-sm);padding:6px 9px;background:var(--paper);color:var(--ink)">
      </div>
      <div class="field" style="margin:0">
        <label style="font-size:11px;font-weight:600;letter-spacing:.06em;text-transform:uppercase;color:var(--slate);display:block;margin-bottom:4px">Monthly amount</label>
        <input type="number" class="bloom-amount" placeholder="0" min="0" step="0.01"
          value="${inc.amount||''}"
          style="width:100%;font-family:var(--font-mono);font-size:13px;border:1px solid var(--steel);border-radius:var(--r-sm);padding:6px 9px;background:var(--paper);color:var(--ink)">
      </div>
    </div>
    <div class="field" style="margin:0 0 12px">
      <label style="font-size:11px;font-weight:600;letter-spacing:.06em;text-transform:uppercase;color:var(--slate);display:block;margin-bottom:4px">Type</label>
      <select class="bloom-type" style="font-size:12px;border:1px solid var(--steel);border-radius:var(--r-sm);padding:6px 9px;background:var(--paper);color:var(--ink)">
        <option value="salary"     ${(inc.type||'salary')==='salary'     ?'selected':''}>Payroll / Salary</option>
        <option value="variable"   ${(inc.type||'')==='variable'   ?'selected':''}>Variable / Bonus</option>
        <option value="freelance"  ${(inc.type||'')==='freelance'  ?'selected':''}>Freelance / 1099</option>
        <option value="benefits"   ${(inc.type||'')==='benefits'   ?'selected':''}>Benefits</option>
        <option value="other"      ${(inc.type||'')==='other'      ?'selected':''}>Other</option>
      </select>
    </div>
    <div style="display:flex;gap:8px">
      <button class="btn btn-sm btn-primary" onclick="_budgetSaveIncomeBloom(this)">Save</button>
      <button class="btn btn-sm btn-ghost"   onclick="_budgetCancelBloom(this)">Cancel</button>
      ${idx >= 0 ? `<button class="btn btn-sm btn-ghost" style="margin-left:auto;color:var(--ember)" onclick="_budgetDeleteIncome(${idx})">Remove</button>` : ''}
    </div>
  `;
  return bloom;
}

function _budgetSaveIncomeBloom(btn) {
  const bloom = btn.closest('.budget-bloom');
  const idx   = parseInt(bloom.dataset.incomeIdx);
  const name  = bloom.querySelector('.bloom-name').value.trim();
  const amt   = parseFloat(bloom.querySelector('.bloom-amount').value) || 0;
  const type  = bloom.querySelector('.bloom-type').value;
  if (!name) { showToast('Name required','Enter a source name','warning'); return; }
  if (amt <= 0) { showToast('Amount required','Enter a positive amount','warning'); return; }

  const item = { name, amount: amt, type, id: idx >= 0 ? (S.incomes[idx]?.id||null) : null };
  if (idx >= 0) S.incomes[idx] = item;
  else S.incomes.push(item);

  _syncBudgetItemsToDb('income', S.incomes);
  awardAchievement('eyes_open');
  renderBudget();
}

function _budgetDeleteIncome(idx) {
  S.incomes.splice(idx, 1);
  _syncBudgetItemsToDb('income', S.incomes);
  renderBudget();
}

// ── Expense bloom ─────────────────────────────────────────────────────────────
// ── Budget CP1+CP2: Live spend + Projection engine ────────────────────────────
// CP1: spent-so-far is pulled from S.transactions by category, current month.
// CP2: projection = (spent / days_elapsed) * days_in_month, needs 5+ days.
// Blueprint §6, §9.

function _budgetSpentForCat(catName) {
  // Sum debit transactions for a category in the budget month.
  // Uses hierarchy-aware _catSpentInMonth:
  //   - Parent category → sums all children (rollup)
  //   - Child category  → exact match only
  //   - Falls back to t.category string match for legacy rows
  if (!catName) return 0;

  // Try hierarchy-aware lookup first (uses category_id)
  const hierarchyTotal = _catSpentInMonth(catName, _budgetMonthKey);
  if (hierarchyTotal > 0) return hierarchyTotal;

  // Legacy fallback: match on t.category string (old imports)
  const children = _catChildren(catName);
  const matchNames = children.length > 0 ? [catName, ...children] : [catName];
  return S.transactions
    .filter(t => t.type === 'debit'
              && (t.date || '').startsWith(_budgetMonthKey)
              && matchNames.includes(t.category))
    .reduce((sum, t) => sum + t.amount, 0);
}

function _budgetProjection(catName, budgetedAmt) {
  // Blueprint §9 — verbatim algorithm. Returns null before 5 days elapsed
  // or when not in the current calendar month (no projection for past months).
  const today = new Date();
  const nowKey = `${today.getFullYear()}-${String(today.getMonth()+1).padStart(2,'0')}`;
  if (_budgetMonthKey !== nowKey) return null;   // past/future months: no projection

  const daysInMonth = new Date(today.getFullYear(), today.getMonth()+1, 0).getDate();
  const daysElapsed = today.getDate();
  if (daysElapsed < 5) return null;

  const spent     = _budgetSpentForCat(catName);
  const projected = (spent / daysElapsed) * daysInMonth;

  return {
    spent:     Math.round(spent * 100) / 100,
    projected: Math.round(projected),
    pct:       budgetedAmt > 0 ? projected / budgetedAmt : 0,
    spentPct:  budgetedAmt > 0 ? spent / budgetedAmt : 0,
    trending:  projected > budgetedAmt        ? 'over'
             : projected > budgetedAmt * 0.85 ? 'warn' : 'ok',
  };
}

function _budgetSixMonthAvg(catName) {
  // 6-month average using hierarchy-aware lookup. Blueprint §6.
  return _catSixMonthAvg(catName);
}

// How many distinct calendar months of transaction data exist?
function _budgetDataMonths() {
  return new Set(S.transactions.map(t => (t.date||'').slice(0,7)).filter(Boolean)).size;
}

function _budgetRenderExpenseRow(exp, idx) {
  const cont = g('budgetExpenseRows');
  if (!cont) return;

  const emptyEl = cont.querySelector('.empty-state');
  if (emptyEl) emptyEl.remove();

  const cs      = _categoryStyle(exp.cat || exp.name || 'Other');
  const budget  = _rowMonth(exp);
  const catName = exp.cat || exp.name || 'Other';
  const proj    = _budgetProjection(catName, budget);
  const spent   = proj ? proj.spent : _budgetSpentForCat(catName);

  // Progress bar: uses spent% for past months, projected% for current month
  const barPct   = budget > 0
    ? Math.min(150, Math.round((proj ? proj.pct : spent / budget) * 100))
    : 0;
  const barColor = barPct >= 100 ? 'var(--ember)'
                 : barPct >= 85  ? 'var(--gold)'
                 : 'var(--pine)';

  // Projected label (CP2) — only shown for current month with 5+ days
  let projLabel = '';
  if (proj) {
    const trendIcon = proj.trending === 'over' ? '↑' : proj.trending === 'warn' ? '↗' : '';
    const trendClr  = proj.trending === 'over' ? 'var(--ember)'
                    : proj.trending === 'warn' ? 'var(--gold)'
                    : 'var(--pine)';
    projLabel = `<span style="font-family:var(--font-mono);font-size:11px;color:${trendClr}" title="Projected end-of-month">${trendIcon} ${fmt(proj.projected)} proj.</span>`;
  }

  const row = document.createElement('div');
  row.className = 'ledger-row';
  row.dataset.expenseIdx = idx;
  row.style.cssText = 'padding:10px 0;border-bottom:1px solid var(--steel);cursor:pointer';
  const iconBg     = _catTint(cs.color);
  const iconBorder = _catTintBorder(cs.color);
  row.innerHTML = `
    <div style="display:flex;align-items:center;gap:10px">
      <div><div class="cat-icon" style="background:${iconBg};border-color:${iconBorder};color:${cs.color}">${_renderCatIcon(cs.icon, cs.color, 18)}</div></div>
      <div style="flex:1;min-width:0">
        <div style="display:flex;align-items:baseline;justify-content:space-between;gap:8px;margin-bottom:5px">
          <span style="font-size:13px;font-weight:500;color:var(--ink)">${esc(exp.name||catName)}</span>
          <div style="display:flex;gap:10px;align-items:baseline;flex-shrink:0">
            ${spent > 0 ? `<span style="font-family:var(--font-mono);font-size:12px;color:var(--slate)">${fmt(spent)} spent</span>` : ''}
            ${projLabel}
            <span style="font-family:var(--font-mono);font-size:13px;color:var(--ink)">${fmt(budget)}</span>
          </div>
        </div>
        ${budget > 0 ? `
        <div style="position:relative;height:4px;background:var(--steel);border-radius:2px;overflow:hidden">
          <div style="position:absolute;inset:0 auto 0 0;width:${Math.min(100, barPct)}%;background:${barColor};border-radius:2px;transition:width .4s ease"></div>
        </div>
        <div style="display:flex;justify-content:space-between;margin-top:3px;font-size:10px;color:var(--slate-2)">
          <span>${barPct}%${proj ? ' projected' : spent > 0 ? ' spent' : ''}</span>
          <span style="color:var(--slate-2)">${esc(exp.cat||'')}</span>
        </div>` : ''}
        ${_utilityBenchmarkNote(catName)}
      </div>
    </div>
  `;
  row.onclick = () => _budgetOpenExpenseBloom(row, exp, idx);
  cont.appendChild(row);
}

function _budgetAddExpenseBloom() {
  const cont = g('budgetExpenseRows');
  if (!cont) return;
  _budgetCloseAllBlooms();
  const emptyEl = cont.querySelector('.empty-state');
  if (emptyEl) emptyEl.remove();
  const bloom = _budgetBuildExpenseBloom({ cat:'', name:'', amount:'' }, -1);
  cont.appendChild(bloom);
  bloom.querySelector('input')?.focus();
}

function _budgetOpenExpenseBloom(row, exp, idx) {
  _budgetCloseAllBlooms();
  const bloom = _budgetBuildExpenseBloom(exp, idx);
  row.replaceWith(bloom);
  bloom.querySelector('input')?.focus();
}

function _budgetBuildExpenseBloom(exp, idx) {
  // Build category options as parent/child tree
  const catOptions = _categoryNames().filter(c => c !== 'Income' && c !== 'Transfer');
  const selected   = exp.cat || 'Other';
  // BUG FIX (July 6): `selected` was computed but never actually compared
  // against any option below, so no <option> ever got a `selected`
  // attribute. With zero options marked selected, the browser just shows
  // whatever option happens to be first in DOM order — completely
  // ignoring the item's real saved category. Confirmed in the field:
  // every single budget item's edit bloom displayed the same category
  // regardless of what was actually saved. Worse than a display bug —
  // _budgetSaveExpenseBloom() writes whatever the dropdown currently shows
  // straight back into the item's category on Save, so opening any
  // expense row (even just to tweak the dollar amount) and saving would
  // silently corrupt its real category to whatever this bug happened to
  // be displaying. Fixed by actually marking the matching option selected.
  const _buildCatTreeOptions = () => {
    const tree = _catTree('expense');
    const opts = [];
    tree.forEach(({parent, children}) => {
      if (children.length === 0) {
        // Leaf parent (no children) — selectable directly
        opts.push(`<option value="${esc(parent.name)}" ${parent.name === selected ? 'selected' : ''}>${esc(parent.name)}</option>`);
      } else {
        // Parent with children — show as group header (not selectable)
        opts.push(`<optgroup label="${esc(parent.name)}">`);
        children.forEach(child => {
          opts.push(`<option value="${esc(child.name)}" ${child.name === selected ? 'selected' : ''}>${esc(child.name)}</option>`);
        });
        opts.push(`</optgroup>`);
      }
    });
    return opts.join('');
  };
  const budget     = parseFloat(exp.amount) || 0;
  const catName    = exp.cat || exp.name || 'Other';
  const proj       = _budgetProjection(catName, budget);
  const spent      = proj ? proj.spent : _budgetSpentForCat(catName);
  const avg6       = _budgetSixMonthAvg(catName);

  // Live spend summary block for the bloom (CP1 + CP2)
  let spendSummary = '';
  if (catName && catName !== 'Other') {
    const rows = [];
    if (spent > 0)  rows.push(`<span style="color:var(--slate)">Spent: </span><span style="font-family:var(--font-mono)">${fmt(spent)}</span>`);
    if (proj)       rows.push(`<span style="color:var(--slate)">Projected: </span><span style="font-family:var(--font-mono);color:${proj.trending==='over'?'var(--ember)':proj.trending==='warn'?'var(--gold)':'var(--pine)'}">${fmt(proj.projected)}</span>`);
    if (budget > 0) rows.push(`<span style="color:var(--slate)">Budgeted: </span><span style="font-family:var(--font-mono)">${fmt(budget)}</span>`);
    if (rows.length) {
      spendSummary = `<div style="font-size:12px;display:flex;gap:16px;flex-wrap:wrap;padding:8px 10px;background:var(--mist);border-radius:var(--r-sm);margin-bottom:12px">${rows.join('<span style="color:var(--steel-2);margin:0 2px">·</span>')}</div>`;
    }
  }

  // 6-month average note (informational only — never prescriptive)
  let avgNote = '';
  if (avg6 !== null && avg6 > 0) {
    const tight = budget > 0 && avg6 > budget * 1.1;
    avgNote = `<div style="font-size:11px;color:${tight?'var(--gold)':'var(--slate)'};margin-bottom:12px">
      6-month average: <span style="font-family:var(--font-mono)">${fmt(avg6)}</span>${tight ? ' — your budget may be tight' : ''}
    </div>`;
  }

  const bloom = document.createElement('div');
  bloom.className = 'budget-bloom';
  bloom.dataset.bloomType = 'expense';
  bloom.dataset.expenseIdx = idx;
  bloom.style.cssText = 'border-left:3px solid var(--pine);background:var(--pine-bg);padding:14px 16px;border-radius:var(--r-sm);margin:4px 0';
  bloom.innerHTML = `
    ${spendSummary}
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:10px">
      <div class="field" style="margin:0">
        <label style="font-size:11px;font-weight:600;letter-spacing:.06em;text-transform:uppercase;color:var(--slate);display:block;margin-bottom:4px">Description</label>
        <input type="text" class="bloom-name" placeholder="e.g. Honda lease"
          value="${esc(exp.name||'')}"
          style="width:100%;font-size:13px;border:1px solid var(--steel);border-radius:var(--r-sm);padding:6px 9px;background:var(--paper);color:var(--ink)">
      </div>
      <div class="field" style="margin:0">
        <label style="font-size:11px;font-weight:600;letter-spacing:.06em;text-transform:uppercase;color:var(--slate);display:block;margin-bottom:4px">Monthly budget</label>
        <input type="number" class="bloom-amount" placeholder="0" min="0" step="0.01"
          value="${exp.amount||''}"
          style="width:100%;font-family:var(--font-mono);font-size:13px;border:1px solid var(--steel);border-radius:var(--r-sm);padding:6px 9px;background:var(--paper);color:var(--ink)">
      </div>
    </div>
    <div class="field" style="margin:0 0 10px">
      <label style="font-size:11px;font-weight:600;letter-spacing:.06em;text-transform:uppercase;color:var(--slate);display:block;margin-bottom:4px">Category</label>
      <select class="bloom-cat" style="font-size:12px;border:1px solid var(--steel);border-radius:var(--r-sm);padding:6px 9px;background:var(--paper);color:var(--ink)">
        ${_buildCatTreeOptions()}
      </select>
    </div>
    ${avgNote}
    <div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap">
      <button class="btn btn-sm btn-primary" onclick="_budgetSaveExpenseBloom(this)">Save</button>
      <button class="btn btn-sm btn-ghost"   onclick="_budgetCancelBloom(this)">Cancel</button>
      ${idx >= 0 ? `<button class="btn btn-sm btn-ghost" style="margin-left:auto;color:var(--ember)" onclick="_budgetDeleteExpense(${idx})">Remove</button>` : ''}
      ${catName && catName !== 'Other' && spent > 0 ? `
      <button class="btn btn-sm btn-ghost" style="margin-left:${idx >= 0 ? '0' : 'auto'};color:var(--pine);font-size:11px"
        onclick="showView('ledger');setTimeout(()=>{const cf=g('ledgerCatFilter');if(cf){cf.value=${JSON.stringify(catName)};renderLedger();updateLedgerStats();}},80)">
        See ${fmt(spent)} in Ledger →
      </button>` : ''}
    </div>
  `;
  return bloom;
}

function _budgetSaveExpenseBloom(btn) {
  const bloom = btn.closest('.budget-bloom');
  const idx   = parseInt(bloom.dataset.expenseIdx);
  const name  = bloom.querySelector('.bloom-name').value.trim();
  const amt   = parseFloat(bloom.querySelector('.bloom-amount').value) || 0;
  const cat   = bloom.querySelector('.bloom-cat').value;
  if (!name) { showToast('Description required','Enter a name for this expense','warning'); return; }
  if (amt <= 0) { showToast('Amount required','Enter a positive amount','warning'); return; }

  const item = { name, amount: amt, cat: cat||'Other', id: idx >= 0 ? (S.expenses[idx]?.id||null) : null };
  if (idx >= 0) S.expenses[idx] = { ...S.expenses[idx], ...item };
  else S.expenses.push(item);

  _syncBudgetItemsToDb('expense', S.expenses);
  if (S.expenses.length >= 5) awardAchievement('honest_count');
  renderBudget();
}

function _budgetDeleteExpense(idx) {
  S.expenses.splice(idx, 1);
  _syncBudgetItemsToDb('expense', S.expenses);
  renderBudget();
}

// ── Pre-fill from history (CP1) ───────────────────────────────────────────────
// Blueprint §6: never silently overwrites. Shows a preview, user applies or dismisses.
function _budgetPrefillFromHistory() {
  // Compute 6-month category averages from real imports
  const now     = new Date();
  const months  = [];
  for (let i = 1; i <= 6; i++) {
    const d = new Date(now.getFullYear(), now.getMonth() - i, 1);
    months.push(`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`);
  }

  const catTotals  = {};
  const catMonths  = {};   // how many months had spend for this cat
  S.transactions
    .filter(t => t.type === 'debit' && months.includes((t.date||'').slice(0,7))
              && t.category && t.category !== 'Income' && t.category !== 'Transfer')
    .forEach(t => {
      const c = t.category;
      const mo = (t.date||'').slice(0,7);
      catTotals[c] = (catTotals[c]||0) + t.amount;
      if (!catMonths[c]) catMonths[c] = new Set();
      catMonths[c].add(mo);
    });

  // Average only over months that had spend (don't dilute with $0 months)
  const suggestions = Object.entries(catTotals)
    .map(([cat, total]) => ({
      cat,
      avg: Math.round(total / catMonths[cat].size),
      months: catMonths[cat].size,
    }))
    .filter(s => s.avg > 0)
    .sort((a, b) => b.avg - a.avg);

  if (!suggestions.length) {
    showToast('Not enough data', 'Import more transactions to use pre-fill.', 'warning');
    return;
  }

  // Build preview modal-style inline panel
  const existing = g('budgetPrefillPanel');
  if (existing) { existing.remove(); return; }   // toggle

  const panel = document.createElement('div');
  panel.id = 'budgetPrefillPanel';
  panel.style.cssText = 'position:fixed;inset:0;z-index:800;background:rgba(0,0,0,.45);display:flex;align-items:flex-end;justify-content:center;padding:0';
  panel.innerHTML = `
    <div style="background:var(--paper);border-radius:var(--r-lg) var(--r-lg) 0 0;padding:24px;width:100%;max-width:520px;max-height:80vh;overflow-y:auto">
      <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:4px">
        <div style="font-size:16px;font-weight:600;color:var(--ink)">Pre-fill from history</div>
        <button onclick="document.getElementById('budgetPrefillPanel')?.remove()" style="background:none;border:none;font-size:20px;color:var(--slate);cursor:pointer;padding:0 4px">×</button>
      </div>
      <div style="font-size:12px;color:var(--slate);margin-bottom:16px">Based on ${months.length} months of imports. Edit any amount before applying.</div>
      <div id="prefillRows" style="display:flex;flex-direction:column;gap:6px;margin-bottom:16px">
        ${suggestions.map((s, i) => {
          const cs = _categoryStyle(s.cat);
          return `<div style="display:flex;align-items:center;gap:10px;padding:8px 10px;background:var(--mist);border-radius:var(--r-sm)">
            <div style="flex-shrink:0">${_renderCatIcon(cs.icon, cs.color, 14)}</div>
            <span style="flex:1;font-size:13px;color:var(--ink)">${esc(s.cat)}</span>
            <span style="font-size:10px;color:var(--slate-2)">${s.months}mo avg</span>
            <input type="number" class="prefill-amt" data-cat="${esc(s.cat)}" value="${s.avg}" min="0" step="0.01"
              style="width:80px;font-family:var(--font-mono);font-size:13px;text-align:right;border:1px solid var(--steel);border-radius:var(--r-sm);padding:4px 6px;background:var(--paper);color:var(--ink)">
          </div>`;
        }).join('')}
      </div>
      <div style="display:flex;gap:8px">
        <button class="btn btn-primary" style="flex:1" onclick="_budgetApplyPrefill()">Apply suggestions</button>
        <button class="btn btn-ghost" onclick="document.getElementById('budgetPrefillPanel')?.remove()">Dismiss</button>
      </div>
    </div>
  `;
  document.body.appendChild(panel);
  panel.addEventListener('click', e => { if (e.target === panel) panel.remove(); });
}

async function _budgetApplyPrefill() {
  const rows = document.querySelectorAll('#prefillRows .prefill-amt');
  let added = 0, filled = 0;
  const toPersist = [];   // rows needing a DB write (new creates OR filled updates)
  rows.forEach(inp => {
    const cat = inp.dataset.cat;
    const amt = parseFloat(inp.value) || 0;
    if (!cat || amt <= 0) return;
    // Match an existing budget row by category/name.
    const existing = S.expenses.find(e => (e.cat || e.name) === cat);
    if (existing) {
      // A row exists — only FILL it if it's currently empty ($0). Never
      // overwrite an amount the user actually set. (This is the common case:
      // the budget was seeded with $0 category rows, and prefill is meant to
      // populate exactly those — previously it skipped them as "already
      // budgeted," so nothing ever changed.)
      if ((parseFloat(existing.amount) || 0) === 0) {
        existing.amount = amt;
        toPersist.push(existing);
        filled++;
      }
    } else {
      const row = { name: cat, amount: amt, cat, id: null };
      S.expenses.push(row);
      toPersist.push(row);
      added++;
    }
  });
  g('budgetPrefillPanel')?.remove();

  const changed = added + filled;
  if (changed === 0) {
    showToast('Nothing to fill', 'Your suggested categories already have budgeted amounts.', 'info');
    renderBudget();
    return;
  }

  // Render immediately so the user sees the result even if the DB is slow.
  renderBudget();

  // Persist only the rows we touched. New rows POST; existing filled rows PATCH
  // (they already have a DB id). Await so we can report the true outcome.
  let saveFailed = false;
  for (const item of toPersist) {
    try {
      const payload = { type: 'expense', name: item.name, amount: item.amount, category: item.cat || item.name || '' };
      if (item.id) {
        await API.patch(`/api/budget/items/${item.id}`, payload);
      } else {
        const res = await API.post('/api/budget/items', payload);
        const dbId = res?.id || res?.data?.id;
        if (dbId) item.id = dbId;   // stamp so future edits update instead of duplicate
      }
    } catch (e) {
      saveFailed = true;
      _gwLogError(`_budgetApplyPrefill: ${e?.message || e}`, 'catch', 0, 0, e);
    }
  }

  const summary = [added ? `${added} added` : '', filled ? `${filled} filled` : ''].filter(Boolean).join(', ');
  if (saveFailed) {
    showToast('Saved locally', 'Some rows couldn\u2019t sync to the database yet — they\u2019ll retry on your next edit.', 'warning');
  } else {
    showToast(`Budget updated`, `${summary}. Edit any row to adjust.`, 'success');
  }
}

// ── CP2+CP5: Consequence surfacing ────────────────────────────────────────────
// Blueprint §13. Finds the worst-projecting expense category, runs the
// amortization engine with and without the overage to compute exact payoff delay.
// "Groceries trending $40 over. Delays credit card payoff ~3 weeks."
// Pure arithmetic. No AI. Calm statement of fact.
function _budgetConsequenceSentence() {
  // Find the expense projecting furthest over budget
  let worstCat = null, worstOverage = 0;
  S.expenses.forEach(exp => {
    const p = _budgetProjection(exp.cat || exp.name || 'Other', _rowMonth(exp));
    if (!p || p.trending === 'ok') return;
    const overage = p.projected - _rowMonth(exp);
    if (overage > worstOverage) { worstOverage = overage; worstCat = exp.cat || exp.name; }
  });
  if (!worstCat || worstOverage < 5) return '';

  // Find the highest-APR active non-lease debt to compute payoff delay against
  const today2 = new Date().toISOString().slice(0, 10);
  const activeDebts = S.debtCards.filter(c =>
    !c.paidInFull &&
    parseFloat(c.rate) > 0 &&
    (c.debtType || 'credit') !== 'lease' &&
    !(c.endDate && c.endDate < today2)
  );
  if (!activeDebts.length) return '';
  const topDebt = [...activeDebts].sort((a,b) => parseFloat(b.rate) - parseFloat(a.rate))[0];
  const bal     = _cardBal(topDebt);
  const pmt     = _payoffPayment(topDebt) || 0;   // V3
  const apr     = parseFloat(topDebt.rate) || 0;
  if (!bal || !pmt || !apr) return '';

  // Use the amortization engine for a precise delay: run with and without overage
  // The overage hits this month only — it reduces principal paid this month.
  const snapsNormal  = _projectPayoff(bal, apr, pmt);
  // Overage means less money available this month → effectively one month of lower payment
  const pmtReduced   = Math.max(0, pmt - worstOverage);
  const balAfterReduced = bal - Math.max(0, pmtReduced - bal * (apr / 100 / 12));
  const snapsDelayed = _projectPayoff(Math.max(bal, balAfterReduced), apr, pmt);

  const monthsDelay = snapsDelayed.length - snapsNormal.length;
  const weeksDelay  = Math.round(monthsDelay * 4.3);
  if (weeksDelay < 1) return '';

  const debtName = topDebt.name || 'your debt';
  const delay    = weeksDelay >= 4
    ? `~${Math.round(weeksDelay / 4.3)} month${Math.round(weeksDelay/4.3)!==1?'s':''}`
    : `~${weeksDelay} week${weeksDelay!==1?'s':''}`;
  return `${worstCat} trending ${fmt(worstOverage)} over. Delays ${debtName} payoff ${delay}.`;
}

// ── Budget CP3: Debt intelligence ─────────────────────────────────────────────
// Blueprint §7 — full debt bloom: payment, minimum, balance, APR, credit limit,
// amortization engine, payoff forecast, balance cross-check.
// Blueprint §8 — JS mirror of project_payoff() for live recalculation.
// Blueprint §11 — snapshot-on-save to debt_balance_history.

// JS amortization engine — mirrors server-side project_payoff() exactly.
function _projectPayoff(balance, aprPct, monthlyPayment) {
  const monthlyRate = aprPct / 100 / 12;
  const snaps = [];
  let bal = balance;
  let month = 0;

  while (bal > 0.01 && month < 360) {
    const interest  = bal * monthlyRate;
    // If payment doesn't cover interest the balance grows — cap at 360 and bail
    if (monthlyPayment <= interest) {
      // Fill remaining slots to signal "never pays off at this payment"
      snaps.push({ month: 360, balance: bal, interest, principal: 0, noPayoff: true });
      break;
    }
    const principal = Math.max(0, monthlyPayment - interest);
    bal             = Math.max(0, bal - principal);
    const minPmt    = Math.max(25, bal * 0.01 + interest);
    month++;
    snaps.push({ month, balance: Math.round(bal*100)/100,
                 interest: Math.round(interest*100)/100,
                 principal: Math.round(principal*100)/100,
                 min_payment: Math.round(minPmt*100)/100 });
  }
  return snaps;
}

function _calcMinPayment(balance, aprPct) {
  // Blueprint §7: max($25, balance × 0.01 + monthly_interest)
  const interest = balance * (aprPct / 100 / 12);
  return Math.round(Math.max(25, balance * 0.01 + interest) * 100) / 100;
}

function _payoffDateLabel(monthsFromNow) {
  if (monthsFromNow <= 0) return 'Already paid off';
  const d = new Date();
  d.setMonth(d.getMonth() + monthsFromNow);
  return d.toLocaleDateString('en-US', { month: 'long', year: 'numeric' });
}

// Save a snapshot for all active debts (blueprint §11).
async function _budgetSaveDebtSnapshot(month) {
  const activeDebts = S.debtCards.filter(c => !c.paidInFull && c._dbId);
  if (!activeDebts.length) return;
  const snapshots = activeDebts.map(card => {
    const bal  = _cardBal(card);
    const apr  = parseFloat(card.rate) || 0;
    const pmt  = parseFloat(card.minimum) || 0;
    const min  = _calcMinPayment(bal, apr);
    // V6: history records an APR nobody entered as unknown, not as 0%.
    return { debt_id: card._dbId, balance: bal, payment: pmt, min_payment: min,
             apr: _isBlank(card.rate) ? null : apr };
  });
  await API.post('/api/debt/history', { month, snapshots }).catch(_gwErr('_budgetSaveDebtSnapshot'));
}

// ── Budget CP4: Minimum decay + wealth feedback ───────────────────────────────
// Blueprint §12 Level 1 (badge on row), Level 2 (section summary line).
// Blueprint §7 avalanche engine — payoff sequence, interest saved, waterfall.

// Module-level history cache — loaded when Budget page opens.
// Shape: { [dbId]: [{ month, balance, payment, min_payment, apr }, ...] } newest first
let _debtHistoryCache = {};

async function _budgetLoadDebtHistory() {
  try {
    const res = await API.get('/api/debt/history/all');
    _debtHistoryCache = res.data ?? res ?? {};
  } catch(e) {
    _debtHistoryCache = {};
  }
}

// Minimum decay delta for a card: current calc min vs. last stored min.
// Returns { delta, label } where delta < 0 means minimum decreased (good).
function _budgetMinDecay(card) {
  const bal  = _cardBal(card);
  const apr  = parseFloat(card.rate) || 0;
  if (!bal || !apr || !card._dbId) return null;

  const history = _debtHistoryCache[String(card._dbId)] || [];
  if (!history.length) return null;

  const lastMin  = history[0].min_payment;  // most recent snapshot
  const calcMin  = _calcMinPayment(bal, apr);
  const delta    = Math.round((calcMin - lastMin) * 100) / 100;
  if (Math.abs(delta) < 1) return null;     // too small to surface
  return { delta, freed: -delta };          // freed > 0 means minimum dropped
}

// ── The Budget page's payoff forecast is the plan (V10) ─────────────────────
// The Budget page, its two-scenario line and the Debt Payoff report ran their own
// payoff maths: always avalanche, whatever plan the user chose, and with a
// mortgage's whole payment (escrow too) taken as principal - so a snowball user
// saw one date here and another on the Debt page, and a mortgage cleared years
// early. They now show the Debt page's own engine run, and "minimums only" is the
// shared "minimums only" (_minimumsOnly, V11) - the same pair the Debt page shows.
function _budgetPlanForecast() {
  const cards = _simCards();
  if (!cards.length) return { plan: null, mins: null };
  const data = getCardData();
  return { plan: _simulatePayoff(0),   // the Debt page's run: same cards, budget and plan
           mins: data.length ? _minimumsOnly(data) : null };
}

// ── Freed minimums this year ──────────────────────────────────────────────────
// From debt_balance_history: compare earliest 2026 snapshot min to current calc min
// for each card. Sum the freed amount across all cards.
function _budgetFreedMinimumsThisYear(cards) {
  const yearKey = String(new Date().getFullYear());
  let freed = 0;
  let hasData = false;

  for (const card of cards) {
    if (card.paidInFull || !card._dbId) continue;
    const history = _debtHistoryCache[String(card._dbId)] || [];
    // Find earliest snapshot in this calendar year
    const yearSnaps = history.filter(h => h.month.startsWith(yearKey));
    if (!yearSnaps.length) continue;
    const earliest  = yearSnaps[yearSnaps.length - 1]; // sorted newest first, so last = oldest
    const bal       = _cardBal(card);
    const apr       = parseFloat(card.rate) || 0;
    const currentMin= apr > 0 ? _calcMinPayment(bal, apr) : parseFloat(card.minimum)||0;
    freed   += Math.max(0, earliest.min_payment - currentMin);
    hasData  = true;
  }

  return hasData ? Math.round(freed) : null;
}

function _budgetRenderDebtRow(card) {
  const cont = g('budgetDebtRows');
  if (!cont) return;

  const emptyEl = cont.querySelector('.empty-state');
  if (emptyEl) emptyEl.remove();

  const bal       = _cardBal(card);
  const beginBal  = parseFloat(card.beginBal) || bal;
  const min       = parseFloat(card.minimum) || 0;
  const apr       = parseFloat(card.rate) || 0;
  const limit     = card.creditLimit ? parseFloat(card.creditLimit) : null;
  const isLease   = (card.debtType || 'credit') === 'lease';
  const isLoan    = (card.debtType || 'credit') === 'loan';
  const today     = new Date().toISOString().slice(0, 10);

  // End date countdown for leases and loans
  let endDateBadge = '';
  if (card.endDate && card.endDate >= today) {
    const moLeft = Math.round((new Date(card.endDate) - new Date()) / (1000*60*60*24*30.4));
    const endLbl = new Date(card.endDate).toLocaleDateString('en-US',{month:'short',year:'numeric'});
    const badgeColor = moLeft <= 3 ? 'var(--gold)' : 'var(--slate-2)';
    endDateBadge = `<span style="font-size:10px;color:${badgeColor};font-family:var(--font-mono)">${isLease ? 'ends' : 'matures'} ${endLbl}</span>`;
  }

  // Due date status — suppress entirely if payment already confirmed this month.
  // Otherwise: red when overdue or ≤2 days, gold for 3–7 days, slate beyond.
  let dueLabel = '', dueColor = 'var(--slate)';
  if (card.dueDay) {
    const today   = new Date();
    const moKey2  = `${today.getFullYear()}-${String(today.getMonth()+1).padStart(2,'0')}`;
    const dueDate = new Date(today.getFullYear(), today.getMonth(), parseInt(card.dueDay));
    const diff    = Math.round((dueDate - today) / 86400000);

    // Only show urgency alerts within ±30 days of due
    if (diff >= -30 && diff <= 14) {
      // Check if already paid — if so, suppress the alert
      const hasImported = S.transactions.some(t => (t.date||'').startsWith(moKey2));
      const alreadyPaid = hasImported && _debtPaidThisMonth({
        id: card.id, name: card.name || '',
        minimum: parseFloat(card.minimum) || 0,
        total:   parseFloat(card.minimum) || 0,
      }, moKey2).paid;

      if (!alreadyPaid) {
        if (diff < 0)       { dueLabel = `${Math.abs(diff)}d overdue`; dueColor = 'var(--ember)'; }
        else if (diff === 0){ dueLabel = 'due today';                   dueColor = 'var(--ember)'; }
        else if (diff <= 2) { dueLabel = `in ${diff}d`;                 dueColor = 'var(--ember)'; }
        else if (diff <= 7) { dueLabel = `in ${diff}d`;                 dueColor = 'var(--gold)';  }
        else if (diff <= 14){ dueLabel = `in ${diff}d`;                 dueColor = 'var(--slate)'; }
      }
    }
  }

  // CP4 Level 1: progress bar — % of original balance paid, ember→pine as balance drops
  let progressBar = '';
  if (beginBal > 0 && bal < beginBal) {
    const paidPct  = Math.min(100, Math.round(((beginBal - bal) / beginBal) * 100));
    const barColor = paidPct >= 75 ? 'var(--pine)' : paidPct >= 40 ? 'var(--gold)' : 'var(--ember)';
    progressBar = `<div style="margin-top:5px;height:4px;background:var(--steel);border-radius:2px;overflow:hidden">
      <div style="width:${paidPct}%;height:100%;background:${barColor};border-radius:2px;transition:width .5s ease"></div>
    </div>
    <div style="font-size:10px;color:var(--slate-2);margin-top:2px">${paidPct}% paid</div>`;
  }

  // CP4 Level 1: minimum decay badge
  const decay = _budgetMinDecay(card);
  const decayBadge = (decay && decay.freed > 0)
    ? `<span style="font-size:10px;color:var(--pine);background:var(--pine-bg);border:1px solid var(--pine-border);border-radius:10px;padding:1px 6px;margin-left:6px">↓ min ${fmt(decay.freed)}</span>`
    : '';

  // Utilization bar (only when credit limit entered)
  let utilBar = '';
  if (limit && limit > 0 && bal > 0) {
    const utilPct = Math.min(150, Math.round((bal / limit) * 100));
    // One neutral colour: the bar shows how much of the limit is in use, not
    // whether that amount is good or bad (the same rule as the utilization lines).
    utilBar = `<div style="margin-top:5px;height:4px;background:var(--steel);border-radius:2px;overflow:hidden">
      <div style="width:${Math.min(100,utilPct)}%;height:100%;background:var(--slate);border-radius:2px"></div>
    </div>`;
  }

  const row = document.createElement('div');
  row.className = 'ledger-row';
  row.dataset.debtId = card.id;

  // B0b: Scheduler highlight — amber for pending target, pine for accepted/adjusted
  const isTarget = card.id === _budgetSchedulerTargetId;
  const schedKey = _schedulerCardKey(card);
  const schedState = _schedulerState[schedKey] || 'pending';
  const schedStyle = isTarget
    ? (schedState === 'accepted' || schedState === 'adjusted'
        ? 'border-left:3px solid var(--pine);background:var(--pine-bg);'
        : 'border-left:3px solid var(--gold);background:var(--gold-bg);')
    : '';
  row.style.cssText = `padding:10px 0 10px 10px;border-bottom:1px solid var(--steel);cursor:pointer;${schedStyle}`;
  row.innerHTML = `
    <div style="display:flex;align-items:center;gap:10px">
      <div><div class="cat-icon" style="background:var(--ember-bg);border-color:var(--ember-border);color:var(--ember)">${_renderCatIcon(isLease ? 'car' : isLoan ? 'bank' : 'credit-card', 'var(--ember)', 18)}</div></div>
      <div style="flex:1;min-width:0">
        <div style="display:flex;align-items:baseline;justify-content:space-between;gap:8px">
          <span style="font-size:13px;font-weight:500;color:var(--ink)">${esc(card.name||'Debt account')}${decayBadge}</span>
          <span style="font-family:var(--font-mono);font-size:14px;color:var(--ember);flex-shrink:0">${fmt(min)}/mo</span>
        </div>
        <div style="font-size:11px;display:flex;gap:10px;align-items:center;margin-top:2px;flex-wrap:wrap">
          ${isLease ? `<span style="color:var(--slate-2);font-size:10px;font-weight:500;text-transform:uppercase;letter-spacing:.04em">Lease</span>` : isLoan ? `<span style="color:var(--slate-2);font-size:10px;font-weight:500;text-transform:uppercase;letter-spacing:.04em">Loan</span>` : ''}
          ${dueLabel ? `<span style="color:${dueColor};font-family:var(--font-mono)">${esc(dueLabel)}</span>` : ''}
          ${bal > 0  ? `<span style="color:var(--slate)">Balance ${fmt(bal)}</span>` : ''}
          ${apr > 0  ? `<span style="color:var(--slate-2)">${apr}% APR</span>` : ''}
          ${endDateBadge}
          ${card.linkedAccountId && card.calculatedBalance !== null
            ? `<span style="color:var(--pine);font-size:10px">● from imports</span>` : ''}
        </div>
        ${progressBar}
        ${utilBar}
      </div>
    </div>
  `;
  row.onclick = () => {
    if (isTarget && (schedState === 'pending' || schedState === 'adjusted')) {
      _budgetOpenSchedulerPopup(card.id);
    } else {
      _budgetOpenDebtBloom(row, card);
    }
  };
  cont.appendChild(row);
}

// CP4: render the summary line, utilization summary, and waterfall toggle
// ── Phase B0: Monthly payoff scheduler (Budget Blueprint §19.3–19.8) ─────────
// Stores per-card scheduler state for the current month.
// Shape: { [cardId]: 'pending' | 'accepted' | 'adjusted' }
let _schedulerState = {};
// Whether the user has dismissed the explanation popup ("don't show again")
let _schedulerExplainerDismissed = false;

function _loadSchedulerPrefs() {
  try {
    _schedulerExplainerDismissed = localStorage.getItem('gw_sched_nodesc') === '1';
    const stored = localStorage.getItem('gw_sched_state');
    if (stored) _schedulerState = JSON.parse(stored);
  } catch(e) { _gwErr('_loadSchedulerPrefs')(e); }
}

function _saveSchedulerPrefs() {
  try {
    localStorage.setItem('gw_sched_state', JSON.stringify(_schedulerState));
    if (_schedulerExplainerDismissed)
      localStorage.setItem('gw_sched_nodesc', '1');
  } catch(e) { _gwErr('_saveSchedulerPrefs')(e); }
}

function _schedulerCardKey(card) {
  // Key: card._dbId + current month key — resets every month automatically
  return `${card._dbId||card.id}_${_budgetMonthKey}`;
}

// Run the scheduler client-side using the avalanche sequence already computed.
// Returns { targetCard, suggestedPayment, availableExtra, otherMins } or null.
function _runScheduler(activeDebts) {
  if (!activeDebts.length) return null;

  const totalIncome   = S.incomes.reduce((s,i) => s + i.amount, 0);
  if (totalIncome <= 0) return null;

  const projExpenses = S.expenses.reduce((sum, exp) => {
    const p = _budgetProjection(exp.cat || exp.name || 'Other', _rowMonth(exp));
    return sum + (p ? p.projected : _rowMonth(exp));
  }, 0);
  const available = Math.max(0, totalIncome - projExpenses);

  const totalMins = activeDebts.reduce((s,c) => s + (parseFloat(c.minimum)||0), 0);
  if (available < totalMins) return null;  // shortfall handled by CFPB banner

  // Avalanche target: highest APR non-lease, non-PSLF card with remaining balance
  const target = [...activeDebts]
    .filter(c => {
      const isLease = (c.debtType || 'credit') === 'lease';
      const isPSLF  = _pslfIsFlagged(c._dbId || c.id);
      return !isLease && !isPSLF && parseFloat(c.rate) > 0 && _cardBal(c) > 0;
    })
    .sort((a,b) => parseFloat(b.rate) - parseFloat(a.rate))[0];
  if (!target) return null;

  const otherMins    = totalMins - (parseFloat(target.minimum)||0);
  const extra        = Math.max(0, available - totalMins);
  const suggestedPmt = (parseFloat(target.minimum)||0) + extra;

  return { targetCard: target, suggestedPayment: suggestedPmt,
           availableExtra: extra, otherMins, available };
}

// B0b: Called from _budgetRenderDebtRow to get the amber/pine border state.


// B0c: Open the suggestion popup for the amber (target) card.
function _budgetOpenSchedulerPopup(cardId) {
  // Remove any existing popup
  g('budgetSchedulerPopup')?.remove();

  const activeDebts = _activeDebtCards();
  const sched       = _runScheduler(activeDebts);
  if (!sched || sched.targetCard.id !== cardId) return;

  const card = sched.targetCard;
  const key  = _schedulerCardKey(card);

  const popup = document.createElement('div');
  popup.id = 'budgetSchedulerPopup';
  popup.style.cssText = `
    position:fixed;inset:0;z-index:700;display:flex;align-items:flex-end;
    justify-content:center;background:rgba(0,0,0,.35)
  `;

  const explainer = _schedulerExplainerDismissed ? '' : `
    <div style="font-size:12px;color:var(--slate);margin-bottom:14px;line-height:1.6">
      <strong style="color:var(--ink)">${esc(card.name||'This card')}</strong>
      has your highest APR (${parseFloat(card.rate)||0}%). Putting extra here
      costs the least in total interest — that's the avalanche method.
    </div>
    <div style="font-size:12px;color:var(--slate);margin-bottom:14px;line-height:1.6">
      Where the extra comes from:
      <span style="font-family:var(--font-mono)">${fmt(sched.available)}</span> available
      after expenses, minus <span style="font-family:var(--font-mono)">${fmt(sched.otherMins)}</span>
      for other card minimums.
    </div>`;

  popup.innerHTML = `
    <div style="background:var(--paper);border-radius:var(--r-lg) var(--r-lg) 0 0;
                padding:24px 20px;width:100%;max-width:480px;
                box-shadow:0 -4px 24px rgba(0,0,0,.12)">
      <div style="font-size:15px;font-weight:600;color:var(--ink);margin-bottom:4px">
        ${esc(card.name||'Debt card')}
      </div>
      <div style="font-size:12px;color:var(--gold);font-weight:600;
                  letter-spacing:.06em;text-transform:uppercase;margin-bottom:16px">
        Avalanche target this month
      </div>

      ${explainer}

      <div style="background:var(--mist);border-radius:var(--r-sm);padding:14px;
                  margin-bottom:16px;font-size:13px">
        <div style="display:flex;justify-content:space-between;margin-bottom:6px">
          <span style="color:var(--slate)">Suggested payment</span>
          <span style="font-family:var(--font-mono);font-weight:600;color:var(--ink)">
            ${fmt(sched.suggestedPayment)}
          </span>
        </div>
        <div style="display:flex;justify-content:space-between;font-size:11px">
          <span style="color:var(--slate-2)">Minimum ${fmt(parseFloat(card.minimum)||0)} + extra ${fmt(sched.availableExtra)}</span>
        </div>
      </div>

      <div style="display:flex;gap:10px;margin-bottom:${_schedulerExplainerDismissed ? 0 : 14}px">
        <button onclick="_budgetAcceptScheduler(${card.id})"
          style="flex:1;background:var(--pine);color:#fff;border:none;
                 border-radius:var(--r-md);padding:11px 0;font-size:14px;
                 font-weight:500;cursor:pointer">
          Accept ${fmt(sched.suggestedPayment)}
        </button>
        <button onclick="_budgetAdjustScheduler(${card.id}, ${sched.suggestedPayment})"
          style="flex:1;background:none;border:1px solid var(--steel);color:var(--ink);
                 border-radius:var(--r-md);padding:11px 0;font-size:14px;cursor:pointer">
          Adjust
        </button>
      </div>

      ${!_schedulerExplainerDismissed ? `
      <label style="display:flex;align-items:center;gap:8px;font-size:12px;
                    color:var(--slate);cursor:pointer">
        <input type="checkbox" id="schedNoDescChk"
               onchange="_schedulerExplainerDismissed=this.checked;_saveSchedulerPrefs()">
        Don't show this explanation again
      </label>` : ''}
    </div>
  `;

  popup.addEventListener('click', e => { if (e.target === popup) popup.remove(); });
  document.body.appendChild(popup);
}

function _budgetAcceptScheduler(cardId) {
  const activeDebts = _activeDebtCards();
  const sched       = _runScheduler(activeDebts);
  if (!sched || sched.targetCard.id !== cardId) { g('budgetSchedulerPopup')?.remove(); return; }

  const card = sched.targetCard;
  const key  = _schedulerCardKey(card);
  _schedulerState[key] = 'accepted';
  // Update the card's payment for this month
  card.minimum = sched.suggestedPayment;
  setCardField(card.id, 'minimum', sched.suggestedPayment);
  _saveSchedulerPrefs();
  g('budgetSchedulerPopup')?.remove();
  renderBudget();
  showToast(`${card.name||'Card'} payment set`, `${fmt(sched.suggestedPayment)} this month`, 'success');
}

function _budgetAdjustScheduler(cardId, suggestedAmt) {
  g('budgetSchedulerPopup')?.remove();

  // Open the bloom directly, pre-filled with the suggested payment
  const card = S.debtCards.find(c => c.id === cardId);
  if (!card) return;
  const row = document.querySelector(`[data-debt-id="${cardId}"]`);
  if (row) {
    _budgetOpenDebtBloom(row, card);
    // Pre-fill the payment field with the suggestion
    setTimeout(() => {
      const pmt = document.querySelector('.bloom-debt-payment');
      if (pmt) { pmt.value = suggestedAmt; _budgetDebtBloomCalc(pmt.closest('.budget-bloom')); }
    }, 50);
  }

  const key = _schedulerCardKey(card);
  _schedulerState[key] = 'adjusted';
  _saveSchedulerPrefs();
}

// B0d: Two-scenario comparison for What's Left card
function _budgetTwoScenarioComparison(activeDebts) {
  if (!activeDebts.length) return '';
  // V10: the plan the Debt page shows. V11: "minimums only" as the Debt page means
  // it (_minimumsOnly). Pending, not covering the minimums, or a loan that cannot
  // amortize says nothing here; the page redraws when the plan's answer lands.
  const { plan, mins } = _budgetPlanForecast();
  if (!plan || !mins) return '';
  const currentDate = _payoffDateLabel(plan.months);
  const minNever = mins.capped;
  const minDate = minNever ? 'not within 30 years' : _payoffDateLabel(mins.months);
  if (!minNever && currentDate === minDate) return '';

  const minStyle = minNever ? 'color:var(--ember)' : '';

  return `<div style="display:flex;justify-content:space-between;padding-top:8px;
                       border-top:1px solid var(--steel);margin-top:8px;font-size:11px;
                       color:var(--slate)">
    <span>At minimums only: <span style="font-family:var(--font-mono);${minStyle}">${minDate}</span></span>
    <span>Your ${_planName()} plan at ${fmt(_getMonthlyBudget())}/mo: <span style="font-family:var(--font-mono);color:var(--pine)">${currentDate}</span></span>
  </div>`;
}

function _budgetRenderDebtSummary(activeDebts) {
  const summaryEl   = g('budgetDebtSummary');
  const waterfallEl = g('budgetDebtWaterfall');
  if (!summaryEl || !activeDebts.length) return;

  const { plan, mins } = _budgetPlanForecast();   // V10: the Debt page's plan, not a Budget-page avalanche
  const freed     = _budgetFreedMinimumsThisYear(activeDebts);

  // ── Level 2 summary line ──
  const lines = [];

  if (plan === undefined) {
    lines.push(`<div style="font-size:12px;color:var(--slate);line-height:1.6">Payoff forecast: working it out…</div>`);
  } else if (plan) {
    let summaryText = `Payoff forecast (your ${_planName()} plan, ${fmt(_getMonthlyBudget())}/mo): ${_payoffDateLabel(plan.months)}`;   // V4, V10
    // Only against a minimums run that finishes: a 30-year cut-off would understate it.
    const saves = mins && !mins.capped ? mins.totalInterest - plan.totalInterest : 0;
    if (saves > 0) summaryText += ` · Saves ${fmt(saves)} vs. minimums only`;
    lines.push(`<div style="font-size:12px;color:var(--slate);line-height:1.6">${summaryText}</div>`);
  }

  if (freed !== null && freed > 0) {
    const jan = `${new Date().getFullYear()}-01`;
    const sinceLabel = Object.values(_debtHistoryCache).some(h =>
      h.some(s => s.month === jan)
    ) ? ' since January' : ' this year';
    lines.push(`<div style="font-size:12px;color:var(--pine);margin-top:3px">Freed minimums${sinceLabel}: +${fmt(freed)}/month</div>`);
  }

  if (plan) {
    lines.push(`<button onclick="showView('reports');setTimeout(()=>_rcOpenReport('debt_payoff'),80)" style="background:none;border:none;padding:0;font-size:12px;color:var(--pine);cursor:pointer;margin-top:6px;text-decoration:underline;text-underline-offset:2px;font-weight:500">See full payoff plan →</button>`);
  }

  // ── Credit utilization summary ──
  const cardsWithLimits = activeDebts.filter(c => c.creditLimit && parseFloat(c.creditLimit) > 0);
  if (cardsWithLimits.length > 0) {
    const totalBal   = cardsWithLimits.reduce((s,c) => s + (_cardBal(c)), 0);
    const totalLimit = cardsWithLimits.reduce((s,c) => s + parseFloat(c.creditLimit), 0);
    const utilPct    = Math.round((totalBal / totalLimit) * 100);
    // A metric, not a prescription: the figure is shown plainly — no target
    // sentence, and no threshold colours that would say the same thing
    // without words. What a "good" utilization is was never Groundwork's to set.
    lines.push(`<div style="font-size:12px;color:var(--slate);margin-top:6px">Combined credit utilization: ${utilPct}% across ${cardsWithLimits.length} card${cardsWithLimits.length!==1?'s':''} with limits.</div>`);
  }

  // V6: say what the projections above assumed for figures that weren't entered.
  const _assumed = _debtAssumptionNote(activeDebts);
  if (_assumed) lines.push(`<div style="font-size:12px;color:var(--gold);margin-top:6px;line-height:1.5">${_assumed}</div>`);

  if (lines.length) {
    summaryEl.innerHTML = lines.join('');
    summaryEl.style.display = 'block';
  }
}


// ── The bank window (gw 2.0/BANK_BROWSER.md) ─────────────────────────────────
// The bank's page opens in its own window - its own process - with nothing
// but the address. Groundwork never reads, fills or watches it. Whatever the
// user downloads there reaches Groundwork only through the Downloads folder
// and the usual offer -> review -> import. Groundwork does not check that an
// address belongs to the bank; the field says so.

const _PORTAL_INPUT_ATTRS = `type="url" placeholder="https://www.yourbank.com" aria-label="Bank website"
          style="font-size:12px;padding:5px 7px;border:1px solid var(--steel);border-radius:var(--r-sm);background:var(--paper);font-family:var(--font-mono)"`;

// The caller writes its own <input> with a literal id, so the ghost-ID
// tripwire in smoke_test.py sees the element every lookup refers to.
function _portalFieldHTML(inputHTML) {
  return `
      <div style="display:flex;flex-direction:column;gap:4px;padding:6px 4px">
        <span style="font-size:11px;color:var(--slate)">Bank website</span>
        ${inputHTML}
        <span style="font-size:11px;color:var(--slate-2);line-height:1.5">This is the address Groundwork will open. Groundwork doesn't check that it belongs to your bank. Make sure it does.</span>
      </div>`;
}

function _portalButtonsHTML(kind, id) {
  const btn = `font-size:11px;font-family:inherit;border-radius:var(--r-md);padding:4px 9px;cursor:pointer;white-space:nowrap`;
  return `
      <button onclick="_openBankPortal('${kind}', ${id}, 'window')" title="Open your bank's website in its own window"
        style="${btn};background:var(--sky);color:#fff;border:none">Open bank</button>
      <button onclick="_openBankPortal('${kind}', ${id}, 'browser')" title="Open your bank's website in your usual browser"
        style="${btn};background:none;border:1px solid var(--steel-2);color:var(--ink)">Open in my browser</button>`;
}

async function _openBankPortal(kind, id, mode) {
  const base = kind === 'account' ? `/api/accounts/${id}` : `/api/debt/${id}`;
  try {
    const res = await API.post(`${base}/portal/open`, { mode });
    const result = res?.result;
    if (result === 'opened' || result === 'already_open') _autoImportFastUntil = Date.now() + 30 * 60 * 1000;
    if (result === 'engine_unavailable') {
      confirmAction(
        "Groundwork can't open your bank here on this computer",
        `<div style="line-height:1.7;font-size:13px;color:var(--slate)">This computer's built-in web engine isn't available to Groundwork, so the bank can't open in its own window. Your usual browser works the same way: download your transactions or statement there and Groundwork will offer to import them.</div>`,
        () => _openBankPortal(kind, id, 'browser'),
        'Open in my browser',
        false
      );
    } else if (result === 'already_open') {
      showToast('Your bank is already open', 'Look for its window.', 'success');
    } else {
      showToast(mode === 'browser' ? 'Opened in your browser' : 'Bank website opened',
        'Save your download to your Downloads folder and Groundwork will offer to import it. Saved somewhere else? Use Import file.',
        'success');
    }
  } catch(e) {
    showToast('Could not open your bank', e.message || '', 'error');
  }
}

async function _debtLinkPortalConflict(dbId, acctId, portalKeep) {
  // Try the link change as-is. If it would put two different bank websites on
  // one card the server refuses it with a 409 carrying the conflict; if not,
  // it has simply been applied, and the caller's own PATCH repeats it harmlessly.
  if (portalKeep) return null;
  const r = await _gwFetch(`/api/debt/${dbId}`, {
    method: 'PATCH', headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ linked_account_id: acctId }),
  });
  if (r.status !== 409) return null;
  const j = await r.json().catch(() => ({}));
  return j.portal_conflict || null;
}

function _askPortalConflict(conflict, done) {
  document.getElementById('portalConflictPrompt')?.remove();
  const el = document.createElement('div');
  el.id = 'portalConflictPrompt';
  el.style.cssText = `
    position:fixed;bottom:24px;left:50%;transform:translateX(-50%);
    background:var(--paper);border:1px solid var(--steel);border-left:3px solid var(--sky);
    border-radius:var(--r-lg);box-shadow:var(--shadow-md);padding:14px 18px;
    max-width:480px;width:calc(100vw - 48px);z-index:200;display:flex;flex-direction:column;gap:10px;`;
  const b = `font-size:12px;font-family:inherit;border-radius:var(--r-md);padding:6px 12px;cursor:pointer`;
  el.innerHTML = `
    <div style="font-size:13px;color:var(--ink);line-height:1.5">
      This card opens <b style="font-weight:600;word-break:break-all">${esc(conflict.card_url)}</b>, and
      <b style="font-weight:600">${esc(conflict.account_name)}</b> opens <b style="font-weight:600;word-break:break-all">${esc(conflict.account_url)}</b>.
      A linked card uses one bank website. Which one?
    </div>
    <div style="display:flex;gap:8px;flex-wrap:wrap">
      <button data-keep="card" style="${b};background:var(--sky);color:#fff;border:none">Keep the card's</button>
      <button data-keep="account" style="${b};background:var(--sky);color:#fff;border:none">Keep ${esc(conflict.account_name)}'s</button>
      <button data-keep="" style="${b};background:none;border:1px solid var(--steel-2);color:var(--ink)">Don't link</button>
    </div>`;
  el.querySelectorAll('button').forEach(btn => btn.addEventListener('click', () => {
    el.remove();
    done(btn.dataset.keep || null);
  }));
  document.body.appendChild(el);
}

async function _bloomLoadPortal(el) {
  const dbId = parseInt(el?.dataset.dbId);
  if (!dbId) return;
  let d;
  try { d = await API.get(`/api/debt/${dbId}/portal`); } catch(e) { return; }
  const box = `padding:10px 12px;background:var(--mist);border-radius:var(--r-sm)`;
  if (d.owner === 'account') {
    el.innerHTML = `<div style="${box}">
      <div style="font-size:10px;font-weight:600;letter-spacing:.06em;text-transform:uppercase;color:var(--slate);margin-bottom:6px">Bank website</div>
      ${d.url
        ? `<div style="font-size:12px;color:var(--ink);margin-bottom:8px">Uses <b style="font-weight:600">${esc(d.account_name || 'its account')}</b>'s bank website. Change it in Settings → Accounts.</div>
           <div style="display:flex;gap:6px;flex-wrap:wrap">${_portalButtonsHTML('card', dbId)}</div>`
        : `<div style="font-size:12px;color:var(--slate-2)">No bank website yet. Add one to <b style="font-weight:600">${esc(d.account_name || 'its account')}</b> in Settings → Accounts.</div>`}
    </div>`;
    return;
  }
  el.innerHTML = `<div style="${box}">
    ${_portalFieldHTML(`<input id="bloomPortal${dbId}" value="${esc(d.url || '')}" ${_PORTAL_INPUT_ATTRS}>`)}
    <div style="display:flex;gap:6px;flex-wrap:wrap;padding:0 4px">
      <button onclick="_bloomSavePortal(${dbId})" class="btn btn-primary btn-sm">Save website</button>
      ${d.url ? _portalButtonsHTML('card', dbId) : ''}
    </div>
  </div>`;
}

async function _bloomSavePortal(dbId) {
  const input = g(`bloomPortal${dbId}`);
  if (!input) return;
  try {
    await API.put(`/api/debt/${dbId}/portal`, { url: input.value.trim() });
    showToast('Bank website saved', '', 'success');
    _bloomLoadPortal(input.closest('.bloom-portal'));
  } catch(e) {
    showToast('Bank website not saved', e.message || '', 'warning');
  }
}

function _budgetOpenDebtBloom(row, card) {
  _budgetCloseAllBlooms();
  const bloom = _budgetBuildDebtBloom(card);
  row.replaceWith(bloom);
  _budgetDebtBloomCalc(bloom);
}

// B4: Pending APR change alerts — set after import, consumed when bloom opens.
// Shape: [{ debt_id, debt_name, stored_apr, implied_apr, interest_charge, month }]
let _pendingAprAlerts = [];

function _showAprChangeAlerts(alerts) {
  // Store alerts — they display the next time the affected debt bloom opens.
  // Also show a quiet toast so the user knows something needs attention.
  _pendingAprAlerts = alerts;
  const names = alerts.map(a => a.debt_name).join(', ');
  showToast(
    'APR may have changed',
    `Open ${names} in the debt section to review.`,
    'warning'
  );
}

// Called from _budgetBuildDebtBloom to inject the APR alert when present.
function _budgetAprAlertHTML(card) {
  const alert = _pendingAprAlerts.find(a => a.debt_id === card._dbId);
  if (!alert) return '';
  return `
    <div style="margin-bottom:14px;padding:12px 14px;background:var(--gold-bg);
                border:1px solid var(--gold-border);border-radius:var(--r-sm);
                font-size:12px;line-height:1.6">
      <div style="font-weight:600;color:#92400e;margin-bottom:6px">⚠ APR may have changed</div>
      <div style="color:var(--ink)">
        Groundwork calculated <strong style="font-family:var(--font-mono)">${alert.implied_apr}%</strong>
        from your ${alert.month || 'recent'} interest charge of
        <strong style="font-family:var(--font-mono)">${fmt(alert.interest_charge)}</strong>.
        Your stored rate is <strong style="font-family:var(--font-mono)">${alert.stored_apr}%</strong>
        — a difference of <strong>${Math.abs(alert.implied_apr - alert.stored_apr).toFixed(1)} points</strong>.
      </div>
      <div style="display:flex;gap:8px;margin-top:10px;flex-wrap:wrap">
        <button class="btn btn-sm btn-ghost"
          onclick="_budgetApplyAprUpdate(${card.id}, ${card._dbId}, ${alert.implied_apr})">
          Update to ${alert.implied_apr}%
        </button>
        <button class="btn btn-sm btn-ghost"
          onclick="_budgetDismissAprAlert(${card._dbId})">
          Keep ${alert.stored_apr}%
        </button>
        <button class="btn btn-sm btn-ghost"
          onclick="_budgetEnterAprManually(this)">
          Enter manually
        </button>
      </div>
      <div style="font-size:11px;color:var(--slate-2);margin-top:6px">
        Verify against your statement before updating. Groundwork never auto-updates your rate.
      </div>
    </div>`;
}

async function _budgetApplyAprUpdate(cardId, dbId, newApr) {
  const card = S.debtCards.find(c => c.id === cardId);
  if (!card) return;
  card.rate = newApr;
  card.rateSource = 'calculated';   // V2: worked out from the interest charged
  if (dbId) {
    await API.patch(`/api/debt/${dbId}`, { interest_rate: newApr, interest_rate_source: 'calculated' }).catch(_gwErr('_budgetApplyAprUpdate'));
    // Write a history snapshot with the new APR
    _budgetSaveDebtSnapshot(_budgetMonthKey);
  }
  _pendingAprAlerts = _pendingAprAlerts.filter(a => a.debt_id !== dbId);
  showToast(`APR updated to ${newApr}%`, `${card.name} amortization recalculated.`, 'success');
  renderBudget();
}

function _budgetDismissAprAlert(dbId) {
  _pendingAprAlerts = _pendingAprAlerts.filter(a => a.debt_id !== dbId);
  renderBudget();
}

function _budgetEnterAprManually(btn) {
  const bloom  = btn.closest('.budget-bloom');
  const aprIn  = bloom?.querySelector('.bloom-debt-apr');
  if (aprIn) { aprIn.focus(); aprIn.select(); }
  btn.closest('div[style*="display:flex"]')?.parentElement?.remove();
}

function _budgetBuildDebtBloom(card) {
  const bal     = _cardBal(card);
  const apr     = parseFloat(card.rate) || 0;
  const min     = parseFloat(card.minimum) || 0;
  const calcMin = bal > 0 && apr > 0 ? _calcMinPayment(bal, apr) : min;
  const limit   = card.creditLimit ? parseFloat(card.creditLimit) : '';

  // B2: Build account link selector from S.accounts
  const acctOptions = S.accounts
    .filter(a => a.is_active !== false)
    .map(a => `<option value="${a.id}" ${card.linkedAccountId == a.id ? 'selected' : ''}>${esc(a.name)}</option>`)
    .join('');

  const linkSection = `
    <div style="margin-bottom:14px;padding:10px 12px;background:var(--mist);border-radius:var(--r-sm)">
      <div style="font-size:10px;font-weight:600;letter-spacing:.06em;text-transform:uppercase;color:var(--slate);margin-bottom:6px">
        Link to imported account
        <span title="Link this debt card to one of your imported bank accounts. After linking, importing that account's statement will automatically update this card's balance." style="cursor:help;color:var(--slate-2)"> ⓘ</span>
      </div>
      <select class="bloom-debt-link"
        onchange="_budgetBloomLinkAccount(this)"
        style="width:100%;font-size:12px;border:1px solid var(--steel);border-radius:var(--r-sm);padding:6px 9px;background:var(--paper);color:var(--ink)">
        <option value="">Not linked</option>
        ${acctOptions}
      </select>
      ${card.linkedAccountId
        ? `<div style="font-size:11px;color:var(--pine);margin-top:5px">● Importing this account updates this card's balance automatically.</div>`
        : `<div style="font-size:11px;color:var(--slate-2);margin-top:5px">Import a statement from a linked account to keep this balance current.</div>`}
    </div>
    ${card._dbId ? `<div class="bloom-portal" data-db-id="${card._dbId}" style="margin-bottom:14px"></div>` : ''}`;

  // Balance cross-check: if calculated balance from imports differs from entered
  const calcBal = card.calculatedBalance;
  const crossCheck = (calcBal !== null && calcBal !== undefined && Math.abs(calcBal - bal) > 1)
    ? `<div style="margin-bottom:12px;padding:10px 12px;background:var(--mist);border:1px solid var(--steel);border-radius:var(--r-sm);font-size:12px;line-height:1.6">
        ${card.balanceBasis === 'bank'
          ? `Your bank's last reported balance is ${fmt(calcBal)}. You entered ${fmt(bal)}.`
          : `Imported activity adds up to ${fmt(calcBal)}. You entered ${fmt(bal)}.`}<br>
        Difference: ${fmt(Math.abs(calcBal - bal))} — likely interest or a fee.<br>
        <div style="font-size:11px;color:var(--slate-2);margin-top:4px">Updates the balance field below. Hit Save to apply.</div>
        <div style="display:flex;gap:8px;margin-top:8px">
          <button class="btn btn-sm btn-ghost" onclick="_budgetCrossCheckUse(this,'${calcBal}')">Use Groundwork's ${fmt(calcBal)}</button>
          <button class="btn btn-sm btn-ghost" onclick="_budgetCrossCheckUse(this,'${bal}')">Use statement's ${fmt(bal)}</button>
        </div>
      </div>`
    : '';

  const bloom = document.createElement('div');
  bloom.className = 'budget-bloom';
  bloom.dataset.bloomType = 'debt';
  bloom.dataset.debtId = card.id;
  bloom.style.cssText = 'border-left:3px solid var(--ember);background:var(--ember-bg);padding:14px 16px;border-radius:var(--r-sm);margin:4px 0';
  bloom.innerHTML = `
    <div style="font-size:13px;font-weight:600;color:var(--ink);margin-bottom:12px">${esc(card.name||'Debt account')}</div>
    ${_budgetAprAlertHTML(card)}
    ${crossCheck}
    <div style="font-size:10px;font-weight:600;letter-spacing:.06em;text-transform:uppercase;color:var(--slate);margin-bottom:8px">Payment</div>
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:14px">
      <div>
        <label style="font-size:11px;color:var(--slate);display:block;margin-bottom:3px">This month's payment</label>
        <input type="number" class="bloom-debt-payment" min="0" step="0.01" value="${(min!=null&&min!=='')?min:(calcMin||'')}"
          oninput="_budgetDebtBloomCalc(this.closest('.budget-bloom'))"
          style="width:100%;font-family:var(--font-mono);font-size:13px;border:1px solid var(--steel);border-radius:var(--r-sm);padding:6px 9px;background:var(--paper);color:var(--ink)">
        <div style="font-size:11px;color:var(--slate-2);margin-top:3px">
          Minimum: <span class="bloom-min-display" style="font-family:var(--font-mono)">${fmt(calcMin)}</span>
        </div>
      </div>
      <div>
        <label style="font-size:11px;color:var(--slate);display:block;margin-bottom:3px">Due day of month</label>
        <input type="number" class="bloom-debt-due" min="1" max="31" value="${card.dueDay!=null?card.dueDay:''}"
          style="width:100%;font-family:var(--font-mono);font-size:13px;border:1px solid var(--steel);border-radius:var(--r-sm);padding:6px 9px;background:var(--paper);color:var(--ink)">
      </div>
    </div>
    <div style="font-size:10px;font-weight:600;letter-spacing:.06em;text-transform:uppercase;color:var(--slate);margin-bottom:8px">Balance and rate — enter from your statement</div>
    <div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:10px;margin-bottom:14px">
      <div>
        <label style="font-size:11px;color:var(--slate);display:block;margin-bottom:3px">Current balance</label>
        <input type="number" class="bloom-debt-bal" min="0" step="0.01" value="${bal!=null?bal:''}"
          oninput="_budgetDebtBloomCalc(this.closest('.budget-bloom'))"
          style="width:100%;font-family:var(--font-mono);font-size:13px;border:1px solid var(--steel);border-radius:var(--r-sm);padding:6px 9px;background:var(--paper);color:var(--ink)">
      </div>
      <div>
        <label style="font-size:11px;color:var(--slate);display:block;margin-bottom:3px">APR (%)</label>
        <input type="number" class="bloom-debt-apr" min="0" max="100" step="0.1" value="${apr!=null?apr:''}"
          oninput="_budgetDebtBloomCalc(this.closest('.budget-bloom'))"
          style="width:100%;font-family:var(--font-mono);font-size:13px;border:1px solid var(--steel);border-radius:var(--r-sm);padding:6px 9px;background:var(--paper);color:var(--ink)">
      </div>
      <div>
        <label style="font-size:11px;color:var(--slate);display:block;margin-bottom:3px">
          Credit limit
          <span title="Optional. Groundwork uses this only to calculate your utilization ratio — it never leaves your computer." style="cursor:help;color:var(--slate-2)">ⓘ</span>
        </label>
        <input type="number" class="bloom-debt-limit" min="0" step="0.01" value="${limit!=null?limit:''}"
          oninput="_budgetDebtBloomCalc(this.closest('.budget-bloom'))"
          style="width:100%;font-family:var(--font-mono);font-size:13px;border:1px solid var(--steel);border-radius:var(--r-sm);padding:6px 9px;background:var(--paper);color:var(--ink)">
      </div>
    </div>
    <div class="bloom-debt-estimate" style="display:none;margin-bottom:14px;padding:10px 12px;background:var(--mist);border-radius:var(--r-sm)">
      <div style="font-size:10px;font-weight:600;letter-spacing:.06em;text-transform:uppercase;color:var(--slate);margin-bottom:8px">Groundwork's estimate</div>
      <div class="bloom-est-rows" style="display:flex;flex-direction:column;gap:5px;font-size:12px"></div>
    </div>
    ${linkSection}
    <div style="display:flex;gap:8px;flex-wrap:wrap">
      <button class="btn btn-sm btn-primary" onclick="_budgetSaveDebtBloom(this)">Save</button>
      <button class="btn btn-sm btn-ghost"   onclick="_budgetCancelBloom(this)">Cancel</button>
      <button class="btn btn-sm btn-ghost" style="margin-left:auto;color:var(--slate)" onclick="showView('debt')">Full payoff plan →</button>
    </div>
  `;
  bloom.querySelectorAll('.bloom-portal').forEach(_bloomLoadPortal);
  return bloom;
}

function _budgetDebtBloomCalc(bloom) {
  if (!bloom) return;
  const bal  = parseFloat(bloom.querySelector('.bloom-debt-bal')?.value)     || 0;
  const apr  = parseFloat(bloom.querySelector('.bloom-debt-apr')?.value)     || 0;
  const pmt  = parseFloat(bloom.querySelector('.bloom-debt-payment')?.value) || 0;
  const lim  = parseFloat(bloom.querySelector('.bloom-debt-limit')?.value)   || 0;

  const calcMin = bal > 0 && apr > 0 ? _calcMinPayment(bal, apr) : 0;
  const minDisp = bloom.querySelector('.bloom-min-display');
  if (minDisp && calcMin > 0) minDisp.textContent = fmt(calcMin);

  const estBox  = bloom.querySelector('.bloom-debt-estimate');
  const estRows = bloom.querySelector('.bloom-est-rows');
  if (!estBox || !estRows) return;

  if (bal <= 0 || apr <= 0) { estBox.style.display = 'none'; return; }

  const effectivePmt = pmt > 0 ? pmt : calcMin;
  const snaps        = _projectPayoff(bal, apr, effectivePmt);
  // V11: minimums only as everywhere else - the minimum falling with the balance,
  // not today's frozen for the life of the debt. Compared only when both finish.
  const minOnly      = _minimumsOnly([{ balance: bal, rate: apr, minimum: calcMin, debtType: 'credit' }]);

  if (!snaps.length) { estBox.style.display = 'none'; return; }

  const provable    = minOnly && !minOnly.capped && !snaps[snaps.length - 1].noPayoff;
  const totalInt    = Math.round(snaps.reduce((s, r) => s + r.interest, 0) * 100) / 100;
  const savesInt    = provable ? Math.round((minOnly.totalInterest - totalInt) * 100) / 100 : 0;
  const savesMo     = provable ? minOnly.months - snaps.length : 0;

  const rows = [];
  rows.push(`<div style="display:flex;justify-content:space-between">
    <span style="color:var(--slate)">Payoff date at this payment alone</span>
    <span style="font-family:var(--font-mono);color:var(--ink);font-weight:500">${_payoffDateLabel(snaps.length)}</span>
  </div>`);
  rows.push(`<div style="display:flex;justify-content:space-between">
    <span style="color:var(--slate)">Total remaining interest</span>
    <span style="font-family:var(--font-mono);color:var(--ember)">${fmt(totalInt)}</span>
  </div>`);
  if (savesInt > 0 || savesMo > 0) {
    rows.push(`<div style="display:flex;justify-content:space-between">
      <span style="color:var(--slate)">vs. minimums only</span>
      <span style="font-family:var(--font-mono);color:var(--pine)">${savesInt > 0 ? `${fmt(savesInt)} less interest` : ''}${savesInt > 0 && savesMo > 0 ? ' · ' : ''}${savesMo > 0 ? `${savesMo} month${savesMo!==1?'s':''} sooner` : ''}</span>
    </div>`);
  }
  if (lim > 0 && bal > 0) {
    const utilPct = Math.round((bal / lim) * 100);
    // The figure only — no "aim for", no "good", no threshold colour.
    rows.push(`<div style="display:flex;justify-content:space-between;align-items:center">
      <span style="color:var(--slate)">Utilization</span>
      <span style="font-family:var(--font-mono)">${utilPct}%</span>
    </div>`);
  }

  estRows.innerHTML = rows.join('');
  estBox.style.display = 'block';
}

function _budgetCrossCheckUse(btn, value) {
  const bloom    = btn.closest('.budget-bloom');
  const balInput = bloom?.querySelector('.bloom-debt-bal');
  if (balInput) { balInput.value = parseFloat(value); _budgetDebtBloomCalc(bloom); }
  btn.closest('div[style*="display:flex"]')?.parentElement?.remove();
}

// B2: Handle account link change in debt bloom
async function _budgetBloomLinkAccount(select, portalKeep) {
  const bloom  = select.closest('.budget-bloom');
  const cardId = parseInt(bloom?.dataset.debtId);
  const card   = S.debtCards.find(c => c.id === cardId);
  if (!card) return;

  const acctId = select.value ? parseInt(select.value) : null;
  const prevAcctId = card.linkedAccountId;

  // A card and an account that each have a different bank website: the user
  // chooses which one the linked card uses. Groundwork never picks (F3).
  if (card._dbId) {
    const conflict = await _debtLinkPortalConflict(card._dbId, acctId, portalKeep);
    if (conflict) {
      _askPortalConflict(conflict, keep => {
        if (keep) _budgetBloomLinkAccount(select, keep);
        else select.value = prevAcctId ?? '';
      });
      return;
    }
  }
  card.linkedAccountId = acctId;

  // Persist immediately — don't wait for Save
  if (card._dbId) {
    try {
      const res = await API.patch(`/api/debt/${card._dbId}`, { linked_account_id: acctId, portal_keep: portalKeep || null });
      // Server returns fresh calculated_balance after link change
      if (res?.calculated_balance !== undefined) {
        card.calculatedBalance = res.calculated_balance;
        card.linkedTxnCount   = res.linked_txn_count ?? null;
      } else if (res?.data?.calculated_balance !== undefined) {
        card.calculatedBalance = res.data.calculated_balance;
        card.linkedTxnCount   = res.data.linked_txn_count ?? null;
      }
      // Refresh the bloom to show updated cross-check state
      const row = document.querySelector(`[data-debt-id="${cardId}"]`);
      _budgetCloseAllBlooms();
      if (row) _budgetOpenDebtBloom(row, card);
      else renderBudget();
    } catch(e) {
      showToast('Could not save link', 'Check your connection', 'error');
    }
  }
}

function _budgetSaveDebtBloom(btn) {
  const bloom  = btn.closest('.budget-bloom');
  const cardId = parseInt(bloom.dataset.debtId);
  const card   = S.debtCards.find(c => c.id === cardId);
  if (!card) return;

  // BUG FIX (July 6): every field below used `if (fieldValue)` — a truthy
  // check — to decide both (a) whether to update the local card object and
  // (b) whether to include the field in the save payload. But 0 is a
  // legitimate, intentional value: a debt paid down to exactly $0, a 0%
  // APR promotional card, a due day or credit limit someone is explicitly
  // clearing. A truthy check treats "the user set this to zero" identically
  // to "the user left this blank" — so the edit gets silently dropped, the
  // API call still reports success, but the real value never changes.
  // Confirmed in the field: users could not save an edited amount. Fixed
  // by checking whether the raw input was actually non-empty (was this
  // field touched at all), not whether its parsed number is truthy.
  const pmtEl   = bloom.querySelector('.bloom-debt-payment');
  const dueEl   = bloom.querySelector('.bloom-debt-due');
  const balEl   = bloom.querySelector('.bloom-debt-bal');
  const aprEl   = bloom.querySelector('.bloom-debt-apr');
  const limitEl = bloom.querySelector('.bloom-debt-limit');

  const pmtTouched   = !!pmtEl   && pmtEl.value   !== '';
  const dueTouched   = !!dueEl   && dueEl.value   !== '';
  const balTouched   = !!balEl   && balEl.value   !== '';
  const aprTouched   = !!aprEl   && aprEl.value   !== '';
  const limitTouched = !!limitEl && limitEl.value !== '';

  const pmt   = pmtTouched   ? (parseFloat(pmtEl.value)   || 0) : 0;
  const due   = dueTouched   ? (parseInt(dueEl.value)     || null) : null;
  const bal   = balTouched   ? (parseFloat(balEl.value)   || 0) : 0;
  const apr   = aprTouched   ? (parseFloat(aprEl.value)   || 0) : 0;
  const limit = limitTouched ? (parseFloat(limitEl.value) || null) : null;

  const calcMin = bal > 0 && apr > 0 ? _calcMinPayment(bal, apr) : parseFloat(card.minimum)||0;
  if (pmtTouched && pmt > 0 && pmt < calcMin) {
    showToast(`Minimum is ${fmt(calcMin)}`, 'Payment cannot be below the calculated minimum.', 'warning');
    return;
  }

  // Local state: only overwrite a field if it was actually touched —
  // otherwise preserve whatever the card already had, exactly like the
  // save payload below. This keeps the in-app display correct even before
  // the save round-trips.
  if (pmtTouched)   card.minimum     = pmt || calcMin;
  if (dueTouched)   card.dueDay      = due;
  if (balTouched)   card.currentBal  = bal;
  if (aprTouched)   card.rate        = apr;
  if (limitTouched) card.creditLimit = limit;

  if (card._dbId) {
    const payload = {};
    if (pmtTouched)   payload.minimum_payment = pmt || calcMin;
    if (dueTouched)   payload.due_day         = due;
    if (balTouched)   payload.current_balance = bal;
    if (aprTouched)   payload.interest_rate   = apr;
    if (limitTouched) payload.credit_limit    = limit;
    API.patch(`/api/debt/${card._dbId}`, payload).catch(_gwErr('_budgetSaveDebtBloom'));
    _budgetSaveDebtSnapshot(_budgetMonthKey);
  }

  renderBudget();
  renderDashboard();   // mission card, freed minimums widget
  updateNetWorth();    // liabilities update immediately
  _refreshDebtIfActive(); // debt page card list stays current
}

