// ─── Debt payoff ───────────────────────────────────────────────────────────────
const DEBT_ACH_IDS = ['full_picture','real_cost','above_minimum','chipping_away',
  'halfway','first_card_down','interest_slayer','zero'];

function addCard(name='',beginBal='',startDate='',rate='',minimum='',currentBal='',dueDay='',_dbId=null,paidInFull=false,context='',debtType='credit',linkedAccountId=null,calculatedBalance=null,creditLimit=null,endDate='',linkedTxnCount=null) {
  const id = S.debtIdCounter++;
  const card = {id,name,beginBal,startDate,endDate:endDate||'',rate,minimum,
                currentBal:currentBal||beginBal,dueDay,_dbId,
                paidInFull:paidInFull||false,
                context:context||'',
                debtType:debtType||'credit',
                linkedAccountId: linkedAccountId || null,
                calculatedBalance: calculatedBalance,
                linkedTxnCount:   linkedTxnCount,     // null = unknown, 0 = no txns, N = count
                creditLimit: creditLimit,
               };
  S.debtCards.push(card);
  _renderCardList();
}

function setCardPaidInFull(id, checked) {
  const card = S.debtCards.find(c => c.id === id);
  if (!card) return;
  // INVARIANT (d21, Option 2): paidInFull is a display flag only. This function
  // must NEVER write to currentBal/beginBal — the struck-through balance in the
  // card row is styling on the untouched value, so unchecking is fully lossless.
  card.paidInFull = checked;
  // Stamp the payoff date (kept on uncheck-recheck within a day; cleared on
  // uncheck). _syncDebtToDb sends it as paid_off_at — the persistence half
  // of the paid flag, which was missing entirely until d21.
  card.paidOffAt  = checked ? (card.paidOffAt || new Date().toISOString().slice(0,10)) : null;
  setCardField(id, 'paidInFull', checked);
  calculate();

  if (checked) {
    // ── Cascade: update every surface that reads S.debtCards ──────────────
    renderDashboard();                          // mission card, freed minimums
    updateNetWorth();                           // liabilities drop immediately
    // Item 38 P1: the payoff is a note on this month's snapshot - the one real snapshot carries it (a month already
    // taken gets the note added, its figures untouched). It used to post a second "marker" snapshot with no figures,
    // which recorded a $0 net worth whenever it reached the server first.
    autoSnapshotNetWorthIfDue(`Paid off: ${card.name || 'Debt account'}`);
    buildFinancialProfile().catch(_gwErr('setCardPaidInFull'));    // debt trajectory stale

    // ── Re-render the Debt page row in paid-off pine state ────────────────
    const row = g(`dc-${id}`);
    if (row) {
      // Find next avalanche target for the freed-minimum sentence
      const remaining = S.debtCards.filter(c => !c.paidInFull && c.id !== id);
      const nextTarget = [...remaining]
        .filter(c => parseFloat(c.rate) > 0)
        .sort((a,b) => parseFloat(b.rate) - parseFloat(a.rate))[0] || remaining[0];
      const min      = parseFloat(card.minimum) || 0;
      const paidMo   = new Date().toLocaleDateString('en-US', { month:'long', year:'numeric' });
      const nextName = nextTarget?.name || 'your next target';

      row.outerHTML = _paidOffCardHTML(card, min, paidMo, nextName, nextTarget);
    }

    // ── Celebration overlay ───────────────────────────────────────────────
    _showCardPaidOffCelebration(card.name || 'Card');
    _refreshBudgetIfActive();
  } else {
    // Un-marking paid in full — restore normal row
    const row = g(`dc-${id}`);
    if (row) row.outerHTML = _debtCardRowHTML(card);
    renderDashboard();
    updateNetWorth();
  }
}

