function calcDailyInterest() {
  // Exclude paid-in-full cards and expired leases/loans
  const today = new Date().toISOString().slice(0, 10);
  return S.debtCards
    .filter(c => !c.paidInFull && !(c.endDate && c.endDate < today))
    .reduce((sum, c) => {
      const bal  = _cardBal(c);
      const rate = parseFloat(c.rate) || 0;
      return sum + (bal * (rate / 100) / 365);
    }, 0);
}

// ─── Phase 9C: Payoff date on dashboard ──────────────────────────────────────

function _getPayoffDateString() {
  const result = _simulatePayoff(0);
  if (!result || !result.freeDate) return null;
  return result.freeDate;
}


// ─── Phase 9D: Stage-aware AI ────────────────────────────────────────────────
// All AI prompts read calcUserStage() and adjust tone and focus accordingly.
// 'debt'       → focus on payoff date, interest savings, spending habits
// 'transition' → acknowledge progress, introduce wealth-building concept
// 'wealth'     → focus on savings rate, net worth trajectory, investment pace

function _buildStageContext() {
  const stage     = calcUserStage();
  const lean      = calcLeanMode();
  const hasBuffer = calcHasEmergencyBuffer();
  const _active   = _activeDebtCards();
  const totalDebt = _active.reduce((s,c)=>s+(_cardBal(c)),0);
  const beginDebt = _active.reduce((s,c)=>s+(parseFloat(c.beginBal)||0),0);
  const pctPaid   = beginDebt > 0 ? ((beginDebt-totalDebt)/beginDebt*100).toFixed(0) : 0;
  const freeDate  = _simulatePayoff(0);
  const daily     = calcDailyInterest();
  const monthly   = daily * 30;
  const nw        = S.netWorth;
  const netWorth  = (nw.savings||0)+(nw.investments||0)+(nw.cash||0)+(nw.homeValue||0)
                   -_nwMortgageInfo().counted-totalDebt;   // V9

  // ── Variable income detection ─────────────────────────────────────────────
  // If the user's actual monthly income varies significantly (freelancers,
  // contractors, commission), flag this so the AI doesn't treat a low-deposit
  // month as a failure. Uses last 6 months of transaction income if available.
  let variableIncomeNote = '';
  try {
    const now = new Date();
    const monthlyIncome = [];
    for (let i = 1; i <= 6; i++) {
      const d = new Date(now.getFullYear(), now.getMonth() - i, 1);
      const key = `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;
      const inc = S.transactions
        .filter(t => t.date?.startsWith(key) && t.type === 'credit' &&
                    (t.category === 'Income' || t.category === 'income'))
        .reduce((s,t) => s + t.amount, 0);
      if (inc > 0) monthlyIncome.push(inc);
    }
    if (monthlyIncome.length >= 3) {
      const avg = monthlyIncome.reduce((s,v) => s+v, 0) / monthlyIncome.length;
      const variance = monthlyIncome.reduce((s,v) => s + Math.pow(v-avg,2), 0) / monthlyIncome.length;
      const cv = Math.sqrt(variance) / avg; // coefficient of variation
      if (cv > 0.25) {
        variableIncomeNote = `\nIMPORTANT — This user has variable income (month-to-month variation ~${Math.round(cv*100)}%). ` +
          `Do NOT treat a below-average income month as a failure or spending problem — ` +
          `it may simply be a slow invoice month. Focus analysis on spending patterns, not income shortfalls.`;
      }
    }
  } catch(e) { /* non-fatal */ }

  // Lean mode context added to every AI prompt when margin is thin
  const leanContext = lean
    ? `IMPORTANT — This user is in lean budget mode (under $200/month surplus after all expenses and debt payments). 
Every dollar redirected has to come from somewhere specific. 
${!hasBuffer ? 'They have no emergency buffer yet — gently prioritize building $500 in savings before aggressive debt acceleration.' : 'They have a small emergency buffer in place.'}
Do NOT use aspirational language like "financial journey" or "excellent progress." 
Instead: be plain, specific, and acknowledge the difficulty. 
Celebrate concrete dollar amounts saved, not abstract milestones.
Use language like "you kept $X that would have been interest" not "you're making great strides."
If you name a next step, name only one, and only using a number already given above, stated as
a plain fact — not a command or suggestion, and never a number you calculate yourself. Write
"X carries the highest rate at Y%," never "Consider paying more on X" or "You should redirect...".`
    : '';

  // Debt origin context — user-supplied notes on where the debt came from
  // Changes how AI writes about payoff progress in monthly reports
  const debtContexts = S.debtCards
    .filter(c => c.context && !c.paidInFull)
    .map(c => `${c.name||'Debt'}: "${c.context}"`)
    .join('; ');
  const debtContextNote = debtContexts
    ? `\nDebt origin context: ${debtContexts}. Factor this into your tone — debt from divorce, medical emergencies, or business failures carries different weight than discretionary spending.`
    : '';

  // ── Life stage flags — PSLF and commission mode ───────────────────────────
  const pslfCards    = S.debtCards.filter(c => _pslfIsFlagged(c._dbId || c.id));
  const pslfNote     = pslfCards.length > 0
    ? `\nIMPORTANT — The following loan(s) are on income-based forgiveness (PSLF/IBR/SAVE): ${pslfCards.map(c => {
        const key  = c._dbId || c.id;
        const data = _pslfData(key);
        const made = data?.paymentsMade || 0;
        const remaining = Math.max(0, 120 - made);
        return `${c.name}${made > 0 ? ` (${made}/120 qualifying payments — ${remaining} to go)` : ''}`;
      }).join(', ')}. NEVER recommend accelerating payoff on these loans. Strategic minimum payment is the financially correct move. Exclude them from avalanche/snowball ordering. ${pslfCards.some(c => (_pslfData(c._dbId||c.id)?.paymentsMade||0) > 100) ? 'This user is CLOSE to PSLF forgiveness — acknowledge this milestone.' : ''}`
    : '';

  const commNote = S.lifeStage?.commissionMode
    ? `\nIMPORTANT — This user is on commission or has irregular income. Do NOT frame monthly income variation as a problem or failure. Focus entirely on spending patterns and sinking fund health. The monthly income number may look low — that is normal for this user.`
    : '';

  // Pay frequency context
  const payFreq = S.lifeStage?.payFrequency || null;
  const payFreqNote = (payFreq === 'weekly' || payFreq === 'biweekly')
    ? `\nNote: User is paid ${payFreq}. Monthly budget comparisons may appear uneven mid-month — this is expected, not a spending problem.`
    : '';

  const stageNote = {
    debt:
      `User is in the debt payoff phase. ${pctPaid}% of starting debt paid. ` +
      `Debt-free date: ${freeDate?.freeDate||'unknown'}. ` +
      `Interest burning: ${fmt(daily)}/day ($${Math.round(monthly)}/month) — estimated from each card's APR × current balance, NOT posted interest charges; if you cite it, say "roughly" or "an estimated", never present it as a billed figure. ` +
      `Keep all advice focused on debt payoff, spending habits, and momentum. ` +
      `Do not discuss investments yet. Mention wealth building only as a future reward.` +
      debtContextNote + pslfNote + commNote + payFreqNote,
    transition:
      `User has paid off ${pctPaid}% of their debt — real progress. ` +
      `Debt-free date: ${freeDate?.freeDate||'unknown'}. ` +
      `They are in the transition phase. Acknowledge their momentum. ` +
      `Begin gently introducing what happens when the debt is gone — ` +
      `emergency fund, redirecting minimums to savings. Keep it light. ` +
      `Debt payoff is still the primary focus.` +
      pslfNote + commNote + payFreqNote,
    wealth:
      `User is in the wealth-building phase — debt is essentially gone. ` +
      `Net worth: ${fmt(netWorth)}. ` +
      `Focus entirely on savings rate, net worth growth, investment pace, ` +
      `and retirement trajectory. Debt is behind them. ` +
      `Celebrate that and point forward.` +
      commNote + payFreqNote,
  }[stage] + variableIncomeNote + _householdIncomeNote();

  return { stage, lean, hasBuffer, stageNote, leanContext, totalDebt, pctPaid, freeDate, daily, monthly, netWorth };
}

// ─── Phase 9E: Stage-aware monthly report ────────────────────────────────────

// ── Profile context builder — converts S.profile into a clean prompt block ────
function _buildProfileContext() {
  const p = S.profile;
  if (!p) return '';

  const lines = ['HISTORICAL CONTEXT (12 months of data — use this to write about patterns, not just this month):'];

  // Income character
  if (p.income) {
    const inc = p.income;
    if (inc.isVariable) {
      lines.push(`- Income: Variable (${Math.round(inc.variabilityCV * 100)}% volatility). 6-month average: ${fmt(inc.avg6)}/month. Do NOT treat low-income months as failures — they are part of a known pattern.`);
    } else {
      lines.push(`- Income: Stable. 6-month average: ${fmt(inc.avg6)}/month. Trend: ${inc.trendDir}.`);
    }
  }

  // Behavioral history
  if (p.behavior) {
    const b = p.behavior;
    lines.push(`- Budget performance: ${b.greenMonths12} of last 12 months under budget (${b.greenMonthRate}% green rate). Current streak: ${b.currentStreak} month${b.currentStreak !== 1 ? 's' : ''}.`);
    if (b.mostOverageCategory) {
      lines.push(`- Most consistent overage category: ${b.mostOverageCategory} — this has been a recurring pattern, not just a one-month slip.`);
    }
    // Best month insight — surface when we're in a historically strong month
    if (b.bestPerformingMonth !== undefined && b.bestPerformingMonth !== null) {
      const monthNames = ['January','February','March','April','May','June',
                          'July','August','September','October','November','December'];
      const currentMonth = new Date().getMonth();
      if (b.bestPerformingMonth === currentMonth) {
        lines.push(`- Behavioral pattern: ${monthNames[currentMonth]} is historically this user's strongest budget month. Acknowledge this momentum if it fits the report naturally.`);
      }
    }
  }

  // Debt trajectory — d21 interpretation layer: the narrator gets the
  // reconciled verdict, never two unreconciled numbers to novelize a gap from.
  if (p.debt && (p.debt.beginDebt > 0 || p.debt.totalDebt > 0)) {
    const d = p.debt;
    if (d.payoffImpossible) {
      lines.push(`- Debt: the committed monthly budget does not cover minimum debt payments — no valid payoff projection exists. Treat this as the most important fact about this user's debt situation.`);
    } else if (d.reconciliation) {
      // Verified path: state the computed split. The gap is interest + fees +
      // new charges — a fact to report, not a failure to diagnose.
      const r = d.reconciliation;
      const balLine = r.balanceReduction >= 0
        ? `balances decreased ${fmt(r.balanceReduction)}`
        : `balances INCREASED ${fmt(Math.abs(r.balanceReduction))}`;
      lines.push(`- Debt (verified from ${d.monthsOfHistory} months of balance history — first recorded balance vs latest, all accounts): total payments ${fmt(r.paidTotal)}; ${balLine}; the ${fmt(Math.abs(r.gap))} difference is interest, fees, or new charges. Use ONLY these numbers for any statement about debt payments or principal.`);
      if ((d.paceStatus === 'ahead' || d.paceStatus === 'behind') && Math.abs(d.paceMonths || 0) >= 1) {
        lines.push(`- Debt pace (schedule-verified, same engine as the projection): debt-free date is ${Math.abs(d.paceMonths)} month${Math.abs(d.paceMonths)!==1?'s':''} ${d.paceStatus === 'ahead' ? 'earlier than' : 'later than'} the plan in place when balance history began.`);
      } else if (d.paceStatus === 'on_track') {
        lines.push(`- Debt pace (balance-verified): on track with projection.`);
      }
    } else {
      // Unverified path: keyword-matched spending only. Label it as exactly
      // that and forbid the conclusions the data cannot support.
      if (d.avgMonthlyPayment > 0) {
        lines.push(`- Debt-CATEGORIZED transactions average ${fmt(d.avgMonthlyPayment)}/month over the last 3 months. These are keyword-matched and may include transfers, payoffs, new charges, or unrelated bills — they are NOT verified debt payments.`);
      }
      lines.push(`- No balance history exists to verify what these transactions accomplished. Make NO claims about principal reduction, "covering minimums", progress, or pace. If debt comes up, state only what is written here.`);
    }
    // Balance-change fact: prefer verified history; beginBal-derived only as
    // a labeled manual figure, never alongside an unverified activity number.
    if (d.reconciliation === null && d.eliminated > 0 && d.beginDebt > 0) {
      lines.push(`- Per manually-entered starting balances: ${fmt(d.eliminated)} (${d.pctPaid}%) of original debt no longer owed.`);
    }
    // Data-quality next step (d21): the verdict is computed above — the AI's
    // only job is to relay the next move, Groundwork-style: a plain suggested
    // action, never "let's" or a dialogue invitation, never framed as failure.
    const dq = d.balancesUnverified ? 'unverified (no balance history has been recorded — balances are as manually entered)'
      : d.balancesStale ? `stale (last recorded balance is from ${d.lastSnapshotMonth})`
      : d.reconAnomaly ? 'anomalous (payments were recorded but balances did not decrease — could be new charges, or balances not being updated; the data cannot distinguish)'
      : null;
    if (dq) {
      lines.push(`- DATA QUALITY: debt balances are ${dq}. End the debt portion with ONE plain sentence suggesting the user open the Debt page and confirm each balance against their latest creditor statement, so the picture reflects reality. Frame it as completing the record, not as something they did wrong.`);
    }
    // Milestone verdict (d21): computed above as a business rule. The AI's job
    // is to make the user care about THIS milestone — never to substitute one.
    if (d.nextMilestone && !dq) {
      lines.push(`- NEXT MILESTONE (computed): ${d.nextMilestone} If debt comes up, close that portion by naming this milestone and what changes when it's reached. Do not invent a different milestone.`);
    }

    // Interest saved milestone — surface this when it crosses meaningful thresholds
    if (d.interestSaved >= 500) {
      const milestone = d.interestSaved >= 5000 ? 5000
        : d.interestSaved >= 2000 ? 2000
        : d.interestSaved >= 1000 ? 1000
        : 500;
      lines.push(`- MILESTONE: Cumulative interest saved vs minimum payments has crossed $${milestone.toLocaleString()}. Total saved: ${fmt(d.interestSaved)}. This is real money that no longer exists as debt cost. Acknowledge this if it fits naturally.`);
    }
  }

  // Spending trends — patterns that span multiple months
  if (p.spending?.growingCategories?.length > 0) {
    const trends = p.spending.growingCategories.slice(0, 3)
      .map(c => `${c.category} (+${c.trendPct}% over 6 months, now averaging ${fmt(c.avg6)}/month)`);
    lines.push(`- Spending trends requiring attention: ${trends.join('; ')}. If paragraph 2 references this month's overage in one of these categories, note it is a multi-month pattern, not an isolated event.`);
  }

  // Subscription footprint — if notable
  if (p.spending?.subscriptionCandidates?.length >= 3) {
    const total = p.spending.subscriptionCandidates
      .slice(0, 8)
      .reduce((s, c) => s + c.amount, 0);
    lines.push(`- Detected recurring subscriptions: approximately ${fmt(total)}/month across ${p.spending.subscriptionCandidates.length} services. Mention only if relevant to the month's spending story.`);
  }

  // Net worth trajectory
  if (p.netWorth?.monthlyDelta && p.netWorth.snapshotCount >= 2) {
    const nw = p.netWorth;
    lines.push(`- Net worth trend: ${nw.trend} — moving ${nw.monthlyDelta >= 0 ? '+' : ''}${fmt(nw.monthlyDelta)}/month on average.`);
  }

  // §8 / Appendix B: the causal findings, computed. They are handed over as
  // FACTS the narrator may voice — never as an invitation to derive more. The
  // measured reason is sharper than the principle: inference-smuggling ran
  // 37-70% on every model tested and ROSE with size, so the failure this block
  // guards against is the likeliest one there is (MODEL_PLACEMENT.md).
  const findings = (typeof _rcTeachingData !== 'undefined' && _rcTeachingData
                    && _rcTeachingData.findings) || [];
  if (findings.length) {
    lines.push('CAUSAL FINDINGS (computed by the engine from this ledger — these are the ONLY');
    lines.push('cause-and-effect claims you may make. Do not derive others, do not explain WHY');
    lines.push('the user did anything, and do not state them with more confidence than written):');
    findings.forEach(f => {
      const bits = [`- ${f.kind}: ${f.subject}`];
      if (f.months != null)   bits.push(`${f.months} month(s) ${f.months_label || ''}`.trim());
      if (f.interest != null) bits.push(`${fmt(f.interest)} in interest`);
      if (f.monthly != null)  bits.push(`${fmt(f.monthly)}/mo`);
      lines.push(bits.join(' · '));
    });
  }

  return lines.length > 1 ? '\n' + lines.join('\n') + '\n' : '';
}

// Item 12 step 2 K5 (NARRATION_CAPS.md; STREAMING.md T8): the old monthly report (generateReport, surface
// 'monthly_report') wrote into a modal no path opens, and narrated $0.00 when forced. Removed; its buttons open the
// live report (monthly_report_v2).
function _renderReportFallback(content, ctx, spent, income, under, streak, topCats, month) {
  const beginDebt = S.debtCards.reduce((s,c)=>s+(parseFloat(c.beginBal)||0),0);
  const paid      = beginDebt - (ctx.totalDebt||0);
  const intSaved  = S._interestSaved || 0;

  // Build plain-language paragraphs for the magazine layout
  const p1 = `${month}: spent ${fmt(spent)} against ${fmt(income)} in income — ${
    under >= 0 ? fmt(under)+' under budget' : fmt(Math.abs(under))+' over budget'
  }. ${streak > 0 ? `${streak} month${streak!==1?'s':''} on track.` : ''}`;

  const p2 = topCats ? `Top spending categories: ${topCats}.` : '';

  const p3 = ctx.lean
    ? paid > 0
      ? `${fmt(paid)} paid down since you started${intSaved > 0 ? ` — keeping ${fmt(intSaved)} that would have gone to interest` : ''}.`
      : `Debt remaining: ${fmt(ctx.totalDebt||0)}. Interest: ${fmt(ctx.daily||0)}/day.`
    : ctx.stage === 'debt'
    ? `Debt remaining: ${fmt(ctx.totalDebt||0)}. Debt-free: ${ctx.freeDate?.freeDate||'set a budget to calculate'}.`
    : ctx.stage === 'transition'
    ? `${ctx.pctPaid}% of starting debt paid. The finish line is coming into view.`
    : `Net worth: ${fmt(ctx.netWorth||0)}. Keep building.`;

  const p4 = ctx.lean && !ctx.hasBuffer
    ? `Consider saving $500 as an emergency buffer before accelerating debt payments.`
    : '';

  const paragraphs = [p1, p2, p3, p4].filter(Boolean);

  // First paragraph as pullquote in the magazine layout
  content.innerHTML = `
    ${paragraphs[0] ? `<div class="report-pullquote">${esc(paragraphs[0])}</div>` : ''}
    ${paragraphs.slice(1).map(p => `<p>${esc(p)}</p>`).join('')}`;
}


// ─── Phase 10: Trip Planner ────────────────────────────────────────────────────

let _tripMode    = 'drive';   // 'drive' | 'fly'
let _tripFunding = 'now';     // 'now' | 'save'
let _tripBudgetData = null;   // calculated trip budget
let _gasPriceData = null;     // { price, period, live, source } — Phase 5A, from /api/trip/gas-price
let _tripDistanceData = null; // { miles, live, source } — Phase 5E, for the CURRENT origin/destination pair
let _tripDistanceKey  = '';   // "origin|destination" (lowercased) the above data is valid for
let _tripDistanceTimer = null;
let _tripLearnedBasis = null; // Phase 5C — { label, hotelPerNight, diningPerPersonDay, activitiesPerPersonDay } once confirmed
let _tripLearnPending  = null; // computed but not yet applied (waiting on "Use these numbers")
let _tripQuoteData    = null; // Phase 5D — { label, hotelTotal, hotelPerNight, flightTotal } once confirmed
let _tripQuotePending = null; // extracted but not yet applied (waiting on "Fill the form")
let _airfareMarkets = null;   // item 41 — { year, quarter, byName: {name: id} } from /api/trip/airfare-markets
let _airfareData    = null;   // the DOT lookup for _airfareKey
let _airfareKey     = '';     // "fromId|toId|fromAirport|toAirport" the above is valid for
let _airfareTimer   = null;

// Phase 5E: debounced distance fetch — origin/destination fire this on
// every keystroke (oninput="tripUpdateBudget()"), so this waits for a
// pause before hitting the server (which itself respects Nominatim's rate
// limit and caches every geocode). No-ops once already fetched for the
// current pair, or while either field is empty.
function _maybeLoadTripDistance(origin, destination) {
  if (!origin || !destination) return;
  const key = `${origin.toLowerCase()}|${destination.toLowerCase()}`;
  if (key === _tripDistanceKey) return;
  clearTimeout(_tripDistanceTimer);
  _tripDistanceTimer = setTimeout(async () => {
    try {
      _tripDistanceData = await API.get(`/api/trip/distance?origin=${encodeURIComponent(origin)}&destination=${encodeURIComponent(destination)}`);
      _tripDistanceKey  = key;
    } catch (e) {
      _gwErr('_maybeLoadTripDistance')(e);
    }
    tripUpdateBudget();
  }, 600);
}

function _joinNames(items) {
  const names = (items || []).map(i => i.name).filter(Boolean);
  if (names.length <= 1) return names[0] || '';
  return names.slice(0, -1).join(', ') + ' and ' + names[names.length - 1];
}

// months-from-now as "Mar 2027". The consequence engine returns a month count,
// not a date string — formatting is the view's job, and this matches how
// _simulatePayoff has always rendered its own free date.
function _monthsFromNowLabel(months) {
  const d = new Date();
  d.setMonth(d.getMonth() + (parseInt(months, 10) || 0));
  return d.toLocaleDateString('en-US', { month: 'short', year: 'numeric' });
}

// Item 41 (gw 2.0/DOT_AIRFARE.md): the DOT city list for the From / To
// pickers, then a weekly check for a newer DOT quarter. The check downloads
// DOT's whole table, never the user's route; a newer quarter reloads the list.
async function _loadAirfareMarkets(checkForNewer) {
  try {
    const res = await API.get('/api/trip/airfare-markets');
    if (res?.available) {
      const byName = {}, airports = {};
      res.markets.forEach(m => { byName[m.name] = m.id; airports[m.id] = m.airports || []; });
      _airfareMarkets = { year: res.year, quarter: res.quarter, byName, airports };
      const list = g('airfareMarketList');
      if (list) list.innerHTML = res.markets.map(m => `<option value="${esc(m.name)}"></option>`).join('');
      _airfareKey = '';
      _tripCarryCities();
      tripUpdateBudget();
    }
  } catch (e) {
    _gwErr('_loadAirfareMarkets')(e);
  }
  if (checkForNewer) {
    try {
      const r = await API.post('/api/trip/airfare-refresh', {});
      if (r?.updated) _loadAirfareMarkets(false);
    } catch (e) {
      _gwErr('_loadAirfareMarkets refresh')(e);
    }
  }
}

// Item 43 (gw 2.0/AIRPORT_FILL.md): picking a city fills its airport code.
// One airport → filled in. Several → the user is asked which, and the code
// they pick is filled in. A code the user typed themselves is never replaced.
function tripCityChanged(side) {
  const cityId = side === 'from' ? 'tripFromCity' : 'tripToCity';
  const codeEl = g(side === 'from' ? 'tripAirport' : 'tripDestAirport');
  const choice = g(side === 'from' ? 'tripFromAirportChoice' : 'tripToAirportChoice');
  const id = _airfareMarketId(cityId);
  const aps = (id && _airfareMarkets?.airports?.[id]) || [];
  const mine = codeEl && codeEl.value && codeEl.dataset.auto !== '1';
  if (choice) { choice.style.display = 'none'; choice.innerHTML = ''; }
  if (codeEl && !mine) {
    if (aps.length === 1) { codeEl.value = aps[0][0]; codeEl.dataset.auto = '1'; }
    else { codeEl.value = ''; codeEl.dataset.auto = ''; }
  }
  if (aps.length > 1 && choice && !mine) {
    choice.innerHTML = 'Which airport? ' + aps.map(([code, name]) =>
      `<button class="btn btn-secondary btn-sm" style="margin:2px 4px 2px 0" onclick="tripPickAirport('${side}','${esc(code)}')">${esc(code)} · ${esc(name)}</button>`).join('');
    choice.style.display = '';
  }
  tripUpdateBudget();
}

// Item 43 follow-up (AIRPORT_FILL.md s4, Rob 2026-10-08): the trip's own
// Destination and Home city carry into the Fly section once Fly is chosen,
// matched to DOT's city list. Only an unambiguous match is used: "Columbus"
// with no state is three DOT cities, so nothing is guessed and the user is
// asked to pick. A Fly-section city the user chose themselves is kept.
function _airfareNorm(s) {
  return String(s || '').toLowerCase().replace(/\(metropolitan area\)/g, '').replace(/\./g, '')
    .replace(/\bsaint\b/g, 'st').replace(/\bfort\b/g, 'ft').replace(/\s+/g, ' ').trim();
}

const _AIRFARE_ALIASES = { 'new york': 'new york city', 'nyc': 'new york city', 'washington dc': 'washington',
                           'dc': 'washington', 'la': 'los angeles', 'sf': 'san francisco' };

function airfareMatchCity(text, byName) {
  let city = _airfareNorm(text), st = '';
  if (!city) return null;
  const m = city.match(/^(.+?),?\s+([a-z]{2})$/);          // "nashville, tn" or "nashville tn"
  if (m && !_AIRFARE_ALIASES[city]) { city = m[1].replace(/,$/, '').trim(); st = m[2]; }
  city = _AIRFARE_ALIASES[city] || city;
  if (city === 'washington' && !st) st = 'dc';
  const hits = Object.keys(byName || {}).filter(name => {
    const n = _airfareNorm(name), i = n.lastIndexOf(', ');
    if (i < 0) return false;
    const c = n.slice(0, i), s = n.slice(i + 2);
    if (st && s !== st) return false;
    return c === city || c.split('/').map(x => x.trim()).includes(city);
  });
  return hits.length === 1 ? hits[0] : null;
}

function _tripCarryCities() {
  if (_tripMode !== 'fly' || !_airfareMarkets) return;
  [['from', 'tripOrigin', 'tripFromCity'], ['to', 'tripDestination', 'tripToCity']].forEach(([side, srcId, cityId]) => {
    const el = g(cityId);
    if (!el || (el.value && el.dataset.auto !== '1')) return;        // a city the user chose here is theirs
    const src = g(srcId)?.value?.trim() || '';
    const name = src ? airfareMatchCity(src, _airfareMarkets.byName) : null;
    if (el.value !== (name || '')) {
      el.value = name || '';
      el.dataset.auto = name ? '1' : '';
      tripCityChanged(side);
    }
    const choice = g(side === 'from' ? 'tripFromAirportChoice' : 'tripToAirportChoice');
    if (src && !name && choice) {
      choice.textContent = `"${src}" doesn't match one city in DOT's list. Pick the city here and its airport fills in.`;
      choice.style.display = '';
    }
  });
}

// Back to Drive: a city chosen only in the Fly section fills the top card's
// empty Destination / Home city, so switching never loses what was typed.
function _tripCarryBack() {
  [['tripFromCity', 'tripOrigin'], ['tripToCity', 'tripDestination']].forEach(([flyId, topId]) => {
    const fly = g(flyId)?.value?.trim(), top = g(topId);
    if (fly && top && !top.value.trim()) top.value = fly.replace(/\s*\(Metropolitan Area\)$/, '');
  });
}

function tripPickAirport(side, code) {
  const codeEl = g(side === 'from' ? 'tripAirport' : 'tripDestAirport');
  const choice = g(side === 'from' ? 'tripFromAirportChoice' : 'tripToAirportChoice');
  if (codeEl) { codeEl.value = code; codeEl.dataset.auto = '1'; }
  if (choice) { choice.style.display = 'none'; choice.innerHTML = ''; }
  tripUpdateBudget();
}

function _airfareMarketId(inputId) {
  const name = g(inputId)?.value?.trim() || '';
  return (name && _airfareMarkets?.byName[name]) || '';
}

function _maybeLoadAirfare(fromId, toId, fromAirport, toAirport) {
  const key = `${fromId}|${toId}|${fromAirport}|${toAirport}`;
  if (!fromId || !toId || key === _airfareKey) return;
  clearTimeout(_airfareTimer);
  _airfareTimer = setTimeout(async () => {
    try {
      const p = new URLSearchParams({ from: fromId, to: toId, from_airport: fromAirport, to_airport: toAirport });
      _airfareData = await API.get(`/api/trip/airfare?${p.toString()}`);
      _airfareKey  = key;
    } catch (e) {
      _gwErr('_maybeLoadAirfare')(e);
    }
    tripUpdateBudget();
  }, 300);
}

// The flight line of the trip budget from the DOT average: one way, or the
// outbound leg plus the return leg. DOT keeps one figure for both directions
// of a route, so the return leg is the same average.
function airfareEstimate(lookup, roundTrip, travelers) {
  if (!lookup?.found) return null;
  const legs = roundTrip ? 2 : 1;
  const n = Math.max(1, parseInt(travelers) || 1);
  const fare = Number(lookup.fare_one_way);
  return { fare, legs, travelers: n, total: Math.round(fare * legs * n * 100) / 100 };
}

async function _loadGasPrice() {
  try {
    _gasPriceData = await API.get('/api/trip/gas-price');
  } catch (e) {
    _gwErr('_loadGasPrice')(e);
    _gasPriceData = null;
  }
  tripUpdateBudget();
  if (g('rcCatSelect')) _rcUpdateCategoryDeepDive();
}

// ── View init ─────────────────────────────────────────────────────────────────
function renderTripPlanner() {
  // Load saved vehicle details
  _loadVehicleFromSettings();
  _loadGasPrice();
  _loadAirfareMarkets(true);

  // Set default dates (next weekend)
  const now  = new Date();
  const sat  = new Date(now);
  sat.setDate(now.getDate() + (6 - now.getDay() + 7) % 7 + 7);
  const mon  = new Date(sat);
  mon.setDate(sat.getDate() + 2);
  if (!g('tripDepart')?.value) {
    if (g('tripDepart')) g('tripDepart').value = sat.toISOString().slice(0,10);
    if (g('tripReturn')) g('tripReturn').value = mon.toISOString().slice(0,10);
  }

  // Check oil change history
  _checkOilChange();
  setTripMode('drive');
}

// ── Vehicle profile ───────────────────────────────────────────────────────────
function _loadVehicleFromSettings() {
  // Pre-fill vehicle fields from app_settings if saved
  API.get('/api/settings').then(res => {
    const s = res.data || res;
    if (s.vehicle_make && g('tripVehicle'))       g('tripVehicle').value       = s.vehicle_make;
    if (s.vehicle_year && g('tripVehicleYear'))   g('tripVehicleYear').value   = s.vehicle_year;
    if (s.vehicle_mpg  && g('tripMPG'))           g('tripMPG').value           = s.vehicle_mpg;
  }).catch(_gwErr('_loadVehicleFromSettings'));
}

function tripSaveVehicle() {
  // Persist vehicle details to app_settings (debounced)
  clearTimeout(tripSaveVehicle._t);
  tripSaveVehicle._t = setTimeout(() => {
    const make = g('tripVehicle')?.value?.trim();
    const year = g('tripVehicleYear')?.value;
    const mpg  = g('tripMPG')?.value;
    if (make || year || mpg) {
      API.patch('/api/settings', {
        ...(make ? { vehicle_make: make } : {}),
        ...(year ? { vehicle_year: year } : {}),
        ...(mpg  ? { vehicle_mpg:  mpg  } : {}),
      }).catch(_gwErr('tripSaveVehicle'));
    }
  }, 800);
}

// ── Oil change detection ──────────────────────────────────────────────────────
// Known electric vehicles — skip oil change check for these
const EV_MAKES = new Set([
  'tesla','rivian','lucid','polestar','fisker','nio','byd','vinfast',
  'canoo','lordstown','arrival','bollinger',
]);
const EV_MODELS = [
  'mach-e','mustang mach-e','mach e',
  'bolt','bolt ev','bolt euv',
  'leaf','ariya',
  'ioniq','ioniq 5','ioniq 6',
  'eq','eqs','eqe','eqb','eqc',
  'i4','i7','ix','ix3',
  'etron','e-tron','q4 etron',
  'taycan','macan electric',
  'model s','model 3','model x','model y',
  'lightning','f-150 lightning',
  'hummer ev','silverado ev','blazer ev',
  'r1t','r1s',
  'kona electric','niro ev','ev6','ev9',
  'id.4','id.3','id.buzz',
];

function _isElectricVehicle(makeModel) {
  if (!makeModel) return false;
  const lower = makeModel.toLowerCase();
  if ([...EV_MAKES].some(m => lower.startsWith(m))) return true;
  return EV_MODELS.some(m => lower.includes(m));
}

async function _checkOilChange() {
  const alert  = g('tripOilChangeAlert');
  const vehicle = g('tripVehicle')?.value?.trim() || '';
  if (!alert) return;

  // EV check — no oil needed
  if (_isElectricVehicle(vehicle)) {
    alert.style.display = '';
    alert.style.background = 'var(--pine-bg, rgba(34,197,94,.08))';
    alert.style.borderColor = 'var(--pine-border, rgba(34,197,94,.3))';
    alert.innerHTML = `⚡ Electric vehicle detected — no oil change needed. Consider checking tire pressure and cabin air filter before a long trip.`;
    return;
  }
  try {
    const res  = await API.get('/api/trip/oil-check');
    const data = res.data || res;
    if (data.found) {
      const daysAgo = data.days_ago || 0;
      const months  = Math.round(daysAgo / 30);
      if (data.overdue || daysAgo > 75) {
        alert.style.display = '';
        alert.innerHTML = `⚠ Last oil change: <strong>${fmtDate(data.date)}</strong> (${months} month${months!==1?'s':''} ago · ${esc(data.description||'')}) — recommend getting one before your trip.`;
      } else {
        alert.style.display = '';
        alert.style.background = 'var(--pine-bg)';
        alert.style.borderColor = 'var(--pine-border)';
        alert.innerHTML = `✓ Last oil change: <strong>${fmtDate(data.date)}</strong> (${months} month${months!==1?'s':''} ago) — you're good to go.`;
      }
    } else {
      alert.style.display = '';
      alert.innerHTML = '⚠ No oil change found in your ledger. Consider checking before a long drive.';
    }
  } catch(e) {
    alert.style.display = 'none';
  }
}

// ── Mode toggle ───────────────────────────────────────────────────────────────
// Rob 2026-10-08: choosing Drive or Fly slides the other card up out of the
// way, and the chosen one down, so the page keeps its space. With reduced
// motion asked for (or no Web Animations), the cards switch at once.
function _slideTripPanel(el, show) {
  if (!el) return;
  const hidden = el.style.display === 'none';
  if (el._slideAnim) { el._slideAnim.cancel(); el._slideAnim = null; }
  const still = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  if (still || typeof el.animate !== 'function') { el.style.display = show ? '' : 'none'; return; }
  if (show) {
    if (!hidden) return;                                  // already open: nothing to slide
    el.style.display = '';
    const h = el.scrollHeight;
    el._slideAnim = el.animate([{ height: '0px', opacity: 0, overflow: 'hidden' },
                                { height: h + 'px', opacity: 1, overflow: 'hidden' }],
                               { duration: 260, easing: 'ease-out' });
    el._slideAnim.onfinish = () => { el._slideAnim = null; };
  } else {
    if (hidden) return;
    const h = el.offsetHeight;
    el._slideAnim = el.animate([{ height: h + 'px', opacity: 1, overflow: 'hidden' },
                                { height: '0px', opacity: 0, overflow: 'hidden', paddingTop: '0px',
                                  paddingBottom: '0px', marginBottom: '0px', borderWidth: '0px' }],
                               { duration: 220, easing: 'ease-in' });
    el._slideAnim.onfinish = () => { el.style.display = 'none'; el._slideAnim = null; };
  }
}

function setTripMode(mode) {
  try {
    _tripMode = mode;
    const driveBtn = g('tripModeDrive');
    const flyBtn   = g('tripModeFly');
    const driveDet = g('tripDriveDetails');
    const flyDet   = g('tripFlyDetails');

    if (driveBtn) driveBtn.classList.toggle('active', mode === 'drive');
    if (flyBtn)   flyBtn.classList.toggle('active',   mode === 'fly');
    if (mode === 'drive') _tripCarryBack();
    _slideTripPanel(driveDet, mode === 'drive');
    _slideTripPanel(flyDet,   mode === 'fly');
    // The top card's Destination and Home city repeat Flying to / Flying from,
    // so they slide away while flying and come back for a drive.
    _slideTripPanel(g('tripDestField'),   mode === 'drive');
    _slideTripPanel(g('tripOriginField'), mode === 'drive');

    _tripCarryCities();
    tripUpdateBudget();
  } catch(e) {
    console.error('setTripMode error:', e);
  }
}

function setTripFunding(mode) {
  _tripFunding = mode;
  g('tripFundNow')?.classList.toggle('active',  mode==='now');
  g('tripFundSave')?.classList.toggle('active', mode==='save');
  g('tripFundCard')?.classList.toggle('active', mode==='card');
  _renderFundingDetail();
}

// ── Item 49 (TRIP_ON_CREDIT.md, Rob 2026-10-08): putting the trip on a card ──
// "We are not saying don't do this but if you do this then here is what you need
// to do to pay this off and how much it will cost." Every figure is the engine's
// (core/trip_card.py) and says what it rests on; every sentence is conditional;
// no row is preferred. Choosing a card saves nothing and is learned from nowhere.
let _tripCards = null, _tripCardId = null, _tripCardPlan = null, _tripCardPlanKey = '', _tripSaveRatePick = null;

async function _tripLoadCards() {
  try { _tripCards = (await API.get('/api/trip/cards')).cards || []; }
  catch (e) { _gwErr('_tripLoadCards')(e); _tripCards = []; }
  _renderFundingDetail();
}

function tripPickCard(id) {
  _tripCardId = id ? parseInt(id, 10) : null;
  _tripCardPlan = null; _tripCardPlanKey = '';
  _renderFundingDetail();
}

function tripPickSaveRate(pct) {
  _tripSaveRatePick = pct ? parseFloat(pct) : null;
  _renderFundingDetail();
}

async function _tripLoadCardPlan(amount) {
  const key = `${_tripCardId}|${amount}`;
  if (_tripCardPlanKey === key) return;
  _tripCardPlanKey = key;
  try { _tripCardPlan = await API.get(`/api/trip/card-plan?card_id=${_tripCardId}&amount=${amount}`); }
  catch (e) { _gwErr('_tripLoadCardPlan')(e); _tripCardPlan = null; }
  _renderFundingDetail();
}

// R5: the user's own rate - income minus spending over income, the way the
// annual summary counts it - from the last 6 full months, and only when every
// one of them has income recorded (absence is not zero). Otherwise null, and the
// user picks a rate to plan with.
function tripOwnSavingsRate(transactions, today) {
  const t0 = today || new Date();
  const months = [];
  for (let i = 1; i <= 6; i++) {
    const d = new Date(t0.getFullYear(), t0.getMonth() - i, 1);
    months.push(`${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`);
  }
  let inc = 0, spend = 0;
  for (const m of months) {
    const tx = (transactions || []).filter(t => (t.date || '').startsWith(m));
    const mi = tx.filter(_isEarn).reduce((s, t) => s + t.amount, 0);
    if (!(mi > 0)) return null;
    inc += mi;
    spend += tx.filter(_isSpend).reduce((s, t) => s + t.amount, 0);
  }
  return { rate: Math.round(((inc - spend) / inc) * 1000) / 10, monthlyIncome: inc / 6 };
}

function tripCardDetailHTML(p, surplus, own, pick, incomeMonthly) {
  const c = p.card, money = fmt, n = (k) => `${k} month${k !== 1 ? 's' : ''}`;
  const fit = p.available == null
    ? `${esc(c.name)}'s credit limit isn't entered, so Groundwork can't tell whether ${money(p.amount)} fits.`
    : p.fits
      ? `The trip is ${money(p.amount)}. ${esc(c.name)} has ${money(p.available)} of available credit.`
      : `The trip is ${money(p.amount)}. ${esc(c.name)} has ${money(p.available)} of available credit — ${money(p.short_by)} short.`;
  const left = (pay) => {
    const l = surplus - pay;
    return l >= 0 ? `${money(l)}/mo left` : `${money(-l)}/mo more than your surplus`;
  };
  const rows = p.rows.map(r => `<tr><td>${n(r.months)}</td><td>${money(r.payment)}/mo</td><td>${money(r.interest)}</td>`
    + `<td>${esc(r.paid_off)}</td><td>${left(r.payment)}</td></tr>`).join('');
  const cur = p.current && p.current.payable
    ? `At your current payments, ${esc(c.name)} carries the trip until the plan clears it: your debt-free date moves `
      + `${p.current.months_added > 0 ? `${n(p.current.months_added)} later` : 'no later'} and the trip adds `
      + `${money(p.current.interest_added)} in interest.`
    : (p.current && !p.current.payable ? `At your current payments the plan could not clear the card with the trip on it.` : '');
  let save = '';
  if (own) {
    const after = incomeMonthly > 0 ? Math.round(((own.rate / 100 * incomeMonthly - p.rows[0].payment) / incomeMonthly) * 1000) / 10 : null;
    save = `You've kept ${own.rate}% of your income over the last 6 months (income minus spending, as the annual summary counts it).`
      + (after != null ? ` With the ${money(p.rows[0].payment)}/mo of a 3-month payoff, that would be ${after}% for those months.` : '');
  } else if (pick) {
    const set = Math.round(pick / 100 * incomeMonthly * 100) / 100;
    save = `At the ${pick}% you chose: ${money(set)}/mo set aside, leaving ${money(surplus - set)}/mo of your surplus before any trip payment.`;
  } else {
    save = `Your record doesn't show 6 full months of income, so Groundwork can't tell what you usually keep. Pick a rate to plan with: `
      + [5, 10, 15, 20].map(r => `<button class="btn btn-secondary btn-sm" style="margin:2px" onclick="tripPickSaveRate(${r})">${r}%</button>`).join('');
  }
  return `<div style="font-size:12px;color:var(--ink);line-height:1.7">
    <div>${fit}</div>
    <div style="margin-top:8px">If you pay it off in full by the statement due date: ${money(p.amount)} once, and no interest if your card has a grace period — check your card's terms.</div>
    <table style="width:100%;margin-top:8px;font-size:12px"><tr style="color:var(--slate)"><td>If you pay it off in…</td><td>Each month</td><td>Interest</td><td>Paid off</td><td>Your surplus</td></tr>${rows}</table>
    <div style="margin-top:8px">${cur}</div>
    <div style="margin-top:8px">Your surplus after debt payments today: ${money(surplus)}/mo. ${save}</div>
    <div style="margin-top:8px;font-size:11px;color:var(--slate-2)">${p.assumptions.map(esc).join(' ')}</div>
  </div>`;
}

function _renderCardFunding(detail) {
  if (_tripCards === null) { detail.textContent = 'Loading your cards…'; _tripLoadCards(); return; }
  if (!_tripCards.length) { detail.textContent = 'No credit card is recorded on your Debt page, so there is nothing to put it on yet.'; return; }
  const opts = ['<option value="">Choose a card…</option>'].concat(_tripCards.map(c =>
    `<option value="${c.id}"${c.id === _tripCardId ? ' selected' : ''}>${esc(c.name)} · ${fmt(c.balance)} balance · ${c.apr}% APR · `
    + `${c.available == null ? 'limit not entered' : fmt(c.available) + ' available'}</option>`)).join('');
  let html = `<select id="tripFundCardSelect" onchange="tripPickCard(this.value)" style="width:100%;margin-bottom:8px">${opts}</select>`;
  const total = _tripBudgetData && _tripBudgetData.total;
  if (_tripCardId && total > 0) {
    if (_tripCardPlan && _tripCardPlanKey === `${_tripCardId}|${total}`) {
      const own = tripOwnSavingsRate(S.transactions);
      const income = own ? own.monthlyIncome : (S.incomes || []).reduce((s, i) => s + (i.amount || 0), 0);
      html += tripCardDetailHTML(_tripCardPlan, _tripBudgetData.surplus, own, _tripSaveRatePick, income);
    } else {
      html += 'Working it out…';
      _tripLoadCardPlan(total);
    }
  }
  detail.innerHTML = html;
}

function _renderFundingDetail() {
  const detail = g('tripFundDetail');
  if (!detail || !_tripBudgetData) return;
  const { total, surplus } = _tripBudgetData;
  if (_tripFunding === 'card') { _renderCardFunding(detail); return; }
  if (_tripFunding === 'now') {
    const remaining = surplus - total;
    detail.innerHTML = remaining >= 0
      ? `<span style="color:var(--pine)">✓ You have ${fmt(surplus)} surplus this month. ${fmt(remaining)} left after the trip.</span>`
      : `<span style="color:var(--ember)">⚠ Trip costs ${fmt(Math.abs(remaining))} more than your monthly surplus.</span>`;
  } else {
    // The page's own surplus, which is the honest pool when nothing prices the
    // trip against debt. Lever 6 - saving out of the money now going to debt -
    // is Pillar 3's answer and lives in the teaching layer, which replaces
    // this line when the engine can price it.
    const monthsNeeded = surplus > 0 ? Math.ceil(total / surplus) : '?';
    const readyDate    = surplus > 0 ? _monthsFromNowLabel(Math.ceil(total / surplus)) : 'unknown';
    detail.innerHTML = `Save ${fmt(Math.ceil(total/Math.max(1,monthsNeeded)))}/month · ready by `
      + `<strong>${readyDate}</strong> (${monthsNeeded} month${monthsNeeded!==1?'s':''})`;
  }
}

// ── Phase 5C: Learn from a past trip ──────────────────────────────────────────
// The model NEVER sees or states a dollar amount here — it only assigns a
// bucket label to each transaction id we hand it. The engine looks up every
// real amount itself from S.transactions afterward. This sidesteps R8
// number-provenance by construction: there's no number in the model's
// output for a number to be wrong about, so skipGate:true is appropriate
// here the same way it is for the trip-budget JSON call — this isn't
// narrative prose the voice gate is built to check.
const TRIP_LEARN_BUCKETS = ['hotel', 'dining', 'activities', 'transport', 'exclude'];
const TRIP_LEARN_EXCLUDE_CATEGORIES = new Set(['transfer', 'income', 'debt', 'savings']);

async function _learnFromPastTrip() {
  const start     = g('tripLearnStart')?.value;
  const end       = g('tripLearnEnd')?.value;
  const label     = g('tripLearnLabel')?.value?.trim() || 'that trip';
  const travelers = parseInt(g('tripLearnTravelers')?.value) || 1;
  const resultEl  = g('tripLearnResult');

  if (!start || !end) { showToast('Pick a start and end date first', '', 'warning'); return; }
  if (new Date(end) < new Date(start)) { showToast('End date is before start date', '', 'warning'); return; }

  const txns = S.transactions.filter(t =>
    t.type === 'debit' && t.date >= start && t.date <= end &&
    !TRIP_LEARN_EXCLUDE_CATEGORIES.has((t.category || '').toLowerCase())
  );

  if (txns.length < 3) {
    if (resultEl) resultEl.innerHTML = `<div style="font-size:12px;color:var(--slate)">Only found ${txns.length} transaction${txns.length!==1?'s':''} in that range — not enough to build a real budget from. Try a wider date range.</div>`;
    return;
  }

  if (resultEl) resultEl.innerHTML = `<div style="display:flex;align-items:center;gap:10px;font-size:12px;color:var(--slate)"><div class="spinner"></div>Reading ${txns.length} transactions from ${esc(label)}…</div>`;

  // Item 12 step 2 K4: ten transactions a call (cap 600), not all at once (up to 4,000 tokens); a batch whose reply
  // doesn't read is retried once, then its transactions are left out and the result says how many.
  const promptFor = (batch) => {
  const txnList = batch.map(t => `${t.id}|${t.date}|${(t.description||'').slice(0,60)}|${t.category||'Other'}`).join('\n');
  return `Below is a list of real transactions from a past trip (${label}, ${start} to ${end}). Format: id|date|description|category.

${txnList}

Classify EVERY transaction id into exactly one bucket: "hotel" (lodging), "dining" (restaurants, food, coffee), "activities" (entertainment, attractions, trip-specific shopping), "transport" (gas, flights, rideshare, parking, tolls), or "exclude" (not actually trip spending — e.g. a subscription renewal, a bill, or anything unrelated that just happened to fall in this date range).

Respond with ONLY a JSON object: {"classifications": [{"id": "<id>", "bucket": "<bucket>"}, ...]} — one entry per transaction id given above. Do not include dollar amounts. Do not invent transaction ids.`;
  };

  const classifications = [];
  let unread = 0;
  for (let i = 0; i < txns.length; i += 10) {
    const batch = txns.slice(i, i + 10);
    let parsed = null;
    for (let attempt = 0; attempt < 2 && !parsed; attempt++) {
      let result;
      try {
        result = await callAI({
          max_tokens: 600,
          system: 'You are a strict transaction classifier. You only assign category labels to transaction ids you are given — you never state or compute dollar amounts.',
          messages: [{ role: 'user', content: promptFor(batch) }],
          skipGate: true,
          surface: 'trip_learn_classify',
        });
      } catch (e) {
        result = { ok: false };
      }
      if (!result.ok || !result.text) {
        if (resultEl) resultEl.innerHTML = `<div style="font-size:12px;color:var(--ember)">Couldn't analyze that trip right now. Check your AI settings and try again.</div>`;
        return;
      }
      try { parsed = JSON.parse(result.text.replace(/```json|```/g, '').trim()); } catch (e) { parsed = null; }
    }
    if (parsed) classifications.push(...(parsed.classifications || []));
    else unread += batch.length;
  }
  const parsed = { classifications };

  // Validate: every id must be a REAL transaction we actually sent. Anything
  // the model invents is dropped; anything it left uncovered defaults to
  // "exclude" — the safe direction when the model's judgment is unclear.
  const realIds = new Set(txns.map(t => String(t.id)));
  const bucketById = {};
  (parsed.classifications || []).forEach(c => {
    const id = String(c.id);
    if (!realIds.has(id) || !TRIP_LEARN_BUCKETS.includes(c.bucket)) return;
    bucketById[id] = c.bucket;
  });

  const buckets = { hotel: [], dining: [], activities: [], transport: [], exclude: [] };
  txns.forEach(t => buckets[bucketById[String(t.id)] || 'exclude'].push(t));

  _renderTripLearnResult(label, start, end, travelers, buckets);
  if (unread && resultEl) resultEl.insertAdjacentHTML('beforeend',
    `<div style="font-size:11px;color:var(--slate-2);margin-top:6px">${unread} transaction${unread !== 1 ? 's' : ''} couldn't be read by the model and ${unread !== 1 ? 'are' : 'is'} left out.</div>`);
}

function _renderTripLearnResult(label, start, end, travelers, buckets) {
  const resultEl = g('tripLearnResult');
  if (!resultEl) return;
  const nights = Math.max(1, Math.round((new Date(end) - new Date(start)) / 86400000));
  const days   = nights + 1;

  const sum = arr => arr.reduce((s,t) => s + t.amount, 0);
  const hotelTotal      = sum(buckets.hotel);
  const diningTotal     = sum(buckets.dining);
  const activitiesTotal = sum(buckets.activities);
  const transportTotal  = sum(buckets.transport);

  const hotelPerNight          = nights > 0 ? hotelTotal / nights : 0;
  const diningPerPersonDay     = days > 0 && travelers > 0 ? diningTotal / days / travelers : 0;
  const activitiesPerPersonDay = days > 0 && travelers > 0 ? activitiesTotal / days / travelers : 0;

  // Transport isn't carried into the new trip's basis — it was real for
  // THAT trip's distance/mode, but blindly reapplying a flat total to a
  // different destination would be its own kind of fabrication. The new
  // trip's transport line already comes from real distance + gas-price
  // data (Phase 5A/5E); shown here for context only.
  _tripLearnPending = { label, hotelPerNight, diningPerPersonDay, activitiesPerPersonDay };

  const row = (icon, name, list, total) => `
    <div style="display:flex;justify-content:space-between;padding:6px 0;border-bottom:1px solid var(--steel-2);font-size:12px">
      <span>${icon} ${name} <span style="color:var(--slate-2)">(${list.length} txn${list.length!==1?'s':''})</span></span>
      <strong>${fmt(total)}</strong>
    </div>`;

  const reviewRows = ['hotel','dining','activities','transport'].flatMap(b =>
    buckets[b].map(t => `
      <div style="display:flex;justify-content:space-between;padding:3px 0;font-size:11px;color:var(--slate)">
        <span>${esc(t.date)} · ${esc((t.description||'').slice(0,40))} <span style="color:var(--slate-2)">(${b})</span></span>
        <span>${fmt(t.amount)}</span>
      </div>`)
  ).join('');

  resultEl.innerHTML = `
    <div style="background:var(--mist);border:1px solid var(--steel);border-radius:var(--r-md);padding:14px">
      <div style="font-size:12px;font-weight:600;color:var(--ink);margin-bottom:8px">${esc(label)} — ${nights} night${nights!==1?'s':''}, ${travelers} traveler${travelers!==1?'s':''}</div>
      ${row('🏨','Hotel', buckets.hotel, hotelTotal)}
      ${row('🍽','Dining', buckets.dining, diningTotal)}
      ${row('🎯','Activities', buckets.activities, activitiesTotal)}
      ${row('🚗','Transport (for reference only)', buckets.transport, transportTotal)}
      ${buckets.exclude.length ? `<div style="font-size:11px;color:var(--slate-2);margin-top:8px">${buckets.exclude.length} transaction${buckets.exclude.length!==1?'s':''} excluded as not trip-related.</div>` : ''}
      <details style="margin-top:10px">
        <summary style="font-size:11px;color:var(--slate-2);cursor:pointer">Review what was included</summary>
        <div style="margin-top:8px;max-height:180px;overflow-y:auto">${reviewRows || '<div style="font-size:11px;color:var(--slate-2)">Nothing classified into these buckets.</div>'}</div>
      </details>
      <div style="display:flex;gap:8px;margin-top:12px">
        <button class="btn btn-primary btn-sm" onclick="_applyTripLearnedBasis()">Use these numbers</button>
        <button class="btn btn-ghost btn-sm" onclick="g('tripLearnResult').innerHTML=''; _tripLearnPending=null">Discard</button>
      </div>
    </div>`;
}

function _applyTripLearnedBasis() {
  if (!_tripLearnPending) return;
  _tripLearnedBasis = _tripLearnPending;
  _tripLearnPending = null;
  const resultEl = g('tripLearnResult');
  if (resultEl) resultEl.innerHTML = `<div style="font-size:12px;color:var(--pine)">✓ Using ${esc(_tripLearnedBasis.label)}'s real spending as this trip's budget basis. <button onclick="_clearTripLearnedBasis()" style="background:none;border:none;color:var(--sky);text-decoration:underline;cursor:pointer;font-size:12px;padding:0;margin-left:6px">Clear</button></div>`;
  showToast(`Using real numbers from ${_tripLearnedBasis.label}`, '', 'success');
  tripUpdateBudget();

  // Write hook 2/2 for trip_history (Phase H2 Feature 3, deferred from
  // Phase H1 — see server.py :: save_trip_learned_actual). region_hint
  // comes from the CURRENT trip's destination, since learning happens in
  // service of planning that trip — an approximation, not a verified fact
  // that the past trip was to the same place.
  const depart = g('tripDepart')?.value, ret = g('tripReturn')?.value;
  const travelers = parseInt(g('tripTravelers')?.value) || 1;
  const nights = (depart && ret) ? Math.max(1, Math.round((new Date(ret) - new Date(depart)) / 86400000)) : null;
  const days   = nights != null ? nights + 1 : null;
  const actualTotal = (nights != null)
    ? Math.round(_tripLearnedBasis.hotelPerNight * nights
        + _tripLearnedBasis.diningPerPersonDay * days * travelers
        + _tripLearnedBasis.activitiesPerPersonDay * days * travelers)
    : null;
  API.post('/api/trip/learned-actual', {
    label: _tripLearnedBasis.label,
    region_hint: g('tripDestination')?.value?.trim() || '',
    hotel_per_night: _tripLearnedBasis.hotelPerNight,
    dining_per_person_day: _tripLearnedBasis.diningPerPersonDay,
    activities_per_person_day: _tripLearnedBasis.activitiesPerPersonDay,
    actual_total: actualTotal,
  }).catch(_gwErr('_applyTripLearnedBasis:saveActual'));
}

function _clearTripLearnedBasis() {
  _tripLearnedBasis = null;
  const resultEl = g('tripLearnResult');
  if (resultEl) resultEl.innerHTML = '';
  tripUpdateBudget();
}

// ── Phase 5D: Paste a quote / describe the trip ──────────────────────────────
// One intake for both: a pasted VRBO/flight/hotel quote OR a plain-English
// trip description ("me and my wife are driving to Nashville Aug 12-15").
// The model extracts structure as strict JSON; every DOLLAR figure it
// returns is then checked against the pasted text (the same R8
// number-provenance discipline as Phase 4's PDF pipeline — _financialNumbers
// here is the byte-identical JS twin of pdf_statement.py's). A figure the
// source text can't back up is nulled, never trusted. Dates/names are
// format conversions, not financial claims — shape-checked only. Nothing
// touches the form until the user confirms.

// JS twin of pdf_statement.py's _number_candidates(): the formattings a
// model-returned JSON number could plausibly appear as in the source text.
// abs() because a quote's own printed figure is unsigned.
function _tripNumberCandidates(val) {
  const f = Math.abs(parseFloat(val));
  if (isNaN(f)) return [String(val).trim()];
  const out = [f.toFixed(2)];
  out.push(f === Math.trunc(f) ? String(Math.trunc(f)) : String(f));
  return out;
}

async function _readTripQuote() {
  const text     = g('tripQuoteText')?.value?.trim();
  const resultEl = g('tripQuoteResult');
  if (!text) { showToast('Paste a quote or describe your trip first', '', 'warning'); return; }
  if (resultEl) resultEl.innerHTML = `<div style="display:flex;align-items:center;gap:10px;font-size:12px;color:var(--slate)"><div class="spinner"></div>Reading…</div>`;

  const thisYear = new Date().getFullYear();
  const prompt = `Below is either a travel quote (lodging, flight, hotel — pasted from an email or website) or a plain-English description of a planned trip. Today's year is ${thisYear}; dates without a year mean the next time that date occurs.

TEXT:
${text}

Extract what is ACTUALLY PRESENT into this exact JSON shape — null for anything the text does not state. Never guess, estimate, or compute a figure: if the text shows a nightly rate but no total, fill lodgingPerNight and leave lodgingTotal null. Do not do arithmetic.
{
  "kind": "lodging" | "flight" | "trip_description" | "other",
  "destination": "City, ST" or null,
  "origin": "City, ST" or null,
  "departDate": "YYYY-MM-DD" or null,
  "returnDate": "YYYY-MM-DD" or null,
  "travelers": number or null,
  "mode": "drive" | "fly" or null,
  "lodgingTotal": number or null,
  "lodgingPerNight": number or null,
  "flightTotal": number or null
}
Respond with ONLY the JSON object.`;

  let result;
  try {
    result = await callAI({
      max_tokens: 400,
      system: 'You are a strict travel-document transcriber. You extract only what is literally present in the text into JSON. You never invent, estimate, or compute numbers.',
      messages: [{ role: 'user', content: prompt }],
      skipGate: true,   // strict-JSON extraction, not narrative prose
      surface: 'trip_quote_extract',
    });
  } catch (e) { result = { ok: false }; }

  if (!result.ok || !result.text) {
    if (resultEl) resultEl.innerHTML = `<div style="font-size:12px;color:var(--ember)">Couldn't read that right now. Check your AI settings and try again.</div>`;
    return;
  }

  let raw;
  try {
    const cleaned = result.text.replace(/```json|```/g, '').trim();
    const start = cleaned.indexOf('{');
    raw = JSON.parse(cleaned.slice(start, cleaned.lastIndexOf('}') + 1));
  } catch (e) {
    if (resultEl) resultEl.innerHTML = `<div style="font-size:12px;color:var(--ember)">The model's response wasn't valid — try again.</div>`;
    return;
  }

  // ── Validate. Dollar figures get R8 provenance against the pasted text;
  // everything else gets shape checks. Failures null the field + warn.
  const warnings = [];
  const sourceNums = _financialNumbers(text);
  const checkMoney = (field) => {
    const v = raw[field];
    if (v == null) return null;
    if (_tripNumberCandidates(v).some(c => sourceNums.has(c))) return Math.abs(parseFloat(v));
    warnings.push(`${field} (${v}) isn't in the pasted text — discarded`);
    return null;
  };
  const checkDate = (field) => {
    const v = raw[field];
    if (v && /^\d{4}-\d{2}-\d{2}$/.test(String(v))) return String(v);
    if (v != null) warnings.push(`${field} ("${v}") wasn't a readable date — discarded`);
    return null;
  };

  const clean = {
    kind:            ['lodging','flight','trip_description','other'].includes(raw.kind) ? raw.kind : 'other',
    destination:     typeof raw.destination === 'string' ? raw.destination.trim().slice(0, 80) : null,
    origin:          typeof raw.origin === 'string' ? raw.origin.trim().slice(0, 80) : null,
    departDate:      checkDate('departDate'),
    returnDate:      checkDate('returnDate'),
    travelers:       Number.isFinite(parseInt(raw.travelers)) && parseInt(raw.travelers) >= 1 && parseInt(raw.travelers) <= 10 ? parseInt(raw.travelers) : null,
    mode:            ['drive','fly'].includes(raw.mode) ? raw.mode : null,
    lodgingTotal:    checkMoney('lodgingTotal'),
    lodgingPerNight: checkMoney('lodgingPerNight'),
    flightTotal:     checkMoney('flightTotal'),
  };
  if (clean.departDate && clean.returnDate && clean.returnDate < clean.departDate) {
    warnings.push(`return date was before departure — discarded`);
    clean.returnDate = null;
  }

  const hasAnything = clean.destination || clean.departDate || clean.travelers ||
                      clean.lodgingTotal != null || clean.lodgingPerNight != null || clean.flightTotal != null;
  if (!hasAnything) {
    if (resultEl) resultEl.innerHTML = `<div style="font-size:12px;color:var(--slate)">Couldn't find trip details in that text${warnings.length ? ` (${warnings.length} figure${warnings.length!==1?'s':''} failed verification)` : ''}. Try pasting more of the quote.</div>`;
    return;
  }

  _tripQuotePending = { clean, warnings };
  _renderTripQuoteResult(clean, warnings);
}

function _renderTripQuoteResult(clean, warnings) {
  const resultEl = g('tripQuoteResult');
  if (!resultEl) return;
  const KIND_LABEL = { lodging: 'Lodging quote', flight: 'Flight quote', trip_description: 'Trip description', other: 'Travel text' };
  const row = (label, val) => val == null ? '' : `
    <div style="display:flex;justify-content:space-between;padding:4px 0;font-size:12px">
      <span style="color:var(--slate)">${label}</span><strong>${esc(String(val))}</strong>
    </div>`;
  resultEl.innerHTML = `
    <div style="background:var(--mist);border:1px solid var(--steel);border-radius:var(--r-md);padding:14px">
      <div style="font-size:12px;font-weight:600;color:var(--ink);margin-bottom:6px">${KIND_LABEL[clean.kind]} — here's what was found:</div>
      ${row('Destination', clean.destination)}
      ${row('From', clean.origin)}
      ${row('Departure', clean.departDate)}
      ${row('Return', clean.returnDate)}
      ${row('Travelers', clean.travelers)}
      ${row('Getting there', clean.mode === 'drive' ? 'Driving' : clean.mode === 'fly' ? 'Flying' : null)}
      ${row('Lodging total', clean.lodgingTotal != null ? fmt(clean.lodgingTotal) : null)}
      ${row('Lodging per night', clean.lodgingPerNight != null ? fmt(clean.lodgingPerNight) : null)}
      ${row('Flight total', clean.flightTotal != null ? fmt(clean.flightTotal) : null)}
      ${warnings.length ? `<div style="font-size:11px;color:#92400e;background:var(--gold-bg);border:1px solid var(--gold-border);border-radius:var(--r-sm);padding:6px 10px;margin-top:8px">⚠️ ${warnings.map(esc).join(' · ')}</div>` : ''}
      <div style="display:flex;gap:8px;margin-top:12px">
        <button class="btn btn-primary btn-sm" onclick="_applyTripQuote()">Fill the trip form</button>
        <button class="btn btn-ghost btn-sm" onclick="g('tripQuoteResult').innerHTML=''; _tripQuotePending=null">Discard</button>
      </div>
    </div>`;
}

function _applyTripQuote() {
  if (!_tripQuotePending) return;
  const { clean } = _tripQuotePending;
  _tripQuotePending = null;

  if (clean.destination && g('tripDestination')) g('tripDestination').value = clean.destination;
  if (clean.origin      && g('tripOrigin'))      g('tripOrigin').value      = clean.origin;
  if (clean.departDate  && g('tripDepart'))      g('tripDepart').value      = clean.departDate;
  if (clean.returnDate  && g('tripReturn'))      g('tripReturn').value      = clean.returnDate;
  if (clean.travelers   && g('tripTravelers'))   g('tripTravelers').value   = clean.travelers;

  if (clean.lodgingTotal != null || clean.lodgingPerNight != null || clean.flightTotal != null) {
    _tripQuoteData = {
      label:         clean.kind === 'flight' ? 'your flight quote' : 'your quote',
      hotelTotal:    clean.lodgingTotal,
      hotelPerNight: clean.lodgingPerNight,
      flightTotal:   clean.flightTotal,
    };
    if (clean.flightTotal != null && g('tripFlightFare')) g('tripFlightFare').value = clean.flightTotal;
  }

  const resultEl = g('tripQuoteResult');
  if (resultEl) resultEl.innerHTML = `<div style="font-size:12px;color:var(--pine)">✓ Trip form filled from ${_tripQuoteData ? 'your quote’s real numbers' : 'your description'}. ${_tripQuoteData ? `<button onclick="_clearTripQuote()" style="background:none;border:none;color:var(--sky);text-decoration:underline;cursor:pointer;font-size:12px;padding:0;margin-left:6px">Clear quote prices</button>` : ''}</div>`;
  showToast('Trip form filled', clean.destination || '', 'success');

  // setTripMode re-runs tripUpdateBudget itself; only call directly when
  // the mode isn't changing.
  if (clean.mode) setTripMode(clean.mode);
  else tripUpdateBudget();
}

function _clearTripQuote() {
  _tripQuoteData = null;
  if (g('tripFlightFare')) g('tripFlightFare').value = '';
  const resultEl = g('tripQuoteResult');
  if (resultEl) resultEl.innerHTML = '';
  tripUpdateBudget();
}

// Flight fares (gw 2.0/FLIGHT_FARES.md, item 40, Rob 2026-10-07). The old
// "Search live flight prices" button needed a flight-search service key the user was told
// to put in config.json — no user has one, so every click failed. Now the
// search opens in the user's own browser (Groundwork sends nothing) and the
// fare they pick is typed into tripFlightFare, which fills the same
// _tripQuoteData.flightTotal slot the "paste a quote" flow uses, so
// tripUpdateBudget() picks it up through its existing priority chain.
// Item 42 (gw 2.0/FLIGHTS_WINDOW.md): the search opens in Groundwork's own
// window with the airports, dates and travelers already filled in. The server
// builds the address; the window is the bank window's separate process.
function _tripAirportCode(id) {
  const v = g(id)?.value?.trim().toUpperCase() || '';
  return /^[A-Z]{3}$/.test(v) ? v : '';
}

// Item 44 (FLIGHT_FARE_READ.md): after a search opens in Groundwork's window,
// look for the fare the user picks there (the Continue button they click),
// and ask before using it. The figure is named as Google's: the airline's
// checkout may add taxes or fees (R0 (a)).
let _googleFareTimer = null, _googleFareTrip = null;

function _watchGoogleFare(trip) {
  clearInterval(_googleFareTimer);
  _googleFareTrip = trip;
  const started = Date.now();
  _googleFareTimer = setInterval(async () => {
    if (Date.now() - started > 30 * 60 * 1000) { clearInterval(_googleFareTimer); return; }
    try {
      const r = await API.get('/api/trip/flights-window/fare');
      if (r && typeof r.fare === 'number' && r.fare > 0) {
        clearInterval(_googleFareTimer);
        _offerGoogleFare(r.fare);
      }
    } catch (e) { /* the window may have closed; keep the box as it is */ }
  }, 2000);
}

function googleFareMessage(amount, trip) {
  const n = trip?.travelers || 1;
  return `Google Flights showed ${fmt(amount)} for this trip (${n} traveler${n !== 1 ? 's' : ''}, ${trip?.roundTrip ? 'round trip' : 'one way'}). ` +
         `The airline's checkout may add taxes or fees.`;
}

function _offerGoogleFare(amount) {
  const el = g('tripFlightSearchResult');
  if (!el) return;
  el.style.color = 'var(--ink)';
  el.innerHTML = `${esc(googleFareMessage(amount, _googleFareTrip))}
    <button class="btn btn-secondary btn-sm" style="margin-left:6px" onclick="tripUseGoogleFare(${Number(amount)})">Use ${fmt(amount)}</button>
    <button class="btn btn-secondary btn-sm" style="margin-left:4px" onclick="tripDeclineGoogleFare()">Enter the airline's total</button>`;
}

function tripUseGoogleFare(amount) {
  const box = g('tripFlightFare');
  if (box) box.value = Number(amount).toFixed(2);
  _tripQuoteData = { ..._tripQuoteData, label: 'Google Flights', flightTotal: Number(amount) };
  const el = g('tripFlightSearchResult');
  if (el) { el.style.color = 'var(--slate)'; el.textContent = 'Using Google Flights\' price. If the airline\'s checkout shows more, type its total in the box.'; }
  API.post('/api/trip/flights-window/fare/clear', {}).catch(_gwErr('googleFareClear'));
  tripUpdateBudget();
}

function tripDeclineGoogleFare() {
  const el = g('tripFlightSearchResult');
  if (el) { el.style.color = 'var(--slate)'; el.textContent = 'Type the airline\'s total in the box.'; }
  API.post('/api/trip/flights-window/fare/clear', {}).catch(_gwErr('googleFareClear'));
  g('tripFlightFare')?.focus();
}

async function openFlightSearch(mode) {
  const resultEl = g('tripFlightSearchResult');
  const say = (text, color) => { if (resultEl) { resultEl.style.color = color; resultEl.innerHTML = text; } };
  const origin = _tripAirportCode('tripAirport');
  const dest   = _tripAirportCode('tripDestAirport');
  const depart = g('tripDepart')?.value;
  if (!origin || !dest || !depart) {
    say('Enter both 3-letter airport codes and your departure date to open the search filled in.', 'var(--ember)');
    return;
  }
  const roundTrip = g('tripRoundTrip')?.checked !== false;
  const ret = roundTrip ? (g('tripReturn')?.value || '') : '';
  if (roundTrip && !ret) {
    say('Round trip is ticked: enter your return date above, or untick Round trip to search one way.', 'var(--ember)');
    return;
  }
  try {
    const r = await API.post('/api/trip/flights-window', {
      origin, dest, depart, return: ret, travelers: parseInt(g('tripTravelers')?.value) || 1, mode: mode || 'window',
    });
    if (r?.result === 'engine_unavailable') {
      say(`Groundwork's window could not open on this computer. <button onclick="openFlightSearch('browser')" style="background:none;border:none;color:var(--sky);text-decoration:underline;cursor:pointer;font-size:11px;padding:0">Open in my browser</button>`, 'var(--ember)');
    } else {
      if (mode !== 'browser' && r?.result === 'opened') _watchGoogleFare({ travelers: parseInt(g('tripTravelers')?.value) || 1, roundTrip: !!ret });
      say(`${mode === 'browser' ? 'Opened in your browser' : 'Opened in a Groundwork window'}: ${esc(origin)} → ${esc(dest)}${ret ? ' and back' : ', one way'}. ` +
          (mode === 'browser' ? '' : `<button onclick="openFlightSearch('browser')" style="background:none;border:none;color:var(--sky);text-decoration:underline;cursor:pointer;font-size:11px;padding:0">Open in my browser instead</button>`), 'var(--slate)');
    }
  } catch (e) {
    _gwErr('openFlightSearch')(e);
    say('Could not open the search — try again.', 'var(--ember)');
  }
}

function tripSetFlightFare() {
  const raw = g('tripFlightFare')?.value;
  const fare = raw === '' || raw == null ? null : parseFloat(raw);
  const resultEl = g('tripFlightSearchResult');
  if (fare != null && !(Number.isFinite(fare) && fare >= 0)) {
    if (resultEl) { resultEl.style.color = 'var(--ember)'; resultEl.textContent = 'Enter the fare as a dollar amount.'; }
    return;
  }
  if (resultEl) resultEl.textContent = '';
  if (fare != null) {
    _tripQuoteData = { ..._tripQuoteData, label: 'the fare you entered', flightTotal: fare };
  } else if (_tripQuoteData) {
    const { flightTotal, ...rest } = _tripQuoteData;
    _tripQuoteData = (rest.hotelTotal != null || rest.hotelPerNight != null) ? rest : null;
  }
  tripUpdateBudget();
}

// The DOT lookup for the route on screen, starting one if the route changed.
function _airfareCurrent() {
  const fromId = _airfareMarketId('tripFromCity');
  const toId   = _airfareMarketId('tripToCity');
  const ap = id => { const v = g(id)?.value?.trim().toUpperCase() || ''; return /^[A-Z]{3}$/.test(v) ? v : ''; };
  const fa = ap('tripAirport'), fb = ap('tripDestAirport');
  _maybeLoadAirfare(fromId, toId, fa, fb);
  return (fromId && toId && _airfareKey === `${fromId}|${toId}|${fa}|${fb}`) ? _airfareData : null;
}

// Item 51 (FARE_CHANGE.md, Rob 2026-10-08: "approve F1-F8 as recommended"):
// the route's DOT average against the same quarter a year earlier - a season
// moves the average ~10% within a year, so a quarter is only compared with its
// own season. Stated by sign, with both figures and both quarters; nothing is
// estimated, adjusted for inflation, or called high or low.
function airfareChangeLine(d) {
  const ch = d && d.change;
  if (!ch) return '';
  const now = `${d.year} Q${d.quarter}`, was = `${ch.year} Q${ch.quarter}`;
  if (!ch.available) {
    return ch.reason === 'no_earlier_route' ? `DOT has no average for this route in ${was}, so there's nothing to compare it with.` : '';
  }
  const where = ch.basis === 'airport' ? 'between these two airports' : 'between these two cities, all their airports';
  const pax = n => Math.round(n).toLocaleString();
  const how = ch.direction === 'same'
    ? `the same as in ${was}, the same quarter a year earlier (${fmt(ch.fare_then)})`
    : `${fmt(ch.difference)} (${ch.percent.toFixed(1)}%) ${ch.direction} than in ${was}, the same quarter a year earlier (${fmt(ch.fare_then)})`;
  return `Compared with a year earlier, ${where}: the ${fmt(ch.fare_now)} average one-way fare in ${now} is ${how}. ` +
         `Both are in each quarter's own dollars, not adjusted for inflation; about ${pax(ch.passengers_now)} passengers a day in ${now}, ${pax(ch.passengers_then)} in ${was}.`;
}

function _airfareNoteHtml(travelers) {
  const box = inner => `<div style="padding:10px 14px;border-radius:var(--r-md);background:var(--paper);border:0.5px solid var(--steel);font-size:12px;color:var(--slate)">${inner}</div>`;
  const fromTyped = g('tripFromCity')?.value?.trim(), toTyped = g('tripToCity')?.value?.trim();
  if (!_airfareMarkets) return '';
  if ((fromTyped && !_airfareMarketId('tripFromCity')) || (toTyped && !_airfareMarketId('tripToCity'))) {
    return box('Pick each city from the list so Groundwork can find DOT\'s average fare for the route.');
  }
  const d = _airfareCurrent();
  if (!d) return '';
  const quarter = `${d.year} Q${d.quarter}`;
  if (!d.found) {
    return box(d.reason === 'same_market'
      ? 'From and To are the same city.'
      : `DOT has no average fare for ${esc(d.from_name)} – ${esc(d.to_name)} in ${quarter} (it lists routes averaging 10+ passengers a day in the lower 48 states). Enter your fare below; until then flights are not in the trip total.`);
  }
  const roundTrip = g('tripRoundTrip')?.checked !== false;
  const est = airfareEstimate(d, roundTrip, travelers);
  const name = (city, ap) => `${esc(city)}${ap ? ` (${esc(ap)})` : ''}`;
  const from = name(d.from_name, d.from_airport), to = name(d.to_name, d.to_airport);
  const typed = _tripQuoteData?.flightTotal != null;
  return box(`✈ The average cost of this flight is <strong style="color:var(--ink)">${fmt(est.fare)}</strong> one way,
    ${from} → ${to}${roundTrip ? `, and ${fmt(est.fare)} back, ${to} → ${from}` : ''}.
    ${roundTrip ? `Round trip: (${fmt(est.fare)} + ${fmt(est.fare)})` : `One way: ${fmt(est.fare)}`}
    × ${est.travelers} traveler${est.travelers !== 1 ? 's' : ''} = <strong style="color:var(--ink)">${fmt(est.total)}</strong>.
    <div style="margin-top:6px;font-size:11px;color:var(--slate-2)">Source: ${esc(d.source)}, ${quarter} — the average one-way fare passengers actually paid${d.basis === 'airport' ? ' between these two airports' : ' between these two cities, all their airports'}, from a 10% sample of real tickets (about ${Math.round(d.passengers_per_day).toLocaleString()} passengers a day). DOT keeps one figure for both directions of a route, so the return leg is the same average. It is not a fare you can book: compare it with the fares Google Flights shows for your dates${typed ? '. The fare you entered is used in your total instead' : ''}.</div>
    ${airfareChangeLine(d) ? `<div style="margin-top:6px;font-size:11px;color:var(--slate-2)">${airfareChangeLine(d)}</div>` : ''}`);
}

// Item 48 (TRIP_EXACT_TOTALS.md, Rob 2026-10-08: "it should grab the exact
// total since a good chance the user ordered it"): a total the user chose or
// typed - a fare, a hotel quote - is a price, and is kept to the cent. Only the
// planner's own estimates (fuel, dining, activities, a per-night guess) are
// rounded, because they were never exact.
function tripExactTotal(x) {
  return Math.round(Number(x) * 100) / 100;
}

// ── Item 50 (TRIP_BOOKED.md, Rob 2026-10-08, B1-B8): "I booked it" ──
// A booking is a planned record: it never enters spending or a balance. The real
// charge is counted once, when it is imported, and only linked on the user's yes.
// The confirmation number is the user's own typing, never read from a page.
let _tripBookings = [], _tripBookingsKey = null, _tripBookingAccounts = null;

function tripBookingLabel() {
  const dest = (_tripMode === 'fly' && g('tripToCity')?.value?.trim()) || g('tripDestination')?.value?.trim() || '';
  const depart = g('tripDepart')?.value || '';
  return dest && depart ? `${dest} · ${depart}` : '';
}

async function _tripLoadBookings(force) {
  const label = tripBookingLabel();
  if (!force && label === _tripBookingsKey) return;
  _tripBookingsKey = label;
  if (!label) { _tripBookings = []; _tripRenderBookings(); return; }
  try { _tripBookings = (await API.get(`/api/trip/bookings?trip=${encodeURIComponent(label)}`)).bookings || []; }
  catch (e) { _gwErr('_tripLoadBookings')(e); _tripBookings = []; }
  _tripRenderBookings();
  tripUpdateBudget();
}

function tripBookingCost(bookings) {
  const live = (bookings || []).filter(b => b.trip_cost);
  return live.length ? live[live.length - 1] : null;
}

async function tripOpenBooking() {
  const box = g('tripBookingForm');
  if (!box) return;
  if (!tripBookingLabel()) {
    box.style.display = ''; box.textContent = 'Enter the destination and departure date first, so the booking belongs to this trip.';
    return;
  }
  if (!_tripBookingAccounts) {
    try { _tripBookingAccounts = await API.get('/api/trip/booking-accounts'); }
    catch (e) { _gwErr('tripOpenBooking')(e); _tripBookingAccounts = { cards: [], accounts: [] }; }
  }
  const a = _tripBookingAccounts;
  const opt = (kind, x) => `<option value="${kind}:${x.id}">${esc(x.name)}</option>`;
  const fare = g('tripFlightFare')?.value || '';
  box.style.display = '';
  box.innerHTML = `<div class="field-row" style="flex-wrap:wrap;gap:8px">
      <div class="field"><label>Airline</label><input type="text" id="tripBkAirline" placeholder="e.g. Delta"></div>
      <div class="field"><label>Amount paid ($)</label><input type="number" id="tripBkAmount" min="0" step="0.01" value="${esc(fare)}"></div>
      <div class="field"><label>Paid with</label><select id="tripBkPaid">
        ${a.cards.length ? `<optgroup label="Credit cards">${a.cards.map(x => opt('card', x)).join('')}</optgroup>` : ''}
        ${a.accounts.length ? `<optgroup label="Checking (debit card)">${a.accounts.map(x => opt('account', x)).join('')}</optgroup>` : ''}
        <option value="other:">Other / not listed</option></select></div>
      <div class="field"><label>Booked on</label><input type="date" id="tripBkDate" value="${today()}"></div>
      <div class="field"><label>Confirmation (optional)</label><input type="text" id="tripBkConf" maxlength="40" placeholder="You type it"></div>
    </div>
    <div style="font-size:11px;color:var(--slate-2);margin:6px 0">Saved as a booking, not as spending: the charge counts once, when your bank or card import brings it in and you confirm it's this booking. Groundwork doesn't read the airline's pages.</div>
    <button class="btn btn-primary btn-sm" onclick="tripSaveBooking()">Save booking</button>
    <button class="btn btn-secondary btn-sm" onclick="g('tripBookingForm').style.display='none'">Cancel</button>
    <span id="tripBkMsg" style="font-size:11px;margin-left:6px"></span>`;
}

async function tripSaveBooking() {
  const [kind, id] = (g('tripBkPaid')?.value || 'other:').split(':');
  const body = { trip_label: tripBookingLabel(), airline: g('tripBkAirline')?.value?.trim(), amount: g('tripBkAmount')?.value,
                 booked_on: g('tripBkDate')?.value, confirmation: g('tripBkConf')?.value?.trim(), paid_with_kind: kind };
  if (kind === 'card') body.debt_account_id = parseInt(id, 10);
  if (kind === 'account') body.account_id = parseInt(id, 10);
  try {
    await API.post('/api/trip/bookings', body);
    g('tripBookingForm').style.display = 'none';
    _tripLoadBookings(true);
  } catch (e) {
    const m = g('tripBkMsg'); if (m) { m.style.color = 'var(--ember)'; m.textContent = e?.message || 'Could not save the booking.'; }
  }
}

function tripBookingLine(b, payName) {
  const when = fmtDate(b.booked_on), on = payName ? ` on ${esc(payName)}` : '';
  if (b.status === 'booked') return `Booked: ${esc(b.airline)}, ${fmt(b.amount)}${on}, ${when} — waiting for the charge.`;
  if (b.status === 'charged') return `Charged: ${esc(b.airline)}, ${fmt(b.charged_amount)}${on}`
    + (Math.abs(b.charged_amount - b.amount) >= 0.005 ? ` (booked ${fmt(b.amount)})` : '') + `, booked ${when}.`;
  if (b.status === 'cancelled') return `Cancelled: ${esc(b.airline)}, ${fmt(b.amount)}${on}, booked ${when}`
    + (b.refund_expected ? ' — refund expected.' : '.');
  return `Refunded: ${esc(b.airline)}, ${fmt(b.amount)}${on}, booked ${when}.`;
}

function _tripPayName(b) {
  const a = _tripBookingAccounts || { cards: [], accounts: [] };
  if (b.paid_with_kind === 'card') return (a.cards.find(x => x.id === b.debt_account_id) || {}).name;
  if (b.paid_with_kind === 'account') return (a.accounts.find(x => x.id === b.account_id) || {}).name;
  return null;
}

function _tripRenderBookings() {
  const box = g('tripBookings');
  if (!box) return;
  box.innerHTML = _tripBookings.map(b => {
    const btns = b.status === 'booked'
      ? `<button class="btn btn-secondary btn-sm" onclick="tripFindCharge(${b.id})">Find the charge</button>
         <button class="btn btn-secondary btn-sm" onclick="tripCancelBooking(${b.id}, true)">Cancelled — refund expected</button>
         <button class="btn btn-secondary btn-sm" onclick="tripCancelBooking(${b.id}, false)">Cancelled — no refund</button>`
      : (b.status === 'cancelled' && b.refund_expected ? `<button class="btn btn-secondary btn-sm" onclick="tripFindCharge(${b.id})">Find the refund</button>` : '');
    return `<div style="font-size:12px;color:var(--ink);padding:6px 0;border-top:1px solid var(--steel)">${tripBookingLine(b, _tripPayName(b))}
      ${b.confirmation ? `<span style="color:var(--slate-2)"> · confirmation ${esc(b.confirmation)}</span>` : ''}
      <div style="margin-top:4px">${btns}</div><div id="tripBkFind${b.id}" style="margin-top:4px"></div></div>`;
  }).join('');
}

async function tripFindCharge(id) {
  const out = g(`tripBkFind${id}`), b = _tripBookings.find(x => x.id === id);
  if (!out || !b) return;
  let r;
  try { r = await API.get(`/api/trip/bookings/${id}/candidates`); }
  catch (e) { _gwErr('tripFindCharge')(e); return; }
  const what = r.for === 'refund' ? 'refund' : 'charge';
  if (!r.candidates.length) {
    out.innerHTML = `<span style="color:var(--slate)">No ${what} ${_tripPayName(b) ? `on ${esc(_tripPayName(b))} ` : ''}matches yet — within $1.00 of ${fmt(b.amount)}, within 7 days of ${fmtDate(b.booked_on)}, naming ${esc(b.airline)}. It may not have been imported yet.</span>`;
    return;
  }
  out.innerHTML = r.candidates.map(c => `<div>Is this the ${what} for your ${esc(b.airline)} booking of ${fmtDate(b.booked_on)}?
      <strong>${fmt(c.amount)}</strong> · ${esc(c.text.trim())} · ${fmtDate(c.date)}
      <button class="btn btn-secondary btn-sm" onclick="tripMatchBooking(${id}, '${c.kind}', ${c.id})">Yes</button>
      <button class="btn btn-secondary btn-sm" onclick="this.parentElement.remove()">No</button></div>`).join('');
}

async function tripMatchBooking(id, kind, rowId) {
  try { await API.post(`/api/trip/bookings/${id}/match`, { kind, id: rowId }); }
  catch (e) { _gwErr('tripMatchBooking')(e); return; }
  _tripLoadBookings(true);
}

async function tripCancelBooking(id, refund) {
  try { await API.put(`/api/trip/bookings/${id}`, { status: 'cancelled', refund_expected: !!refund }); }
  catch (e) { _gwErr('tripCancelBooking')(e); return; }
  _tripLoadBookings(true);
}

// ── Budget calculator ─────────────────────────────────────────────────────────
function tripUpdateBudget() {
  const dest      = (_tripMode === 'fly' && g('tripToCity')?.value?.trim()) || g('tripDestination')?.value?.trim();
  const depart    = g('tripDepart')?.value;
  const ret       = g('tripReturn')?.value;
  const travelers = parseInt(g('tripTravelers')?.value) || 1;
  const calcCard  = g('tripBudgetCalc');

  // Item 41: the DOT average as its own finding, with its working — shown as
  // soon as both cities are picked, before the rest of the trip is filled in.
  if (tripBookingLabel() !== _tripBookingsKey) _tripLoadBookings();

  const airNote = g('tripAirfareNote');
  if (airNote) {
    airNote.innerHTML = _tripMode === 'fly' ? _airfareNoteHtml(travelers) : '';
    airNote.style.display = airNote.innerHTML ? '' : 'none';
  }

  if (!dest || !depart || !ret) { if (calcCard) calcCard.style.display='none'; return; }

  const nights    = Math.max(1, Math.round((new Date(ret) - new Date(depart)) / 86400000));
  const days      = nights + 1;

  // Transport cost estimate
  let transportCost = 0, transportNote = '';
  // Phase 5A: real EIA national average when available, honest $3.40
  // estimate otherwise — never silently wrong either way. Hoisted out of
  // the drive branch so the exogenous-fact display below (5B) can show it
  // even though it's only used in the cost math for driving trips.
  const gasRate      = _gasPriceData?.price || 3.40;
  const gasPriceLive = !!_gasPriceData?.live;
  const gasPricePeriod = _gasPriceData?.period || '';
  if (_tripMode === 'drive') {
    const mpg    = parseFloat(g('tripMPG')?.value) || 28;
    const origin = g('tripOrigin')?.value?.trim() || '';
    // Phase 5E: real one-way distance (geocoded + great-circle estimate)
    // once origin+destination are both entered and resolved; honest 400mi
    // placeholder otherwise (matches the old hardcoded behavior exactly
    // when there's nothing real to look up yet, or origin is blank).
    _maybeLoadTripDistance(origin, dest);
    const distKey  = `${origin.toLowerCase()}|${dest.toLowerCase()}`;
    const distLive = !!(origin && _tripDistanceKey === distKey && _tripDistanceData?.live);
    const distOneWay = (origin && _tripDistanceKey === distKey) ? _tripDistanceData.miles : 400;
    const distEst = distOneWay * 2;
    const gallons = distEst / mpg;
    transportCost  = Math.round(gallons * gasRate);
    transportNote  = `~${distEst} mi ${distLive ? '(estimated route)' : 'est.'} · ${mpg} mpg · $${gasRate.toFixed(2)}/gal ${gasPriceLive ? '(national avg)' : 'est.'}`;
  } else if (tripBookingCost(_tripBookings)) {
    // Item 50 B7: a booking for this trip is the flight line - the booked amount
    // while waiting, the charged amount once the user matched the real charge.
    const bk = tripBookingCost(_tripBookings), tc = bk.trip_cost;
    transportCost = tc.amount;
    transportNote = tc.label === 'charged'
      ? `${fmt(tc.amount)} charged by ${bk.airline}${tc.differs ? ` (booked ${fmt(tc.booked)})` : ''}`
      : `${fmt(tc.amount)} booked with ${bk.airline} — waiting for the charge`;
  } else if (_tripQuoteData?.flightTotal != null) {
    // Phase 5D: a real pasted flight-quote total beats the $220/person guess.
    transportCost = tripExactTotal(_tripQuoteData.flightTotal);
    transportNote = _tripQuoteData.label === 'Google Flights'
      ? `${fmt(transportCost)} total (from Google Flights; the airline may add taxes or fees)`
      : `${fmt(transportCost)} total (from your quote)`;
  } else {
    // Item 41: the DOT average fare for the route replaces the old $220/person
    // guess. No DOT figure → no flight cost, and the line says it is left out.
    const est = airfareEstimate(_airfareCurrent(), g('tripRoundTrip')?.checked !== false, travelers);
    if (est) {
      transportCost = est.total;
      transportNote = `DOT avg ${fmt(est.fare)} one way × ${est.legs} leg${est.legs !== 1 ? 's' : ''} × ${est.travelers} traveler${est.travelers !== 1 ? 's' : ''}`;
    } else {
      transportCost = 0;
      transportNote = 'Not in the total yet — pick both cities or enter your fare';
    }
  }

  // Hotel estimate, in priority order: a real pasted quote (Phase 5D, either
  // an exact total for the whole stay or a per-night rate) > a real past
  // trip's learned rate (Phase 5C) > the rough $140/night default.
  let hotelCost, hotelPerNight;
  if (_tripQuoteData?.hotelTotal != null) {
    hotelCost = tripExactTotal(_tripQuoteData.hotelTotal);
    hotelPerNight = Math.round(hotelCost / nights);
  } else {
    hotelPerNight = _tripQuoteData?.hotelPerNight ?? _tripLearnedBasis?.hotelPerNight ?? 140;
    hotelCost = Math.round(hotelPerNight * nights);
  }

  // Dining: Phase 5C learned basis > the user's actual average dining
  // transaction as a per-person/day proxy > $45/person/day default.
  // BUG FIX (July 8, audit week): the old code summed the last 30 dining
  // transactions but divided by a hardcoded 30 regardless of how many it
  // actually found — so a user with sparse history got a nonsensically low
  // number (3 meals totaling $135 → $4.50/day, LOWER than the $45 default a
  // user with no history gets). Now it averages over the real count, and
  // requires at least 4 samples before trusting history over the default so
  // one big dinner can't skew the whole trip estimate.
  let avgDailyDining;
  if (_tripLearnedBasis) {
    avgDailyDining = _tripLearnedBasis.diningPerPersonDay * travelers;
  } else {
    const diningHistory = S.transactions
      .filter(t => t.type==='debit' && (t.category||'').toLowerCase().includes('dining'))
      .slice(-30);
    avgDailyDining = diningHistory.length >= 4
      ? (diningHistory.reduce((s,t)=>s+t.amount,0) / diningHistory.length) * travelers
      : 45 * travelers;
  }
  const diningCost = Math.round(avgDailyDining * days);

  // Activities: Phase 5C learned basis > $50/person/day default.
  const activitiesPerPersonDay = _tripLearnedBasis?.activitiesPerPersonDay ?? 50;
  const activitiesCost = Math.round(activitiesPerPersonDay * travelers * days);

  // Buffer: 10%
  const subtotal = transportCost + hotelCost + diningCost + activitiesCost;
  const buffer   = Math.round(subtotal * 0.1);
  const total    = subtotal + buffer;

  // Monthly surplus after debt commitment
  const income   = S.incomes.reduce((s,i)=>s+i.amount,0);
  const expenses = S.expenses.reduce((s,e)=>s+_rowMonth(e),0);
  const debtPay  = _getMonthlyBudget();
  const surplus  = Math.max(0, income - expenses - debtPay);

  // Payoff impact
  // (_simulatePayoff(0) for the base date was dropped with payoffImpact — it was
  //  running a full simulation whose only consumer was the removed sentence.
  //  Pillar 1 computes base and impact together.)
  // payoffImpact is NOT COMPUTED. It used to be Math.round((total/income)*30),
  // labelled 'rough days impact' — and measured on 2026-09-03 it understated the
  // real figure by 4.4x to 17.4x across six scenarios, worst for the tightest
  // budgets, because it divides the trip by INCOME when what drives payoff is the
  // surplus over minimums. Five of six landed under the <=14d threshold that
  // printed 'A worthy trade.'
  //
  // It cannot be computed correctly yet: _simulatePayoff takes only a monthly
  // delta, and a trip is a ONE-TIME cost. That missing dimension is why the
  // heuristic existed. The blueprint's signature is
  // decisionImpact({ monthlyDelta, oneTimeCost }) — Pillar 1 — and per
  // gw 2.0/CALCULATION_PLACEMENT.md a claim-backing derivation belongs in Python.
  // Until then: honest-null. No history, no claim.
  const payoffImpact = null;

  // Store for funding/AI use
  _tripBudgetData = {
    dest, depart, ret, nights, days, travelers,
    transport: transportCost, transportNote,
    hotel:      hotelCost,
    dining:     diningCost,
    activities: activitiesCost,
    buffer,
    total,
    surplus,
    payoffImpact,
    gasRate, gasPriceLive, gasPricePeriod,
  };

  // Pillar 1 impact for this total — debounced, never blocking.

  // Render budget cells
  if (calcCard) calcCard.style.display = '';
  const cells = g('tripBudgetCells');
  if (cells) {
    cells.innerHTML = `
      <div class="trip-cell">
        <div class="trip-cell-label">Trip length</div>
        <div class="trip-cell-value">${nights} night${nights!==1?'s':''}</div>
        <div class="trip-cell-sub">${days} day${days!==1?'s':''} · ${travelers} traveler${travelers!==1?'s':''}</div>
      </div>
      <div class="trip-cell">
        <div class="trip-cell-label">Estimated total</div>
        <div class="trip-cell-value">${fmt(total)}</div>
        <div class="trip-cell-sub">AI will refine this</div>
      </div>
      <div class="trip-cell">
        <div class="trip-cell-label">Monthly surplus</div>
        <div class="trip-cell-value" style="color:${surplus>=total?'var(--pine)':'var(--ember)'}">${fmt(surplus)}</div>
        <div class="trip-cell-sub">after debt payment</div>
      </div>`;
  }

  // Phase 5B: the EIA national average as its own labeled finding, distinct
  // from the transport-cost line above — a fact about the country, not a
  // claim about what this user will actually pay at the pump.
  const gasNote = g('tripGasPriceNote');
  if (gasNote) {
    if (_tripMode === 'drive' && gasPriceLive) {
      gasNote.style.display = '';
      gasNote.innerHTML = `<div style="padding:10px 14px;border-radius:var(--r-md);background:var(--mist);border:0.5px solid var(--steel);font-size:12px;color:var(--slate)">
        ⛽ U.S. national average gas price${gasPricePeriod ? ` (week of ${esc(gasPricePeriod)})` : ''}:
        <strong style="color:var(--ink)">$${gasRate.toFixed(2)}/gal</strong> — source: EIA.
        Your trip's fuel line above uses this; actual prices along your route may differ.
      </div>`;
    } else {
      gasNote.style.display = 'none';
    }
  }

  // The plain summary. What this costs the payoff date is Pillar 2's
  // sentence and lives in the teaching layer, which overwrites this line when
  // the engine has an answer for the trip on screen.
  const impact = g('tripPayoffImpact');
  if (impact) {
    impact.innerHTML = `Estimated trip cost: <strong>${fmt(total)}</strong>. Your monthly surplus is <strong>${fmt(surplus)}</strong>.`;
  }

  // Show save options
  const saveOpts = g('tripSaveOptions');
  if (saveOpts) {
    saveOpts.style.display = '';
    if (!_tripFunding) setTripFunding('now');
    else _renderFundingDetail();
  }

  _showTripForecastHint(dest, total);
}

// Phase H2 Feature 3: adjust the estimate using real regional variance from
// trip_history, once there's data to adjust from (server.py ::
// get_improved_trip_estimate). Silent no-op — no hint shown — until then.
let _tripForecastReqId = 0;
let _tripLastForecast   = null;   // cached for _tripLaunchAdvisorAI — avoids a duplicate fetch
async function _showTripForecastHint(dest, baseTotal) {
  const hint = g('tripForecastHint');
  if (!hint) return;
  const reqId = ++_tripForecastReqId;   // dest changes fast while typing — only the latest fetch may render
  try {
    const res = await API.get(`/api/trip/forecast?region=${encodeURIComponent(dest)}&base_estimate=${baseTotal}`);
    if (reqId !== _tripForecastReqId) return;
    _tripLastForecast = { ...res, region: dest };
    _tripRenderAdvisorEntry(res);
    if (res.confidence === 'none') { hint.style.display = 'none'; return; }
    const dir = res.adjustment_pct > 0 ? 'higher' : 'lower';
    hint.style.display = '';
    hint.innerHTML = `<div style="padding:10px 14px;border-radius:var(--r-md);background:var(--mist);border:0.5px solid var(--steel);font-size:12px;color:var(--slate)">
      📍 Your past trips to this region ran ${Math.abs(res.adjustment_pct)}% ${dir} than estimated (${res.trip_count} trip${res.trip_count!==1?'s':''} tracked · ${res.confidence} confidence).
      Adjusted estimate: <strong style="color:var(--ink)">${fmt(res.estimate)}</strong>.
    </div>`;
  } catch (e) {
    if (reqId === _tripForecastReqId) hint.style.display = 'none';
    _gwErr('_showTripForecastHint')(e);
  }
}

// Trip advisor — mirrors the other pages' one-time "Generate" entry point,
// delegating to the shared _rcAnalyzeWithAI flow. Only shown once real
// trip_history exists for this region (confidence !== 'none') — an honest
// gate, same as every other advisor surface requiring real data first.
let _tripAdvisorAICache = false;

function _tripRenderAdvisorEntry(forecast) {
  const card = g('tripAdvisorCard');
  if (!card) return;
  if (!forecast || forecast.confidence === 'none') { card.style.display = 'none'; return; }
  if (_tripAdvisorAICache || g('tripAdvisorAIEntry')) return;

  card.style.display = '';
  card.innerHTML = `
    <div id="tripAdvisorAIEntry" style="display:flex;align-items:center;justify-content:space-between;gap:16px">
      <div>
        <div style="font-size:13px;font-weight:500;color:var(--ink)">Groundwork's trip-planning analysis</div>
        <div style="font-size:12px;color:var(--slate);margin-top:2px">AI-powered read of this trip against your real regional cost history</div>
      </div>
      <button onclick="_tripLaunchAdvisorAI()"
        style="font-size:12px;padding:7px 16px;background:var(--pine);color:#fff;border:none;border-radius:var(--r-sm);cursor:pointer;white-space:nowrap;font-weight:500">
        ✦ Generate
      </button>
    </div>`;
}

async function _tripLaunchAdvisorAI() {
  g('tripAdvisorAIEntry')?.remove();
  const d = _tripBudgetData;
  const f = _tripLastForecast;
  if (!d || !f || f.confidence === 'none') return;

  const dataLines = [
    `Destination: ${d.dest}`,
    `Trip length: ${d.nights} night(s), ${d.travelers} traveler(s)`,
    `Estimated total: ${fmt(d.total)}`,
    `Breakdown: transport ${fmt(d.transport)}, hotel ${fmt(d.hotel)}, dining ${fmt(d.dining)}, activities ${fmt(d.activities)}`,
    '---',
    `Regional history: past trips to this region ran ${Math.abs(f.adjustment_pct)}% ${f.adjustment_pct>0?'higher':'lower'} than estimated (${f.trip_count} trip(s) tracked, ${f.confidence} confidence)`,
    `Historically-adjusted estimate: ${fmt(f.estimate)}`,
  ];

  const buildPrompt = (profileCtx, stageCtx) => [
    profileCtx || '',
    `TRIP PICTURE — ${new Date().toLocaleDateString('en-US',{month:'long',year:'numeric'})}`,
    '',
    dataLines.join('\n'),
    stageCtx?.stageNote || '',
    '',
    'Rules: Lead with how this trip\'s estimate compares to the region\'s real historical cost, stated as a plain fact from the numbers above. Name dollar amounts. Never invent a number or a projection not given above. 2-3 short paragraphs. No headers, no bullets.',
  ].filter(Boolean).join('\n').trim();

  const target = g('tripAdvisorCard');
  if (target) {
    await _rcAnalyzeWithAI('trip_advisor', dataLines, buildPrompt, target);
    _tripAdvisorAICache = true;
  }
}

// ── Phase 10C: AI trip budget ─────────────────────────────────────────────────
async function generateTripBudget() {
  const output  = g('tripBudgetOutput');
  const content = g('tripBudgetContent');
  const badge   = g('tripAIBadge');
  if (!output || !content) return;
  if (!_tripBudgetData) { tripUpdateBudget(); if (!_tripBudgetData) return; }

  output.style.display = '';
  content.innerHTML = `<div style="display:flex;align-items:center;gap:10px;color:var(--slate-2);padding:16px 0">
    <div class="spinner"></div><span>Building your ${esc(_tripBudgetData.dest)} budget…</span></div>`;

  const d       = _tripBudgetData;
  const vehicle = g('tripVehicle')?.value?.trim() || 'your vehicle';
  const mpg     = g('tripMPG')?.value || '28';
  const airport = g('tripAirport')?.value?.trim() || '';
  const origin  = g('tripOrigin')?.value?.trim() || 'your city';

  if (!aiEnabled()) {
    _renderTripBudgetFallback(content, badge, d);
    return;
  }

  if (badge) badge.textContent = '✦ AI · live prices';

  // Build prompt with web search enabled
  const transportContext = _tripMode === 'drive'
    ? `Driving from ${origin} to ${d.dest}. Vehicle: ${vehicle}, ${mpg} MPG highway. Need: distance in miles, current gas price estimate along the route, total fuel cost. Also check if an oil change is advisable (user's last was flagged in their ledger).`
    : `Flying from ${airport || origin} to ${d.dest}. Need: current roundtrip flight price range for ${d.travelers} passenger${d.travelers!==1?'s':''}, departure ${d.depart}.`;

  const prompt = `You are building a detailed trip budget. Use web search to find current prices.

Trip details:
  Destination: ${d.dest}
  Dates: ${d.depart} to ${d.ret} (${d.nights} nights, ${d.days} days)
  Travelers: ${d.travelers}
  Transport: ${_tripMode === 'drive' ? 'driving' : 'flying'}

Transport specifics:
  ${transportContext}

User's financial context:
  Total trip budget available: ${fmt(d.total)}
  Monthly surplus after debt: ${fmt(d.surplus)}

Tasks:
1. Search for current gas prices if driving, or flight prices if flying
2. Search for hotel options in ${d.dest} for ${d.nights} nights around ${d.depart} — find options in the $90-$160/night range
3. Estimate dining costs for ${d.dest} (${d.days} days, ${d.travelers} people) based on the city's typical restaurant prices
4. Suggest 1-2 activities appropriate for ${d.dest}

Return a complete line-item budget that stays within ${fmt(d.total)} total.
Format your response as a JSON object with this exact structure:
{
  "transport": { "cost": number, "note": "string", "detail": "string" },
  "hotel": { "cost": number, "note": "string", "options": ["string"] },
  "dining": { "cost": number, "note": "string" },
  "activities": { "cost": number, "note": "string", "suggestions": ["string"] },
  "buffer": { "cost": number },
  "total": number,
  "verdict": "string (one sentence on whether this fits their budget)",
  "tip": "string (one specific money-saving tip for this destination)",
  ${_tripMode === 'drive' ? '"road_notes": "string (stops, traffic, anything useful)",' : '"flight_notes": "string (booking tips, best time to search)",'}
  "within_budget": boolean
}
Respond with ONLY the JSON object. No markdown, no explanation.`;

  try {
    const result = await callAI({
      max_tokens: 800,
      system: 'You are a travel budget assistant. Always search for real current prices. Return only valid JSON.',
      messages: [{ role:'user', content: prompt }],
      tools: [{ type: 'web_search_20250305', name: 'web_search' }],
      // Strict-JSON output, not narrative prose — voice/R8 don't apply
      // (prices come from a live web search, not pre-supplied findings).
      skipGate: true,
    });

    if (result.ok) {
      try {
        const clean = result.text.replace(/```json|```/g, '').trim();
        const data  = JSON.parse(clean);
        _renderTripBudgetResult(content, badge, data, d, result.payload);
        // Save to DB for tracking
        API.post('/api/trip/budget', { ...d, aiResult: data, generatedAt: new Date().toISOString() })
          .catch(_gwErr('generateTripBudget'));
      } catch(e) {
        // AI returned text not JSON — render as narrative
        _renderTripBudgetNarrative(content, badge, result.text, d, result.payload);
      }
    } else {
      _renderTripBudgetFallback(content, badge, d);
    }
  } catch(e) {
    _renderTripBudgetFallback(content, badge, d);
  }
}

function _renderTripBudgetResult(content, badge, data, d, payload) {
  if (badge) badge.textContent = '✦ AI · live prices';

  const withinBudget = data.within_budget !== false && data.total <= d.total * 1.05;
  const statusColor  = withinBudget ? 'var(--pine)' : 'var(--ember)';
  const statusIcon   = withinBudget ? '✓' : '⚠';

  const rows = [
    { cat: _tripMode==='drive' ? '🚗 Transport' : '✈ Flights', cost: data.transport?.cost, note: data.transport?.note },
    { cat: '🏨 Hotel', cost: data.hotel?.cost, note: data.hotel?.note },
    { cat: '🍽 Dining', cost: data.dining?.cost, note: data.dining?.note },
    { cat: '🎯 Activities', cost: data.activities?.cost, note: data.activities?.note },
    { cat: '🛡 Buffer', cost: data.buffer?.cost, note: '10% contingency' },
  ].filter(r => r.cost > 0);

  content.innerHTML = `
    <div style="margin-bottom:16px">
      ${rows.map(r => `
        <div class="trip-budget-row">
          <span class="trip-budget-cat">${r.cat}</span>
          <span><span class="trip-budget-amt">${fmt(r.cost||0)}</span><span class="trip-budget-note">${esc(r.note||'')}</span></span>
        </div>`).join('')}
      <div class="trip-budget-row">
        <span class="trip-budget-cat">Total</span>
        <span class="trip-budget-amt">${fmt(data.total||0)}</span>
      </div>
    </div>

    <div style="padding:10px 14px;border-radius:var(--r-md);border:0.5px solid ${statusColor};background:${withinBudget?'var(--pine-bg)':'var(--ember-bg)'};font-size:12px;color:var(--ink);margin-bottom:14px">
      ${statusIcon} ${esc(data.verdict||'')}
    </div>

    ${data.hotel?.options?.length ? `
    <div style="margin-bottom:14px">
      <div style="font-size:11px;font-weight:600;letter-spacing:.06em;text-transform:uppercase;color:var(--slate-2);margin-bottom:6px">Hotel suggestions</div>
      ${data.hotel.options.map(o => `<div style="font-size:12px;color:var(--ink);padding:4px 0;border-bottom:0.5px solid var(--steel)">${esc(o)}</div>`).join('')}
    </div>` : ''}

    ${data.activities?.suggestions?.length ? `
    <div style="margin-bottom:14px">
      <div style="font-size:11px;font-weight:600;letter-spacing:.06em;text-transform:uppercase;color:var(--slate-2);margin-bottom:6px">Activities</div>
      ${data.activities.suggestions.map(s => `<div style="font-size:12px;color:var(--ink);padding:4px 0;border-bottom:0.5px solid var(--steel)">${esc(s)}</div>`).join('')}
    </div>` : ''}

    ${data.road_notes || data.flight_notes ? `
    <div style="padding:10px 14px;background:var(--mist);border-radius:var(--r-md);font-size:12px;color:var(--slate);margin-bottom:14px">
      ${esc(data.road_notes || data.flight_notes || '')}
    </div>` : ''}

    ${data.tip ? `
    <div style="padding:10px 14px;border-left:2px solid var(--sky);background:var(--sky-bg);border-radius:0 var(--r-md) var(--r-md) 0;font-size:12px;color:var(--ink)">
      💡 <strong>Money tip:</strong> ${esc(data.tip)}
    </div>` : ''}
    ${_renderAIDisclosure(payload)}`;
}

function _renderTripBudgetNarrative(content, badge, text, d, payload) {
  if (badge) badge.textContent = '✦ AI';
  content.innerHTML = `
    <div style="font-size:13px;color:var(--ink);line-height:1.75;margin-bottom:16px">${esc(text)}</div>
    ${_tripBudgetFallbackHTML(d)}
    ${_renderAIDisclosure(payload)}`;
}

function _renderTripBudgetFallback(content, badge, d) {
  if (badge) badge.textContent = '';
  content.innerHTML = _tripBudgetFallbackHTML(d);
}

function _tripBudgetFallbackHTML(d) {
  const withinBudget = d.total <= d.surplus * 1.2;
  return `
    <div class="trip-budget-row"><span class="trip-budget-cat">${_tripMode==='drive'?'🚗 Transport':'✈ Flights'}</span><span class="trip-budget-amt">${fmt(d.transport)}<span class="trip-budget-note">${esc(d.transportNote)}</span></span></div>
    <div class="trip-budget-row"><span class="trip-budget-cat">🏨 Hotel</span><span><span class="trip-budget-amt">${fmt(d.hotel)}</span><span class="trip-budget-note">${d.nights} nights · est. avg</span></span></div>
    <div class="trip-budget-row"><span class="trip-budget-cat">🍽 Dining</span><span><span class="trip-budget-amt">${fmt(d.dining)}</span><span class="trip-budget-note">${d.days} days · based on your avg</span></span></div>
    <div class="trip-budget-row"><span class="trip-budget-cat">🎯 Activities</span><span class="trip-budget-amt">${fmt(d.activities)}</span></div>
    <div class="trip-budget-row"><span class="trip-budget-cat">🛡 Buffer</span><span class="trip-budget-amt">${fmt(d.buffer)}</span></div>
    <div class="trip-budget-row"><span class="trip-budget-cat">Total</span><span class="trip-budget-amt">${fmt(d.total)}</span></div>
    <div style="margin-top:12px;padding:10px 14px;border-radius:var(--r-md);border:0.5px solid ${withinBudget?'var(--pine)':'var(--gold)'};background:${withinBudget?'var(--pine-bg)':'var(--gold-bg)'};font-size:12px">
      ${withinBudget ? '✓ This trip fits within your budget.' : '⚠ Consider saving for this trip over 2–3 months.'}
      Turn on AI in Settings for AI-powered live price estimates.
    </div>`;
}


// ─── Focused session: annotation, Sunday card, stage transition ───────────────

// ── Monthly annotation ────────────────────────────────────────────────────────

function _annotationKey() {
  // Key format: annotation_YYYY-MM — one per calendar month
  const now = new Date();
  return `annotation_${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}`;
}

function saveReportAnnotation() {
  const val = g('reportAnnotation')?.value?.trim();
  const key = _annotationKey();
  // Save to app_settings — debounced
  clearTimeout(saveReportAnnotation._t);
  saveReportAnnotation._t = setTimeout(() => {
    API.patch('/api/settings', { [key]: val || '' }).catch(_gwErr('saveReportAnnotation'));
  }, 600);
}


function getReportAnnotation() {
  // Called by generateReport() to inject into the AI prompt
  return g('reportAnnotation')?.value?.trim() || '';
}

// ── Monthly annotation ────────────────────────────────────────────────────────

function _checkStageTransition() {
  // Fires once when calcUserStage() changes from 'debt' → 'transition' → 'wealth'
  // Shows a one-time message on the dashboard greeting sub.
  const currentStage = calcUserStage();
  const lastStage    = sessionStorage.getItem('gw_last_stage');

  if (!lastStage) {
    sessionStorage.setItem('gw_last_stage', currentStage);
    return null;
  }

  if (lastStage === currentStage) return null;

  // Stage changed — compose the transition message
  sessionStorage.setItem('gw_last_stage', currentStage);

  // Build data-aware messages so the handoff feels personal, not generic
  const totalDebt  = _activeDebtCards().reduce((s,c) => s+(_cardBal(c)), 0);
  const beginDebt  = S.debtCards.reduce((s,c) => s+(parseFloat(c.beginBal)||0), 0);
  const eliminated = Math.round(beginDebt - totalDebt);
  const savings    = parseFloat(S.netWorth?.savings) || 0;
  const hasBuffer  = savings >= 500;

  const messages = {
    'debt→transition': [
      `You've paid off ${fmt(eliminated)} — enough to change the math.`,
      hasBuffer
        ? `Your buffer is in place. Next: keep attacking debt while leaving savings alone.`
        : `Next: build a $500 emergency buffer so one bad month can't undo this progress.`,
    ].join(' '),

    'transition→wealth': [
      `The last debt is gone.`,
      `What used to go to minimum payments can now go to work for you.`,
      `Redirect those payments to savings first — then look at the Net Worth page and set a target.`,
    ].join(' '),

    'debt→wealth': [
      `You went from carrying debt to positive net worth.`,
      `That's the whole journey in one move.`,
      `Open Net Worth and set your first wealth target — the momentum you built doesn't have to stop here.`,
    ].join(' '),
  };

  const key = `${lastStage}→${currentStage}`;
  return messages[key] || null;
}

// ── Sunday number card ────────────────────────────────────────────────────────

async function renderSundayCard() {
  const card    = g('dashSundayCard');
  const content = g('dashSundayContent');
  const badge   = g('dashSundayBadge');
  if (!card || !content) return;

  // Only show on Sundays
  const today = new Date();
  if (today.getDay() !== 0) { card.style.display = 'none'; return; }

  card.style.display = '';

  // Gather this week's data
  const weekStart = new Date(today);
  weekStart.setDate(today.getDate() - 6);
  const weekStartStr = weekStart.toISOString().slice(0,10);
  const todayStr     = today.toISOString().slice(0,10);

  const weekTxns  = S.transactions.filter(t =>
    t.date >= weekStartStr && t.date <= todayStr
  );
  const spent     = weekTxns.filter(t=>t.type==='debit').reduce((s,t)=>s+t.amount,0);
  const income    = weekTxns.filter(t=>t.type==='credit').reduce((s,t)=>s+t.amount,0);
  const totalIncome = S.incomes.reduce((s,i)=>s+i.amount,0);
  const weeklyIncome = totalIncome / 4.33;
  const onTrack   = spent <= weeklyIncome;

  // Top category this week
  const cats = {};
  weekTxns.filter(t=>t.type==='debit').forEach(t=>{
    cats[t.category||'Other'] = (cats[t.category||'Other']||0) + t.amount;
  });
  const topCat = Object.entries(cats).sort((a,b)=>b[1]-a[1])[0];

  // Daily interest
  const daily = calcDailyInterest();
  const weeklyInterest = daily * 7;

  if (!aiEnabled()) {
    _renderSundayFallback(content, badge, {
      spent, weeklyIncome, onTrack, topCat, weeklyInterest, daily
    });
    return;
  }

  if (badge) badge.textContent = '✦ AI';
  content.innerHTML = `<div style="display:flex;align-items:center;gap:10px;color:var(--slate-2)">
    <div class="spinner"></div><span style="font-size:12px">Preparing your Sunday check-in…</span>
  </div>`;

  const stageCtx = _buildStageContext();
  const householdNote = _householdIncomeNote();

  // Couples vs solo framing
  const isCouple    = S_household.enabled && S_household.user2Name;
  const audienceNote = isCouple
    ? `This check-in is for ${S_household.user1Name||'you'} and ${S_household.user2Name} reading together.`
    : 'This check-in is for one person.';

  const prompt = `${stageCtx.leanContext ? stageCtx.leanContext + '\n\n' : ''}You are writing a brief Sunday financial check-in. ${audienceNote} Keep it conversational and warm — not clinical.
${householdNote}
This week:
  Spent: ${fmt(spent)} (weekly target: ~${fmt(weeklyIncome)})
  ${onTrack ? 'Under target for the week.' : 'Over target for the week.'}
  ${topCat ? `Biggest category: ${topCat[0]} (${fmt(topCat[1])})` : ''}
  Interest paid this week: ${fmt(weeklyInterest)} ($${daily.toFixed(2)}/day)
  ${stageCtx.stageNote}

Write exactly 2 sentences:
1. What happened this week with money — specific, honest, one number.
2. One thing worth ${isCouple ? 'talking about together' : 'reflecting on'} today — state it as an observation, not a lecture and not a question.

No greeting. No sign-off. No question marks. Write as if you're a trusted friend, not a financial advisor.`;

  try {
    const result = await callAI({
      max_tokens: 200,   // item 12 step 2 K1: measured 100 of 100 used, twice
      max_sentences: 2,  // after K7 (Rob: "a"): the model wrote 82-139 words for "two sentences"; the code keeps the promise
      system: 'You write brief, warm, honest Sunday financial check-ins for couples. Two sentences, about 40 words. Conversational. Never preachy.',
      messages: [{ role:'user', content: prompt }],
      surface: 'sunday_checkin',
      findings_kinds: ['income', 'total', 'category', 'debt', 'household_name'],
    });

    if (result.ok) {
      // d21: unified renderer
      const sundayDataLines = [
        `Spent this week: ${fmt(spent)}`,
        `Weekly income: ${fmt(weeklyIncome)}`,
        onTrack ? 'Under target for the week' : 'Over target for the week',
        ...(topCat ? [`Biggest category: ${topCat[0]} (${fmt(topCat[1])})`] : []),
        `Interest this week (estimated from APRs × balances): ${fmt(weeklyInterest)}`,
      ];
      _rcRenderAIPanel('sunday_checkin', result.text, content, sundayDataLines, null,
        { compact: true, replace: true, payload: result.payload, title: 'Sunday check-in',
          model: result.model, provider: result.provider });
    } else {
      _renderSundayFallback(content, badge, {
        spent, weeklyIncome, onTrack, topCat, weeklyInterest, daily
      });
    }
  } catch(e) {
    _renderSundayFallback(content, badge, {
      spent, weeklyIncome, onTrack, topCat, weeklyInterest, daily
    });
  }
}

function _renderSundayFallback(content, badge, d) {
  if (badge) badge.textContent = '';
  const direction = d.onTrack ? 'under' : 'over';
  const diff      = Math.abs(d.spent - d.weeklyIncome);
  const topLine   = `This week: ${fmt(d.spent)} spent — ${fmt(diff)} ${direction} your weekly pace.`;
  const catLine   = d.topCat
    ? `${d.topCat[0]} was the biggest category at ${fmt(d.topCat[1])}.`
    : '';
  const intLine   = `The debt cost ${fmt(d.weeklyInterest)} in interest this week.`;

  content.innerHTML = [topLine, catLine, intLine]
    .filter(Boolean)
    .map(l => `<span style="display:block;margin-bottom:4px">${l}</span>`)
    .join('');
}


