let _helpCardTimer = null;

function showHelp(topic, anchorEl) {
  const def = HELP_TOPICS[topic];
  if (!def) return;

  // Close any open card first
  closeHelpCard();

  const card   = g('helpCard');
  if (!card) return;

  card.className = 'help-card';
  card.innerHTML = `
    <span class="help-card-close" onclick="closeHelpCard()">✕</span>
    <div class="help-card-title">${esc(def.title)}</div>
    <div class="help-card-body">${esc(def.body)}</div>`;
  card.style.display = 'block';

  // Position near the anchor element
  if (anchorEl) {
    const rect  = anchorEl.getBoundingClientRect();
    const cardW = 280;
    let   left  = rect.left + rect.width / 2 - cardW / 2;
    let   top   = rect.bottom + 8;
    // Keep within viewport
    left = Math.max(8, Math.min(left, window.innerWidth - cardW - 8));
    if (top + 140 > window.innerHeight) top = rect.top - 148;
    card.style.left = `${left}px`;
    card.style.top  = `${top}px`;
  } else {
    card.style.left = '50%';
    card.style.top  = '50%';
    card.style.transform = 'translate(-50%,-50%)';
  }

  // Auto-close after 8 seconds
  _helpCardTimer = setTimeout(closeHelpCard, 8000);

  // Close on outside click
  setTimeout(() => {
    document.addEventListener('click', _closeHelpOnOutsideClick, { once: true });
  }, 50);
}

function closeHelpCard() {
  const card = g('helpCard');
  if (card) { card.style.display = 'none'; card.style.transform = ''; }
  if (_helpCardTimer) { clearTimeout(_helpCardTimer); _helpCardTimer = null; }
}

function _closeHelpOnOutsideClick(e) {
  const card = g('helpCard');
  if (card && !card.contains(e.target)) closeHelpCard();
}

// Helper: renders a ⓘ icon that calls showHelp on click
function helpIcon(topic) {
  return `<span class="help-icon" onclick="showHelp('${topic}',this)" title="What is this?">i</span>`;
}

// ── LAYER 2: First-visit banners ──────────────────────────────────────────────

const FVB_DISMISSED_KEY = 'gw_fvb_dismissed';

function _getFVBDismissed() {
  try { return JSON.parse(localStorage.getItem(FVB_DISMISSED_KEY) || '{}'); }
  catch(e) { return {}; }
}

function dismissFVB(view) {
  try {
    const d = _getFVBDismissed();
    d[view] = true;
    localStorage.setItem(FVB_DISMISSED_KEY, JSON.stringify(d));
  } catch(e) { _gwErr('dismissFVB')(e); }
  const el = g(`fvb-${view}`);
  if (el) el.innerHTML = '';
}

