function renderFirstVisitBanner(view) {
  const el = g(`fvb-${view}`);
  if (!el) return;

  // Don't show if dismissed
  if (_getFVBDismissed()[view]) { el.innerHTML = ''; return; }

  // Don't show if user already has data for this view
  const hasData = {
    ledger:      S.transactions.length > 0,
    budget:      S.incomes.length > 0 || S.expenses.length > 0,
    debt:        S.debtCards.length > 0,
    byb:         false,  // always show on first visit
    investments: false,  // always show on first visit
    networth:    (S.netWorth?.savings||0) + (S.netWorth?.investments||0) + (S.netWorth?.homeValue||0) > 0,
    trip:        false,  // always show on first visit
  };

  if (hasData[view]) { el.innerHTML = ''; return; }

  const b = FIRST_VISIT_BANNERS[view];
  if (!b) return;

  el.innerHTML = `
    <div class="first-visit-banner">
      <div class="first-visit-icon">${b.icon}</div>
      <div class="first-visit-body">
        <div class="first-visit-title">${esc(b.title)}</div>
        <div class="first-visit-text">${esc(b.text)}</div>
        <div style="display:flex;align-items:center;gap:16px;margin-top:8px">
          ${b.action ? `<button class="btn btn-sm btn-secondary" onclick="${b.action};dismissFVB('${view}')">${esc(b.actionLabel)}</button>` : ''}
          <span class="first-visit-dismiss" onclick="dismissFVB('${view}')">Got it, don't show again</span>
        </div>
      </div>
    </div>`;
}

