function renderGettingStarted() {
  const card  = g('gettingStartedCard');
  const steps = g('gettingStartedSteps');
  if (!card || !steps) return;

  // Hide if user has dismissed or completed onboarding long ago
  if (localStorage.getItem('gs_dismissed') === 'true') { card.style.display = 'none'; return; }

  // Auto-hide if all checkable steps are done and user has been around a while
  const hasIncome  = S.incomes.length > 0;
  const hasExpense = S.expenses.length > 0;
  const hasDebt    = S.debtCards.length > 0;
  const hasTxns    = S.transactions.length > 0;
  const allDone    = hasIncome && hasExpense && hasDebt && hasTxns;

  // If user already has substantial data, don't show the checklist at all
  if (S.transactions.length > 50 || (hasIncome && hasExpense && hasDebt && hasTxns)) {
    // They're clearly past week 1 — but show briefly if any step is incomplete
    if (allDone) { card.style.display = 'none'; return; }
  }

  card.style.display = '';

  const completedCount = GETTING_STARTED_STEPS.filter(s => s.check()).length;
  const progressPct    = Math.round((completedCount / GETTING_STARTED_STEPS.length) * 100);

  steps.innerHTML = `
    <div style="height:4px;background:var(--steel-2);border-radius:99px;overflow:hidden;margin-bottom:14px">
      <div style="height:100%;width:${progressPct}%;background:var(--sky);border-radius:99px;transition:width .4s ease"></div>
    </div>
    ${GETTING_STARTED_STEPS.map(step => {
      const done = step.check();
      return `<div style="display:flex;align-items:center;gap:12px;padding:8px 0;
                           border-bottom:0.5px solid var(--steel-2);cursor:pointer"
                   onclick="${done ? '' : `(${step.action.toString()})()`}">
        <div style="width:22px;height:22px;border-radius:50%;flex-shrink:0;display:flex;align-items:center;justify-content:center;
                    background:${done ? 'var(--pine)' : 'var(--steel)'};
                    color:${done ? '#fff' : 'var(--slate)'};font-size:12px">
          ${done ? '✓' : ''}
        </div>
        <div style="flex:1">
          <div style="font-size:13px;font-weight:${done ? '400' : '500'};
                      color:${done ? 'var(--slate)' : 'var(--ink)'};
                      text-decoration:${done ? 'line-through' : 'none'}">
            ${esc(step.label)}
          </div>
          ${!done ? `<div style="font-size:11px;color:var(--slate);margin-top:1px">${esc(step.sub)}</div>` : ''}
        </div>
        ${!done ? `<span style="font-size:11px;color:var(--sky)">→</span>` : ''}
      </div>`;
    }).join('')}
    <div style="font-size:11px;color:var(--slate);margin-top:10px;text-align:center">
      ${completedCount} of ${GETTING_STARTED_STEPS.length} complete
    </div>`;
}

function dismissGettingStarted() {
  localStorage.setItem('gs_dismissed', 'true');
  const card = g('gettingStartedCard');
  if (card) { card.style.opacity = '0'; card.style.transition = 'opacity .3s'; setTimeout(() => card.style.display = 'none', 300); }
}

// ── Shared helper: active debt cards excluding expired leases ─────────────────
// Use this everywhere instead of S.debtCards.filter(c => !c.paidInFull).
// Leases whose endDate is in the past have no remaining payment obligation.
function _activeDebtCards() {
  const today = new Date().toISOString().slice(0, 10);
  return S.debtCards.filter(c =>
    !c.paidInFull && !(c.endDate && c.endDate < today)
  );
}

function calcUserStage() {
  const activeCards = _activeDebtCards();
  const totalDebt  = activeCards.reduce((s,c)=>s+(_cardBal(c)),0);
  const beginDebt  = activeCards.reduce((s,c)=>s+(parseFloat(c.beginBal)||0),0);
  const pctPaid    = beginDebt > 0 ? (beginDebt-totalDebt)/beginDebt : 0;
  const hasInvest  = typeof _invPositions !== 'undefined' && _invPositions && _invPositions.length > 0;
  const freeDate   = _simulatePayoff(0);
  const monthsLeft = freeDate?.months || 999;
  if (totalDebt < 500 || (totalDebt < 2000 && hasInvest)) return 'wealth';
  if (pctPaid >= 0.40 || monthsLeft <= 12) return 'transition';
  return 'debt';
}

function calcLeanMode() {
  const income   = _effectiveIncome();    // rolling avg in commission mode
  const expenses = S.expenses.reduce((s,e) => s+_rowMonth(e), 0);
  const debtPay  = _getMonthlyBudget();
  if (!income) return false;
  return (income - expenses - debtPay) < 200;
}

function calcHasEmergencyBuffer() {
  return (parseFloat(S.netWorth?.savings) || 0) >= 500;
}

function calcDTI() {
  const today    = new Date().toISOString().slice(0, 10);
  const totalMin = S.debtCards
    .filter(c => !c.paidInFull)
    .filter(c => {
      // Exclude any card whose end date is in the past —
      // the payment obligation is over. Applies to leases and fixed-term loans.
      if (c.endDate && c.endDate < today) return false;
      return true;
    })
    .reduce((s,c) => s + (parseFloat(c.minimum) || 0), 0);
  const income   = S.incomes.reduce((s,i) => s + i.amount, 0);
  if (!income) return null;
  return (totalMin / income) * 100;
}

// ─── Debt payoff simulation ────────────────────────────────────────────────────

const MAX_MONTHS = 360;

// ── Single source of truth for the committed monthly debt budget ─────────────
// HARDENING (July 8): the July 6 fix (#20) gave _simulatePayoff() an
// S.monthlyBudget fallback, but a dozen other functions — including
// buildSnapshot(), which PERSISTS the value — were still reading
// g('monthlyBudget')?.value directly. That works today only because the
// field lives statically in index.html and restoreFromBootstrap() populates
// it at boot, i.e. by accident of load order. Every read now goes through
// this helper, which makes the whole bug class structurally impossible:
// use the DOM when the field has a value (and sync it into app state so an
// in-progress edit is immediately visible everywhere), otherwise fall back
// to stored state. Functions that need the element itself (userSet flag,
// writing a suggestion into it) still use g('monthlyBudget') directly.
function _getMonthlyBudget() {
  const el = g('monthlyBudget');
  if (el && el.value !== '') {
    const v = parseFloat(el.value) || 0;
    S.monthlyBudget = v;
    return v;
  }
  return parseFloat(S.monthlyBudget) || 0;
}

// ── Canonical card balance ───────────────────────────────────────────────────
// BUG FIX (July, reported from field): a debt paid down to exactly $0 could
// not be saved — the pervasive `currentBal || beginBal` idiom treats a real
// balance of 0 as falsy and silently falls back to the ORIGINAL balance. So
// setting TJ Max to 0.00 re-rendered (and persisted) as its begin balance
// (e.g. 104.72). currentBal is a real, distinct field that can legitimately
// be 0; it is authoritative whenever it holds an actual value. Only when it's
// genuinely absent (null / undefined / '') do we fall back to beginBal.
// Every read and the save payload route through this so 0 means 0 everywhere.
function _cardBal(c) {
  if (!c) return 0;
  const cur = c.currentBal;
  if (cur !== null && cur !== undefined && cur !== '') {
    const n = parseFloat(cur);
    if (!isNaN(n)) return n;
  }
  return parseFloat(c.beginBal) || 0;
}



// Computes "pay this much on each card this month" — minimum (capped at
// remaining balance) plus any extra from the monthly budget, allocated per
// the avalanche/snowball strategy and cascading to the next card if the
// current target's balance is smaller than the extra available.
function _thisMonthPaymentPlan() {
  const today = new Date().toISOString().slice(0, 10);
  const data = S.debtCards
    .filter(c => !c.paidInFull)
    .filter(c => !(c.endDate && c.endDate < today)) // exclude expired leases
    .map(c => ({
      id:       c.id,
      name:     c.name || 'Card',
      balance:  Math.max(0, _cardBal(c)),
      rate:     Math.max(0, parseFloat(c.rate) || 0),
      minimum:  Math.max(1, _payoffPayment(c) || 25),   // V3: a mortgage's escrow never reduces the balance
      non_principal: _nonPrincipalPart(c),   // V3: taken out of the budget in _simAsk
      pslf:     _pslfIsFlagged(c._dbId || c.id),
      isLease:  (c.debtType || 'credit') === 'lease',
    }))
    .filter(c => c.balance > 0);

  if (!data.length) return null;

  const budget = _getMonthlyBudget();

  // Minimums, capped so we never suggest paying more than what's owed
  const mins = {};
  data.forEach(c => { mins[c.id] = Math.min(c.minimum, c.balance); });
  const totalMin = Object.values(mins).reduce((s,m) => s+m, 0);

  // Extra beyond minimums, allocated to the avalanche/snowball target —
  // loans flagged for income-driven forgiveness never receive extra.
  const sorted = data.filter(c => !c.pslf && !c.isLease).sort((a,b) =>
    S.debtMethod === 'avalanche' ? b.rate - a.rate : a.balance - b.balance);

  let remainingExtra = Math.max(0, budget - totalMin);
  const extras = {};
  let payoffTargetId = null, nextTargetId = null;
  for (const c of sorted) {
    const room = Math.max(0, c.balance - mins[c.id]);
    if (remainingExtra > 0.01 && room > 0) {
      const apply = Math.min(remainingExtra, room);
      extras[c.id] = apply;
      remainingExtra -= apply;
      if (payoffTargetId === null) payoffTargetId = c.id;
      else if (nextTargetId === null) nextTargetId = c.id;
    } else if (payoffTargetId !== null && nextTargetId === null && c.id !== payoffTargetId) {
      nextTargetId = c.id;
    }
  }

  const rows = data.map(c => ({
    id:      c.id,
    name:    c.name,
    minimum: mins[c.id],
    extra:   extras[c.id] || 0,
    total:   mins[c.id] + (extras[c.id] || 0),
    pslf:    c.pslf,
  }));

  // If the primary target gets fully paid off this month, the extra shifts
  // to the next debt in line next month — surface that as a preview.
  let nextMonthNote = null;
  if (payoffTargetId !== null) {
    const target = data.find(c => c.id === payoffTargetId);
    const targetRow = rows.find(r => r.id === payoffTargetId);
    if (target && targetRow && targetRow.total >= target.balance - 0.01) {
      const next = data.find(c => c.id === (nextTargetId ?? sorted.find(c=>c.id!==payoffTargetId)?.id));
      if (next) nextMonthNote = `Once ${target.name} is paid off, next month's extra shifts to ${next.name}.`;
      else nextMonthNote = `Once ${target.name} is paid off, you're debt-free!`;
    }
  }

  return { rows, totalMin, budget, underMinimum: budget < totalMin, nextMonthNote };
}

function _paymentPlanHTML() {
  const plan = _thisMonthPaymentPlan();
  if (!plan) return '';

  const rowsHTML = plan.rows.map(r => `
    <div style="display:flex;justify-content:space-between;align-items:center;padding:8px 0;border-bottom:0.5px solid var(--steel-2)">
      <div>
        <div style="font-size:13px;font-weight:500">${esc(r.name)}</div>
        ${r.extra > 0.01
          ? `<div style="font-size:11px;color:var(--pine)">Minimum ${fmt(r.minimum)} + extra ${fmt(r.extra)}</div>`
          : `<div style="font-size:11px;color:var(--slate)">${r.pslf ? 'Minimum (income-driven plan)' : 'Minimum payment'}</div>`}
      </div>
      <div style="font-family:var(--font-mono);font-size:15px;font-weight:600;${r.extra > 0.01 ? 'color:var(--pine)' : ''}">${fmt(r.total)}</div>
    </div>`).join('');

  const warning = plan.underMinimum ? `
    <div style="padding:8px 10px;background:var(--gold-bg);border-radius:var(--r-md);
                border:0.5px solid var(--gold);margin-bottom:10px;font-size:12px;line-height:1.5">
      ⚠ Your monthly budget (${fmt(plan.budget)}) is below the combined minimums (${fmt(plan.totalMin)}).
      The amounts below are minimums only — increase your budget to add extra toward payoff.
    </div>` : '';

  const note = plan.nextMonthNote ? `
    <div style="margin-top:10px;font-size:11px;color:var(--slate)">${esc(plan.nextMonthNote)}</div>` : '';

  return `
    <div class="card mb-4">
      <div class="card-label">This month's payments${helpIcon('this_months_payments')}</div>
      ${warning}
      ${rowsHTML}
      ${note}
    </div>`;
}


// Cards collapsed to a compact summary row (in-memory; resets on reload)
let _collapsedCards = new Set();

function toggleCardCollapse(id) {
  if (_collapsedCards.has(id)) _collapsedCards.delete(id);
  else _collapsedCards.add(id);
  _renderCardList();
  renderLoanFlags();
}

// ── Debt card trend helpers ───────────────────────────────────────────────────
// These functions read _debtHistoryCache to produce inline sparklines and
// trend stats for each debt card. History is loaded when the Budget page opens
// and auto-written after every import (B6b). No history = no sparkline (silent).

// Returns an SVG sparkline string for a card's balance history, or '' if < 2 points.
// w/h in px. trending down = pine (progress), flat/up = ember (warning).
function _debtCardSparkline(card, w=80, h=24) {
  const history = (_debtHistoryCache[String(card._dbId)] || []).slice().reverse(); // oldest→newest
  if (history.length < 2) return '';

  const vals = history.map(h => h.balance);
  const maxV  = Math.max(...vals);
  const minV  = Math.min(...vals);
  const range = maxV - minV || 1;

  // Trend: is the last value lower than the first? Pine = going down (good).
  const trending = vals[vals.length-1] < vals[0] ? 'var(--pine)' : 'var(--ember)';

  const pts = vals.map((v, i) => {
    const x = Math.round((i / (vals.length - 1)) * (w - 4)) + 2;
    const y = Math.round(h - 2 - ((v - minV) / range) * (h - 4));
    return `${x},${y}`;
  }).join(' ');

  // Last point dot
  const lastPt = pts.split(' ').pop().split(',');
  const dotSvg = `<circle cx="${lastPt[0]}" cy="${lastPt[1]}" r="2" fill="${trending}"/>`;

  return `<svg width="${w}" height="${h}" viewBox="0 0 ${w} ${h}"
    style="display:block;flex-shrink:0" aria-hidden="true">
    <polyline points="${pts}" fill="none" stroke="${trending}"
      stroke-width="1.5" stroke-linejoin="round" stroke-linecap="round"/>
    ${dotSvg}
  </svg>`;
}

// Returns a stats object from history: { months, totalInterest, avgPayment,
// netReduction, trend } or null if < 2 months of data.
function _debtCardTrendStats(card) {
  const history = (_debtHistoryCache[String(card._dbId)] || []).slice().reverse(); // oldest→newest
  if (history.length < 2) return null;

  // Total interest from interest_charged field (B6a/B6b), or estimated
  let totalInterest = 0;
  let hasRealInterest = false;
  history.forEach(h => {
    if (h.interest_charged != null) {
      totalInterest += h.interest_charged;
      hasRealInterest = true;
    }
  });
  // Fallback estimate: sum(payment - balance_reduction) per month
  if (!hasRealInterest) {
    for (let i = 1; i < history.length; i++) {
      const balDrop = history[i-1].balance - history[i].balance;
      const pmt     = history[i].payment || 0;
      if (pmt > 0 && balDrop < pmt) totalInterest += Math.max(0, pmt - balDrop);
    }
  }

  const payments   = history.filter(h => h.payment > 0).map(h => h.payment);
  const avgPayment = payments.length
    ? Math.round(payments.reduce((s,p) => s+p, 0) / payments.length)
    : 0;

  const netReduction = history[0].balance - history[history.length - 1].balance;
  const months       = history.length;

  // Monthly reduction rate (last 3 months for recency)
  const recent = history.slice(-3);
  const monthlyRate = recent.length >= 2
    ? (recent[0].balance - recent[recent.length-1].balance) / (recent.length - 1)
    : netReduction / Math.max(1, months - 1);

  return {
    months,
    totalInterest: Math.round(totalInterest * 100) / 100,
    hasRealInterest,
    avgPayment,
    netReduction:  Math.round(netReduction * 100) / 100,
    monthlyRate:   Math.round(monthlyRate * 100) / 100,
    trending:      netReduction > 0 ? 'down' : netReduction < -10 ? 'up' : 'flat',
  };
}

function _renderCardList() {
  const cont = g('cardList');
  if (!cont) return;
  // V4: the rows' payoff dates belong to a plan; say which, once.
  const _plan = _simulatePayoff(0);
  const _planNote = _plan
    ? `<div class="debt-plan-note" style="font-size:12px;color:var(--slate);padding:4px 16px 8px;line-height:1.5">Payoff dates are from ${_planScenario()}. Change the plan and they change.</div>`
    : '';
  cont.innerHTML = _planNote + S.debtCards
    .filter(c => !_pslfIsFlagged(c._dbId || c.id))
    .map(c => _debtCardRowHTML(c)).join('');

  // Event delegation for debt type buttons — more reliable than inline onclick
  // on dynamically injected content, especially in pywebview.
  // Use once-per-render listener to avoid stacking multiple handlers.
  cont.removeEventListener('click', _cardListClickHandler);
  cont.addEventListener('click', _cardListClickHandler);
}

function _cardListClickHandler(e) {
  const btn = e.target.closest('[data-settype]');
  if (!btn) return;
  e.stopPropagation();
  const cardId = parseInt(btn.dataset.settype);
  const type   = btn.dataset.type;
  if (cardId && type) setDebtType(cardId, type);
}

// Returns the correct input fields for the debt card bloom based on type.
// Extracted from the template to avoid nested template literal hell.
// Balance field for the debt bloom (loan + credit share it). When the card is
// marked paid in full the value renders struck-through/greyed — DISPLAY ONLY.
// currentBal is never mutated by the paid state; unchecking restores normal style.
function _debtBalanceField(c) {
  const paid = !!c.paidInFull;
  return `
      <div class="field" style="margin:0">
        <label>Balance${paid ? ' <span style="color:var(--pine);font-weight:600">· Paid in full</span>' : ''}</label>
        <input type="number" value="${c.currentBal ?? c.beginBal ?? ''}" min="0" step="0.01"
          style="${paid ? 'text-decoration:line-through;color:var(--slate-2)' : ''}"
          oninput="setCardField(${c.id},'currentBal',this.value)">
      </div>`;
}

function _debtBloomFields(c, debtType, _dds) {
  const dueLabelExtra = _dds
    ? ` <span style="font-family:var(--font-mono);font-weight:400;color:${_dds.color}">${_dds.label}</span>`
    : '';
  const termVal = (c.startDate && c.endDate) ? _debtCalcTermMonths(c.startDate, c.endDate) : '';

  if (debtType === 'lease') {
    // Lease: fixed payment, no balance/APR. Just payment + dates.
    return `
      <div class="field" style="margin:0">
        <label>Monthly payment</label>
        <input type="number" value="${c.minimum ?? ''}" min="0" step="0.01"
          oninput="setCardField(${c.id},'minimum',this.value)">
        <div style="font-size:10px;color:var(--slate-2);margin-top:3px;min-height:12px">${_figureSourceLabel(c.minSource, c.statementAsOf)}</div>
      </div>
      <div class="field" style="margin:0">
        <label>Due day${dueLabelExtra}</label>
        <input type="number" value="${c.dueDay ?? ''}" min="1" max="31" placeholder="e.g. 15"
          oninput="setCardField(${c.id},'dueDay',this.value)">
      </div>
      <div class="field" style="margin:0">
        <label>Lease start</label>
        <input type="date" value="${c.startDate || ''}"
          oninput="setCardField(${c.id},'startDate',this.value);_debtCalcEndDate(${c.id})">
      </div>
      <div class="field" style="margin:0">
        <label>Term (months)</label>
        <input type="number" min="1" max="120" step="1"
          value="${termVal}" placeholder="e.g. 36"
          id="bterm-${c.id}"
          oninput="setCardField(${c.id},'_termMonths',this.value);_debtCalcEndDate(${c.id})"
          style="font-family:var(--font-mono)">
      </div>
      <div class="field" style="margin:0">
        <label>Lease ends</label>
        <input type="date" value="${c.endDate || ''}"
          id="bend-${c.id}"
          oninput="setCardField(${c.id},'endDate',this.value);_debtCalcTermFromEnd(${c.id})">
      </div>`;
  }

  if (debtType === 'loan' || debtType === 'mortgage') {
    // Loan / mortgage: balance + APR + fixed payment + due + start + term + maturity date
    // (a mortgage adds the principal & interest split below - V3)
    return `${_debtBalanceField(c)}
      <div class="field" style="margin:0">
        <label>APR %${helpIcon('apr')}</label>
        <input type="number" id="dcRate-${c.id}" value="${c.rate ?? ''}" min="0" step="0.1"
          oninput="setCardField(${c.id},'rate',this.value)">
        <div style="font-size:10px;color:var(--slate-2);margin-top:3px;min-height:12px">${_figureSourceLabel(c.rateSource, c.statementAsOf)}</div>
      </div>
      <div class="field" style="margin:0">
        <label>Payment</label>
        <input type="number" value="${c.minimum ?? ''}" min="0" step="0.01"
          oninput="setCardField(${c.id},'minimum',this.value)">
        <div style="font-size:10px;color:var(--slate-2);margin-top:3px;min-height:12px">${_figureSourceLabel(c.minSource, c.statementAsOf)}</div>
      </div>
      <div class="field" style="margin:0">
        <label>Due day${dueLabelExtra}</label>
        <input type="number" value="${c.dueDay ?? ''}" min="1" max="31" placeholder="e.g. 15"
          oninput="setCardField(${c.id},'dueDay',this.value)">
      </div>
      <div class="field" style="margin:0">
        <label>Loan start</label>
        <input type="date" value="${c.startDate || ''}"
          oninput="setCardField(${c.id},'startDate',this.value);_debtCalcEndDate(${c.id})">
      </div>
      <div class="field" style="margin:0">
        <label>Term (months)</label>
        <input type="number" min="1" max="360" step="1"
          value="${termVal}" placeholder="e.g. 60"
          id="bterm-${c.id}"
          oninput="setCardField(${c.id},'_termMonths',this.value);_debtCalcEndDate(${c.id})"
          style="font-family:var(--font-mono)">
      </div>
      <div class="field" style="margin:0">
        <label>Payoff / maturity date</label>
        <input type="date" value="${c.endDate || ''}"
          id="bend-${c.id}"
          oninput="setCardField(${c.id},'endDate',this.value);_debtCalcTermFromEnd(${c.id})">
      </div>${debtType === 'mortgage' ? _mortgageSplitHTML(c) : ''}`;
  }

  // Credit card (default): balance + APR + min + due day only
  return `${_debtBalanceField(c)}
      <div class="field" style="margin:0">
        <label>APR %${helpIcon('apr')}</label>
        <input type="number" id="dcRate-${c.id}" value="${c.rate ?? ''}" min="0" step="0.1"
          oninput="setCardField(${c.id},'rate',this.value)">
        <div style="font-size:10px;color:var(--slate-2);margin-top:3px;min-height:12px">${_figureSourceLabel(c.rateSource, c.statementAsOf)}</div>
      </div>
      <div class="field" style="margin:0">
        <label>Min</label>
        <input type="number" value="${c.minimum ?? ''}" min="0" step="0.01"
          oninput="setCardField(${c.id},'minimum',this.value)">
        <div style="font-size:10px;color:var(--slate-2);margin-top:3px;min-height:12px">${_figureSourceLabel(c.minSource, c.statementAsOf)}</div>
      </div>
      <div class="field" style="margin:0">
        <label>Due day${dueLabelExtra}</label>
        <input type="number" value="${c.dueDay ?? ''}" min="1" max="31" placeholder="e.g. 15"
          oninput="setCardField(${c.id},'dueDay',this.value)">
      </div>`;
}

function _debtCardRowHTML(c, opts={}) {
  const pslfKey = c._dbId || c.id;
  const flagged = _pslfIsFlagged(pslfKey);
  const _dds    = _debtDueDateStatus(c);

  // ── Collapsed: compact summary row ──────────────────────────────────────
  if (_collapsedCards.has(c.id)) {
    const programLabel = flagged ? (PSLF_PROGRAMS[_pslfData(pslfKey)?.program || 'pslf']?.label || 'PSLF') : '';
    return `
    <div class="debt-card-row" id="dc-${c.id}" style="display:flex;align-items:center;gap:10px;padding:10px 16px;${c.paidInFull ? 'opacity:.6' : ''}">
      <input type="checkbox" ${c.paidInFull ? 'checked' : ''} title="Paid in full"
        onchange="setCardPaidInFull(${c.id}, this.checked)">
      <div style="flex:1;font-size:13px;font-weight:600;color:var(--ink);overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${esc(c.name||'Card')}</div>
      ${c.paidInFull
        // Option 2 (d21): display-only paid treatment. The stored currentBal is
        // NEVER mutated — strike it through so the history is visible but clearly
        // no longer owed. Unchecking the box restores the normal row untouched.
        ? `<div class="text-mono" style="font-size:13px;flex-shrink:0">
             <s style="color:var(--slate-2);opacity:.65">${fmt(_cardBal(c))}</s>
             <span style="font-size:10px;font-weight:600;color:var(--pine);margin-left:6px">Paid in full</span>
           </div>`
        : `<div class="text-mono" style="font-size:13px;color:var(--slate);flex-shrink:0">${fmt(_cardBal(c))}</div>`}
      ${(!c.paidInFull && _dds) ? `<span style="font-size:10px;font-family:var(--font-mono);color:${_dds.color};flex-shrink:0">${_dds.label}</span>` : ''}
      ${(() => {
        // Lease / loan end date countdown
        if (c.paidInFull) return '';   // paid card: no countdown chip
        if (!c.endDate) return '';
        const today = new Date().toISOString().slice(0,10);
        if (c.endDate < today) {
          return `<span style="font-size:10px;font-family:var(--font-mono);color:var(--slate-2);flex-shrink:0" title="Ended — excluded from DTI">ended ${c.endDate}</span>`;
        }
        const moLeft = Math.round((new Date(c.endDate) - new Date()) / (1000*60*60*24*30.4));
        const endLbl = new Date(c.endDate).toLocaleDateString('en-US',{month:'short',year:'numeric'});
        const color  = moLeft <= 3 ? 'var(--gold)' : 'var(--slate-2)';
        const label  = _debtType(c._dbId||c.id) === 'lease' ? `lease ends ${endLbl}` : `matures ${endLbl}`;
        return `<span style="font-size:10px;font-family:var(--font-mono);color:${color};flex-shrink:0" title="${moLeft} months remaining">${label}</span>`;
      })()}
      ${(() => {
        // Per-card payoff date — use the avalanche simulation if this is the active page
        // Paid cards keep their last currentBal (display-only invariant), so without
        // this guard a paid card shows a bogus "~Mar 2027" / "min too low" chip.
        if (c.paidInFull) return '';
        const bal = _cardBal(c);
        const budget = _getMonthlyBudget();
        if (bal <= 0 || budget <= 0) return '';
        // V4: this debt's month in the plan - the same engine run as the debt-free
        // date, rollover included. It used to project this card on its own at its
        // payment plus "a share of extra", which ignored rollover and put every
        // debt but the first target later than the plan does.
        const plan = _simulatePayoff(0);
        if (plan === undefined) return '';   // the engine's answer is on its way; the page redraws when it lands
        const isTarget = S.debtCards.filter(d=>!d.paidInFull)
          .sort((a,b)=> S.debtMethod==='avalanche' ? (parseFloat(b.rate)||0)-(parseFloat(a.rate)||0) : (_cardBal(a))-(_cardBal(b)))
          [0]?.id === c.id;
        // A fact about this debt's own payment, whatever the plan does with it.
        const lowChip = (_payoffPayment(c) || 0) <= bal * (parseFloat(c.rate) || 0) / 1200
          ? `<span style="font-size:10px;font-family:var(--font-mono);color:var(--ember);flex-shrink:0" title="Minimum payment does not cover interest">min too low</span>`
          : '';
        const payoffMo = _planClearedMonth(c, plan);
        if (payoffMo == null) return lowChip;
        const d2 = new Date(); d2.setMonth(d2.getMonth() + payoffMo);
        const label = d2.toLocaleDateString('en-US',{month:'short',year:'numeric'});
        const color = isTarget ? 'var(--gold)' : 'var(--slate-2)';
        // V6: a date built on a missing figure says so.
        const _u = _debtUnknowns(c);
        const assumed = _u.includes('APR') ? ' · 0% APR assumed' : _u.includes('minimum payment') ? ' · minimum estimated'
                      : _u.includes('maturity date') ? ' · whole payment assumed' : '';
        return lowChip + `<span style="font-size:10px;font-family:var(--font-mono);color:${color};flex-shrink:0" title="Under ${_planScenario()}${assumed}">~${label}${assumed}</span>`;
      })()}
      ${(() => {
        const _u = _debtUnknowns(c);
        return _u.length ? `<span style="font-size:10px;color:var(--gold);flex-shrink:0;white-space:nowrap">${_u.join(', ')} not entered</span>` : '';
      })()}
      ${flagged ? `<span style="font-size:10px;padding:1px 7px;border-radius:20px;background:var(--pine-bg);color:#3B6D11;border:0.5px solid #C0DD97;flex-shrink:0;white-space:nowrap">🎓 ${esc(programLabel.split(' ')[0])}</span>` : ''}
      ${_debtCardSparkline(c, 60, 20)}
      <button class="row-del" onclick="toggleCardCollapse(${c.id})" title="Show details">▾ Show</button>
      <button class="row-del" onclick="confirmRemoveCard(${c.id})" title="Remove">×</button>
    </div>`;
  }

  // ── Expanded: full editable row ─────────────────────────────────────────
  const debtType = _debtType(pslfKey);
  return `
    <div class="debt-card-row" id="dc-${c.id}" style="${c.paidInFull ? 'opacity:.75' : ''}">
      <div class="debt-card-name">
        <input type="checkbox" ${c.paidInFull ? 'checked' : ''} title="Paid in full"
          onchange="setCardPaidInFull(${c.id}, this.checked)">
        <input type="text" value="${esc(c.name||'')}" placeholder="Card or loan name"
          oninput="setCardField(${c.id},'name',this.value)"
          style="flex:1;border:none;background:transparent;font-weight:600;font-size:14px;outline:none;font-family:inherit;color:var(--ink)">
        <button class="row-del" onclick="toggleCardCollapse(${c.id})" title="Hide details">▴ Hide</button>
        <button class="row-del" onclick="confirmRemoveCard(${c.id})" title="Remove">×</button>
      </div>
      <div style="display:flex;align-items:flex-end;gap:14px;flex-wrap:wrap;margin-bottom:10px">
        <div style="display:flex;align-items:center;gap:4px;flex-shrink:0">
          <div class="method-toggle">
            <button type="button" class="method-btn ${debtType==='credit'?'active':''}" style="padding:4px 12px;font-size:11px" data-settype="${c.id}" data-type="credit">Credit Card</button>
            <button type="button" class="method-btn ${debtType==='loan'?'active':''}" style="padding:4px 12px;font-size:11px" data-settype="${c.id}" data-type="loan">Loan</button>
            <button type="button" class="method-btn ${debtType==='mortgage'?'active':''}" style="padding:4px 12px;font-size:11px" data-settype="${c.id}" data-type="mortgage">Mortgage</button>
            <button type="button" class="method-btn ${debtType==='lease'?'active':''}" style="padding:4px 12px;font-size:11px" data-settype="${c.id}" data-type="lease">Lease</button>
          </div>${helpIcon('debt_type')}
        </div>
        <div class="debt-card-meta" style="flex:1;min-width:280px;margin:0">
          ${_debtBloomFields(c, debtType, _dds)}</div>
        ${_debtCardLinkHTML(c)}
        ${debtType !== 'lease' ? `<button class="btn btn-ghost btn-sm" style="flex-shrink:0" onclick="openAprEstimator(${c.id})">Estimate APR →</button>` : ''}
      </div>
      <input type="text" value="${esc(c.context||'')}" placeholder="Notes (optional) — e.g. where this debt came from"
        oninput="setCardField(${c.id},'context',this.value)"
        style="width:100%;font-size:12px;padding:7px 10px;border:1px solid var(--steel-2);border-radius:var(--r-md);background:var(--paper);color:var(--ink)">
      ${debtType === 'loan' ? `
      <div style="margin-top:8px;display:flex;align-items:center;font-size:12px;color:var(--slate)">
        <label style="display:flex;align-items:center;gap:6px;cursor:pointer">
          <input type="checkbox" ${flagged?'checked':''} onchange="togglePSLF(${JSON.stringify(pslfKey)}, this.checked)">
          Flag for income-driven forgiveness (PSLF/IBR/SAVE)
        </label>${helpIcon('pslf')}
      </div>` : ''}
      ${(opts.expanded && flagged) ? _pslfDetailsHTML(pslfKey) : ''}
      <div id="aprEst-${c.id}"></div>
      ${(() => {
        // ── Balance trend panel — only shown when history exists ──────────
        const stats    = _debtCardTrendStats(c);
        const history  = (_debtHistoryCache[String(c._dbId)] || []).slice().reverse();
        if (!stats || history.length < 2) return '';

        const sparkline = _debtCardSparkline(c, 140, 36);
        const trendIcon = stats.trending === 'down' ? '↓' : stats.trending === 'up' ? '↑' : '→';
        const trendColor = stats.trending === 'down' ? 'var(--pine)' : stats.trending === 'up' ? 'var(--ember)' : 'var(--slate)';
        const trendLabel = stats.trending === 'down'
          ? `−${fmt(Math.abs(stats.monthlyRate))}/mo avg`
          : stats.trending === 'up'
            ? `+${fmt(Math.abs(stats.monthlyRate))}/mo avg`
            : 'holding steady';

        // Month labels for sparkline: first and last
        const firstMonth = history[0]?.month || '';
        const lastMonth  = history[history.length-1]?.month || '';
        const fmtMo = mo => { if (!mo) return ''; const [y,m]=mo.split('-'); return new Date(y,m-1,1).toLocaleDateString('en-US',{month:'short',year:'2-digit'}); };

        return `
          <div style="margin-top:12px;padding:12px 14px;background:var(--mist);border-radius:var(--r-md);border:1px solid var(--steel)">
            <div style="font-size:10px;font-weight:600;letter-spacing:.08em;text-transform:uppercase;color:var(--slate-2);margin-bottom:10px">Balance history · ${stats.months} month${stats.months!==1?'s':''}</div>
            <div style="display:flex;align-items:flex-start;gap:16px;flex-wrap:wrap">
              <div style="flex-shrink:0">
                ${sparkline}
                <div style="display:flex;justify-content:space-between;font-family:var(--font-mono);font-size:9px;color:var(--slate-2);margin-top:2px;width:140px">
                  <span>${fmtMo(firstMonth)}</span><span>${fmtMo(lastMonth)}</span>
                </div>
              </div>
              <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px 20px;font-size:12px;flex:1;min-width:160px">
                <div>
                  <div style="color:var(--slate-2);font-size:10px;margin-bottom:1px">Trend</div>
                  <div style="font-family:var(--font-mono);color:${trendColor};font-weight:600">${trendIcon} ${trendLabel}</div>
                </div>
                <div>
                  <div style="color:var(--slate-2);font-size:10px;margin-bottom:1px">Net reduction</div>
                  <div style="font-family:var(--font-mono);color:${stats.netReduction>0?'var(--pine)':'var(--ember)'};font-weight:600">${stats.netReduction>0?'−':'+'} ${fmt(Math.abs(stats.netReduction))}</div>
                </div>
                ${stats.avgPayment > 0 ? `<div>
                  <div style="color:var(--slate-2);font-size:10px;margin-bottom:1px">Avg payment</div>
                  <div style="font-family:var(--font-mono);color:var(--ink)">${fmt(stats.avgPayment)}/mo</div>
                </div>` : ''}
                ${stats.totalInterest > 0 ? `<div>
                  <div style="color:var(--slate-2);font-size:10px;margin-bottom:1px">Interest paid${stats.hasRealInterest?'':' (est)'}</div>
                  <div style="font-family:var(--font-mono);color:var(--ember)">${fmt(stats.totalInterest)}</div>
                </div>` : ''}
              </div>
            </div>
          </div>`;
      })()}
      ${_debtLedgerSectionHTML(c)}
    </div>`;
}

// ── Debt ledger — manual charge/payment entries (Debt Reconciliation Phase B) ──
// Charges/payments the user enters directly (no CSV/OFX import needed).
// current_balance on the debt account itself stays the single source of
// truth for what's owed; this ledger is a supplementary activity record —
// its "running total" column is the net of the manual entries themselves,
// not a re-derivation of the account balance.
const _debtLedgerCache     = {};   // dbId (string) -> array of entries, or undefined = not loaded
const _debtLinkableCache   = {};   // dbId (string) -> array of linkable checking transactions
const _debtLedgerOpenForm  = {};   // dbId (string) -> 'charge' | 'payment' | null
const _recurringCache      = {};   // dbId (string) -> array of recurring payment patterns

function _debtLedgerSectionHTML(c) {
  if (!c._dbId) return '';   // card not saved yet — no debt_account_id to attach entries to
  const key = String(c._dbId);
  if (_debtLedgerCache[key] === undefined) {
    loadDebtLedger(c._dbId);
    return `<div id="ledgerSection-${c.id}" style="margin-top:12px;padding:12px 14px;background:var(--mist);border-radius:var(--r-md);border:1px solid var(--steel);font-size:11px;color:var(--slate-2)">Loading ledger…</div>`;
  }
  return `<div id="ledgerSection-${c.id}">${_debtLedgerBodyHTML(c)}</div>`;
}

function _debtLedgerBodyHTML(c) {
  const key     = String(c._dbId);
  const entries = _debtLedgerCache[key] || [];
  const openForm= _debtLedgerOpenForm[key];

  // Running total, oldest-first: charge/interest/fee add, payment subtracts.
  // Skipped occurrences never moved money — excluded from the total, not just
  // zero-valued, so they don't reserve a row in runningById at all.
  const chrono = entries.slice().reverse();
  let running = 0;
  const runningById = {};
  for (const e of chrono) {
    if (e.source_type === 'skipped') continue;
    running += (e.entry_type === 'payment') ? -e.amount : e.amount;
    runningById[e.id] = running;
  }

  const VERB = { charge: 'Charged', payment: 'Payment', interest: 'Interest', fee: 'Fee' };
  const rows = entries.length ? entries.map(e => {
    const skipped = e.source_type === 'skipped';
    const verb = skipped ? 'Skipped' : (VERB[e.entry_type] || e.entry_type);
    const linkIcon = e.linked_checking_transaction_id
      ? ` <span title="Linked to a checking transaction — click to view" style="cursor:pointer" onclick="jumpToLinkedCheckingTxn(${e.linked_checking_transaction_id})">💳</span>
          <span title="Unlink (keeps both entries)" style="cursor:pointer;font-size:10px" onclick="unlinkDebtLedgerEntry(${c.id},${e.id})">⛓️‍💥</span>`
      : '';
    return `
    <div id="dle-${e.id}" style="display:flex;align-items:center;gap:10px;padding:6px 0;border-bottom:1px solid var(--steel);font-size:12px;${skipped?'opacity:.55':''}">
      <div style="width:72px;flex-shrink:0;color:var(--slate-2);font-family:var(--font-mono)">${e.entry_date}</div>
      <div style="flex:1;color:var(--ink);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;${skipped?'text-decoration:line-through':''}">${esc(verb)}${e.merchant ? ' · ' + esc(e.merchant) : ''}${e.description ? ' · ' + esc(e.description) : ''}${linkIcon}</div>
      <div style="font-family:var(--font-mono);flex-shrink:0;color:${skipped ? 'var(--slate-2)' : e.entry_type==='payment' ? 'var(--pine)' : 'var(--ink)'}">${skipped?'':(e.entry_type==='payment'?'−':'+')}${fmt(e.amount)}</div>
      <div style="font-family:var(--font-mono);flex-shrink:0;width:70px;text-align:right;color:var(--slate-2)" title="Running total of manual entries">${skipped ? '' : fmt(runningById[e.id])}</div>
      <button class="row-del" onclick="deleteDebtLedgerEntry(${c.id},${e.id})" title="Remove">×</button>
    </div>`;
  }).join('') : `<div style="font-size:11px;color:var(--slate-2);padding:6px 0">No manual entries yet.</div>`;

  return `
    <div style="margin-top:12px;padding:12px 14px;background:var(--mist);border-radius:var(--r-md);border:1px solid var(--steel)">
      <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:8px">
        <div style="font-size:10px;font-weight:600;letter-spacing:.08em;text-transform:uppercase;color:var(--slate-2)">Ledger — manual entries</div>
        <div style="display:flex;gap:8px">
          <button class="btn btn-ghost btn-sm" onclick="toggleDebtLedgerAdd(${c.id},'charge')">+ Charge</button>
          <button class="btn btn-ghost btn-sm" onclick="toggleDebtLedgerAdd(${c.id},'payment')">+ Payment</button>
        </div>
      </div>
      ${openForm ? _debtLedgerAddFormHTML(c, openForm) : ''}
      ${rows}
      ${_recurringListHTML(c)}
    </div>`;
}

// ── Recurring payment patterns (Phase C) ────────────────────────────────────
function _recurringListHTML(c) {
  const key = String(c._dbId);
  if (_recurringCache[key] === undefined) {
    loadRecurringPayments(c._dbId);
    return '';   // nothing to show yet — loader will re-render when it resolves
  }
  const patterns = _recurringCache[key];
  if (!patterns.length) return '';

  const FREQ_LABEL = { monthly: '/month', biweekly: '/2wk', weekly: '/week' };
  const rows = patterns.map(r => {
    const dayLabel = r.scheduled_date_of_month ? `day ${r.scheduled_date_of_month}` : 'last day of month';
    const comp = r.compliance;
    // "the plan" here is the pattern's own saved amount — this codebase has
    // no persisted payoff-plan entity to compare against (see server.py ::
    // get_payment_compliance). Only worth a line once there's real history.
    const complianceLine = (comp && comp.total > 0) ? `
      <div style="font-size:11px;color:var(--slate-2);margin-top:2px">
        ${comp.on_time}/${comp.total} on-time (±5%)${comp.under_plan ? ` · ${comp.under_plan} under-plan` : ''}${comp.over_plan ? ` · ${comp.over_plan} over-plan` : ''} · avg variance ${comp.avg_variance_pct > 0 ? '+' : ''}${comp.avg_variance_pct}%
      </div>` : '';
    return `
      <div style="padding:5px 0;font-size:12px;${r.is_active?'':'opacity:.55'}">
        <div style="display:flex;align-items:center;gap:10px">
          <div style="flex:1">${fmt(r.amount)}${FREQ_LABEL[r.frequency]||''} · ${dayLabel}${r.is_active?'':' · paused'}</div>
          <button class="btn btn-ghost btn-sm" onclick="toggleRecurringActive(${c.id},${r.id},${!r.is_active})">${r.is_active?'Pause':'Resume'}</button>
          <button class="btn btn-ghost btn-sm" onclick="removeRecurringPayment(${c.id},${r.id})">Remove</button>
        </div>
        ${complianceLine}
      </div>`;
  }).join('');

  return `
    <div style="margin-top:10px;padding-top:10px;border-top:1px solid var(--steel)">
      <div style="font-size:10px;font-weight:600;letter-spacing:.08em;text-transform:uppercase;color:var(--slate-2);margin-bottom:6px">Recurring payments</div>
      ${rows}
    </div>`;
}

async function loadRecurringPayments(dbId) {
  try {
    _recurringCache[String(dbId)] = await API.get(`/api/debt/${dbId}/recurring`);
  } catch (e) {
    _recurringCache[String(dbId)] = [];
    _gwErr('loadRecurringPayments')(e);
  }
  const card = S.debtCards.find(x => x._dbId === dbId);
  const el = card && g(`ledgerSection-${card.id}`);
  if (el) el.innerHTML = _debtLedgerBodyHTML(card);
}

async function toggleRecurringActive(cardId, rid, makeActive) {
  const c = S.debtCards.find(x => x.id === cardId);
  if (!c || !c._dbId) return;
  try {
    await API.patch(`/api/debt/recurring/${rid}`, { is_active: makeActive });
    delete _recurringCache[String(c._dbId)];
    await loadRecurringPayments(c._dbId);
  } catch (e) {
    _gwErr('toggleRecurringActive')(e);
    showToast('Could not update recurring payment', e.message || '', 'error');
  }
}

function removeRecurringPayment(cardId, rid) {
  const c = S.debtCards.find(x => x.id === cardId);
  if (!c || !c._dbId) return;
  confirmAction('Remove this recurring payment?', 'No more drafts will be generated from it. Past entries are unaffected.', async () => {
    try {
      await API.delete(`/api/debt/recurring/${rid}`);
      delete _recurringCache[String(c._dbId)];
      await loadRecurringPayments(c._dbId);
    } catch (e) {
      _gwErr('removeRecurringPayment')(e);
      showToast('Could not remove recurring payment', e.message || '', 'error');
    }
  });
}

// ── Pending draft confirmations (Phase C) ───────────────────────────────────
let _pendingDrafts = [];

async function loadPendingDrafts() {
  try {
    _pendingDrafts = await API.get('/api/debt/drafts/pending');
  } catch (e) {
    _pendingDrafts = [];
    _gwErr('loadPendingDrafts')(e);
  }
  _renderPendingDrafts();
}

function _renderPendingDrafts() {
  const card = g('pendingDraftsCard');
  const list = g('pendingDraftsList');
  if (!card || !list) return;
  if (!_pendingDrafts.length) { card.style.display = 'none'; return; }
  card.style.display = '';
  list.innerHTML = _pendingDrafts.map(_pendingDraftRowHTML).join('');
}

function _pendingDraftRowHTML(d) {
  return `
    <div style="padding:8px 0;border-bottom:1px solid var(--steel);font-size:13px" id="draftRow-${d.id}">
      <div style="display:flex;align-items:center;gap:10px">
        <div style="flex:1">
          <div style="color:var(--ink);font-weight:600">${esc(d.debt_account_name)}</div>
          <div style="font-size:11px;color:var(--slate-2)">Due ${d.entry_date} · your usual ${fmt(d.amount)}</div>
        </div>
        <div style="display:flex;gap:6px;flex-shrink:0">
          <button class="btn btn-secondary btn-sm" onclick="confirmDraftAsIs(${d.id})">Confirm</button>
          <button class="btn btn-ghost btn-sm" onclick="toggleDraftEditForm(${d.id})">Edit</button>
          <button class="btn btn-ghost btn-sm" onclick="skipDraft(${d.id})">Skip</button>
        </div>
      </div>
      <div id="draftEditArea-${d.id}"></div>
    </div>`;
}

function toggleDraftEditForm(entryId) {
  const area = g(`draftEditArea-${entryId}`);
  if (!area) return;
  if (area.innerHTML.trim()) { area.innerHTML = ''; return; }
  const d = _pendingDrafts.find(x => x.id === entryId);
  if (!d) return;
  area.innerHTML = `
    <div style="margin-top:8px;padding:10px;background:var(--paper);border:1px solid var(--steel-2);border-radius:var(--r-sm)">
      <div class="field-row" style="margin-bottom:8px">
        <div class="field" style="margin:0"><label>Date</label><input type="date" id="draftDate-${d.id}" value="${d.entry_date}"></div>
        <div class="field" style="margin:0"><label>Amount ($)</label><input type="number" id="draftAmount-${d.id}" min="0.01" step="0.01" value="${d.amount}"></div>
      </div>
      <div style="display:flex;gap:8px;align-items:center">
        <button class="btn btn-secondary btn-sm" onclick="confirmDraftWithEdits(${d.id})">Save &amp; confirm</button>
        <button class="btn btn-ghost btn-sm" onclick="toggleDraftEditForm(${d.id})">Cancel</button>
        <span id="draftError-${d.id}" style="font-size:11px;color:var(--ember)"></span>
      </div>
    </div>`;
}

function _refreshDebtLedgerAfterDraftChange(debtAccountId) {
  delete _debtLedgerCache[String(debtAccountId)];
  const card = S.debtCards.find(x => x._dbId === debtAccountId);
  if (card && g(`ledgerSection-${card.id}`)) loadDebtLedger(debtAccountId);
}

async function confirmDraftAsIs(entryId) {
  const draft = _pendingDrafts.find(d => d.id === entryId);
  try {
    await API.post(`/api/debt/drafts/${entryId}/confirm`, {});
    _pendingDrafts = _pendingDrafts.filter(d => d.id !== entryId);
    _renderPendingDrafts();
    showToast('Payment confirmed');
    if (draft) _refreshDebtLedgerAfterDraftChange(draft.debt_account_id);
  } catch (e) {
    _gwErr('confirmDraftAsIs')(e);
    showToast('Could not confirm payment', e.message || '', 'error');
  }
}

async function confirmDraftWithEdits(entryId) {
  const draft  = _pendingDrafts.find(d => d.id === entryId);
  const errEl  = g(`draftError-${entryId}`);
  const amount = parseFloat(g(`draftAmount-${entryId}`)?.value);
  const dateVal= g(`draftDate-${entryId}`)?.value;
  if (!(amount > 0) || !dateVal) {
    if (errEl) errEl.textContent = 'Enter a date and an amount greater than $0.';
    return;
  }
  try {
    await API.post(`/api/debt/drafts/${entryId}/confirm`, { amount, entry_date: dateVal });
    _pendingDrafts = _pendingDrafts.filter(d => d.id !== entryId);
    _renderPendingDrafts();
    showToast('Payment confirmed');
    if (draft) _refreshDebtLedgerAfterDraftChange(draft.debt_account_id);
  } catch (e) {
    if (errEl) errEl.textContent = e.message || 'Could not save.';
  }
}

async function skipDraft(entryId) {
  const draft = _pendingDrafts.find(d => d.id === entryId);
  try {
    // Not a delete — a deleted draft has no idempotency record, so it would
    // silently regenerate on the next load. skip marks the occurrence
    // dismissed instead (server.py :: skip_debt_draft).
    await API.post(`/api/debt/drafts/${entryId}/skip`, {});
    _pendingDrafts = _pendingDrafts.filter(d => d.id !== entryId);
    _renderPendingDrafts();
    if (draft) _refreshDebtLedgerAfterDraftChange(draft.debt_account_id);
  } catch (e) {
    _gwErr('skipDraft')(e);
    showToast('Could not skip payment', e.message || '', 'error');
  }
}

// ── Checking transaction linking (Phase D) ──────────────────────────────────
function _flashHighlight(el) {
  if (!el) return;
  el.scrollIntoView({ behavior: 'smooth', block: 'center' });
  const prev = el.style.outline;
  el.style.outline = '2px solid var(--gold)';
  el.style.outlineOffset = '2px';
  setTimeout(() => { el.style.outline = prev; }, 2000);
}

async function jumpToLinkedDebtEntry(entryId) {
  let entry;
  try {
    entry = await API.get(`/api/debt/ledger/${entryId}`);
  } catch (e) {
    _gwErr('jumpToLinkedDebtEntry')(e);
    showToast('Could not open the linked debt entry', e.message || '', 'error');
    return;
  }
  showView('debt');
  const card = S.debtCards.find(c => c._dbId === entry.debt_account_id);
  if (!card) return;
  _collapsedCards.delete(card.id);
  _renderCardList();
  await loadDebtLedger(card._dbId);
  setTimeout(() => _flashHighlight(g(`dle-${entryId}`)), 150);
}

function jumpToLinkedCheckingTxn(txnId) {
  showView('ledger');
  setTimeout(() => {
    _flashHighlight(document.querySelector(`#ledgerBody .row[data-id="${txnId}"]`));
  }, 150);
}

function openLinkToDebtPicker(txnId) {
  const debts = (S.debtCards || []).filter(c => c._dbId);
  if (!debts.length) {
    showToast('No debt accounts yet', 'Add a card or loan first, on the Debt Payoff page', 'info');
    return;
  }
  const options = debts.map(c => `<option value="${c._dbId}">${esc(c.name || 'Card')}</option>`).join('');
  const html = `
    <div style="margin-top:10px;text-align:left">
      <label style="font-size:12px;color:var(--slate);display:block;margin-bottom:6px">Link this transaction to:</label>
      <select id="linkDebtPicker" style="width:100%">${options}</select>
    </div>`;
  confirmAction('Link to a debt account', html, () => {
    const debtId = parseInt(g('linkDebtPicker')?.value);
    if (debtId) submitLinkCheckingTxnToDebt(txnId, debtId);
  }, 'Link', false);
}

async function submitLinkCheckingTxnToDebt(txnId, debtId) {
  try {
    await API.post(`/api/transactions/${txnId}/link-debt`, { debt_account_id: debtId });
    showToast('Linked to debt account');
    delete _debtLedgerCache[String(debtId)];
    // linked_debt_entry_id lives server-side only — re-fetch this page of
    // transactions rather than guessing the new entry id client-side.
    const res = await API.get('/api/transactions?per_page=5000');
    const payload = res.data || res;
    S.transactions = Array.isArray(payload) ? payload : (payload?.items || payload?.transactions || []);
    if (document.querySelector('#view-ledger.active')) renderLedger();
  } catch (e) {
    _gwErr('submitLinkCheckingTxnToDebt')(e);
    showToast('Could not link transaction', e.message || '', 'error');
  }
}

function unlinkDebtLedgerEntry(cardId, entryId) {
  const c = S.debtCards.find(x => x.id === cardId);
  if (!c || !c._dbId) return;
  confirmAction('Unlink this entry?', 'The debt entry and the checking transaction both stay — only the connection between them is removed.', async () => {
    try {
      await API.post(`/api/debt/ledger/${entryId}/unlink`, {});
      delete _debtLedgerCache[String(c._dbId)];
      await loadDebtLedger(c._dbId);
      const res = await API.get('/api/transactions?per_page=5000');   // clears the checking side's 💳 too
      const payload = res.data || res;
      S.transactions = Array.isArray(payload) ? payload : (payload?.items || payload?.transactions || []);
    } catch (e) {
      _gwErr('unlinkDebtLedgerEntry')(e);
      showToast('Could not unlink', e.message || '', 'error');
    }
  }, 'Unlink', false);
}

function _debtLedgerAddFormHTML(c, type) {
  const isPayment = type === 'payment';
  const linkable  = isPayment ? (_debtLinkableCache[String(c._dbId)] || []) : [];
  if (isPayment && _debtLinkableCache[String(c._dbId)] === undefined) {
    loadLinkableTransactions(c._dbId, c.id);
  }
  return `
    <div style="margin-bottom:10px;padding:10px;background:var(--paper);border:1px solid var(--steel-2);border-radius:var(--r-sm)">
      <div class="field-row" style="margin-bottom:8px">
        <div class="field" style="margin:0"><label>Date</label><input type="date" id="ledgerDate-${c.id}" value="${today()}"></div>
        <div class="field" style="margin:0"><label>Amount ($)</label><input type="number" id="ledgerAmount-${c.id}" min="0.01" step="0.01" placeholder="0.00"></div>
      </div>
      ${!isPayment ? `
      <div class="field-row" style="margin-bottom:8px">
        <div class="field" style="margin:0"><label>Merchant</label><input type="text" id="ledgerMerchant-${c.id}" placeholder="e.g. Costco" onblur="suggestCategoryFor(${c.id})"></div>
        <div class="field" style="margin:0"><label>Category <span id="ledgerCatSuggest-${c.id}" style="font-weight:400;color:var(--slate-2)"></span></label><input type="text" id="ledgerCategory-${c.id}" placeholder="optional"></div>
      </div>` : ''}
      <div class="field" style="margin:0 0 8px 0"><label>Description (optional)</label><input type="text" id="ledgerDesc-${c.id}"></div>
      ${isPayment && linkable.length ? `
      <div class="field" style="margin:0 0 8px 0">
        <label>Link to a checking transaction? (optional)</label>
        <select id="ledgerLinkTxn-${c.id}">
          <option value="">— none —</option>
          ${linkable.map(t => `<option value="${t.id}">${t.date} · ${esc(t.description||t.merchant||'')} · ${fmt(Math.abs(t.amount))}</option>`).join('')}
        </select>
      </div>` : ''}
      ${isPayment ? `
      <div style="margin:0 0 8px 0">
        <label style="display:flex;align-items:center;gap:6px;cursor:pointer;font-size:12px;color:var(--slate)">
          <input type="checkbox" id="ledgerSaveRecurring-${c.id}" onchange="_toggleRecurringFields(${c.id})">
          Save this as a recurring payment
        </label>
        <div id="ledgerRecurringFields-${c.id}" style="display:none;margin-top:8px" class="field-row">
          <div class="field" style="margin:0"><label>Day of month (blank = last day)</label><input type="number" id="ledgerRecurDay-${c.id}" min="1" max="31" placeholder="e.g. 15"></div>
          <div class="field" style="margin:0"><label>Frequency</label>
            <select id="ledgerRecurFreq-${c.id}">
              <option value="monthly">Monthly</option>
              <option value="biweekly">Biweekly</option>
              <option value="weekly">Weekly</option>
            </select>
          </div>
        </div>
      </div>` : ''}
      <div style="display:flex;gap:8px;align-items:center">
        <button class="btn btn-secondary btn-sm" onclick="submitDebtLedgerEntry(${c.id},'${type}')">Add ${isPayment?'payment':'charge'}</button>
        <button class="btn btn-ghost btn-sm" onclick="toggleDebtLedgerAdd(${c.id},'${type}')">Cancel</button>
        <span id="ledgerError-${c.id}" style="font-size:11px;color:var(--ember)"></span>
      </div>
    </div>`;
}

function _toggleRecurringFields(cardId) {
  const box = g(`ledgerSaveRecurring-${cardId}`);
  const area = g(`ledgerRecurringFields-${cardId}`);
  if (area) area.style.display = box?.checked ? '' : 'none';
}

function toggleDebtLedgerAdd(cardId, type) {
  const c = S.debtCards.find(x => x.id === cardId);
  if (!c || !c._dbId) return;
  const key = String(c._dbId);
  _debtLedgerOpenForm[key] = (_debtLedgerOpenForm[key] === type) ? null : type;
  const el = g(`ledgerSection-${cardId}`);
  if (el) el.innerHTML = _debtLedgerBodyHTML(c);
  if (_debtLedgerOpenForm[key]) g(`ledgerAmount-${cardId}`)?.focus();
}

// Phase H2 Feature 1 (adaptive learning): suggest a category from real
// merchant history (server.py :: suggest_category_for_merchant). Only fills
// the category field if it's still empty — never overwrites something the
// user already typed. _debtCatSuggestions tracks what was shown per cardId
// so submitDebtLedgerEntry can log whether it was kept or changed at save
// time (categorization_suggestion_confirm/reject — Historian).
const _debtCatSuggestions = {};

async function suggestCategoryFor(cardId) {
  const merchantEl = g(`ledgerMerchant-${cardId}`);
  const catEl       = g(`ledgerCategory-${cardId}`);
  const suggestEl   = g(`ledgerCatSuggest-${cardId}`);
  if (!merchantEl || !catEl || !merchantEl.value.trim()) return;
  try {
    const res = await API.get(`/api/categories/suggest?merchant=${encodeURIComponent(merchantEl.value.trim())}`);
    if (!res.category || res.sample_size < 2) { if (suggestEl) suggestEl.textContent = ''; return; }
    if (suggestEl) suggestEl.textContent = `· ${res.category}? (${res.confidence_pct}% of ${res.sample_size})`;
    _debtCatSuggestions[cardId] = { merchant: merchantEl.value.trim(), category: res.category };
    if (!catEl.value.trim()) catEl.value = res.category;
  } catch (e) {
    _gwErr('suggestCategoryFor')(e);
  }
}

// Phase H2 Feature 4 (adaptive learning): recurring-transaction
// auto-detection. Dismissal is session-only (in-memory, not persisted) —
// a real, complete behavior for "stop showing me this today," just not
// "forever," which would need a new persisted table this feature doesn't
// have yet.
const _recurringDismissed = new Set();

async function loadRecurringDetection() {
  const banner = g('recurringDetectedBanner');
  if (!banner) return;
  try {
    const patterns = (await API.get('/api/budget/detect-recurring')).filter(p => !_recurringDismissed.has(p.merchant));
    if (!patterns.length) { banner.style.display = 'none'; return; }
    banner.style.display = '';
    banner.innerHTML = `
      <div style="padding:10px 14px;border-radius:var(--r-md);background:var(--mist);border:0.5px solid var(--steel)">
        <div style="font-size:10px;font-weight:600;letter-spacing:.08em;text-transform:uppercase;color:var(--slate-2);margin-bottom:6px">Recurring patterns spotted</div>
        ${patterns.map(p => `
          <div style="display:flex;align-items:center;gap:10px;padding:4px 0;font-size:12px">
            <div style="flex:1;color:var(--ink)">${esc(p.merchant)} ${fmt(p.avg_amount)} — seen ${p.frequency} times, consistently</div>
            <button class="btn btn-secondary btn-sm" onclick="acceptRecurringDetection('${esc(p.merchant).replace(/'/g,"\\'")}', ${p.avg_amount})">Add to budget</button>
            <button class="btn btn-ghost btn-sm" onclick="dismissRecurringDetection('${esc(p.merchant).replace(/'/g,"\\'")}', ${p.avg_amount})">Dismiss</button>
          </div>`).join('')}
      </div>`;
  } catch (e) {
    _gwErr('loadRecurringDetection')(e);
  }
}

async function acceptRecurringDetection(merchant, avgAmount) {
  try {
    await API.post('/api/budget/items', { type: 'expense', name: merchant, amount: avgAmount, category: '' });
    showToast('Added to budget', `${merchant} — ${fmt(avgAmount)}/mo`);
    _recurringDismissed.add(merchant);
    API.post('/api/budget/detect-recurring/feedback',
      { merchant, avg_amount: avgAmount, confirmed: true }).catch(_gwErr('acceptRecurringDetection:historian'));
    loadRecurringDetection();
  } catch (e) {
    _gwErr('acceptRecurringDetection')(e);
    showToast('Could not add to budget', e.message || '', 'error');
  }
}

function dismissRecurringDetection(merchant, avgAmount) {
  _recurringDismissed.add(merchant);
  API.post('/api/budget/detect-recurring/feedback',
    { merchant, avg_amount: avgAmount, confirmed: false }).catch(_gwErr('dismissRecurringDetection:historian'));
  loadRecurringDetection();
}

async function loadDebtLedger(dbId) {
  try {
    _debtLedgerCache[String(dbId)] = await API.get(`/api/debt/${dbId}/ledger`);
  } catch (e) {
    _debtLedgerCache[String(dbId)] = [];
    _gwErr('loadDebtLedger')(e);
  }
  const card = S.debtCards.find(x => x._dbId === dbId);
  const el = card && g(`ledgerSection-${card.id}`);
  if (el) el.innerHTML = _debtLedgerBodyHTML(card);
}

async function loadLinkableTransactions(dbId, cardId) {
  try {
    _debtLinkableCache[String(dbId)] = await API.get(`/api/debt/${dbId}/linkable-transactions`);
  } catch (e) {
    _debtLinkableCache[String(dbId)] = [];
    _gwErr('loadLinkableTransactions')(e);
  }
  const card = S.debtCards.find(x => x.id === cardId);
  if (card && _debtLedgerOpenForm[String(dbId)]) {
    const el = g(`ledgerSection-${cardId}`);
    if (el) el.innerHTML = _debtLedgerBodyHTML(card);
  }
}

async function submitDebtLedgerEntry(cardId, type) {
  const c = S.debtCards.find(x => x.id === cardId);
  if (!c || !c._dbId) return;
  const errEl    = g(`ledgerError-${cardId}`);
  const dateVal  = g(`ledgerDate-${cardId}`)?.value;
  const amountVal= parseFloat(g(`ledgerAmount-${cardId}`)?.value);
  if (!dateVal || !(amountVal > 0)) {
    if (errEl) errEl.textContent = 'Enter a date and an amount greater than $0.';
    return;
  }
  const payload = {
    entry_type:  type,
    amount:      amountVal,
    entry_date:  dateVal,
    description: g(`ledgerDesc-${cardId}`)?.value || '',
  };
  if (type === 'charge') {
    payload.merchant = g(`ledgerMerchant-${cardId}`)?.value || '';
    payload.category = g(`ledgerCategory-${cardId}`)?.value || '';
  }
  const linkSel = g(`ledgerLinkTxn-${cardId}`);
  if (linkSel && linkSel.value) payload.linked_checking_transaction_id = parseInt(linkSel.value);

  try {
    await API.post(`/api/debt/${c._dbId}/ledger`, payload);

    // Historian: did the shown category suggestion survive to save, or
    // did the user change it? Only logged when a suggestion was actually
    // shown for this entry (suggestCategoryFor populated it).
    const shownSuggestion = _debtCatSuggestions[cardId];
    if (type === 'charge' && shownSuggestion) {
      API.post('/api/categories/suggest-feedback', {
        merchant: shownSuggestion.merchant,
        suggested_category: shownSuggestion.category,
        kept: payload.category === shownSuggestion.category,
      }).catch(_gwErr('submitDebtLedgerEntry:categoryFeedback'));
      delete _debtCatSuggestions[cardId];
    }

    if (type === 'payment' && g(`ledgerSaveRecurring-${cardId}`)?.checked) {
      const dayVal = g(`ledgerRecurDay-${cardId}`)?.value;
      try {
        await API.post(`/api/debt/${c._dbId}/recurring`, {
          amount: amountVal,
          frequency: g(`ledgerRecurFreq-${cardId}`)?.value || 'monthly',
          scheduled_date_of_month: dayVal ? parseInt(dayVal) : null,
        });
        delete _recurringCache[String(c._dbId)];
      } catch (e) {
        _gwErr('submitDebtLedgerEntry:saveRecurring')(e);   // ledger entry already saved — don't block on this
      }
    }

    delete _debtLedgerCache[String(c._dbId)];
    delete _debtLinkableCache[String(c._dbId)];   // the linked txn, if any, is no longer a candidate
    _debtLedgerOpenForm[String(c._dbId)] = null;
    await loadDebtLedger(c._dbId);
    showToast(`${type === 'payment' ? 'Payment' : 'Charge'} added`, fmt(amountVal));
  } catch (e) {
    if (errEl) errEl.textContent = e.message || 'Could not save entry.';
  }
}

function deleteDebtLedgerEntry(cardId, entryId) {
  const c = S.debtCards.find(x => x.id === cardId);
  if (!c || !c._dbId) return;
  confirmAction('Remove this ledger entry?', 'This cannot be undone.', async () => {
    try {
      await API.delete(`/api/debt/ledger/${entryId}`);
      delete _debtLedgerCache[String(c._dbId)];
      delete _debtLinkableCache[String(c._dbId)];
      await loadDebtLedger(c._dbId);
    } catch (e) {
      _gwErr('deleteDebtLedgerEntry')(e);
      showToast('Could not remove entry', e.message || '', 'error');
    }
  });
}

// ── Debt card → account link UI ───────────────────────────────────────────
// Shows the account link picker and, when linked, the calculated balance
// from real imported transactions vs. the manually entered balance.
// This is the core of Budget Blueprint §10.7 (balance cross-check).
// ── Lease / loan term helpers ─────────────────────────────────────────────────

// Returns number of whole months between two YYYY-MM-DD strings.
function _debtCalcTermMonths(startStr, endStr) {
  if (!startStr || !endStr) return '';
  const s = new Date(startStr + 'T00:00:00');
  const e = new Date(endStr   + 'T00:00:00');
  const months = (e.getFullYear() - s.getFullYear()) * 12 + (e.getMonth() - s.getMonth());
  return months > 0 ? months : '';
}

// When start date OR term changes → recompute and fill end date field.
function _debtCalcEndDate(cardId) {
  const card = S.debtCards.find(c => c.id === cardId);
  if (!card) return;
  const start  = card.startDate;
  const termEl = g(`bterm-${cardId}`);
  const endEl  = g(`bend-${cardId}`);
  if (!start || !termEl || !endEl) return;
  const term = parseInt(termEl.value);
  if (!term || term < 1) return;
  const s = new Date(start + 'T00:00:00');
  s.setMonth(s.getMonth() + term);
  const iso = s.toISOString().slice(0, 10);
  endEl.value = iso;
  setCardField(cardId, 'endDate', iso);
}

// When end date is typed directly → back-calculate term months.
function _debtCalcTermFromEnd(cardId) {
  const card = S.debtCards.find(c => c.id === cardId);
  if (!card) return;
  const termEl = g(`bterm-${cardId}`);
  const endEl  = g(`bend-${cardId}`);
  if (!card.startDate || !endEl || !termEl) return;
  const months = _debtCalcTermMonths(card.startDate, endEl.value);
  if (months) termEl.value = months;
}

function _debtCardLinkHTML(c) {
  const accounts = _accountNames();
  if (!accounts.length) return ''; // no accounts yet, nothing to link

  const linked  = c.linkedAccountId;
  const calcBal = c.calculatedBalance;
  const manBal  = _cardBal(c);

  // Account picker dropdown
  const opts = accounts.map(a => {
    const id = S.accounts?.find(acc => acc.name === a)?.id;
    return `<option value="${id||''}" ${linked == id ? 'selected' : ''}>${esc(a)}</option>`;
  }).join('');

  const picker = `
    <div class="field" style="margin:0;min-width:160px">
      <label style="display:flex;align-items:center;gap:4px">
        Link to account
        <span style="font-size:10px;color:var(--slate-2)" title="Link this debt card to an imported account so Groundwork can calculate your balance from real transactions">ⓘ</span>
      </label>
      <select style="font-size:12px;padding:5px 8px;border:1px solid var(--steel);border-radius:var(--r-sm);background:var(--paper);color:var(--ink);width:100%"
        onchange="setCardField(${c.id},'linkedAccountId',this.value?parseInt(this.value):null)">
        <option value="">Not linked</option>
        ${opts}
      </select>
    </div>`;

  // Cross-check: only show when linked AND we have a calculated balance
  let crossCheck = '';
  if (linked && calcBal !== null) {
    const diff = Math.abs(calcBal - manBal);
    const match = diff < 0.50; // within 50 cents = match

    // Detect partial-history situation: when calculatedBalance is just a net
    // change over the imported period (no opening balance on file), the number
    // is meaningless as a current balance. This happens when:
    // (a) linkedTxnCount is low AND calcBal << manBal, OR
    // (b) calcBal is negative (more payments than charges imported — impossible
    //     for a real credit card balance), OR
    // (c) calcBal < manBal * 0.5 (calc is less than half the stated balance —
    //     almost certainly missing the pre-import history)
    const txnCount = c.linkedTxnCount ?? null;
    const isPartialHistory = calcBal < 0 ||
      (manBal > 100 && calcBal < manBal * 0.5) ||
      (txnCount !== null && txnCount < 12 && calcBal < manBal * 0.8);

    if (isPartialHistory) {
      // Don't show a mismatch — explain what the number actually is
      crossCheck = `
        <div style="margin-top:8px;padding:8px 12px;background:var(--mist);border:1px solid var(--steel);border-radius:var(--r-md);font-size:12px;color:var(--slate);line-height:1.6">
          <b>Partial import history.</b> Groundwork sees ${fmt(Math.abs(calcBal))} in net transactions from your import
          (${txnCount !== null ? txnCount + ' transactions' : 'partial history'}).
          Your full balance of <b>${fmt(manBal)}</b> is correct — the imported file doesn't go back far enough
          to calculate the balance independently. Import older statements to enable balance verification.
        </div>`;
    } else if (match) {
      crossCheck = `
        <div style="margin-top:8px;padding:8px 12px;background:var(--pine-bg);border:1px solid var(--pine-border);border-radius:var(--r-md);font-size:12px;color:#166534">
          <b>✓ Balances match.</b> Groundwork's calculated balance from imports (${fmt(calcBal)}) matches what you entered.
        </div>`;
    } else if (_crossCheckDismissed.has(c.id)) {
      // User already chose to keep their manual balance this session — show a quiet acknowledgment
      crossCheck = `
        <div style="margin-top:8px;padding:6px 12px;background:var(--mist);border:1px solid var(--steel);border-radius:var(--r-md);font-size:11px;color:var(--slate)">
          Keeping your balance of <b>${fmt(manBal)}</b>. Groundwork calculates ${fmt(calcBal)} from imports.
          <span onclick="setCardField(${c.id},'currentBal',${calcBal});_crossCheckDismissed.delete(${c.id});_renderCardList()"
            style="cursor:pointer;color:var(--pine);margin-left:6px;text-decoration:underline">Switch to Groundwork's value</span>
        </div>`;
    } else {
      crossCheck = `
        <div style="margin-top:8px;padding:8px 12px;background:var(--gold-bg);border:1px solid var(--gold-border);border-radius:var(--r-md);font-size:12px;color:#92400e">
          <b>Balance difference of ${fmt(diff)}.</b>
          Groundwork calculates <b>${fmt(calcBal)}</b> from your imported transactions.
          You entered <b>${fmt(manBal)}</b> manually.
          This could be an unimported transaction, an interest charge, or a fee.
          <div style="margin-top:6px;display:flex;gap:8px">
            <button onclick="setCardField(${c.id},'currentBal',${calcBal});_crossCheckDismissed.delete(${c.id});_renderCardList()"
              style="font-size:11px;padding:3px 10px;background:var(--pine);color:#fff;border:none;border-radius:var(--r-sm);cursor:pointer">
              Use Groundwork's ${fmt(calcBal)}
            </button>
            <button onclick="closeDebtCrossCheck(${c.id})"
              style="font-size:11px;padding:3px 10px;background:none;border:1px solid var(--gold-border);border-radius:var(--r-sm);cursor:pointer;color:#92400e">
              Keep my ${fmt(manBal)}
            </button>
          </div>
        </div>`;
    }
  } else if (linked && calcBal === null) {
    crossCheck = `
      <div style="margin-top:8px;padding:8px 12px;background:var(--mist);border:1px solid var(--steel);border-radius:var(--r-md);font-size:12px;color:var(--slate)">
        No transactions imported for this account yet. Import a statement to see the calculated balance.
      </div>`;
  }

  return `<div style="width:100%;margin-top:10px">${picker}${crossCheck}</div>`;
}

// Tracks which card IDs the user has chosen to keep their manual balance for.
// Stored in memory only — cleared on page reload, which is intentional:
// a fresh import should re-surface the mismatch if it still exists.
const _crossCheckDismissed = new Set();

function closeDebtCrossCheck(cardId) {
  // User chose to keep their manually entered balance.
  // Suppress the mismatch banner for this card until the page reloads
  // or until they accept Groundwork's value (which clears the divergence).
  _crossCheckDismissed.add(cardId);
  _renderCardList();
}
// Loan Forgiveness card (opts.expanded), where program type, start date,
// qualifying-payment progress, and recertification live.
function _pslfDetailsHTML(key) {
  const data  = _pslfData(key);
  const total = _pslfTotal(data);
  const made  = Math.min(total, data?.paymentsMade || 0);
  const remain = Math.max(0, total - made);
  const pct   = Math.min(100, Math.round((made / total) * 100));
  const forgiveDate = remain > 0
    ? (() => { const d = new Date(); d.setMonth(d.getMonth() + remain); return d.toLocaleDateString('en-US',{month:'long',year:'numeric'}); })()
    : 'Eligible now';

  return `
    <div style="background:var(--mist);border-radius:var(--r-md);padding:10px;margin-top:8px">
      <div class="field-row" style="margin-bottom:10px">
        <div class="field" style="margin:0">
          <label style="font-size:11px">Program</label>
          <select style="font-size:13px" onchange="updatePSLFProgram(${JSON.stringify(key)}, this.value)">
            ${Object.entries(PSLF_PROGRAMS).map(([k,p]) =>
              `<option value="${k}" ${(data?.program||'pslf')===k?'selected':''}>${esc(p.label)}</option>`
            ).join('')}
          </select>
        </div>
        <div class="field" style="margin:0">
          <label style="font-size:11px">Qualifying payments started</label>
          <input type="date" value="${data?.startDate||''}" style="font-size:13px"
            onchange="updatePSLFStartDate(${JSON.stringify(key)}, this.value)">
        </div>
      </div>

      <!-- Progress bar -->
      <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:6px">
        <div style="font-size:11px;font-weight:500;color:var(--ink)">Qualifying payments</div>
        <div style="font-size:13px;font-weight:500;font-family:var(--font-mono)">
          <span style="color:var(--pine)">${made}</span>
          <span style="color:var(--slate)"> / ${total}</span>
        </div>
      </div>
      <div style="height:6px;background:var(--steel-2);border-radius:99px;overflow:hidden;margin-bottom:8px">
        <div style="height:100%;width:${pct}%;background:var(--pine);border-radius:99px;transition:width .4s ease"></div>
      </div>

      <!-- Countdown and forgiveness date -->
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:10px">
        <div style="text-align:center;padding:8px;background:var(--paper);border-radius:var(--r-md)">
          <div style="font-size:20px;font-weight:500;color:${remain===0?'var(--pine)':'var(--ink)'}">${remain}</div>
          <div style="font-size:10px;color:var(--slate);margin-top:1px">payments to go</div>
        </div>
        <div style="text-align:center;padding:8px;background:var(--paper);border-radius:var(--r-md)">
          <div style="font-size:13px;font-weight:500;color:var(--pine)">${forgiveDate}</div>
          <div style="font-size:10px;color:var(--slate);margin-top:1px">estimated forgiveness</div>
        </div>
      </div>

      <!-- Inputs: payments made (override) + recertification date -->
      <div class="field-row">
        <div class="field" style="margin:0">
          <label style="font-size:11px">Qualifying payments made</label>
          <input type="number" value="${made}" min="0" max="${total}" style="font-size:13px"
            onchange="updatePSLFPayments(${JSON.stringify(key)}, this.value)">
        </div>
        <div class="field" style="margin:0">
          <label style="font-size:11px">IBR/SAVE recertification due</label>
          <input type="date" value="${data?.certifiedUntil||''}" style="font-size:13px"
            onchange="updatePSLFCertification(${JSON.stringify(key)}, this.value)">
        </div>
      </div>

      ${remain === 0 ? `
      <div style="margin-top:10px;padding:8px;background:var(--pine-bg);border-radius:var(--r-md);
                  font-size:12px;color:#3B6D11;text-align:center;font-weight:500">
        🎉 ${total} qualifying payments complete — you may be eligible for forgiveness. Contact your loan servicer.
      </div>` : ''}
    </div>`;
}

function getCardData() {
  return _activeDebtCards().map(c => ({
    id:       c.id, name: c.name||'Card',
    balance:  _cardBal(c),
    beginBal: parseFloat(c.beginBal)||0,
    rate:     parseFloat(c.rate)||0,
    minimum:  Math.max(1, _payoffPayment(c)||25),   // V3
    dueDay:   parseInt(c.dueDay)||null,
    endDate:  c.endDate || null,
    debtType: c.debtType || 'credit',
  })).filter(c => c.balance > 0 || c.beginBal > 0);
}

// ── Debt page redesign — CP-D0 / D1 / D2 / D3 ────────────────────────────

// Tab state
let _debtActiveTab = 'setup';
// What-if state (shared between hero expander and advisor tab)
let _debtWhatIfExtra = 0;
// AI advisor cache (session only)
let _debtAdvisorAICache = null;
// Whether the suggested commitment note has been shown
let _debtSuggestionShown = false;

// CP-D1: Tab switching
function _debtShowTab(tab) {
  _debtActiveTab = tab;
  ['setup', 'tracker', 'advisor'].forEach(t => {
    const btn = g(`debtTab-${t}`);
    const panel = g(`debtPanel-${t}`);
    const active = t === tab;
    if (btn) {
      btn.style.color = active ? 'var(--pine)' : 'var(--slate)';
      btn.style.borderBottomColor = active ? 'var(--pine)' : 'transparent';
      btn.style.fontWeight = active ? '500' : 'normal';
    }
    if (panel) panel.style.display = active ? '' : 'none';
  });
  if (tab === 'tracker') _debtRenderTrackerTab();
  if (tab === 'advisor') _debtRenderAdvisorTab();
}

// CP-D0: Write hero band from result
function _debtWriteHero(result, data, budget, totalMin, intSaved) {
  const heroDate     = g('debtHeroDate');
  const heroDuration = g('debtHeroDuration');
  const heroStats    = g('debtHeroStats');
  const heroBarWrap  = g('debtHeroBarWrap');
  const heroBarFill  = g('debtHeroBarFill');
  const heroBarLabel = g('debtHeroBarLabel');

  if (!heroDate) return;

  if (!result || !data || !data.length || budget <= 0) {
    heroDate.textContent = data && data.length ? '—' : 'Add your cards';
    heroDate.style.color = 'var(--slate-2)';
    heroDuration.textContent = '';
    heroStats.textContent = '';
    if (heroBarWrap) heroBarWrap.style.display = 'none';
    return;
  }

  // Hero date — ember if budget < minimums, pine otherwise
  const budgetBelowMin = totalMin && budget < totalMin;
  heroDate.style.color = budgetBelowMin ? 'var(--ember)' : 'var(--pine)';
  heroDate.textContent = budgetBelowMin ? 'Increase budget' : result.freeDate;

  // Duration
  if (!budgetBelowMin && result.months) {
    const yrs = Math.floor(result.months / 12);
    const mos = result.months % 12;
    heroDuration.textContent = yrs > 0
      ? `${yrs} yr${yrs !== 1 ? 's' : ''} ${mos > 0 ? mos + ' mo' : ''} from today`.trim()
      : `${mos} month${mos !== 1 ? 's' : ''} from today`;
  } else {
    heroDuration.textContent = '';
  }

  // Stats row
  const strategy = (S.debtMethod === 'avalanche') ? 'Avalanche' : 'Snowball';
  const totalBal = data.reduce((s,c) => s + c.balance, 0);
  const dti = _debtCalcDTI();
  const statsparts = [strategy, fmt(totalBal) + ' remaining'];
  if (result.totalInterest) statsparts.push(fmt(result.totalInterest) + ' interest');
  if (dti)                  statsparts.push('DTI ' + dti.toFixed(1) + '%');
  heroStats.textContent = statsparts.join(' · ');

  // Progress bar
  const totalBegin = data.reduce((s,c) => s + (c.beginBal || c.balance), 0);
  const totalElim  = totalBegin - totalBal;
  if (totalBegin > 0 && totalElim > 0 && heroBarWrap) {
    const pct = Math.round((totalElim / totalBegin) * 100);
    heroBarWrap.style.display = '';
    heroBarFill.style.width = pct + '%';
    heroBarLabel.textContent = `${pct}% eliminated · ${fmt(totalElim)} paid`;
  } else if (heroBarWrap) {
    heroBarWrap.style.display = 'none';
  }

  // Update what-if toggle label with impact if slider > 0
  _debtUpdateWhatIfLabel();
}

function _debtCalcDTI() {
  const today  = new Date().toISOString().slice(0, 10);
  const income = S.incomes ? S.incomes.reduce((s,i) => s + (parseFloat(i.amount)||0), 0) : 0;
  if (!income) return null;
  const data     = getCardData();
  const totalMin = data
    .filter(c => !c.endDate || c.endDate >= today)
    .reduce((s,c) => s + c.minimum, 0);
  // S.incomes amounts are monthly. DTI = monthly debt payments / monthly income.
  // Use one decimal to match calcDTI() shown in the Advisor tab.
  return Math.round((totalMin / income) * 1000) / 10; // one decimal, e.g. 12.3
}

// CP-D0: What-if expander toggle
function _debtToggleWhatIf() {
  const panel  = g('debtHeroWhatIfPanel');
  const toggle = g('debtHeroWhatIfToggle');
  if (!panel || !toggle) return;
  const open = panel.style.display !== 'none';
  panel.style.display = open ? 'none' : '';
  _debtUpdateWhatIfLabel();
}

function _debtUpdateWhatIfLabel() {
  const toggle  = g('debtHeroWhatIfToggle');
  const panel   = g('debtHeroWhatIfPanel');
  if (!toggle) return;
  const open    = panel && panel.style.display !== 'none';
  const extra   = _debtWhatIfExtra;
  const freeDateEl = g('whatIfFreeDate');
  const wiDate  = extra > 0 && freeDateEl ? freeDateEl.textContent : '';
  const baseResult = _simulatePayoff ? _simulatePayoff(0) : null;
  const baseDate = baseResult ? baseResult.freeDate : '';

  if (extra > 0 && wiDate && wiDate !== '—' && wiDate !== baseDate) {
    toggle.textContent = (open ? '▾' : '▸') + ` Paying ${fmt(extra)}/month extra · debt-free ${wiDate}`;
  } else {
    toggle.textContent = (open ? '▾' : '▸') + ' What if you paid extra?';
  }
}

// CP-D3: Sync hero date when what-if slider moves
function _debtSyncWhatIfHero(value) {
  _debtWhatIfExtra = parseFloat(value) || 0;
  // Update what-if slider max dynamically (blueprint §12 open question 3)
  const data = getCardData();
  const totalDebt = data.reduce((s,c) => s + c.balance, 0);
  const slider = g('whatIfSlider');
  if (slider) slider.max = Math.max(500, Math.round(totalDebt * 0.1));
  _debtUpdateWhatIfLabel();
}

// CP-D1: Show suggested commitment on first visit
function _debtMaybeSuggestCommitment() {
  if (_debtSuggestionShown) return;
  const budgetEl = g('monthlyBudget');
  if (!budgetEl) return;
  // Only suggest if the field still has the placeholder default or is blank
  const currentVal = parseFloat(budgetEl.value);
  const hasUserValue = budgetEl.dataset.userSet === '1';
  if (hasUserValue) return;

  const income = S.incomes ? S.incomes.reduce((s,i) => s + (parseFloat(i.amount)||0), 0) : 0;
  const bills  = S.expenses ? S.expenses.reduce((s,e) => s + _rowMonth(e), 0) : 0;
  const today_sug = new Date().toISOString().slice(0, 10);
  const mins   = S.debtCards ? S.debtCards.filter(c => !c.paidInFull && !(c.endDate && c.endDate < today_sug)).reduce((s,c) => s + (parseFloat(c.minimum)||0), 0) : 0;
  if (!income) return;

  const sug = _obSuggestedBudget ? _obSuggestedBudget(income, bills, mins) : null;
  if (!sug || !sug.suggestedMonthlyBudget) return;

  const sugEl = g('debtSuggestedCommitment');
  if (!sugEl) return;
  sugEl.style.display = '';
  sugEl.innerHTML = `Suggested <b style="font-family:var(--font-mono)">${fmt(sug.suggestedMonthlyBudget)}</b> — keeps you in a healthy 50/30/20 split.
    <span onclick="g('monthlyBudget').value=${sug.suggestedMonthlyBudget};g('monthlyBudget').dataset.userSet='1';g('debtSuggestedCommitment').style.display='none';calculate()"
      style="color:var(--pine);cursor:pointer;text-decoration:underline;margin-left:4px">Use this</span>`;

  _debtSuggestionShown = true;
}

// Mark the budget field as user-set on manual input


// CP-D2: Month Tracker tab render
// Returns { paid: bool, amount: number, date: string } for a tracker row.
// Scans S.transactions for the current month looking for a debit that
// plausibly represents a payment made toward this card.
//
// Matching strategy (in priority order):
// 1. category==='Debt' AND amount within 10% of card's planned total payment
// 2. category==='Debt' AND amount within 10% of card's minimum payment
// 3. description fuzzy-matches the card name AND category is Debt or Transfer
//    (catches "APPLE CARD PMT", "CHASE AUTOPAY", etc.)
//
// We use ±10% tolerance because:
// - Users sometimes pay a round number ($75 instead of $71)
// - Interest that posts mid-month can shift the exact minimum slightly
// - Overpayments are still payments
//
// No transaction data = { paid: false, amount: 0, date: '' } — callers
// check hasImportedTxns before showing any status badge.
function _debtPaidThisMonth(planRow, moKey) {
  const thisMonthDebits = S.transactions.filter(t =>
    t.type === 'debit' &&
    (t.date || '').startsWith(moKey) &&
    ((t.category === 'Debt' || _catParentName(t.category) === 'Debt') || t.category === 'Transfer' || t.category === 'Payment')
  );

  if (!thisMonthDebits.length) return { paid: false, amount: 0, date: '' };

  const totalPmt = planRow.total || planRow.minimum || 0;
  const minPmt   = planRow.minimum || 0;
  const cardName = (planRow.name || '').toLowerCase();

  // Helper: normalize card name for fuzzy matching
  // "Apple Master Card" → "apple", "Chase Visa" → "chase"
  const nameKeywords = cardName.split(/\s+/).filter(w =>
    w.length > 3 &&
    !['card','visa','master','credit','loan','account'].includes(w)
  );

  for (const t of thisMonthDebits) {
    const amt  = t.amount || 0;
    const desc = (t.description || '').toLowerCase();

    // Priority 1: amount matches planned total (±10%)
    if (totalPmt > 0 && Math.abs(amt - totalPmt) / totalPmt <= 0.10) {
      return { paid: true, amount: amt, date: t.date };
    }

    // Priority 2: amount matches minimum (±10%)
    if (minPmt > 0 && Math.abs(amt - minPmt) / minPmt <= 0.10) {
      return { paid: true, amount: amt, date: t.date };
    }

    // Priority 3: description mentions the card name AND amount >= minimum*0.5
    if (nameKeywords.length > 0 && nameKeywords.some(kw => desc.includes(kw)) && amt >= minPmt * 0.5) {
      return { paid: true, amount: amt, date: t.date };
    }
  }

  return { paid: false, amount: 0, date: '' };
}

function _debtRenderTrackerTab() {
  const body = g('debtPanel-tracker');
  if (!body) return;

  const plan = _thisMonthPaymentPlan ? _thisMonthPaymentPlan() : null;
  const now  = new Date();
  const moLabel = now.toLocaleDateString('en-US', {month:'long', year:'numeric'});

  if (!plan || !plan.rows || !plan.rows.length) {
    body.innerHTML = `
      <div style="font-family:var(--font-serif);font-style:italic;font-size:22px;color:var(--ink);margin-bottom:16px">${moLabel}</div>
      <div class="empty-state" style="padding:32px">
        <div class="empty-state-icon">📅</div>
        <div class="empty-state-title">Add cards and set a budget</div>
        <div class="empty-state-sub">Your payment schedule for ${moLabel} will appear here once you have active debt cards.</div>
      </div>`;
    return;
  }

  const data       = getCardData();
  const totalDebt  = data.reduce((s,c) => s + c.balance, 0);
  const totalBegin = data.reduce((s,c) => s + (c.beginBal || c.balance), 0);
  const totalElim  = totalBegin - totalDebt;
  const pct        = totalBegin > 0 ? Math.round((totalElim / totalBegin) * 100) : 0;

  // The target card is the first row that has extra > 0 and isn't PSLF
  const targetRow    = plan.rows.find(r => r.extra > 0.01 && !r.pslf);
  const targetCardId = targetRow?.id ?? null;

  // Check whether any transactions have been imported this month at all.
  // If none exist, we can't determine paid status — show neutral state.
  const moKey = `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}`;
  const hasImportedTxns = S.transactions.some(t => (t.date||'').startsWith(moKey));

  const rows = plan.rows.map(p => {
    const isTarget = p.id === targetCardId;
    const isPSLF   = p.pslf || false;
    const rowBg    = isTarget
      ? 'background:rgba(217,119,6,.06);border-left:3px solid var(--gold)'
      : 'border-left:3px solid transparent';
    const extraPart = (!isPSLF && p.extra > 0.01)
      ? ` + <span style="color:var(--gold)">${fmt(p.extra)} extra</span>`
      : '';
    const pslfNote = isPSLF
      ? ' <span style="font-style:italic;color:var(--slate-2)">(income-driven plan)</span>'
      : '';

    // Payment status indicator
    const paidStatus = _debtPaidThisMonth(p, moKey);
    let paidBadge = '';
    if (!hasImportedTxns) {
      paidBadge = ''; // no data — show nothing
    } else if (paidStatus.paid) {
      paidBadge = `<span title="Payment of ${fmt(paidStatus.amount)} found on ${paidStatus.date}"
        style="font-size:11px;color:var(--pine);font-weight:600;flex-shrink:0">✓ paid</span>`;
    } else {
      paidBadge = `<span title="No matching payment found in imported transactions this month"
        style="font-size:11px;color:var(--slate-2);flex-shrink:0">○ not yet</span>`;
    }

    return `
      <div style="display:flex;align-items:center;gap:12px;padding:10px 12px;${rowBg};border-radius:var(--r-sm);margin-bottom:4px">
        <div style="flex:1;font-size:13px;color:var(--ink)">${esc(p.name)}</div>
        <div style="font-size:12px;color:var(--slate);font-family:var(--font-mono)">${fmt(p.minimum)} min${extraPart}${pslfNote}</div>
        <div style="font-family:var(--font-mono);font-size:14px;font-weight:500;color:${isTarget?'var(--gold)':'var(--ink)'};min-width:56px;text-align:right">${fmt(p.total)}</div>
        ${paidBadge ? `<div style="min-width:56px;text-align:right">${paidBadge}</div>` : ''}
      </div>`;
  }).join('');

  const grandTotal = plan.rows.reduce((s,p) => s + p.total, 0);
  const paidCount  = hasImportedTxns
    ? plan.rows.filter(p => _debtPaidThisMonth(p, moKey).paid).length
    : null;
  const allPaid    = paidCount !== null && paidCount === plan.rows.length;

  const nextNote = plan.nextMonthNote
    ? `<div style="margin-top:12px;font-size:12px;color:var(--pine);line-height:1.6;padding:8px 12px;background:var(--pine-bg);border-radius:var(--r-sm);border:1px solid var(--pine-border)">${esc(plan.nextMonthNote)}</div>`
    : '';

  // Payment summary note
  const paidNote = paidCount === null ? '' :
    allPaid
      ? `<div style="margin-top:10px;padding:8px 12px;background:var(--pine-bg);border:1px solid var(--pine-border);border-radius:var(--r-sm);font-size:12px;color:var(--pine);font-weight:500">
           ✓ All ${plan.rows.length} payment${plan.rows.length!==1?'s':''} confirmed this month
         </div>`
      : paidCount > 0
        ? `<div style="margin-top:10px;padding:8px 12px;background:var(--mist);border:1px solid var(--steel);border-radius:var(--r-sm);font-size:12px;color:var(--slate)">
             ${paidCount} of ${plan.rows.length} payments confirmed · ${plan.rows.length - paidCount} pending
           </div>`
        : '';

  body.innerHTML = `
    <div style="font-family:var(--font-serif);font-style:italic;font-size:22px;color:var(--ink);margin-bottom:16px">${moLabel}</div>
    <div style="border:1px solid var(--steel);border-radius:var(--r-md);padding:8px;margin-bottom:4px">
      ${rows}
      <div style="display:flex;justify-content:flex-end;padding:8px 12px;border-top:1px solid var(--steel);margin-top:4px">
        <div style="font-size:12px;color:var(--slate);margin-right:8px">Total this month</div>
        <div style="font-family:var(--font-mono);font-size:14px;font-weight:600;color:var(--ink)">${fmt(grandTotal)}</div>
      </div>
    </div>
    ${paidNote}
    ${nextNote}
    ${!hasImportedTxns ? `
    <div style="margin-top:10px;font-size:11px;color:var(--slate-2);line-height:1.6">
      Import your checking account transactions to see payment confirmation status.
    </div>` : ''}
    ${totalBegin > 0 && pct > 0 ? `
    <div style="margin-top:16px">
      <div style="background:var(--steel);border-radius:9999px;height:6px;overflow:hidden;margin-bottom:6px">
        <div style="height:100%;background:var(--pine);border-radius:9999px;width:${pct}%;transition:width .5s ease"></div>
      </div>
      <div style="font-family:var(--font-mono);font-size:11px;color:var(--pine)">${pct}% eliminated · ${fmt(totalElim)} paid</div>
    </div>` : ''}
    <div style="margin-top:16px">
      <span onclick="showView('reports');setTimeout(()=>{ if(typeof _rcOpenReport==='function') _rcOpenReport('debt_payoff'); },80)"
        style="font-size:12px;color:var(--pine);cursor:pointer;text-decoration:underline">See full payoff plan →</span>
    </div>`;
}
