// Track which report is open inside the Report Center
let _rcActiveReport = null;

// _rcOpenReport: the public entry point for opening a specific report.
// Called from Budget page links, Debt page CTAs, dashboard donut, etc.
// Works whether the Report Center view is already open or not.
function _rcOpenReport(reportId) {
  _rcActiveReport = reportId;
  // If the reports view is already showing, render directly
  const cont = g('reportCenterContent');
  if (cont && g('view-reports')?.classList.contains('active')) {
    _rcRenderReport(reportId);
  } else {
    // Navigate to reports view — renderReportCenter will pick up _rcActiveReport
    showView('reports');
  }
}

function renderReportCenter(reportId) {
  const cont = g('reportCenterContent');
  if (!cont) return;

  // Price context for Electric/Gas/Gas-Fuel narratives — fire-and-forget;
  // each loader re-renders the open Category Deep-Dive once it resolves.
  _loadUtilityPrices();
  _loadGasPrice();

  // If a specific report was requested (e.g. from Budget page link), open it
  if (reportId) {
    _rcActiveReport = reportId;
    _rcRenderReport(reportId);
    return;
  }

  // If a report is already open and we re-navigated here, stay on it
  if (_rcActiveReport) {
    _rcRenderReport(_rcActiveReport);
    return;
  }

  // Default: show the catalog
  _rcRenderCatalog(cont);
}

function _rcRenderCatalog(cont) {
  _rcActiveReport = null;

  // Group reports by section
  const sections = {};
  _REPORT_CATALOG.forEach(r => {
    if (!sections[r.section]) sections[r.section] = [];
    sections[r.section].push(r);
  });

  const hasDebtHistory = Object.keys(_debtHistoryCache).length > 0;
  const hasTxns        = S.transactions.length > 0;
  const hasDebts       = S.debtCards.filter(c => !c.paidInFull).length > 0;

  cont.innerHTML = `
    <div style="max-width:720px;margin:0 auto;padding:32px 24px 80px">

      <div style="margin-bottom:32px">
        <h1 style="font-family:'Playfair Display',Georgia,serif;font-style:italic;
                   font-size:28px;font-weight:600;color:var(--ink);margin-bottom:6px">Reports</h1>
        <div style="font-size:13px;color:var(--slate);line-height:1.6">
          What happened · What's the plan · Is it working.
        </div>
      </div>

      ${Object.entries(sections).map(([section, reports]) => `
        <div style="margin-bottom:32px">
          <div style="font-size:10px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;
                      color:var(--slate-2);margin-bottom:12px">${esc(section)}</div>
          <div style="display:flex;flex-direction:column;gap:8px">
            ${reports.map(r => {
              // Availability hints
              let hint = '';
              if (!hasTxns && (r.id === 'monthly' || r.id === 'category' || r.id === 'annual' || r.id === 'budget_vs_actual')) {
                hint = 'Import transactions to unlock';
              } else if (!hasDebts && (r.id === 'debt_payoff' || r.id === 'debt_progress')) {
                hint = 'Add debt accounts to unlock';
              } else if (!hasDebtHistory && r.id === 'debt_progress') {
                hint = 'Link your debt cards to see balance history';
              }

              const locked = hint && !hasTxns && r.id !== 'debt_payoff' && r.id !== 'debt_progress' && r.id !== 'net_worth' && r.id !== 'import_audit';

              return `
              <div onclick="${locked ? '' : `_rcLaunchReport('${r.id}')`}"
                style="display:flex;align-items:center;gap:14px;padding:14px 16px;
                       background:var(--paper);border:1px solid var(--steel);
                       border-radius:var(--r-md);cursor:${locked?'default':'pointer'};
                       opacity:${locked?'.5':'1'};transition:border-color .15s"
                ${locked?'':` onmouseover="this.style.borderColor='var(--pine)'"
                           onmouseout="this.style.borderColor='var(--steel)'"`}>
                <div style="font-size:18px;color:var(--slate);flex-shrink:0;width:24px;text-align:center">${r.icon}</div>
                <div style="flex:1;min-width:0">
                  <div style="display:flex;align-items:center;gap:8px;margin-bottom:3px">
                    <span style="font-size:14px;font-weight:500;color:var(--ink)">${esc(r.title)}</span>
                    ${r.aiUtility === 'high' ? `<span style="font-size:10px;padding:1px 7px;border-radius:10px;background:var(--pine-bg);color:var(--pine);border:1px solid var(--pine-border)">✦ analysis available</span>` : ''}
                  </div>
                  <div style="font-size:12px;color:var(--slate);line-height:1.5">
                    ${hint ? `<span style="color:var(--gold)">${esc(hint)}</span>` : esc(r.sub)}
                  </div>
                </div>
                <div style="flex-shrink:0;color:var(--slate-2);font-size:16px">›</div>
              </div>`;
            }).join('')}
          </div>
        </div>
      `).join('')}

      <div style="margin-top:16px;padding:14px 16px;background:var(--mist);border-radius:var(--r-sm);
                  font-size:12px;color:var(--slate);line-height:1.6">
        ✦ <strong>Groundwork's analysis</strong> — runs on your own machine. Nothing is sent
             anywhere; you'll see exactly what's being analyzed before it runs.
      </div>
    </div>
  `;
}

function _rcLaunchReport(reportId) {
  const report = _REPORT_CATALOG.find(r => r.id === reportId);
  if (!report) return;
  if (report.action) {
    report.action();
  } else {
    _rcActiveReport = reportId;
    _rcRenderReport(reportId);
  }
}

function _rcRenderReport(reportId) {
  const cont = g('reportCenterContent');
  if (!cont) return;

  // Back button header
  const header = `
    <div style="display:flex;align-items:center;gap:12px;padding:16px 24px;
                border-bottom:1px solid var(--steel);background:var(--paper);
                position:sticky;top:0;z-index:10">
      <button onclick="_rcBackToCatalog()"
        style="background:none;border:none;font-size:13px;color:var(--slate);
               cursor:pointer;padding:0;display:flex;align-items:center;gap:4px">
        ← Reports
      </button>
    </div>
    <div style="max-width:720px;margin:0 auto;padding:32px 24px 80px" id="rcReportBody">
      <div style="font-size:13px;color:var(--slate)">Loading…</div>
    </div>`;
  cont.innerHTML = header;

  // Route to the correct report renderer (Phases D, E, F)
  switch(reportId) {
    case 'distance_traveled': _rcRenderDistanceTraveled(); break;
    case 'monthly':         _rcRenderMonthlyReport(); break;
    case 'debt_payoff':     _rcRenderDebtPayoff();   break;
    case 'debt_progress':   _rcRenderDebtProgress(); break;
    case 'category':        _rcRenderCategoryDeepDive(); break;
    case 'spending_breakdown': _rcRenderCategoryDeepDive(); break;  // alias from dashboard donut
    case 'annual':          _rcRenderAnnualSummary(); break;
    case 'budget_vs_actual':_rcRenderBudgetVsActual(); break;
    case 'income_savings':  _rcRenderIncomeSavings(); break;
    case 'net_worth':       _rcRenderNetWorthTimeline(); break;
    case 'import_audit':    _rcRenderImportAudit(); break;
    default:
      g('rcReportBody').innerHTML = `<div style="color:var(--slate)">Report not yet available.</div>`;
  }
}

function _rcBackToCatalog() {
  _rcActiveReport = null;
  const cont = g('reportCenterContent');
  if (cont) _rcRenderCatalog(cont);
}

// Stub renderers for Phase D/E/F — replaced in those phases
// ── Phase D: Local reports ─────────────────────────────────────────────────────

// ── §7.2 Category Deep-Dive ──────────────────────────────────────────────────

// ── Monthly Report (Report Center version) ────────────────────────────────────

function _rcRenderMonthlyReport() {
  const body = g('rcReportBody');
  if (!body) return;

  const now = new Date();
  const monthOpts = [];
  for (let i = 1; i <= 12; i++) {
    const d   = new Date(now.getFullYear(), now.getMonth() - i, 1);
    const val = `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;
    const lbl = d.toLocaleDateString('en-US', { month: 'long', year: 'numeric' });
    monthOpts.push({ val, lbl });
  }
  const defaultMonth = monthOpts[0].val;

  body.innerHTML = `
    <div style="margin-bottom:24px">
      <h2 style="font-family:'Playfair Display',Georgia,serif;font-style:italic;font-size:24px;font-weight:600;color:var(--ink);margin-bottom:4px">Monthly Report</h2>
      <div style="font-size:13px;color:var(--slate);line-height:1.6">A plain-language summary of how the month went — spending, saving, and what it means.</div>
    </div>
    <div style="display:flex;align-items:flex-end;gap:16px;flex-wrap:wrap;margin-bottom:24px">
      <div>
        <label style="font-size:11px;font-weight:600;letter-spacing:.06em;text-transform:uppercase;color:var(--slate);display:block;margin-bottom:4px">Month</label>
        <select id="rcMonthSel" onchange="_rcMonthlyRefreshPreview()" style="font-size:13px;border:1px solid var(--steel);border-radius:var(--r-sm);padding:6px 10px;background:var(--paper);color:var(--ink);font-family:var(--font-mono)">
          ${monthOpts.map(m=>`<option value="${m.val}">${m.lbl}</option>`).join('')}
        </select>
      </div>
      <div style="flex:1;min-width:200px">
        <label style="font-size:11px;font-weight:600;letter-spacing:.06em;text-transform:uppercase;color:var(--slate);display:block;margin-bottom:4px">Anything unusual? <span style="font-weight:400;color:var(--slate-2)">(AI reads this)</span></label>
        <input type="text" id="rcMonthAnnotation" placeholder="car repair, holiday spending, medical bill…"
          oninput="_rcMonthlyAnnotationInput()"
          style="width:100%;padding:6px 10px;border:1px solid var(--steel);border-radius:var(--r-sm);font-size:13px;background:var(--paper);color:var(--ink)">
      </div>
      <button id="rcMonthlyGenBtn" onclick="_rcMonthlyGenerate()"
        style="padding:8px 18px;background:var(--pine);color:#fff;border:none;border-radius:var(--r-sm);font-size:13px;cursor:pointer;white-space:nowrap;display:none">✦ Generate analysis</button>
    </div>
    <div id="rcMonthlyStats" style="margin-bottom:24px"></div>
    <div id="rcMonthlyTeaching" style="margin-bottom:24px"></div>
    <div id="rcMonthlyPast" style="margin-bottom:24px"></div>
    <div id="rcMonthlyNarrative"></div>`;

  _rcMonthlyLoadPastReports();
  _rcMonthlyRefreshPreview();
}

// Local mode has no "Generate" button to click after adding a note (see
// _rcRenderMonthlyReport) — regenerate automatically instead, debounced so
// it fires once after the user stops typing rather than per keystroke.
let _rcMonthlyAnnotationTimer = null;
function _rcMonthlyAnnotationInput() {
  if (!aiEnabled()) return;
  clearTimeout(_rcMonthlyAnnotationTimer);
  _rcMonthlyAnnotationTimer = setTimeout(_rcMonthlyGenerate, 900);
}

function _rcMonthlyRefreshPreview() {
  const month = g('rcMonthSel')?.value;
  if (!month) return;
  const [yr, mo] = month.split('-').map(Number);
  const start = `${yr}-${String(mo).padStart(2,'0')}-01`;
  const end   = new Date(yr, mo, 0).toISOString().slice(0,10);
  const txns  = S.transactions.filter(t => t.date >= start && t.date <= end);
  const spent = txns.filter(t=>t.type==='debit').reduce((s,t)=>s+t.amount,0);
  const earned= txns.filter(t=>t.type==='credit').reduce((s,t)=>s+t.amount,0);
  const net   = earned - spent;
  const monthName = new Date(yr,mo-1).toLocaleDateString('en-US',{month:'long',year:'numeric'});
  const cats = {};
  txns.filter(t=>t.type==='debit').forEach(t=>{
    const pn = _catParentName(t.category||'Other')||'Other';
    cats[pn]=(cats[pn]||0)+t.amount;
  });
  const topCats = Object.entries(cats).sort((a,b)=>b[1]-a[1]).slice(0,5);
  const stats = g('rcMonthlyStats');
  if (!stats) return;
  if (!txns.length) {
    stats.innerHTML=`<div class="card" style="padding:20px;text-align:center;color:var(--slate);font-size:13px">No transactions for ${monthName}.</div>`;
    return;
  }
  stats.innerHTML = `
    <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(130px,1fr));gap:12px;margin-bottom:16px">
      <div class="card" style="padding:14px"><div style="font-size:10px;text-transform:uppercase;letter-spacing:.08em;color:var(--slate-2);margin-bottom:4px">Spent</div><div style="font-family:var(--font-mono);font-size:22px;font-weight:600;color:var(--ember)">${fmt(spent)}</div></div>
      <div class="card" style="padding:14px"><div style="font-size:10px;text-transform:uppercase;letter-spacing:.08em;color:var(--slate-2);margin-bottom:4px">Earned</div><div style="font-family:var(--font-mono);font-size:22px;font-weight:600;color:var(--pine)">${fmt(earned)}</div></div>
      <div class="card" style="padding:14px;${net>=0?'border-color:var(--pine-border)':'border-color:var(--ember-border)'}"><div style="font-size:10px;text-transform:uppercase;letter-spacing:.08em;color:var(--slate-2);margin-bottom:4px">Net</div><div style="font-family:var(--font-mono);font-size:22px;font-weight:600;color:${net>=0?'var(--pine)':'var(--ember)'}">${net>=0?'+':''}${fmt(net)}</div></div>
      <div class="card" style="padding:14px"><div style="font-size:10px;text-transform:uppercase;letter-spacing:.08em;color:var(--slate-2);margin-bottom:4px">Transactions</div><div style="font-family:var(--font-mono);font-size:22px;font-weight:600;color:var(--ink)">${txns.length}</div></div>
    </div>
    ${topCats.length?`<div class="card" style="padding:16px"><div style="font-size:11px;font-weight:600;letter-spacing:.08em;text-transform:uppercase;color:var(--slate-2);margin-bottom:12px">Top spending</div>
    ${topCats.map(([cat,amt])=>{const pct=spent>0?(amt/spent*100):0;const cs=_categoryStyle(cat);return`<div style="display:flex;align-items:center;gap:10px;padding:8px 0;border-bottom:1px solid var(--steel-2)"><div style="flex:1;font-size:13px;color:var(--ink)">${esc(cat)}</div><div style="font-family:var(--font-mono);font-size:13px;color:var(--ink)">${fmt(amt)}</div><div style="width:40px;text-align:right;font-size:11px;color:var(--slate-2)">${pct.toFixed(0)}%</div></div>`;}).join('')}
    </div>`:''}`;

  // AI is local, free and never leaves the machine, so there's no reason to
  // make the user ask for it — generate immediately whenever there's a month
  // with data to analyze, including right after the user switches months.
  if (aiEnabled()) _rcMonthlyGenerate();
}

async function _rcMonthlyLoadPastReports() {
  const container = g('rcMonthlyPast');
  if (!container) return;
  try {
    const res = await API.get('/api/settings');
    const settings = res.data || res;
    const entries = Object.keys(settings).filter(k=>k.startsWith('report_text_')&&settings[k]).sort().reverse()
      .map(k=>{ const [yr,mo]=k.replace('report_text_','').split('-').map(Number); return {key:k,label:new Date(yr,mo-1,1).toLocaleDateString('en-US',{month:'long',year:'numeric'})}; });
    if (!entries.length) return;
    container.innerHTML=`<div style="margin-bottom:8px;font-size:11px;font-weight:600;letter-spacing:.06em;text-transform:uppercase;color:var(--slate-2)">Saved reports</div>
      <div style="display:flex;gap:8px;flex-wrap:wrap">${entries.map(e=>`<button onclick="_rcMonthlyLoadPast('${e.key}')" style="padding:5px 14px;font-size:12px;background:var(--paper);border:1px solid var(--steel);border-radius:20px;cursor:pointer;color:var(--slate)">${esc(e.label)}</button>`).join('')}</div>`;
  } catch(e) { _gwErr('_rcMonthlyLoadPastReports')(e); }
}

async function _rcMonthlyLoadPast(key) {
  try {
    const res = await API.get('/api/settings');
    const text = (res.data||res)[key]||'';
    if (!text) return;
    const [yr,mo]=key.replace('report_text_','').split('-').map(Number);
    const label=new Date(yr,mo-1,1).toLocaleDateString('en-US',{month:'long',year:'numeric'});
    const val=key.replace('report_text_','');
    if(g('rcMonthSel')&&[...g('rcMonthSel').options].some(o=>o.value===val)){g('rcMonthSel').value=val;_rcMonthlyRefreshPreview();}
    _rcMonthlyDisplayNarrative(text,label,true);
  } catch(e) { _gwErr('_rcMonthlyLoadPast')(e); }
}

function _rcMonthlyDisplayNarrative(text, label, isSaved) {
  const cont = g('rcMonthlyNarrative');
  if (!cont) return;
  const paragraphs = text.split('\n\n').map(p=>p.trim()).filter(Boolean);
  const pullquote  = paragraphs[0]||'';
  const rest       = paragraphs.slice(1);
  cont.innerHTML=`<div class="card" style="padding:24px">
    <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:16px">
      <div style="font-size:10px;text-transform:uppercase;letter-spacing:.08em;color:var(--slate-2);font-weight:600">
        Groundwork's analysis${isSaved?` · <span style="color:var(--slate-2)">Saved — ${esc(label)}</span>`:''}
      </div>
      <button onclick="window.print()" style="background:none;border:1px solid var(--steel);border-radius:var(--r-sm);padding:4px 10px;font-size:11px;cursor:pointer;color:var(--slate)">⎙ Print</button>
    </div>
    ${pullquote?`<div style="font-family:'Playfair Display',Georgia,serif;font-style:italic;font-size:20px;color:var(--ink);line-height:1.5;padding:20px 0;border-top:2px solid var(--steel);border-bottom:2px solid var(--steel);margin-bottom:20px">${esc(pullquote)}</div>`:''}
    <div style="font-size:14px;color:var(--ink);line-height:1.8">${rest.map(p=>`<p style="margin:0 0 14px">${esc(p)}</p>`).join('')}</div>
  </div>`;
}

let _rcMonthlyGenerating = false;
async function _rcMonthlyGenerate() {
  // Local mode has no button click to naturally prevent re-entry — it can
  // now be triggered by initial render, a month switch, AND the annotation
  // debounce, any of which could otherwise stack a second concurrent LLM
  // call on top of one already running.
  if (_rcMonthlyGenerating) return;
  const month = g('rcMonthSel')?.value;
  if (!month) return;
  const cont = g('rcMonthlyNarrative');
  if (!cont) return;
  _rcMonthlyGenerating = true;
  // Guard against the stale-response race: if the user switches months (or
  // double-clicks) while a slower request is still in flight, a response
  // for a month the user has since navigated away from must never overwrite
  // what's on screen for the month they're now looking at.
  const btn = g('rcMonthlyGenBtn');
  if (btn) { btn.disabled = true; btn.style.opacity = '0.6'; btn.style.cursor = 'default'; }
  const stillCurrent = () => g('rcMonthSel')?.value === month;
  cont.innerHTML=`<div class="card" style="padding:32px;text-align:center"><div style="display:inline-flex;align-items:center;gap:12px;color:var(--slate);font-size:13px"><div class="spinner"></div>Writing your report…</div></div>`;
  const [yr,mo]=month.split('-').map(Number);
  const start=`${yr}-${String(mo).padStart(2,'0')}-01`;
  const end=new Date(yr,mo,0).toISOString().slice(0,10);
  const txns=S.transactions.filter(t=>t.date>=start&&t.date<=end);
  const monthName=new Date(yr,mo-1).toLocaleDateString('en-US',{month:'long',year:'numeric'});
  // _isSpend, not a raw debit filter — see generateReport(); this is the same
  // budget-profile comparison and was carrying the same transfer inflation.
  const spent=txns.filter(_isSpend).reduce((s,t)=>s+t.amount,0);
  const income=S.incomes.reduce((s,i)=>s+i.amount,0);
  const under=income-spent;
  const cats={}; txns.filter(_isSpend).forEach(t=>{const pn=_catParentName(t.category||'Other')||'Other';cats[pn]=(cats[pn]||0)+t.amount;});
  const topCatEntries=Object.entries(cats).sort((a,b)=>b[1]-a[1]).slice(0,5);
  const topCats=topCatEntries.map(([c,a])=>`${c}: ${fmt(a)}`).join(', ');
  // topCatEntries holds PARENT category names (see _catParentName above) —
  // roll up to find any Electric/Gas/Gas-Fuel children within each so a
  // "Utilities" or "Transportation" line still gets its price context.
  const priceLines=[...new Set(topCatEntries.flatMap(([c])=>_utilityRelevantCategoryNames(c)))]
    .map(n=>_utilityPriceSentence(n)).filter(Boolean);
  const annotation=g('rcMonthAnnotation')?.value?.trim()||'';
  const reenable = () => { _rcMonthlyGenerating = false; if (btn) { btn.disabled = false; btn.style.opacity = ''; btn.style.cursor = 'pointer'; } };
  if (!aiEnabled()) {
    _rcMonthlyDisplayNarrative(_rcMonthlyFallbackText(monthName,spent,income,under,topCats),monthName,false);
    reenable();
    return;
  }
  try {
    // Item 10 S5/S6: the monthly report appears as it is written, sentence by checked sentence, with Stop.
    const live = _gwLiveNarration(cont, 'monthly');
    const result = await callAI({
      onSentence: live.add, onReset: live.reset, signal: live.signal,
      messages:[{role:'user',content:`Monthly report for ${monthName}. Spent: ${fmt(spent)}. Income: ${fmt(income)}. ${under>=0?`Under budget by ${fmt(under)}.`:`Over by ${fmt(Math.abs(under))}.`} Top categories: ${topCats}. ${priceLines.length?`Real market price benchmarks for the categories above (use these to tell price-driven changes apart from usage-driven ones — don't blame the household for a price increase): ${priceLines.join(' ')}`:''} ${annotation?`Note: "${annotation}"`:''}. Write 3-4 paragraphs, about 300 words. Start with one punchy sentence. Follow with analysis. End by naming the single largest category above and its exact dollar amount, stated as a plain fact — not a command or suggestion, and never calculate a new number yourself (write "Transfer was the largest category at $X," never "Consider cutting..." or "You should trim..." or any dollar figure not listed above). No bullets. No headings.`}],
      system:'You are writing a monthly financial report. Tone: direct, honest, like a trusted friend who knows their numbers. Never preachy.',
      surface: 'monthly_report_v2',
      findings_kinds: ['income', 'total', 'category', 'budget', 'date', 'price_benchmark', 'annotation'],
      max_tokens: 1000,   // item 12 step 2 K1/K6: explicit - it was the server's default
    });
    live.close();
    if (result.stopped) {        // S6: shown text stays, marked stopped; not saved as the month's report
      if (stillCurrent()) _gwShowStopped(cont, result.text, 'rcMonthlyStopped', true);
      return;
    }
    if (!result.ok || !result.text) throw new Error('empty');
    if (stillCurrent()) {
      _rcMonthlyDisplayNarrative(result.text,monthName,false);
      _rcMonthlyLoadPastReports();
    }
    API.patch('/api/settings',{[`report_text_${month}`]:result.text}).catch(_gwErr('_rcMonthlyGenerate'));
  } catch(e) {
    if (stillCurrent()) _rcMonthlyDisplayNarrative(_rcMonthlyFallbackText(monthName,spent,income,under,topCats),monthName,false);
  } finally {
    reenable();
  }
}

function _rcMonthlyFallbackText(monthName,spent,income,under,topCats) {
  const net=income-spent;
  const s1=net>=0?`${monthName} was a solid month — you kept ${fmt(net)} of your income.`:`${monthName} was a tight month — spending ran ${fmt(Math.abs(net))} over income.`;
  const s2=topCats?`Your biggest spending categories were ${topCats}. These are the areas worth reviewing if you want to find room.`:'Import your transactions to see a spending breakdown.';
  const s3=net>=0?`That ${fmt(net)} surplus can go straight toward your top debt priority — every dollar applied now saves money in interest.`:`Start next month by identifying one category to trim. Even ${fmt(Math.abs(net)/2)} would get you back to even.`;
  return [s1,s2,s3].join('\n\n');
}

function _rcRenderCategoryDeepDive() {
  const body = g('rcReportBody');
  if (!body) return;

  // Group spending by parent category with child drill-down
  const months = [...new Set(
    S.transactions.map(t => (t.date||'').slice(0,7)).filter(Boolean)
  )].sort().reverse().slice(0, 12);

  // Get all parent categories that have spending data
  const parentSpending = _catTree('expense').map(({parent, children}) => {
    const total = months.reduce((s, mo) => s + _catSpentInMonth(parent.name, mo), 0);
    if (total === 0) return null;
    const childData = children.map(c => ({
      name: c.name,
      color: c.color || parent.color,
      total: months.reduce((s, mo) => s + _catSpentInMonth(c.name, mo), 0),
    })).filter(c => c.total > 0).sort((a,b) => b.total - a.total);
    return { parent, children: childData, total };
  }).filter(Boolean).sort((a,b) => b.total - a.total);

  const cats = parentSpending.map(p => p.parent.name);

  body.innerHTML = `
    <div style="margin-bottom:24px">
      <h2 style="font-family:'Playfair Display',Georgia,serif;font-style:italic;
                 font-size:22px;font-weight:600;color:var(--ink);margin-bottom:4px">Category Deep-Dive</h2>
      <div style="font-size:13px;color:var(--slate)">Trend, total, and top merchants for any category over any date range.</div>
    </div>

    <div style="display:flex;gap:12px;flex-wrap:wrap;margin-bottom:24px">
      <div>
        <label style="font-size:11px;font-weight:600;letter-spacing:.06em;text-transform:uppercase;color:var(--slate);display:block;margin-bottom:4px">Category</label>
        <select id="rcCatSelect" onchange="_rcUpdateCategoryDeepDive()"
          style="font-size:13px;border:1px solid var(--steel);border-radius:var(--r-sm);padding:6px 10px;background:var(--paper);color:var(--ink)">
          ${cats.map(c => `<option value="${esc(c)}">${esc(c)}</option>`).join('')}
        </select>
      </div>
      <div>
        <label style="font-size:11px;font-weight:600;letter-spacing:.06em;text-transform:uppercase;color:var(--slate);display:block;margin-bottom:4px">From</label>
        <select id="rcCatFrom" onchange="_rcUpdateCategoryDeepDive()"
          style="font-size:13px;border:1px solid var(--steel);border-radius:var(--r-sm);padding:6px 10px;background:var(--paper);color:var(--ink)">
          ${months.map(m => {
            const [y,mo] = m.split('-').map(Number);
            const lbl = new Date(y,mo-1,1).toLocaleDateString('en-US',{month:'short',year:'numeric'});
            return `<option value="${m}">${lbl}</option>`;
          }).join('')}
        </select>
      </div>
      <div>
        <label style="font-size:11px;font-weight:600;letter-spacing:.06em;text-transform:uppercase;color:var(--slate);display:block;margin-bottom:4px">To</label>
        <select id="rcCatTo" onchange="_rcUpdateCategoryDeepDive()"
          style="font-size:13px;border:1px solid var(--steel);border-radius:var(--r-sm);padding:6px 10px;background:var(--paper);color:var(--ink)">
          ${[...months].reverse().map(m => {
            const [y,mo] = m.split('-').map(Number);
            const lbl = new Date(y,mo-1,1).toLocaleDateString('en-US',{month:'short',year:'numeric'});
            return `<option value="${m}" ${m===months[0]?'selected':''}>${lbl}</option>`;
          }).join('')}
        </select>
      </div>
    </div>

    <div id="rcCatResult"></div>
  `;

  // Set "From" to 6 months back by default
  const fromSel = g('rcCatFrom');
  if (fromSel && months.length > 6) fromSel.value = months[5];

  _rcUpdateCategoryDeepDive();
}

function _rcUpdateCategoryDeepDive() {
  const cat  = g('rcCatSelect')?.value;
  const from = g('rcCatFrom')?.value;
  const to   = g('rcCatTo')?.value;
  const res  = g('rcCatResult');
  if (!cat || !from || !to || !res) return;

  const [fy,fm] = from.split('-').map(Number);
  const [ty,tm] = to.split('-').map(Number);

  // Build month range
  const moRange = [];
  let cy = fy, cm = fm;
  while (cy < ty || (cy === ty && cm <= tm)) {
    moRange.push(`${cy}-${String(cm).padStart(2,'0')}`);
    cm++; if (cm > 12) { cm = 1; cy++; }
  }

  // Transactions in range for this category. The dropdown only lists
  // parent categories, but real transactions carry their CHILD category
  // (e.g. "Electric", not "Utilities") — roll up by category_id, same as
  // _catSpentInMonth, or every parent with children would show "no
  // transactions" here. Falls back to a plain name match if categories
  // haven't loaded (defensive — S.categories should always be populated).
  const catRow   = _catByName(cat);
  const childIds = catRow && _catIsParent(cat) ? _catChildIds(cat) : [];
  const matchIds = catRow ? [catRow.id, ...childIds] : [];
  const txns = S.transactions.filter(t =>
    t.type === 'debit' &&
    (matchIds.length ? matchIds.includes(t.category_id) : t.category === cat) &&
    moRange.some(m => (t.date||'').startsWith(m))
  );

  if (!txns.length) {
    res.innerHTML = `<div style="color:var(--slate);font-size:13px">No transactions in ${esc(cat)} for this range.</div>`;
    return;
  }

  const total   = txns.reduce((s,t) => s+t.amount, 0);
  const monthly = moRange.map(mo => ({
    mo,
    amt: txns.filter(t => (t.date||'').startsWith(mo)).reduce((s,t) => s+t.amount, 0),
  }));
  const avg     = total / monthly.filter(m => m.amt > 0).length;
  const highest = monthly.reduce((a,b) => b.amt > a.amt ? b : a);
  const lowest  = monthly.filter(m=>m.amt>0).reduce((a,b) => b.amt < a.amt ? b : a, monthly.filter(m=>m.amt>0)[0]);

  // Top merchants (use merchant field if populated, else description)
  const merchants = {};
  txns.forEach(t => {
    const name = t.merchant || t.description || 'Unknown';
    merchants[name] = (merchants[name]||0) + t.amount;
  });
  const topMerchants = Object.entries(merchants)
    .sort((a,b) => b[1]-a[1]).slice(0,8);

  // Sparkline bars
  const maxAmt   = Math.max(...monthly.map(m=>m.amt));
  const barH     = 48;
  const barW     = Math.max(4, Math.floor(320 / Math.max(moRange.length,1)));
  const cs       = _categoryStyle(cat);

  const bars = monthly.map(m => {
    const h    = maxAmt > 0 ? Math.round((m.amt / maxAmt) * barH) : 0;
    const [y,mo] = m.mo.split('-').map(Number);
    const lbl  = new Date(y,mo-1,1).toLocaleDateString('en-US',{month:'short'});
    return `<div style="display:flex;flex-direction:column;align-items:center;gap:3px;flex:1;min-width:${barW}px;max-width:32px">
      <div style="width:100%;height:${barH}px;display:flex;align-items:flex-end">
        <div style="width:100%;height:${h}px;background:${cs.color};border-radius:2px 2px 0 0;opacity:.85"></div>
      </div>
      <div style="font-size:9px;color:var(--slate-2);writing-mode:vertical-rl;transform:rotate(180deg);height:28px;overflow:hidden">${lbl}</div>
    </div>`;
  }).join('');

  const [hy,hm] = highest.mo.split('-').map(Number);
  const highLbl = new Date(hy,hm-1,1).toLocaleDateString('en-US',{month:'long',year:'numeric'});
  const lowLbl  = lowest ? (() => { const [y,m] = lowest.mo.split('-').map(Number); return new Date(y,m-1,1).toLocaleDateString('en-US',{month:'long',year:'numeric'}); })() : '—';
  const priceNames   = _utilityRelevantCategoryNames(cat);
  const priceCtxList = priceNames.map(n => _utilityPriceContext(n)).filter(Boolean);

  res.innerHTML = `
    <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:12px;margin-bottom:24px">
      <div class="card" style="padding:14px">
        <div style="font-size:10px;text-transform:uppercase;letter-spacing:.08em;color:var(--slate-2);margin-bottom:4px">Total</div>
        <div style="font-family:var(--font-mono);font-size:20px;font-weight:600;color:var(--ink)">${fmt(total)}</div>
      </div>
      <div class="card" style="padding:14px">
        <div style="font-size:10px;text-transform:uppercase;letter-spacing:.08em;color:var(--slate-2);margin-bottom:4px">Monthly avg</div>
        <div style="font-family:var(--font-mono);font-size:20px;font-weight:600;color:var(--ink)">${fmt(avg)}</div>
      </div>
      <div class="card" style="padding:14px">
        <div style="font-size:10px;text-transform:uppercase;letter-spacing:.08em;color:var(--slate-2);margin-bottom:4px">Highest month</div>
        <div style="font-family:var(--font-mono);font-size:16px;font-weight:600;color:var(--ember)">${fmt(highest.amt)}</div>
        <div style="font-size:11px;color:var(--slate);margin-top:2px">${highLbl}</div>
      </div>
      <div class="card" style="padding:14px">
        <div style="font-size:10px;text-transform:uppercase;letter-spacing:.08em;color:var(--slate-2);margin-bottom:4px">Lowest month</div>
        <div style="font-family:var(--font-mono);font-size:16px;font-weight:600;color:var(--pine)">${lowest ? fmt(lowest.amt) : '—'}</div>
        <div style="font-size:11px;color:var(--slate);margin-top:2px">${lowLbl}</div>
      </div>
    </div>
    ${priceCtxList.length ? `
    <div class="card" style="padding:12px 16px;margin-bottom:20px;font-size:12px;color:var(--slate)">
      ${priceCtxList.map((ctx, i) => `⛽ ${esc(ctx.areaLabel)} avg ${ctx.label} price${ctx.period ? ` (${esc(ctx.period)})` : ''}: <strong style="color:var(--ink)">${esc(ctx.priceStr)}</strong> · source: EIA${priceCtxList.length > 1 ? ` <span style="color:var(--slate-2)">(${esc(priceNames[i])})</span>` : ''}`).join('<br>')}
      — a swing in this category can reflect market price, not just how much you used.
    </div>` : ''}

    <div class="card" style="margin-bottom:20px;padding:16px">
      <div style="font-size:11px;font-weight:600;letter-spacing:.08em;text-transform:uppercase;color:var(--slate-2);margin-bottom:12px">Monthly trend</div>
      <div style="display:flex;align-items:flex-end;gap:2px;overflow-x:auto;padding-bottom:4px">${bars}</div>
    </div>

    <div class="card" style="padding:16px">
      <div style="font-size:11px;font-weight:600;letter-spacing:.08em;text-transform:uppercase;color:var(--slate-2);margin-bottom:12px">Top merchants</div>
      ${topMerchants.map(([name,amt]) => `
        <div style="display:flex;justify-content:space-between;align-items:center;padding:7px 0;border-bottom:1px solid var(--steel)">
          <span style="font-size:13px;color:var(--ink)">${esc(name)}</span>
          <span style="font-family:var(--font-mono);font-size:13px;color:var(--slate)">${fmt(amt)}</span>
        </div>`).join('')}
    </div>
  `;

  // G1: AI analysis for category deep-dive (medium utility)
  if (total > 0) {
    const fromLbl = new Date(fy, fm-1, 1).toLocaleDateString('en-US',{month:'long',year:'numeric'});
    const toLbl   = new Date(ty, tm-1, 1).toLocaleDateString('en-US',{month:'long',year:'numeric'});
    const moActive = monthly.filter(m => m.amt > 0);
    const dataLines = [
      `Category: ${cat}`,
      `Period: ${fromLbl} – ${toLbl}`,
      `Total spent: ${fmt(total)}`,
      `Monthly average: ${fmt(Math.round(avg))}`,
      // Pre-computed here, not left for the model to derive — R8 rejects any
      // figure not verbatim in the findings, so asking the model to multiply
      // avg×12 itself guaranteed a false "invented figure" rejection every
      // time. Stating it as a given fact lets the model cite it instead.
      // Must multiply the SAME ROUNDED monthly figure shown above (not the
      // raw unrounded avg) — a model reasonably computes from the number it
      // was actually given, and a $5 mismatch from rounding order elsewhere
      // makes a correct answer look "invented" by pure coincidence of math.
      `Annualized cost at this monthly rate: ${fmt(Math.round(avg) * 12)}`,
      `Highest month: ${fmt(highest.amt)} (${highest.mo})`,
      ...(lowest ? [`Lowest month: ${fmt(lowest.amt)} (${lowest.mo})`] : []),
      `Months with activity: ${moActive.length} of ${monthly.length}`,
      // No merchant line. `topMerchants` is built from `t.merchant || t.description` -
      // the bank's own description strings - and a raw transaction description is not
      // an asserted finding merely because it sits in the household's transaction record
      // (gw 2.0/HAZARD_AUDIT.md H5, correction and ruling). "CVS PHARMACY #1234 ($180)"
      // in a gated prompt hands the model wording to manufacture a claim from. The
      // merchants table the household sees above is untouched: that is rendered HTML,
      // not model input. Deterministic totals, counts, dates and the category name stay.
      ...priceNames.map(n => _utilityPriceSentence(n)),
    ];
    const buildPrompt = (profileCtx) => [
      profileCtx || '',
      `CATEGORY DEEP-DIVE: ${cat}`,
      `Period: ${fromLbl} – ${toLbl}`,
      '',
      dataLines.join('\n'),
      '',
      'In 2-3 short paragraphs: describe how the monthly amount moved (up, down, or flat, with the actual figures) — plainly, not as "this shows/indicates/suggests" a pattern, just the numbers themselves. State the annualized cost given above — do not calculate your own. One specific observation.',
      priceCtxList.length ? 'A real market price benchmark is included above — if this category rose, check whether the benchmark price rose too before attributing it to the household using more; say so plainly if price explains some or all of the change.' : '',
      'No generic advice. No headers.',
    ].filter(Boolean).join('\n');
    // Folds the category + date range into the AI cache key — a bare
    // 'category' key would show Groceries' cached analysis after switching
    // to Debt, since _rcAICache/_rcAIThread are keyed by this id and persist
    // across re-renders within the session (and now across restarts too).
    const aiId = `category_${cat.replace(/[^a-z0-9]/gi,'_')}_${from}_${to}`;
    _rcAnalyzeWithAI(aiId, dataLines, buildPrompt, res);
  }
}

// ── §7.6 Annual Summary ───────────────────────────────────────────────────────
function _rcRenderAnnualSummary() {
  const body = g('rcReportBody');
  if (!body) return;

  const availYears = [...new Set(
    S.transactions.map(t => (t.date||'').slice(0,4)).filter(Boolean)
  )].sort().reverse();

  const thisYear = String(new Date().getFullYear());

  body.innerHTML = `
    <div style="margin-bottom:24px">
      <h2 style="font-family:'Playfair Display',Georgia,serif;font-style:italic;
                 font-size:22px;font-weight:600;color:var(--ink);margin-bottom:4px">Annual Summary</h2>
      <div style="font-size:13px;color:var(--slate)">Full year income, spending, savings, and top categories.</div>
    </div>

    <div style="margin-bottom:24px">
      <label style="font-size:11px;font-weight:600;letter-spacing:.06em;text-transform:uppercase;color:var(--slate);display:block;margin-bottom:4px">Year</label>
      <select id="rcAnnualYear" onchange="_rcUpdateAnnualSummary()"
        style="font-size:13px;border:1px solid var(--steel);border-radius:var(--r-sm);padding:6px 10px;background:var(--paper);color:var(--ink)">
        ${availYears.map(y => `<option value="${y}" ${y===thisYear?'selected':''}>${y}</option>`).join('')}
      </select>
    </div>
    <div id="rcAnnualResult"></div>
  `;

  _rcUpdateAnnualSummary();
}

function _rcUpdateAnnualSummary() {
  const year = g('rcAnnualYear')?.value;
  const res  = g('rcAnnualResult');
  if (!year || !res) return;

  const prevYear = String(parseInt(year) - 1);
  const months   = Array.from({length:12}, (_,i) => `${year}-${String(i+1).padStart(2,'0')}`);

  const yearTxns = S.transactions.filter(t => (t.date||'').startsWith(year));
  const prevTxns = S.transactions.filter(t => (t.date||'').startsWith(prevYear));

  // Transfers excluded on BOTH sides. They largely cancel in `totalSaved`, so
  // the bug hid there — but savingsRate divides by the inflated income, and the
  // category ranking below listed "Transfer" as real spending.
  const totalIncome   = yearTxns.filter(_isEarn).reduce((s,t)=>s+t.amount,0);
  const totalExpenses = yearTxns.filter(_isSpend).reduce((s,t)=>s+t.amount,0);
  const totalSaved    = totalIncome - totalExpenses;
  const savingsRate   = totalIncome > 0 ? Math.round((totalSaved / totalIncome) * 100) : 0;

  const prevIncome    = prevTxns.filter(_isEarn).reduce((s,t)=>s+t.amount,0);
  const prevExpenses  = prevTxns.filter(_isSpend).reduce((s,t)=>s+t.amount,0);
  const hasPrev       = prevTxns.length > 0;

  // Top 10 categories — rolled up to parent (e.g. "Electric"+"Gas" under
  // "Utilities" combine into one line), matching Monthly Report's convention
  // instead of splitting the same spending into separate child entries.
  const catTotals = {};
  yearTxns.filter(t=>_isSpend(t)&&t.category).forEach(t => {
    const pn = _catParentName(t.category)||t.category;
    catTotals[pn] = (catTotals[pn]||0) + t.amount;
  });
  const topCats = Object.entries(catTotals).sort((a,b)=>b[1]-a[1]).slice(0,10);

  // Month-by-month
  const moData = months.map(mo => {
    const inc = yearTxns.filter(t=>_isEarn(t) &&(t.date||'').startsWith(mo)).reduce((s,t)=>s+t.amount,0);
    const exp = yearTxns.filter(t=>_isSpend(t)&&(t.date||'').startsWith(mo)).reduce((s,t)=>s+t.amount,0);
    const net = inc - exp;
    const rate = inc > 0 ? Math.round((net / inc) * 100) : 0;
    const [y,m] = mo.split('-').map(Number);
    return { mo, lbl: new Date(y,m-1,1).toLocaleDateString('en-US',{month:'short'}), inc, exp, net, rate };
  });

  const yoyRow = (label, curr, prev) => {
    if (!hasPrev) return '';
    const delta = curr - prev;
    const pct   = prev > 0 ? Math.round((delta/prev)*100) : 0;
    const clr   = delta > 0 ? 'var(--pine)' : delta < 0 ? 'var(--ember)' : 'var(--slate)';
    return `<div style="font-size:11px;color:${clr};margin-top:2px">${delta>=0?'+':''}${pct}% vs ${prevYear}</div>`;
  };

  res.innerHTML = `
    <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:12px;margin-bottom:24px">
      <div class="card" style="padding:14px">
        <div style="font-size:10px;text-transform:uppercase;letter-spacing:.08em;color:var(--slate-2);margin-bottom:4px">Income</div>
        <div style="font-family:var(--font-mono);font-size:20px;font-weight:600;color:var(--pine)">${fmt(totalIncome)}</div>
        ${yoyRow('income', totalIncome, prevIncome)}
      </div>
      <div class="card" style="padding:14px">
        <div style="font-size:10px;text-transform:uppercase;letter-spacing:.08em;color:var(--slate-2);margin-bottom:4px">Expenses</div>
        <div style="font-family:var(--font-mono);font-size:20px;font-weight:600;color:var(--ember)">${fmt(totalExpenses)}</div>
        ${yoyRow('expenses', totalExpenses, prevExpenses)}
      </div>
      <div class="card" style="padding:14px">
        <div style="font-size:10px;text-transform:uppercase;letter-spacing:.08em;color:var(--slate-2);margin-bottom:4px">Saved</div>
        <div style="font-family:var(--font-mono);font-size:20px;font-weight:600;color:${totalSaved>=0?'var(--pine)':'var(--ember)'}">${fmt(totalSaved)}</div>
        <div style="font-size:11px;color:var(--slate);margin-top:2px">${savingsRate}% savings rate</div>
      </div>
    </div>

    <div class="card" style="margin-bottom:20px;padding:16px">
      <div style="font-size:11px;font-weight:600;letter-spacing:.08em;text-transform:uppercase;color:var(--slate-2);margin-bottom:12px">Month by month</div>
      <div style="overflow-x:auto">
        <table style="width:100%;border-collapse:collapse;font-size:12px">
          <thead>
            <tr style="border-bottom:1px solid var(--steel)">
              <th style="text-align:left;padding:5px 8px;color:var(--slate-2);font-weight:500">Month</th>
              <th style="text-align:right;padding:5px 8px;color:var(--slate-2);font-weight:500">Income</th>
              <th style="text-align:right;padding:5px 8px;color:var(--slate-2);font-weight:500">Expenses</th>
              <th style="text-align:right;padding:5px 8px;color:var(--slate-2);font-weight:500">Net</th>
            </tr>
          </thead>
          <tbody>
            ${moData.map(m => `
              <tr style="border-bottom:1px solid var(--steel)">
                <td style="padding:6px 8px;color:var(--ink)">${m.lbl}</td>
                <td style="padding:6px 8px;font-family:var(--font-mono);text-align:right;color:var(--pine)">${m.inc>0?fmt(m.inc):'—'}</td>
                <td style="padding:6px 8px;font-family:var(--font-mono);text-align:right;color:var(--ember)">${m.exp>0?fmt(m.exp):'—'}</td>
                <td style="padding:6px 8px;font-family:var(--font-mono);text-align:right;color:${m.net>=0?'var(--pine)':'var(--ember)'}">${fmt(m.net)}</td>
              </tr>`).join('')}
          </tbody>
        </table>
      </div>
    </div>

    <div class="card" style="padding:16px">
      <div style="font-size:11px;font-weight:600;letter-spacing:.08em;text-transform:uppercase;color:var(--slate-2);margin-bottom:12px">Top spending categories</div>
      ${topCats.map(([cat,amt],i) => {
        const cs  = _categoryStyle(cat);
        const pct = totalExpenses > 0 ? Math.round((amt/totalExpenses)*100) : 0;
        const bg  = _catTint(cs.color);
        const br  = _catTintBorder(cs.color);
        return `<div style="display:flex;align-items:center;gap:10px;padding:7px 0;border-bottom:1px solid var(--steel)">
          <div style="font-size:11px;color:var(--slate-2);width:16px;text-align:right">${i+1}</div>
          <div><div class="cat-icon" style="background:${bg};border-color:${br};color:${cs.color}">${_renderCatIcon(cs.icon,cs.color,18)}</div></div>
          <span style="flex:1;font-size:13px;color:var(--ink)">${esc(cat)}</span>
          <span style="font-size:11px;color:var(--slate-2)">${pct}%</span>
          <span style="font-family:var(--font-mono);font-size:13px;color:var(--ink)">${fmt(amt)}</span>
        </div>`;
      }).join('')}
    </div>
  `;

  // G1: AI analysis for annual summary (medium utility)
  if (totalIncome > 0 || totalExpenses > 0) {
    const moActive = moData.filter(m => m.inc > 0 || m.exp > 0);
    const avgRate  = moActive.length
      ? Math.round(moActive.reduce((s,m) => s + m.rate, 0) / moActive.length)
      : 0;

    // Computed debt reality for the year, from balance history (when loaded).
    // Tester-caught (d21): with only spending variance and "Debt" as a top
    // category, the model invented "just covering minimums while the principal
    // sits" — a claim it had zero balance data to support. Give it the real
    // split so it has facts to state instead of a vibe to judge.
    const debtFacts = (() => {
      const allRows = Object.values(_debtHistoryCache || {});
      if (!allRows.length) return null;
      let startBal = 0, endBal = 0, paid = 0, cards = 0;
      allRows.forEach(rows => {
        const inYear = rows.filter(h => h.month && h.month.startsWith(String(year)))
                           .sort((a,b) => a.month < b.month ? -1 : 1);
        if (inYear.length < 2) return;
        cards++;
        startBal += inYear[0].balance;
        endBal   += inYear[inYear.length - 1].balance;
        paid     += inYear.reduce((s,h) => s + (h.payment || 0), 0);
      });
      if (!cards || paid <= 0) return null;
      const principalDown = startBal - endBal;                    // negative = debt grew; still a fact
      const interestEst   = Math.max(0, Math.round(paid - principalDown));
      return { paid: Math.round(paid), principalDown: Math.round(principalDown), interestEst, cards };
    })();

    const dataLines = [
      `Year: ${year}`,
      `Total income: ${fmt(totalIncome)}`,
      `Total expenses: ${fmt(totalExpenses)}`,
      `Net: ${fmt(totalSaved)}`,
      `Annual savings rate: ${savingsRate}%`,
      ...(hasPrev ? [
        `Prior year income: ${fmt(prevIncome)}`,
        `Prior year expenses: ${fmt(prevExpenses)}`,
      ] : []),
      `Active months: ${moActive.length}`,
      ...(topCats.slice(0,5).length ? [`Top 5 categories: ${topCats.slice(0,5).map(([c,a]) => `${c} (${fmt(a)})`).join(', ')}`] : []),
      ...(debtFacts ? [
        `Debt (computed from balance history, ${debtFacts.cards} account${debtFacts.cards!==1?'s':''}): payments ${fmt(debtFacts.paid)}, principal ${debtFacts.principalDown >= 0 ? 'reduced by' : 'grew by'} ${fmt(Math.abs(debtFacts.principalDown))}, estimated interest portion ${fmt(debtFacts.interestEst)}`,
      ] : []),
    ];
    const buildPrompt = (profileCtx) => [
      profileCtx || '',
      `ANNUAL SUMMARY: ${year}`,
      '',
      dataLines.join('\n'),
      '',
      'Month-by-month:',
      ...moActive.map(m => `  ${m.lbl}: income ${fmt(m.inc)}, expenses ${fmt(m.exp)}, rate ${m.rate}%`),
      '',
      'In 2-3 short paragraphs: state the year\'s income, spending, and savings rate plainly. Name which months had the highest and lowest spending, with the actual figures. State how many months of savings at the current rate it would take to reach a payoff-relevant milestone, as a plain calculation — not as "this means" or "this indicates" anything. One specific fact, not a takeaway framed as an inference. No headers.',
      debtFacts
        ? 'Any statement about debt must use the computed debt line above — payments, principal change, interest portion.'
        : 'No debt balance data was provided: make no claims about principal, minimums, or what debt payments accomplished.',
    ].filter(Boolean).join('\n');
    // Folds the year into the AI cache key — a bare 'annual' key would show
    // 2025's cached analysis after switching the year selector to 2026.
    _rcAnalyzeWithAI(`annual_${year}`, dataLines, buildPrompt, res);
  }
}

// ── §7.7 Import Audit ─────────────────────────────────────────────────────────
function _rcRenderImportAudit() {
  const body = g('rcReportBody');
  if (!body) return;

  const txns       = S.transactions;
  const total      = txns.length;
  const imported   = txns.filter(t => t.source && t.source !== 'manual').length;
  const manual     = txns.filter(t => !t.source || t.source === 'manual').length;
  // Uncategorized = no category, 'Other', or a parent category (should be child)
  const uncatd     = txns.filter(t => {
    if (!t.category || t.category === 'Other') return true;
    // Parent-level category is also "not fully categorized" — should be a child
    if (_catIsParent(t.category) && _catChildren(t.category).length > 0) return true;
    return false;
  }).length;
  const pctCatd    = total > 0 ? Math.round(((total - uncatd) / total) * 100) : 0;

  // Category breakdown
  const catCounts = {};
  txns.forEach(t => { const c = t.category||'Other'; catCounts[c]=(catCounts[c]||0)+1; });
  const catRows = Object.entries(catCounts).sort((a,b)=>b[1]-a[1]);

  // Source breakdown
  const srcCounts = {};
  txns.forEach(t => { const s = t.source||'manual'; srcCounts[s]=(srcCounts[s]||0)+1; });

  // Accounts breakdown
  const acctCounts = {};
  txns.forEach(t => { const a = t.account||'Unknown'; acctCounts[a]=(acctCounts[a]||0)+1; });
  const acctRows = Object.entries(acctCounts).sort((a,b)=>b[1]-a[1]).slice(0,8);

  // Items needing attention: uncategorized debits
  const needsAttention = txns
    .filter(t => t.type==='debit' && (!t.category || t.category==='Other'))
    .sort((a,b)=>b.amount-a.amount)
    .slice(0,10);

  body.innerHTML = `
    <div style="margin-bottom:24px">
      <h2 style="font-family:'Playfair Display',Georgia,serif;font-style:italic;
                 font-size:22px;font-weight:600;color:var(--ink);margin-bottom:4px">Import Audit</h2>
      <div style="font-size:13px;color:var(--slate)">Data quality overview — categorization rate, sources, and items needing attention.</div>
    </div>

    <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(130px,1fr));gap:12px;margin-bottom:24px">
      <div class="card" style="padding:14px">
        <div style="font-size:10px;text-transform:uppercase;letter-spacing:.08em;color:var(--slate-2);margin-bottom:4px">Total transactions</div>
        <div style="font-family:var(--font-mono);font-size:22px;font-weight:600;color:var(--ink)">${total.toLocaleString()}</div>
      </div>
      <div class="card" style="padding:14px">
        <div style="font-size:10px;text-transform:uppercase;letter-spacing:.08em;color:var(--slate-2);margin-bottom:4px">Imported</div>
        <div style="font-family:var(--font-mono);font-size:22px;font-weight:600;color:var(--ink)">${imported.toLocaleString()}</div>
      </div>
      <div class="card" style="padding:14px">
        <div style="font-size:10px;text-transform:uppercase;letter-spacing:.08em;color:var(--slate-2);margin-bottom:4px">Manual entries</div>
        <div style="font-family:var(--font-mono);font-size:22px;font-weight:600;color:var(--ink)">${manual.toLocaleString()}</div>
      </div>
      <div class="card" style="padding:14px;${uncatd>0?'border-color:var(--gold)':''}">
        <div style="font-size:10px;text-transform:uppercase;letter-spacing:.08em;color:var(--slate-2);margin-bottom:4px">Categorized</div>
        <div style="font-family:var(--font-mono);font-size:22px;font-weight:600;color:${pctCatd>=90?'var(--pine)':pctCatd>=70?'var(--gold)':'var(--ember)'}">${pctCatd}%</div>
        <div style="font-size:11px;color:var(--slate);margin-top:2px">${uncatd} in "Other"</div>
      </div>
    </div>

    ${uncatd > 0 ? `
    <div class="card" style="margin-bottom:20px;padding:16px;border-color:var(--gold);background:var(--gold-bg,var(--gold-bg))">
      <div style="font-size:12px;font-weight:600;color:#92400e;margin-bottom:10px">
        ${uncatd} transaction${uncatd!==1?'s':''} in "Other" — review and categorize for better reports
      </div>
      ${needsAttention.slice(0,5).map(t => `
        <div style="display:flex;justify-content:space-between;align-items:center;padding:5px 0;border-bottom:1px solid rgba(217,119,6,.2);font-size:12px">
          <span style="color:var(--ink)">${esc(t.description||t.merchant||'')}</span>
          <span style="font-family:var(--font-mono);color:var(--ember)">${fmt(t.amount)}</span>
        </div>`).join('')}
      ${uncatd > 5 ? `<div style="font-size:11px;color:var(--slate);margin-top:8px">…and ${uncatd-5} more. Open the Ledger to review.</div>` : ''}
      <div style="margin-top:10px">
        <button onclick="showView('ledger')"
          style="font-size:12px;background:none;border:1px solid var(--gold-border);
                 border-radius:var(--r-sm);padding:5px 12px;cursor:pointer;color:#92400e">
          Review in Ledger →
        </button>
      </div>
    </div>` : `
    <div class="card" style="margin-bottom:20px;padding:14px;border-color:var(--pine-border);background:var(--pine-bg)">
      <div style="font-size:13px;color:var(--pine)">✓ All transactions are categorized. Good data quality.</div>
    </div>`}

    <div style="display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-bottom:20px">
      <div class="card" style="padding:16px">
        <div style="font-size:11px;font-weight:600;letter-spacing:.08em;text-transform:uppercase;color:var(--slate-2);margin-bottom:12px">By source</div>
        ${Object.entries(srcCounts).map(([src,cnt]) => `
          <div style="display:flex;justify-content:space-between;padding:5px 0;border-bottom:1px solid var(--steel);font-size:12px">
            <span style="color:var(--ink);text-transform:capitalize">${esc(src)}</span>
            <span style="font-family:var(--font-mono);color:var(--slate)">${cnt.toLocaleString()}</span>
          </div>`).join('')}
      </div>
      <div class="card" style="padding:16px">
        <div style="font-size:11px;font-weight:600;letter-spacing:.08em;text-transform:uppercase;color:var(--slate-2);margin-bottom:12px">By account</div>
        ${acctRows.map(([acct,cnt]) => `
          <div style="display:flex;justify-content:space-between;padding:5px 0;border-bottom:1px solid var(--steel);font-size:12px">
            <span style="color:var(--ink);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:120px">${esc(acct)}</span>
            <span style="font-family:var(--font-mono);color:var(--slate)">${cnt.toLocaleString()}</span>
          </div>`).join('')}
      </div>
    </div>

    <div class="card" style="padding:16px">
      <div style="font-size:11px;font-weight:600;letter-spacing:.08em;text-transform:uppercase;color:var(--slate-2);margin-bottom:12px">Transactions by category</div>
      ${catRows.map(([cat,cnt]) => {
        const pct = total > 0 ? Math.round((cnt/total)*100) : 0;
        const cs  = _categoryStyle(cat);
        return `<div style="display:flex;align-items:center;gap:10px;padding:5px 0;border-bottom:1px solid var(--steel);font-size:12px">
          <div style="width:6px;height:6px;border-radius:50%;background:${cs.color};flex-shrink:0"></div>
          <span style="flex:1;color:var(--ink)">${esc(cat)}</span>
          <span style="color:var(--slate-2)">${pct}%</span>
          <span style="font-family:var(--font-mono);color:var(--slate);width:36px;text-align:right">${cnt}</span>
        </div>`;
      }).join('')}
    </div>
  `;
}

// ── Phase E: Remaining local reports ─────────────────────────────────────────

// ── §7.3 Debt Progress ────────────────────────────────────────────────────────
// ── Distance Traveled — flagship report ──────────────────────────────────────
// Philosophy (GROUNDWORK_PHILOSOPHY.md): ground covered, not remaining.
// Real numbers only. Every stat below is either computed from recorded data
// (debt_balance_history, net worth snapshots, the cards themselves) or not
// shown at all. No history yet → beginBal is the starting line, so the report
// works on day 1 and deepens each month as snapshots accrue. Most valuable at
// months 3-4, when motivation is most fragile.

function _dtMonthLabel(monthKey) {
  if (!monthKey) return '';
  const [y, m] = monthKey.split('-');
  return new Date(+y, +m - 1, 1).toLocaleDateString('en-US', { month: 'long', year: 'numeric' });
}

function _dtDateFromMonth(monthKey, plusMonths) {
  const [y, m] = monthKey.split('-');
  const d = new Date(+y, +m - 1, 1);
  d.setMonth(d.getMonth() + plusMonths);
  return d;
}

function _dtDateShort(dt) {
  return dt ? dt.toLocaleDateString('en-US', { month: 'short', year: 'numeric' }) : '';
}

// Assemble every number the report shows. Kept separate from rendering so the
// same object feeds the AI dataLines — one computation, two consumers.
function _dtComputeDistance() {
  const cards = S.debtCards.filter(c => (parseFloat(c.beginBal) || _cardBal(c) || 0) > 0 || c.paidInFull);

  let earliestMonth = null;
  const perCard = cards.map(card => {
    const history = [...(_debtHistoryCache[String(card._dbId)] || [])].reverse(); // oldest→newest
    const first   = history[0] || null;
    if (first?.month && (!earliestMonth || first.month < earliestMonth)) earliestMonth = first.month;

    const startBal = first ? first.balance : (parseFloat(card.beginBal) || _cardBal(card) || 0);
    const nowBal   = card.paidInFull ? 0 : _cardBal(card);   // display framing only — currentBal untouched
    const covered  = Math.max(0, startBal - nowBal);
    // A paid card can have NO known starting line: no snapshots (manual user,
    // nothing imported), beginBal never filled in, and currentBal walked down
    // to 0 by hand as they paid. All signals read zero — but the user knows
    // the number. The row renderer asks for it (writes beginBal) instead of
    // showing an insulting "0% covered" on their biggest win.
    const startKnown = startBal > 0;

    // Interest actually paid since the window opened — real (imports) or
    // estimated exactly like Debt Progress; null when nothing to estimate from.
    let interestPaid = null;
    const real = history.filter(h => h.interest_charged != null).reduce((s,h) => s + h.interest_charged, 0);
    if (real > 0) interestPaid = real;
    else if (history.length > 1) {
      let est = 0;
      for (let i = 1; i < history.length; i++) {
        const drop = history[i-1].balance - history[i].balance;
        const pmt  = history[i].payment;
        if (pmt > 0 && drop < pmt) est += Math.max(0, pmt - drop);
      }
      if (est > 0) interestPaid = est;
    }

    return { card, history, first, startBal, nowBal, covered, interestPaid, startKnown };
  });

  const totalStart   = perCard.reduce((s,d) => s + d.startBal, 0);
  const totalNow     = perCard.reduce((s,d) => s + d.nowBal, 0);
  const totalCovered = Math.max(0, totalStart - totalNow);
  const pctCovered   = totalStart > 0 ? Math.round((totalCovered / totalStart) * 100) : 0;

  // Retired debts and the monthly cash they no longer claim
  const retired        = perCard.filter(d => d.card.paidInFull);
  const retiredMonthly = retired.reduce((s,d) => s + (parseFloat(d.card.minimum) || 0), 0);
  const decayFreed     = _budgetFreedMinimumsThisYear(perCard.map(d => d.card).filter(c => !c.paidInFull));
  const freedMonthly   = Math.round(retiredMonthly + (decayFreed || 0));

  // Date pulled closer — reads the shared substrate helper (_gwDateMovement:
  // both ends through the same strategy engine, same cascade assumptions).
  // DT keeps its wins-only framing: a pushed-out date is a different report's
  // story, so a negative delta renders nothing here. The financial profile
  // reads the same helper and uses the signed value as paceMonths.
  let dateThen = null, dateNow = null, monthsPulled = null;
  {
    const mv = _gwDateMovement();
    if (mv.computable) {
      dateThen = mv.dateThen;
      dateNow  = mv.dateNow;
      monthsPulled = mv.monthsDelta > 0 ? mv.monthsDelta : null;
    }
  }

  // Interest that will never be charged: per card, the do-nothing path from the
  // first snapshot vs (interest actually paid + projected remaining at the
  // current payment). Cards where either side can't be computed are skipped —
  // an honest partial sum beats a padded total.
  let interestNeverCharged = 0, interestComputable = false;
  perCard.forEach(d => {
    if (!d.first || d.first.balance <= 0 || !(d.first.payment > 0)) return;
    const thenPath = _projectPayoff(d.first.balance, d.first.apr || 0, d.first.payment);
    if (!thenPath.length || thenPath[thenPath.length-1].noPayoff) return;
    const thenInterest = thenPath.reduce((s,x) => s + (x.interest || 0), 0);
    let remaining = 0;
    if (!d.card.paidInFull && d.nowBal > 0) {
      const pmt = _payoffPayment(d.card) || 0;   // V3
      if (!(pmt > 0)) return;
      const nowPath = _projectPayoff(d.nowBal, parseFloat(d.card.rate) || 0, pmt);
      if (!nowPath.length || nowPath[nowPath.length-1].noPayoff) return;
      remaining = nowPath.reduce((s,x) => s + (x.interest || 0), 0);
    }
    const saved = thenInterest - (d.interestPaid || 0) - remaining;
    if (saved > 0) { interestNeverCharged += saved; interestComputable = true; }
  });

  const allClear = !perCard.some(d => !d.card.paidInFull && d.nowBal > 0);

  return { perCard, earliestMonth, totalStart, totalNow, totalCovered, pctCovered,
           retired, retiredMonthly, freedMonthly, dateThen, dateNow, monthsPulled, allClear,
           interestNeverCharged: interestComputable ? Math.round(interestNeverCharged) : null };
}

// ── Shared date movement — substrate helper (d21) ────────────────────────────
// The ONE computation for "ahead/behind schedule": project the debt-free date
// from the first-snapshot state and from today's state through the SAME
// strategy engine, and compare. Consumed by Distance Traveled (monthsPulled,
// clamped to wins) and the financial profile (paceMonths, signed). Replaced
// the profile's rate-ratio pace (actual/required monthly reduction), which was
// structurally misleading: totalDebt/monthsRemaining is a flat average of a
// non-linear amortization, so anyone in the acceleration phase showed hugely
// "ahead" while exactly on plan — the field's "116% ahead of schedule".
function _gwDateMovement() {
  const method = S.debtMethod === 'snowball' ? 'snowball' : 'avalanche';
  let earliestMonth = null;
  const projectable = [];
  S.debtCards.forEach(card => {
    const history = [...(_debtHistoryCache[String(card._dbId)] || [])].reverse(); // oldest→newest
    const first = history[0];
    if (!first || !(first.balance > 0) || !(first.payment > 0)) return;
    if (!earliestMonth || first.month < earliestMonth) earliestMonth = first.month;
    projectable.push({ card, first });
  });
  if (!earliestMonth || !projectable.length) return { computable: false };

  const thenCards = projectable.map(d => ({
    name:       d.card.name || 'Card',
    debtType:   d.card.debtType || 'credit',
    endDate:    d.card.endDate || '',
    paidInFull: false,
    currentBal: d.first.balance,
    // Snapshot rows missing apr must NOT project at 0% — that makes the
    // then-plan artificially fast and biases pace toward "behind". Fall back
    // to the card's current rate, which is the best available estimate.
    rate:       (d.first.apr ?? parseFloat(d.card.rate)) || 0,
    minimum:    d.first.payment,
  }));
  const thenBudget = projectable.reduce((s, x) => s + x.first.payment, 0);
  const thenSim = _simulatePayoffStrategy(thenCards, thenBudget, method);
  if (!thenSim || !(thenSim.months > 0)) return { computable: false };
  const dateThen = _dtDateFromMonth(earliestMonth, thenSim.months);

  let dateNow = null;
  const anyLeft = S.debtCards.some(c => !c.paidInFull && _cardBal(c) > 0);
  if (!anyLeft) {
    dateNow = new Date();   // every debt retired — the date is today
  } else {
    const nowSim = _simulatePayoffStrategy(S.debtCards, _getMonthlyBudget(), method);
    if (nowSim && nowSim.months > 0) {
      dateNow = new Date(); dateNow.setDate(1); dateNow.setMonth(dateNow.getMonth() + nowSim.months);
    }
  }
  if (!dateNow) return { computable: false };

  // Signed: positive = debt-free date pulled closer than the opening plan,
  // negative = pushed out. Consumers apply their own framing.
  const monthsDelta = Math.round((dateThen - dateNow) / (1000*60*60*24*30.44));
  return { computable: true, earliestMonth, dateThen, dateNow, monthsDelta };
}

// ── Claim-specific confidence (Dashboard 2.0 foundation, d21) ────────────────
// GROUNDWORK_PHILOSOPHY.md → The Claim Hierarchy. This is THE claim→checks
// mapping table — "the actual intelligence of the system," in one auditable
// place. It answers, per claim: how much should the user trust what Groundwork
// says about THIS part of their finances?
//
// Rules this obeys:
//  - Confidence is PER-CLAIM, never global. Spending can be 'ready' while debt
//    is 'insufficient' — each is independently true and never contaminates the
//    others.
//  - Confidence is an enumerable CHECKLIST, never a score. Each claim exposes
//    the exact checks behind its status so the UI can show the evidence
//    ("14 months · 98% categorized · balances verified"), never "Confidence: 92%".
//  - Language is generated FROM these states, never the reverse.
//  - Each claim reads ONLY the checks that gate it (spending doesn't depend on
//    balance verification; debt doesn't depend on categorization rate).
//
// Status ∈ 'ready' | 'building' | 'insufficient'
//   ready        — enough verified evidence to state conclusions plainly
//   building     — partial; some conclusions allowed, others narrowed
//   insufficient — cannot responsibly conclude; say what's missing, not a verdict
//
// Each check: { key, label, state: 'pass'|'warn'|'fail', detail }

function _computeClaimConfidence() {
  const txns    = S.transactions || [];
  const debits  = txns.filter(t => t.type === 'debit'  && t.amount > 0);
  const credits = txns.filter(t => t.type === 'credit' && t.amount > 0);

  // ── Shared raw signals (computed once) ──
  const monthsSet = new Set(txns.map(t => (t.date || '').slice(0, 7)).filter(Boolean));
  const monthsSpan = monthsSet.size;

  const isUncat = c => !c || c === 'Uncategorized' || c === 'Other' || c === 'uncategorized';
  const catRate = debits.length
    ? Math.round((debits.filter(t => !isUncat(t.category)).length / debits.length) * 100)
    : 0;

  // Reads BOTH fields. `t.category || t.description` only ever tested the
  // description when the category was falsy — so a paycheck filed under
  // "Transfer" (exactly how the importer used to file them) stayed invisible
  // here no matter what its description said.
  const _looksLikeIncome = t =>
    /(income|salary|paycheck|direct.deposit|payroll|wages)/i.test(
      `${t.category || ''} ${t.description || ''}`);

  // Scoped to the window the cash-flow claim gates, not to all of history.
  // As a bare `.some()` over every credit ever imported, one deposit years ago
  // satisfied this check permanently — which is how cash-flow conclusions came
  // to run on months that had no income recorded in them at all. Coverage is
  // the question, not existence.
  //
  // Counts only what the cash-flow engine will actually count: _isEarn, the
  // same predicate. A gate that measures something the arithmetic doesn't see
  // is not a gate. Recognising a paycheck by its DESCRIPTION while the engine
  // skips it for its CATEGORY is precisely how a month of payroll filed under
  // "Transfer" can read as both present and absent at once.
  const cashWindow   = _lastNMonths(6).filter(mk => monthsSet.has(mk));
  const incomeMonths = cashWindow.filter(mk =>
    credits.some(t => (t.date || '').startsWith(mk) && _isEarn(t) && _looksLikeIncome(t)));
  const missingIncomeMonths = cashWindow.length - incomeMonths.length;
  const hasIncomeTxns   = incomeMonths.length > 0;

  // Why they're missing, when we can tell: deposits that read as pay but are
  // filed somewhere the engine won't count. That's a fixable filing problem,
  // and naming it beats reporting an absence with no cause.
  const misfiledIncome = credits.filter(t => !_isEarn(t) && _looksLikeIncome(t)).length;
  const hasBudgetIncome = (S.incomes || []).reduce((s, i) => s + i.amount, 0) > 0;

  // Debt data-quality verdicts — read from the profile the debt engine already
  // computed (never recompute; single source). Falls back to neutral if absent.
  const debtV = (S.profile && S.profile.debt) || {};
  const hasDebtCards = (S.debtCards || []).some(c => !c.paidInFull);
  const balancesUnverified = !!debtV.balancesUnverified;
  const balancesStale      = !!debtV.balancesStale;
  const reconAnomaly       = !!debtV.reconAnomaly;

  // Investment freshness — newest investment/holding price update, if any
  const invAccounts = (S.accounts || []).filter(a => /invest|retire|401|ira|brokerage|roth/i.test(a.name || ''));
  const hasInvestments = invAccounts.length > 0 || (S.holdings || []).length > 0;

  const check = (key, label, state, detail) => ({ key, label, state, detail });

  // ── CLAIM: spending analysis ──
  // Gated by: history + categorization. NOT balance verification.
  const spendChecks = [
    check('history', 'Transaction history',
      monthsSpan >= 3 ? 'pass' : monthsSpan >= 1 ? 'warn' : 'fail',
      monthsSpan ? `${monthsSpan} month${monthsSpan !== 1 ? 's' : ''} available` : 'none imported'),
    check('categorization', 'Categorization',
      catRate >= 90 ? 'pass' : catRate >= 60 ? 'warn' : 'fail',
      debits.length ? `${catRate}% categorized` : 'no spending yet'),
  ];
  const spending = {
    claim: 'spending',
    label: 'Spending patterns',
    status: _claimStatus(spendChecks),
    checks: spendChecks,
  };

  // ── CLAIM: cash flow ──
  // Gated by: income identified + spending categorized + history.
  const cashChecks = [
    // Partial coverage is 'warn', never 'fail': 'fail' would make the whole
    // cash-flow claim 'insufficient', and the P0 branch that catches that says
    // "Verify your account balances" — the wrong instruction for missing
    // deposits. 'building' leaves the specific income-records P0 to speak.
    check('income', 'Income identified',
      !hasIncomeTxns ? (hasBudgetIncome ? 'warn' : 'fail')
        : missingIncomeMonths > 0 ? 'warn' : 'pass',
      !hasIncomeTxns ? (hasBudgetIncome ? 'from budget only' : 'not identified')
        : missingIncomeMonths > 0
          ? (misfiledIncome
              ? `no deposits counted in ${missingIncomeMonths} of the last ${cashWindow.length} months — ${misfiledIncome} look like pay but are filed as transfers`
              : `no deposits in ${missingIncomeMonths} of the last ${cashWindow.length} months`)
          : 'from deposits'),
    check('categorization', 'Spending categorized',
      catRate >= 80 ? 'pass' : catRate >= 50 ? 'warn' : 'fail',
      debits.length ? `${catRate}% categorized` : 'no spending yet'),
    check('history', 'History',
      monthsSpan >= 2 ? 'pass' : monthsSpan >= 1 ? 'warn' : 'fail',
      `${monthsSpan} month${monthsSpan !== 1 ? 's' : ''}`),
  ];
  const cashflow = {
    claim: 'cashflow',
    label: 'Cash flow',
    status: _claimStatus(cashChecks),
    checks: cashChecks,
  };

  // ── CLAIM: debt progress ──
  // Gated by: balance verification + reconciliation + history. NOT categorization.
  // Only meaningful if the user actually has debt.
  let debt = null;
  if (hasDebtCards) {
    const debtChecks = [
      check('balances', 'Balance verification',
        balancesUnverified ? 'fail' : balancesStale ? 'warn' : 'pass',
        balancesUnverified ? 'balances unverified' : balancesStale ? 'last update is old' : 'recently verified'),
      check('reconciliation', 'Reconciliation',
        reconAnomaly ? 'warn' : 'pass',
        reconAnomaly ? 'payments not reducing balances' : 'no anomalies'),
      check('history', 'Balance history',
        (debtV.monthsOfHistory || 0) >= 2 ? 'pass' : (debtV.monthsOfHistory || 0) >= 1 ? 'warn' : 'fail',
        `${debtV.monthsOfHistory || 0} month${(debtV.monthsOfHistory || 0) !== 1 ? 's' : ''} recorded`),
    ];
    debt = {
      claim: 'debt',
      label: 'Debt progress',
      status: _claimStatus(debtChecks),
      checks: debtChecks,
    };
  }

  // ── CLAIM: net worth ──
  // Gated by: balance verification + investment freshness.
  const nwChecks = [
    check('balances', 'Account balances',
      balancesUnverified ? 'fail' : balancesStale ? 'warn' : 'pass',
      balancesUnverified ? 'not verified' : balancesStale ? 'need updating' : 'verified'),
  ];
  if (hasInvestments) {
    // Investment values are only as good as their last price update; if we
    // can't tell, warn rather than claim freshness.
    const invFresh = (S.holdings || []).some(h => h.lastPriceAt) ; // best-effort signal
    nwChecks.push(check('investments', 'Investment values',
      invFresh ? 'pass' : 'warn',
      invFresh ? 'recently priced' : 'may be outdated'));
  }
  const networth = {
    claim: 'networth',
    label: 'Net worth',
    status: _claimStatus(nwChecks),
    checks: nwChecks,
  };

  const claims = { spending, cashflow, networth };
  if (debt) claims.debt = debt;

  // Overall record status = the check-engine light. Healthy only when every
  // applicable claim is at least 'building' and none is 'insufficient' on a
  // conclusion-gating claim. Surfaces which claims are limiting.
  const list = Object.values(claims);
  const anyInsufficient = list.some(c => c.status === 'insufficient');
  const anyBuilding     = list.some(c => c.status === 'building');
  const overall = anyInsufficient ? 'building'          // record is still being built
                : anyBuilding     ? 'partial'           // usable, some claims limited
                : 'ready';
  const limiting = list.filter(c => c.status !== 'ready').map(c => c.label);

  return { claims, overall, limiting };
}

// Roll a claim's checks up to a status. A single 'fail' on a gating check drops
// the claim to 'insufficient'; any 'warn' caps it at 'building'; all 'pass' →
// 'ready'. Conservative by design — a claim never reads as more certain than
// its weakest gating check.
function _claimStatus(checks) {
  if (checks.some(c => c.state === 'fail')) return 'insufficient';
  if (checks.some(c => c.state === 'warn')) return 'building';
  return 'ready';
}

// ── Record Status card — the "check-engine light" (Dashboard 2.0) ────────────
// Visibility ladder: quiet when healthy, promoted only when data
// quality changes what Groundwork can responsibly conclude. Never a warning
// panel — it's "Your Financial Record," historian voice, never "Data Problems."
// Answers "how much should I trust what Groundwork shows me?", not "what's wrong
// with my data?" Shows the evidence (checks), never a confidence score.
let _recordStatusExpanded = false;
function _renderRecordStatus() {
  const host = g('dashRecordStatus');
  if (!host) return;
  const conf = _computeClaimConfidence();

  // Nothing imported at all — the dashboard's own empty state handles it;
  // don't stack a record card on a blank dashboard.
  if (!(S.transactions || []).length) { host.innerHTML = ''; return; }

  const gating = Object.values(conf.claims).filter(c => c.status === 'insufficient');
  const limited = Object.values(conf.claims).filter(c => c.status === 'building');

  // Rung 1 — all ready: quiet one-line indicator, click to expand.
  if (conf.overall === 'ready') {
    host.innerHTML = `
      <div onclick="_toggleRecordStatus()" style="display:flex;align-items:center;gap:8px;margin-bottom:16px;cursor:pointer;font-size:12px;color:var(--slate)">
        <span style="color:var(--pine)">\u2713</span>
        <span>Financial Record: up to date</span>
        <span style="color:var(--slate-2);font-size:11px">\u00b7 what Groundwork can assess</span>
      </div>
      ${_recordStatusExpanded ? _recordStatusDetail(conf) : ''}`;
    return;
  }

  // Rung 3/4 — a conclusion is gated: promote, but stay a slim band, not a
  // heavy alert box. Current Priority is the screen's one accented focal point;
  // the record light supports, never competes.
  const promote = gating.length > 0;
  const tone = promote ? 'var(--gold)' : 'var(--slate-2)';
  const headline = promote ? 'Your Financial Record is still being built' : 'Your Financial Record';
  const blurb = promote
    ? `Groundwork can already assess ${_readyList(conf)}. ${_gatedSentence(gating)}`
    : `Groundwork can assess ${_readyList(conf)}. A few areas will sharpen as more is confirmed.`;

  host.innerHTML = `
    <div style="margin-bottom:20px;padding:12px 0 14px;border-top:2px solid ${tone};border-bottom:1px solid var(--steel)">
      <div style="display:flex;align-items:center;justify-content:space-between;gap:12px">
        <div style="display:flex;align-items:center;gap:8px">
          <span style="color:${tone};font-size:12px">${promote ? '\u25c9' : '\u2713'}</span>
          <span style="font-size:13px;font-weight:600;color:var(--ink)">${headline}</span>
        </div>
        <button onclick="_toggleRecordStatus()" style="font-size:11px;background:none;border:none;color:var(--slate-2);cursor:pointer;white-space:nowrap">${_recordStatusExpanded ? 'Hide details' : 'Details'}</button>
      </div>
      <div style="font-size:12px;color:var(--slate);line-height:1.7;margin-top:6px;padding-left:20px">${blurb}</div>
      ${promote ? `<div style="padding-left:20px;margin-top:8px"><button onclick="_recordStatusAction()" style="font-size:12px;background:none;border:1px solid var(--gold-border);color:var(--gold);border-radius:var(--r-sm);padding:5px 12px;cursor:pointer">Verify account balances \u2192</button></div>` : ''}
      ${_recordStatusExpanded ? `<div style="margin-top:12px;padding-left:20px">${_recordStatusDetail(conf)}</div>` : ''}
    </div>`;
}

function _readyList(conf) {
  const ready = Object.values(conf.claims).filter(c => c.status !== 'insufficient').map(c => c.label.toLowerCase());
  if (!ready.length) return 'the basics';
  if (ready.length === 1) return ready[0];
  return ready.slice(0, -1).join(', ') + ' and ' + ready[ready.length - 1];
}

function _gatedSentence(gating) {
  if (!gating.length) return '';
  const names = gating.map(c => c.label.toLowerCase());
  const list = names.length === 1 ? names[0] : names.slice(0, -1).join(', ') + ' and ' + names[names.length - 1];
  return `It can't yet evaluate ${list} — verifying your account balances against your latest statements completes that part of the picture.`;
}

function _recordStatusDetail(conf) {
  // The evidence, per claim — the audit the historian shows on request.
  const iconFor = s => s === 'pass' ? '<span style="color:var(--pine)">\u2713</span>'
    : s === 'warn' ? '<span style="color:var(--gold)">\u26a0</span>'
    : '<span style="color:var(--ember)">\u00b7</span>';
  return `<div style="font-size:12px;line-height:1.9">
    ${Object.values(conf.claims).map(cl => `
      <div style="margin-bottom:6px">
        <span style="font-weight:600;color:var(--ink)">${cl.label}</span>
        <span style="color:var(--slate-2)"> \u2014 ${cl.status}</span>
        <div style="padding-left:14px;color:var(--slate)">
          ${cl.checks.map(ch => `${iconFor(ch.state)} ${ch.label}: ${ch.detail}`).join('<br>')}
        </div>
      </div>`).join('')}
  </div>`;
}

function _toggleRecordStatus() { _recordStatusExpanded = !_recordStatusExpanded; _renderRecordStatus(); }
function _recordStatusAction() { showView('debt'); }

// ── What Changed — the historian's movement section (Dashboard 2.0) ──────────
// Shows movement since last month, and — the Groundwork part — routes each
// change through the confidence gate. A change from a VERIFIED source is
// "Confirmed"; a change Groundwork can't stand behind (unverified balance,
// insufficient history) goes to "Still being evaluated" with what unlocks it.
// Never lets an unconfirmed number read as progress (the $3.7M rule, on the
// dashboard). Silent in its first month — nothing to compare against yet.
function _prevMonthKey(offset = 1) {
  const d = new Date(); d.setDate(1); d.setMonth(d.getMonth() - offset);
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`;
}

// '2026-03' -> 'March'. Month keys are how the dashboard engines address time;
// this is how they say it out loud.
function _monthLabel(monthKey) {
  const [y, m] = (monthKey || '').split('-').map(Number);
  if (!y || !m) return monthKey || '';
  return new Date(y, m - 1, 1).toLocaleDateString('en-US', { month: 'long' });
}

function _computeWhatChanged() {
  // The two most recent COMPLETE months. This card stamps its rows "Confirmed",
  // the highest claim tier, so it may only compare finished months against each
  // other. Measuring a month-to-date against a full prior month reports every
  // category that simply hasn't come around yet as a decrease — and because the
  // list ranks by absolute delta, those not-yet-spent categories crowd out the
  // real movements. A category that hasn't been spent in yet has not changed.
  const thisKey = _prevMonthKey(1);
  const lastKey = _prevMonthKey(2);
  const conf = _computeClaimConfidence();

  const confirmed = [];   // {label, delta, good}
  const evaluating = [];  // {label, reason}
  let spendWindow = null; // set when a spending comparison actually ran

  // ── Spending by category: this month vs last (verified — transactions are
  // ground truth; spending confidence gates whether we characterize trends) ──
  const spendReady = conf.claims.spending && conf.claims.spending.status !== 'insufficient';
  if (spendReady) {
    const cats = [...new Set((S.transactions || [])
      .filter(_isSpend)
      .map(t => _catParentName(t.category) || t.category)
      .filter(Boolean))];
    const moves = cats.map(cat => {
      const now  = _catSpentInMonth(cat, thisKey);
      const prev = _catSpentInMonth(cat, lastKey);
      return { cat, delta: now - prev, prev };
    }).filter(m => m.prev > 0 && Math.abs(m.delta) >= 25)   // material change only
      .sort((a, b) => Math.abs(b.delta) - Math.abs(a.delta))
      .slice(0, 4);
    if (moves.length) spendWindow = { cur: thisKey, prev: lastKey };
    moves.forEach(m => {
      const down = m.delta < 0;   // spending down is good
      confirmed.push({
        label: `${m.cat} spending ${down ? 'decreased' : 'increased'} ${fmt(Math.abs(m.delta))}`,
        good: down,
      });
    });
  }

  // ── Net worth: verified snapshot movement only ──
  const nw = (typeof _nwHistory !== 'undefined' && _nwHistory) ? _nwHistory : [];
  if (nw.length >= 2) {
    const a = parseFloat(nw[nw.length - 2].net_worth || 0);
    const b = parseFloat(nw[nw.length - 1].net_worth || 0);
    if (Math.abs(b - a) >= 1) {
      // Net worth is only trustworthy if balances are verified — gate it.
      if (conf.claims.networth && conf.claims.networth.status === 'insufficient') {
        evaluating.push({ label: 'Net worth', reason: 'account balances need verifying before this can be confirmed' });
      } else {
        const up = b > a;
        confirmed.push({ label: `Net worth ${up ? 'increased' : 'decreased'} ${fmt(Math.abs(b - a))}`, good: up });
      }
    }
  }

  // ── Debt: only if the debt claim can be trusted; else it's evaluating ──
  if (conf.claims.debt) {
    if (conf.claims.debt.status === 'insufficient') {
      evaluating.push({ label: 'Debt progress', reason: 'balances need verifying against your statements' });
    } else {
      const recon = (S.profile && S.profile.debt && S.profile.debt.reconciliation) || null;
      if (recon && Math.abs(recon.balanceReduction) >= 1) {
        const down = recon.balanceReduction > 0;
        confirmed.push({ label: `Debt ${down ? 'decreased' : 'increased'} ${fmt(Math.abs(recon.balanceReduction))}`, good: down });
      }
    }
  }

  return { confirmed, evaluating, spendWindow,
           hasComparison: nw.length >= 2 || _monthHasData(lastKey) };
}

function _monthHasData(monthKey) {
  return (S.transactions || []).some(t => (t.date || '').startsWith(monthKey));
}

// ── Current Priority — the ranked stability engine (Dashboard 2.0) ───────────
// Business rule: rank by STABILITY IMPACT, not financial size — "what
// condition, if unresolved, creates the greatest risk to the user's ability to
// make progress?" Order: P0 data integrity → P1 instability → P2 immediate risk
// → P3 foundation → P4 optimization → P5 growth. Two overrides on top:
//   - User goal (from onboarding intent) can re-weight what gets nagged.
//   - Conservative tie-breaker: if nothing rises to a real priority, say so —
//     never invent urgency.
// Every priority is a COMPUTED VERDICT: it only appears when Groundwork can
// state WHY in the user's own numbers. If it can't calculate why, it doesn't
// recommend it. This is the claim hierarchy's highest tier (Recommendation).

function _computeCurrentPriority() {
  const conf = _computeClaimConfidence();

  // ── P0: DATA INTEGRITY — before any financial advice, the record must be
  // trustworthy. Reads the confidence engine directly (the unification: P0's
  // input IS claim confidence). Any conclusion-gating claim at 'insufficient'
  // means we cannot responsibly advise until it's resolved. ──
  const insufficientClaims = Object.values(conf.claims).filter(c => c.status === 'insufficient');
  if (insufficientClaims.length) {
    const names = insufficientClaims.map(c => c.label.toLowerCase());
    return {
      tier: 0,
      title: 'Verify your account balances',
      why: [
        `Groundwork can't yet confirm ${names.join(' or ')} because balances haven't been checked against your statements.`,
        'Until they are, any read on progress could be built on numbers that don\u2019t match reality.',
      ],
      actionLabel: 'Review balances \u2192',
      action: "showView('debt')",
    };
  }

  // ── Gather stability signals (all computed, all from real data) ──
  const income = _householdTotalIncome ? _householdTotalIncome() : (S.incomes || []).reduce((s, i) => s + i.amount, 0);
  const savings = parseFloat(S.netWorth?.savings) || 0;
  const hasDebt = (S.debtCards || []).some(c => !c.paidInFull && _cardBal(c) > 0);

  // Monthly cash flow over the last 6 months: income months vs spend months.
  //
  // A month only earns a cash-flow VERDICT if its income record is complete.
  // "No income transactions recorded" is not the same fact as "income was
  // zero", but subtracting spend from a blank month silently converts the
  // first into the second — and manufactures a shortfall the size of the
  // whole month's spending. That is exactly the failure this module's own
  // rule forbids: if we can't calculate WHY, we don't recommend.
  //
  // The completeness test is the household income profile the user set up
  // (S.incomes). Recorded income far below it means the ledger is missing
  // deposits, not that the household stopped being paid. The floor is
  // deliberately low — a genuinely bad income month is real signal and must
  // still reach P1 — so it only fires when income is essentially absent.
  const INCOMPLETE_INCOME_FLOOR = 0.35;
  const cashMonths = [];
  const incompleteMonths = [];
  for (let i = 1; i <= 6; i++) {
    const mk = _prevMonthKey(i);
    const spent = (S.transactions || [])
      .filter(t => _isSpend(t) && (t.date || '').startsWith(mk))
      .reduce((s, t) => s + t.amount, 0);
    const earned = (S.transactions || [])
      .filter(t => _isEarn(t) && (t.date || '').startsWith(mk))
      .reduce((s, t) => s + t.amount, 0);
    if (!(spent > 0 || earned > 0)) continue;
    // Only usable as a check when the user actually has an income profile;
    // without one we have nothing to measure completeness against and fall
    // back to taking the ledger at face value.
    if (income > 0 && earned < income * INCOMPLETE_INCOME_FLOOR) {
      incompleteMonths.push({ mk, earned, spent });
      continue;
    }
    cashMonths.push({ mk, net: earned - spent, earned, spent });
  }

  // ── P0 (continued): INCOMPLETE INCOME RECORD — same tier as unverified
  // balances, and for the same reason: a cash-flow read built on months with
  // no deposits in them would be advice about an artefact of the import, not
  // about the household. Name the months so the fix is obvious. ──
  if (incompleteMonths.length && incompleteMonths.length > cashMonths.length) {
    const names = incompleteMonths.map(m => _monthLabel(m.mk)).join(', ');
    return {
      tier: 0,
      title: 'Check your income records',
      why: [
        `${incompleteMonths.length} of the last 6 months show little or no income — ${names} — against a household income of ${fmt(income)}/mo.`,
        'Deposits are most likely missing or filed under Transfer. Groundwork won’t read cash flow until they’re in.',
      ],
      actionLabel: 'Review transactions →',
      action: "showView('ledger')",
    };
  }

  const negativeMonths = cashMonths.filter(m => m.net < 0);
  const avgShortfall = negativeMonths.length
    ? Math.round(negativeMonths.reduce((s, m) => s + Math.abs(m.net), 0) / negativeMonths.length)
    : 0;

  const monthlyExpenses = cashMonths.length
    ? Math.round(cashMonths.reduce((s, m) => s + m.spent, 0) / cashMonths.length)
    : 0;
  const bufferDays = monthlyExpenses > 0 ? Math.round((savings / monthlyExpenses) * 30) : 0;

  // ── P1: FINANCIAL INSTABILITY — cash flow negative in a majority of months.
  // The foundation is unstable; optimization is moot until it's fixed. ──
  if (cashMonths.length >= 3 && negativeMonths.length >= Math.ceil(cashMonths.length / 2)) {
    return {
      tier: 1,
      title: 'Build monthly cash-flow stability',
      why: [
        `Spending exceeded income in ${negativeMonths.length} of the last ${cashMonths.length} months.`,
        avgShortfall ? `Average monthly shortfall: ${fmt(avgShortfall)}.` : '',
      ].filter(Boolean),
      actionLabel: 'Review spending \u2192',
      action: "showView('budget')",
    };
  }

  // ── P2: IMMEDIATE RISK — no emergency buffer AND carrying debt. One bad
  // month forces more borrowing; the situation compounds. ──
  if (!calcHasEmergencyBuffer() && hasDebt) {
    return {
      tier: 2,
      title: 'Start an emergency buffer',
      why: [
        savings > 0 ? `Emergency savings: ${fmt(savings)} \u2014 about ${bufferDays} days of expenses.` : 'No emergency savings tracked yet.',
        'Without a buffer, an unexpected expense usually means more debt.',
      ],
      actionLabel: 'Set up savings \u2192',
      action: "showView('networth')",
    };
  }

  // ── P3: FOUNDATION — buffer exists but thin (< ~1 month of expenses). ──
  if (calcHasEmergencyBuffer() && monthlyExpenses > 0 && savings < monthlyExpenses) {
    return {
      tier: 3,
      title: 'Grow your emergency fund',
      why: [
        `You have ${fmt(savings)} saved \u2014 about ${bufferDays} days of expenses.`,
        `One month of expenses (${fmt(monthlyExpenses)}) is a solid next target.`,
      ],
      actionLabel: 'View savings \u2192',
      action: "showView('networth')",
    };
  }

  // ── P4: OPTIMIZATION — stable foundation; accelerate debt payoff. ──
  if (hasDebt && calcHasEmergencyBuffer()) {
    const debt = (S.profile && S.profile.debt) || {};
    return {
      tier: 4,
      title: 'Accelerate your debt payoff',
      why: [
        'Your foundation is stable \u2014 buffer in place, cash flow positive.',
        debt.nextMilestone ? debt.nextMilestone : 'Extra toward your highest-rate balance shortens the timeline most.',
      ],
      actionLabel: 'Debt plan \u2192',
      action: "showView('debt')",
    };
  }

  // ── P5: GROWTH — no debt, buffer in place, positive cash flow. ──
  if (!hasDebt && calcHasEmergencyBuffer()) {
    return {
      tier: 5,
      title: 'Continue building wealth',
      why: [
        'Cash flow is positive, no active debt, and your buffer is in place.',
        'This is the stage to grow savings and long-term investments.',
      ],
      actionLabel: 'View goals \u2192',
      action: "showView('goals')",
    };
  }

  // ── Conservative tie-breaker: nothing rose to a real priority. Say so —
  // do NOT invent urgency. This is "insufficient confidence narrows the claim"
  // applied to prioritization. ──
  return {
    tier: null,
    title: 'No single priority stands out',
    why: [
      'Your finances are moving in a reasonable direction and nothing requires urgent attention right now.',
      'Keep doing what you\u2019re doing \u2014 Groundwork will flag anything that shifts.',
    ],
    actionLabel: null,
    action: null,
  };
}

function _renderCurrentPriority() {
  const host = g('dashCurrentPriority');
  if (!host) return;
  if (!(S.transactions || []).length && !(S.debtCards || []).length) { host.innerHTML = ''; return; }

  const p = _computeCurrentPriority();
  const isCalm = p.tier === null;
  const accent = p.tier === 0 ? 'var(--gold)'
    : p.tier === 1 ? 'var(--ember)'
    : p.tier === 2 ? 'var(--gold)'
    : 'var(--pine)';

  host.innerHTML = `
    <div class="card mb-5" style="padding:18px 20px;border-left:3px solid ${accent}">
      <div class="card-label" style="margin-bottom:6px">${isCalm ? 'Where you stand' : 'Current priority'}</div>
      <div style="font-family:'Playfair Display',Georgia,serif;font-style:italic;font-size:19px;color:var(--ink);margin-bottom:8px">${esc(p.title)}</div>
      <div style="font-size:13px;color:var(--slate);line-height:1.7">
        ${p.why.map(w => `<div style="padding:1px 0">${esc(w)}</div>`).join('')}
      </div>
      ${p.actionLabel ? `<button onclick="${p.action}" style="margin-top:12px;font-size:12px;font-weight:600;background:${accent};color:#fff;border:none;border-radius:var(--r-sm);padding:8px 16px;cursor:pointer">${esc(p.actionLabel)}</button>` : ''}
    </div>`;
}

function _renderWhatChanged() {
  const host = g('dashWhatChanged');
  if (!host) return;
  const wc = _computeWhatChanged();

  // First month / nothing to compare — stay silent rather than invent movement.
  if (!wc.hasComparison || (!wc.confirmed.length && !wc.evaluating.length)) {
    host.innerHTML = '';
    return;
  }

  const row = (item) => `
    <div style="display:flex;align-items:center;gap:8px;padding:6px 0;font-size:13px;color:var(--ink)">
      <span style="color:${item.good ? 'var(--pine)' : 'var(--gold)'};flex-shrink:0">${item.good ? '\u2713' : '\u2191'}</span>
      <span>${esc(item.label)}</span>
    </div>`;

  host.innerHTML = `
    <div style="margin-bottom:24px">
      <div class="card-label" style="margin-bottom:12px">What changed since last month</div>
      ${wc.confirmed.length ? `
        <div style="font-size:10px;font-weight:600;text-transform:uppercase;letter-spacing:.08em;color:var(--pine);margin-bottom:4px">Confirmed${wc.spendWindow ? ` · ${esc(_monthLabel(wc.spendWindow.cur))} vs ${esc(_monthLabel(wc.spendWindow.prev))}` : ''}</div>
        ${wc.confirmed.map(row).join('')}` : ''}
      ${wc.evaluating.length ? `
        <div style="font-size:10px;font-weight:600;text-transform:uppercase;letter-spacing:.08em;color:var(--slate-2);margin:${wc.confirmed.length ? '14px' : '0'} 0 4px">Still being evaluated</div>
        ${wc.evaluating.map(e => `
          <div style="font-size:12px;color:var(--slate);line-height:1.6;padding:4px 0">
            <span style="color:var(--ink);font-weight:500">${esc(e.label)}</span> — ${esc(e.reason)}.
          </div>`).join('')}` : ''}
    </div>`;
}



// ── Financial Health Snapshot (Phase 1, onboarding) ──────────────────────────
// The first thing a user sees after their first import. It does NOT collect
// information — it demonstrates reasoning, per the onboarding contract
// (GROUNDWORK_PHILOSOPHY.md → Onboarding): what I can determine / what I can't
// determine yet / confidence. Every line is assembled from a verdict that
// already exists (_calcSpendingIntelligence, _calcIncomeIntelligence,
// _calcDebtIntelligence, the data-quality trio) — the Snapshot computes
// nothing new, it just presents the evidence the app already has. Renders
// through _rcRenderAIPanel like every other narrative surface.

function _computeSnapshot() {
  const txns = S.transactions || [];
  const debits  = txns.filter(t => t.type === 'debit'  && t.amount > 0);
  const credits = txns.filter(t => t.type === 'credit' && t.amount > 0);

  // History span (months touched by data)
  const monthsSet = new Set(txns.map(t => (t.date || '').slice(0, 7)).filter(Boolean));
  const monthsSpan = monthsSet.size;

  // Categorization rate — how much Groundwork placed on its own
  const isUncat = c => !c || c === 'Uncategorized' || c === 'Other' || c === 'uncategorized';
  const catRate = debits.length
    ? Math.round((debits.filter(t => !isUncat(t.category)).length / debits.length) * 100)
    : 0;

  const spend  = _calcSpendingIntelligence();
  const income = _calcIncomeIntelligence();
  const debt   = _calcDebtIntelligence();

  // Income cadence label from the existing detector
  const cadenceLabel = {
    weekly:     'weekly',
    biweekly:   'every two weeks',
    semimonthly:'twice a month',
    monthly:    'monthly',
    irregular:  'on an irregular schedule',
  }[income.payFrequency || S.lifeStage?.payFrequency] || null;

  const topCats = (spend.topCategories || []).slice(0, 5);
  const recurring = (spend.subscriptionCandidates || []);
  const hasIncome = credits.length > 0 && income.avg6 > 0;

  // ── Section 1: what I can determine (only computed truths) ──
  const canDetermine = [];
  if (cadenceLabel && hasIncome)
    canDetermine.push(`Income appears to arrive ${cadenceLabel}, averaging ${fmt(income.avg6 || income.effectiveAvg)}/month.`);
  else if (hasIncome)
    canDetermine.push(`Income detected, averaging ${fmt(income.avg6 || income.effectiveAvg)}/month.`);
  if (debits.length)
    canDetermine.push(`${catRate}% of ${debits.length.toLocaleString()} transactions were categorized automatically.`);
  if (recurring.length)
    canDetermine.push(`${recurring.length} recurring monthly charge${recurring.length !== 1 ? 's' : ''} identified.`);
  if (topCats.length)
    canDetermine.push(`Largest spending: ${topCats.map(c => c.category).slice(0, 3).join(', ')}.`);
  if (monthsSpan)
    canDetermine.push(`Spending history covers ${monthsSpan} month${monthsSpan !== 1 ? 's' : ''}.`);

  // ── Section 2: what I can't determine yet (the honest gaps) ──
  const cantYet = [];
  if (debt.balancesUnverified || !debt.hasHistory)
    cantYet.push('Current account balances haven\u2019t been verified against your statements.');
  if (!S.debtCards || !S.debtCards.length)
    cantYet.push('No debts have been entered, so payoff timing and net worth can\u2019t be estimated yet.');
  if (!(S.accounts || []).some(a => /invest|retire|401|ira|brokerage/i.test(a.name || '')))
    cantYet.push('This import doesn\u2019t appear to include investment or retirement accounts.');
  if (monthsSpan < 3)
    cantYet.push('Spending trends need a few months of history before they\u2019re reliable — this is a start.');

  // ── Section 3: confidence (tied to how much data backs each read) ──
  const confidence = [];
  if (monthsSpan >= 3)      confidence.push('High confidence in spending patterns.');
  else if (debits.length)  confidence.push('Early read on spending — sharpens with more history.');
  if (hasIncome)           confidence.push(income.isVariable ? 'Moderate confidence in income (it varies month to month).' : 'High confidence in income cadence.');
  confidence.push('Net worth can\u2019t be estimated until balances are verified.');

  return {
    canDetermine, cantYet, confidence,
    counts: {
      transactions: txns.length,
      accounts: new Set(txns.map(t => t.account).filter(Boolean)).size || (S.accounts || []).length,
      months: monthsSpan,
    },
    _facts: { catRate, topCats, recurring, hasIncome, cadenceLabel, monthsSpan, income, debt },
  };
}

// Render the Snapshot through the unified panel. Called after the first import.
function _renderFinancialSnapshot(container) {
  const target = container || g('rcReportBody');
  if (!target) return;
  const snap = _computeSnapshot();

  // The evidence, shown as the report body itself — sections are structured
  // HTML (not AI-authored), so they can never drift from the computation.
  const section = (title, items, tone) => items.length ? `
    <div style="margin-bottom:16px">
      <div style="font-size:10px;font-weight:600;text-transform:uppercase;letter-spacing:.08em;color:${tone};margin-bottom:8px">${title}</div>
      ${items.map(t => `<div style="font-size:13px;color:var(--ink);line-height:1.7;padding-left:16px;position:relative">
        <span style="position:absolute;left:0;color:${tone}">${tone === 'var(--pine)' ? '\u2713' : '\u00b7'}</span>${esc(t)}</div>`).join('')}
    </div>` : '';

  const bodyHtml = `
    <div style="margin-bottom:20px">
      <h2 style="font-family:'Playfair Display',Georgia,serif;font-style:italic;font-size:22px;font-weight:600;color:var(--ink);margin-bottom:4px">Your Financial Snapshot</h2>
      <div style="font-size:12px;color:var(--slate)">${snap.counts.transactions.toLocaleString()} transactions${snap.counts.months ? ` \u00b7 ${snap.counts.months} months of history` : ''} \u00b7 already enough to start helping.</div>
    </div>
    ${section('What I can determine', snap.canDetermine, 'var(--pine)')}
    ${section('What I can\u2019t determine yet', snap.cantYet, 'var(--slate-2)')}
    ${section('Confidence', snap.confidence, 'var(--slate-2)')}
    <div id="snapshotAI"></div>`;

  target.innerHTML = bodyHtml;

  // The AI narration is OPTIONAL sugar on top of the structured evidence
  // above — it never replaces it. Same panel, same voice, same disclosure.
  // No AI key configured — the norm for a brand-new user on first import.
  // The structured evidence above is complete and useful on its own; the AI
  // narration is the one thing missing. Say so honestly and offer it in one
  // tap (optional, never a gate — a wall in front of the car breaks the whole
  // onboarding premise). Same pattern as the investment-tracker rewrite:
  // explain the value, make it skippable.
  if (!aiEnabled()) {
    const aiSlot = g('snapshotAI');
    if (aiSlot) {
      // Two distinct reasons AI isn't on, two distinct fixes — never assume
      // the cloud-key case when the real gap is just the toggle being off
      // (the default local-mode state needs no key at all).
      const toggledOff = S.prefs?.aiEnabled === false;
      const msg = 'Everything above is computed on your own machine. Groundwork can also add a written read of what it means — turn AI on in Settings to add this (free, and it runs on your own computer).';
      const btnLabel = 'Turn on AI';
      aiSlot.innerHTML = `
        <div style="margin-top:4px;padding:12px 14px;background:var(--mist);border:1px solid var(--steel);border-radius:var(--r-sm)">
          <div style="font-size:12px;color:var(--ink);line-height:1.7">${msg}</div>
          <button onclick="_snapshotOpenAISetup()" style="margin-top:8px;font-size:12px;background:none;border:1px solid var(--pine-border);border-radius:var(--r-sm);padding:5px 12px;cursor:pointer;color:var(--pine)">${btnLabel}</button>
        </div>`;
    }
    _snapshotShowContinue(target);
    return;
  }

  const dataLines = [
    ...snap.canDetermine,
    ...snap.cantYet.map(l => `Gap: ${l}`),
  ];
  const buildPrompt = (profileCtx) => [
    profileCtx || '',
    'FIRST-IMPORT SNAPSHOT — the user just imported transactions for the first time and has done nothing else.',
    '',
    'What the app computed:',
    dataLines.join('\n'),
    '',
    'Write 2 short paragraphs that make the user feel Groundwork already understands their finances. Lead with the single most useful thing it can already see. Name one real number from above. Then, in one plain sentence, invite them to keep building the picture (verifying balances or adding debts) — framed as completing the record, never as a task they failed to do. No greeting, no headers, no bullets. Do not state any number or fact not listed above.',
  ].filter(Boolean).join('\n');

  _rcAnalyzeWithAI('snapshot', dataLines, buildPrompt, g('snapshotAI'));
  _snapshotShowContinue(target);
}

// From the Snapshot's "add a key" nudge → Settings. Onboarding stays
// dismissible; if they add a key and return, re-opening the Snapshot (or any
// report) will now narrate. We don't block the flow waiting for them.
function _snapshotOpenAISetup() {
  g('onboardingOverlay')?.classList.add('hidden');
  g('obSnapshotHost')?.classList.add('hidden');
  API.patch('/api/settings', { onboarding_complete: 'true' }).catch(_gwErr('_snapshotOpenAISetup'));
  showView('settings');
  showToast(
    'Turn AI on here',
    'Then reopen any report for the written analysis', 'info'
  );
}

function _snapshotShowContinue(target) {
  // One forward action — the museum principle: one insight, one next step.
  if (g('snapshotContinue')) return;
  const btn = document.createElement('div');
  btn.id = 'snapshotContinue';
  btn.style.cssText = 'margin-top:20px;display:flex;gap:10px;align-items:center';
  btn.innerHTML = `
    <button onclick="_onboardingAdvance('income')" style="font-size:13px;font-weight:600;background:var(--pine);color:#fff;border:none;border-radius:var(--r-sm);padding:9px 18px;cursor:pointer">Keep building this picture \u2192</button>
    <button onclick="_onboardingDismiss()" style="font-size:12px;background:none;border:none;color:var(--slate-2);cursor:pointer">I\u2019ll explore on my own</button>`;
  target.appendChild(btn);
}

async function _rcRenderDistanceTraveled() {
  const body = g('rcReportBody');
  if (!body) return;

  if (!Object.keys(_debtHistoryCache).length) {
    body.innerHTML = `<div style="font-size:13px;color:var(--slate);display:flex;align-items:center;gap:8px"><div class="spinner"></div>Loading…</div>`;
    await _budgetLoadDebtHistory().catch(_gwErr('_rcRenderDistanceTraveled'));
  }

  // Net worth window — fetched directly so this report never triggers the
  // Net Worth page's chart renderers as a side effect.
  let nwFirst = null, nwLast = null;
  try {
    const res  = await API.get('/api/net-worth/snapshots?months=24');
    const rows = (Array.isArray(res) ? res : (res.data || [])).filter(r => !r.without_figures);   // item 38
    if (rows.length >= 2) { nwFirst = rows[0]; nwLast = rows[rows.length-1]; }
  } catch(e) { /* net worth section simply doesn't render */ }

  // Recurring-payment compliance (Debt Reconciliation Phase F) — same
  // fetch-ahead-of-render shape as the net worth window above. Aggregates
  // every recurring pattern's compliance (server.py :: get_payment_compliance)
  // across all cards; only rendered/narrated when at least one confirmed
  // payment exists to report on.
  let paymentCompliance = null;
  try {
    const results = await Promise.all(
      S.debtCards.filter(c => c._dbId).map(c =>
        API.get(`/api/debt/${c._dbId}/recurring`).catch(() => []))
    );
    let onTime = 0, under = 0, over = 0, total = 0, varianceWeighted = 0;
    for (const rows of results) {
      for (const r of (rows || [])) {
        const comp = r.compliance;
        if (comp && comp.total > 0) {
          onTime += comp.on_time; under += comp.under_plan; over += comp.over_plan;
          total  += comp.total;
          varianceWeighted += comp.avg_variance_pct * comp.total;
        }
      }
    }
    if (total > 0) {
      paymentCompliance = {
        total, onTime, under, over,
        avgVariancePct: Math.round((varianceWeighted / total) * 10) / 10,
      };
    }
  } catch (e) { _gwErr('_rcRenderDistanceTraveled:compliance')(e); }

  // Phase H2 Feature 5 (adaptive learning — payoff confidence scoring):
  // thin read of Phase H1's get_payment_compliance_confidence per account.
  // Averaged (unweighted) across accounts that have a real score — blending
  // confidence across unrelated debts has no precise meaning, so this is
  // presented as a simple average, not a single deterministic figure.
  let payoffConfidence = null;
  try {
    const confResults = await Promise.all(
      S.debtCards.filter(c => c._dbId).map(c =>
        API.get(`/api/debt/${c._dbId}/confidence`).catch(() => ({confidence_pct: null})))
    );
    const scored = confResults.filter(r => r.confidence_pct !== null);
    if (scored.length) {
      payoffConfidence = Math.round(scored.reduce((s,r) => s + r.confidence_pct, 0) / scored.length);
    }
  } catch (e) { _gwErr('_rcRenderDistanceTraveled:confidence')(e); }

  const d = _dtComputeDistance();
  d.paymentCompliance = paymentCompliance;
  d.payoffConfidence = payoffConfidence;

  if (!d.perCard.length) {
    body.innerHTML = `
      <div style="margin-bottom:24px">
        <h2 style="font-family:'Playfair Display',Georgia,serif;font-style:italic;font-size:22px;font-weight:600;color:var(--ink);margin-bottom:4px">Distance Traveled</h2>
        <div style="font-size:13px;color:var(--slate);line-height:1.7">This report measures the ground you've covered — principal paid down, debts retired, monthly cash flow freed. Add your debt accounts and it starts recording from your first balance.</div>
      </div>
      <button onclick="showView('debt')" style="font-size:12px;background:none;border:1px solid var(--steel);border-radius:var(--r-sm);padding:5px 12px;cursor:pointer;color:var(--ink)">Set up debt accounts</button>`;
    return;
  }

  const sinceLabel = d.earliestMonth ? `Since ${_dtMonthLabel(d.earliestMonth)}` : 'From your starting balances';
  const monthsInWindow = d.earliestMonth
    ? Math.max(1, Math.round((new Date() - _dtDateFromMonth(d.earliestMonth, 0)) / (1000*60*60*24*30.44)))
    : null;

  // Hero stat cells — only stats that exist render at all
  const hero = [];
  hero.push(`<div class="card" style="padding:16px">
    <div style="font-size:10px;text-transform:uppercase;letter-spacing:.08em;color:var(--slate-2);margin-bottom:4px">Ground covered</div>
    <div style="font-family:var(--font-mono);font-size:24px;font-weight:600;color:var(--pine)">${fmt(d.totalCovered)}</div>
    <div style="font-size:11px;color:var(--slate);margin-top:2px">${d.pctCovered}% of ${fmt(d.totalStart)} paid down</div>
  </div>`);
  if (d.retired.length) hero.push(`<div class="card" style="padding:16px">
    <div style="font-size:10px;text-transform:uppercase;letter-spacing:.08em;color:var(--slate-2);margin-bottom:4px">Debts retired</div>
    <div style="font-family:var(--font-mono);font-size:24px;font-weight:600;color:var(--pine)">${d.retired.length}</div>
    <div style="font-size:11px;color:var(--slate);margin-top:2px">${esc(d.retired.map(x=>x.card.name||'Card').join(', '))}</div>
  </div>`);
  if (d.freedMonthly > 0) hero.push(`<div class="card" style="padding:16px;border-color:var(--pine-border);background:var(--pine-bg)">
    <div style="font-size:10px;text-transform:uppercase;letter-spacing:.08em;color:var(--pine);margin-bottom:4px">Freed every month</div>
    <div style="font-family:var(--font-mono);font-size:24px;font-weight:600;color:var(--pine)">+${fmt(d.freedMonthly)}</div>
    <div style="font-size:11px;color:var(--pine);opacity:.85;margin-top:2px">cash that used to be claimed by debt</div>
  </div>`);
  if (d.monthsPulled) hero.push(`<div class="card" style="padding:16px">
    <div style="font-size:10px;text-transform:uppercase;letter-spacing:.08em;color:var(--slate-2);margin-bottom:4px">Date pulled closer</div>
    <div style="font-family:var(--font-mono);font-size:24px;font-weight:600;color:var(--pine)">${d.monthsPulled} mo</div>
    <div style="font-size:11px;color:var(--slate);margin-top:2px">${d.allClear ? 'debt-free today' : `now ${_dtDateShort(d.dateNow)}, was heading to ${_dtDateShort(d.dateThen)}`}</div>
  </div>`);
  if (d.interestNeverCharged) hero.push(`<div class="card" style="padding:16px">
    <div style="font-size:10px;text-transform:uppercase;letter-spacing:.08em;color:var(--slate-2);margin-bottom:4px">Interest never to be charged</div>
    <div style="font-family:var(--font-mono);font-size:24px;font-weight:600;color:var(--pine)">${fmt(d.interestNeverCharged)}</div>
    <div style="font-size:11px;color:var(--slate);margin-top:2px">vs the path you were on ${d.earliestMonth ? 'in ' + _dtMonthLabel(d.earliestMonth) : 'at the start'}</div>
  </div>`);
  if (d.paymentCompliance) hero.push(`<div class="card" style="padding:16px">
    <div style="font-size:10px;text-transform:uppercase;letter-spacing:.08em;color:var(--slate-2);margin-bottom:4px">Payments on schedule</div>
    <div style="font-family:var(--font-mono);font-size:24px;font-weight:600;color:var(--ink)">${d.paymentCompliance.onTime}/${d.paymentCompliance.total}</div>
    <div style="font-size:11px;color:var(--slate);margin-top:2px">±5% of plan · avg variance ${d.paymentCompliance.avgVariancePct > 0 ? '+' : ''}${d.paymentCompliance.avgVariancePct}%</div>
  </div>`);
  if (d.payoffConfidence != null) hero.push(`<div class="card" style="padding:16px">
    <div style="font-size:10px;text-transform:uppercase;letter-spacing:.08em;color:var(--slate-2);margin-bottom:4px">Payoff confidence</div>
    <div style="font-family:var(--font-mono);font-size:24px;font-weight:600;color:${d.payoffConfidence>=70?'var(--pine)':d.payoffConfidence>=40?'var(--gold)':'var(--ember)'}">${d.payoffConfidence}%</div>
    <div style="font-size:11px;color:var(--slate);margin-top:2px">from your real payment reliability</div>
  </div>`);

  // Per-debt distance rows — retired cards get the struck-through display,
  // same visual invariant as the Debt page (display only, data untouched).
  const rows = d.perCard
    .slice().sort((a,b) => b.covered - a.covered)
    .map(x => {
      const paid = x.card.paidInFull;
      const askStart = paid && !x.startKnown;
      const pct  = x.startBal > 0 ? Math.min(100, Math.round((x.covered / x.startBal) * 100)) : 0;
      const spark = x.history.length >= 2 ? _debtCardSparkline(x.card, 120, 28) : '';
      return `<div style="display:flex;align-items:center;gap:14px;padding:12px 0;border-bottom:1px solid var(--steel)">
        <div style="flex:1;min-width:0">
          <div style="font-size:13px;font-weight:600;color:var(--ink);overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${esc(x.card.name||'Card')}
            ${paid ? `<span style="font-size:10px;font-weight:600;color:var(--pine);margin-left:6px">Paid in full</span>` : ''}
          </div>
          ${askStart
            ? `<div style="font-size:11px;color:var(--slate);margin-top:4px;display:flex;align-items:center;gap:6px;flex-wrap:wrap">
                 <span>You paid this off before Groundwork saw its balance · started at</span>
                 <input type="number" min="1" step="0.01" placeholder="e.g. 4200"
                   style="width:84px;font-family:var(--font-mono);font-size:11px;padding:3px 6px;border:1px solid var(--steel);border-radius:var(--r-sm);text-align:right"
                   onchange="_dtSetStartBal(${x.card.id}, this.value)">
                 <span style="color:var(--slate-2)">so this win counts</span>
               </div>`
            : `<div style="font-size:11px;color:var(--slate);font-family:var(--font-mono);margin-top:2px">
                 ${paid ? `<s style="color:var(--slate-2);opacity:.65">${fmt(x.startBal)}</s> → $0` : `${fmt(x.startBal)} → ${fmt(x.nowBal)}`}
               </div>`}
        </div>
        ${spark ? `<div style="flex-shrink:0">${spark}</div>` : ''}
        <div style="text-align:right;flex-shrink:0;min-width:90px">
          ${askStart
            ? `<div style="font-size:10px;color:var(--slate-2)">not counted yet</div>`
            : `<div style="font-family:var(--font-mono);font-size:13px;font-weight:600;color:var(--pine)">${x.covered > 0 ? fmt(x.covered) : '—'}</div>
               <div style="font-size:10px;color:var(--slate-2)">${pct}% covered</div>`}
        </div>
      </div>`;
    }).join('');

  // What the freed cash unlocks — a projection, framed as one, from the same
  // avalanche engine everything else uses.
  let unlockSection = '';
  if (d.freedMonthly > 0 && !d.allClear) {
    const base = _simulatePayoff(0);
    const withRedirect = _simulatePayoff(d.freedMonthly);
    if (base && withRedirect && withRedirect.months < base.months) {
      const sooner = base.months - withRedirect.months;
      const dNow = new Date(); dNow.setMonth(dNow.getMonth() + base.months);
      const dRed = new Date(); dRed.setMonth(dRed.getMonth() + withRedirect.months);
      unlockSection = `<div class="card" style="padding:16px;margin-bottom:24px;border-color:var(--pine-border)">
        <div style="font-size:10px;font-weight:600;text-transform:uppercase;letter-spacing:.08em;color:var(--pine);margin-bottom:8px">What the freed ${fmt(d.freedMonthly)}/mo unlocks</div>
        <div style="font-size:13px;color:var(--ink);line-height:1.7">Routed at your remaining debt, it pulls your debt-free date <strong style="color:var(--pine)">${sooner} month${sooner!==1?'s':''} closer</strong> — ${_dtDateShort(dRed)} instead of ${_dtDateShort(dNow)}.</div>
      </div>`;
    }
  }

  // Net worth movement over the same window
  let nwSection = '';
  if (nwFirst && nwLast && nwLast.net_worth !== nwFirst.net_worth) {
    const delta = nwLast.net_worth - nwFirst.net_worth;
    nwSection = `<div style="font-size:12px;color:var(--slate);margin-bottom:24px;padding:10px 14px;background:var(--mist);border-radius:var(--r-sm);line-height:1.7">
      Net worth over the same stretch: <span style="font-family:var(--font-mono);color:${delta>=0?'var(--pine)':'var(--ember)'}">${delta>=0?'+':'−'}${fmt(Math.abs(delta))}</span>
      (${fmt(nwFirst.net_worth)} → ${fmt(nwLast.net_worth)})
    </div>`;
  }

  const sparseNote = (!d.earliestMonth) ? `<div style="font-size:12px;color:var(--slate);padding:10px 14px;background:var(--mist);border-radius:var(--r-sm);margin-bottom:24px;line-height:1.7">
    Measured from your starting balances. Groundwork records a balance snapshot each month — this report deepens as that history builds, adding your date movement and interest avoided.</div>` : '';

  body.innerHTML = `
    <div style="margin-bottom:24px">
      <h2 style="font-family:'Playfair Display',Georgia,serif;font-style:italic;font-size:22px;font-weight:600;color:var(--ink);margin-bottom:4px">Distance Traveled</h2>
      <div style="font-size:13px;color:var(--slate)">${sinceLabel}${monthsInWindow ? ` · ${monthsInWindow} month${monthsInWindow!==1?'s':''}` : ''} · the ground you've covered, not what's left.</div>
    </div>
    ${sparseNote}
    <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:12px;margin-bottom:24px">${hero.join('')}</div>
    ${unlockSection}
    <div style="margin-bottom:8px;font-size:10px;font-weight:600;text-transform:uppercase;letter-spacing:.08em;color:var(--slate-2)">Per debt</div>
    <div style="margin-bottom:24px">${rows}</div>
    ${nwSection}
    <div id="rcDistanceAI"></div>`;

  _rcDistanceTraveledAI(d);
}

// User-attested starting balance for a paid-off card Groundwork never saw.
// Writes beginBal through the normal setCardField path (debounced DB sync),
// then re-renders — the whole report recalculates from the new starting line.
function _dtSetStartBal(cardId, val) {
  const v = parseFloat(val);
  if (!(v > 0)) return;
  setCardField(cardId, 'beginBal', v);
  _rcRenderDistanceTraveled();
}

function _rcDistanceTraveledAI(d) {
  const target = g('rcDistanceAI');
  if (!target || !aiEnabled()) return;

  const dataLines = [
    `Window: ${d.earliestMonth ? 'since ' + _dtMonthLabel(d.earliestMonth) : 'from starting balances'}`,
    `Principal paid down: ${fmt(d.totalCovered)} of ${fmt(d.totalStart)} (${d.pctCovered}%)`,
    ...(d.retired.length ? [`Debts fully retired: ${d.retired.map(x=>x.card.name||'Card').join(', ')}`] : []),
    ...(d.freedMonthly > 0 ? [`Monthly cash flow freed: ${fmt(d.freedMonthly)}/mo`] : []),
    ...(d.monthsPulled ? [`Debt-free date pulled ${d.monthsPulled} months closer`] : []),
    ...(d.interestNeverCharged ? [`Interest that will never be charged: ${fmt(d.interestNeverCharged)}`] : []),
    // Recurring-payment compliance (Phase F) — "plan" here means the amount
    // saved on the recurring pattern itself, not a payoff-plan entity (this
    // codebase has none — see server.py :: get_payment_compliance).
    ...(d.paymentCompliance ? [
      `Recurring debt payments logged: ${d.paymentCompliance.total}, of which ${d.paymentCompliance.onTime} were within 5% of the planned amount`,
      ...(d.paymentCompliance.under > 0 ? [`Payments below the planned amount: ${d.paymentCompliance.under}`] : []),
      ...(d.paymentCompliance.over > 0 ? [`Payments above the planned amount: ${d.paymentCompliance.over}`] : []),
      `Average variance from the planned payment amount: ${d.paymentCompliance.avgVariancePct > 0 ? '+' : ''}${d.paymentCompliance.avgVariancePct}%`,
    ] : []),
    // Payoff confidence (Phase H2 Feature 5) — from real payment reliability,
    // not a payoff-plan entity (see server.py :: get_payment_compliance_confidence).
    ...(d.payoffConfidence != null ? [`Payoff confidence, from real payment reliability: ${d.payoffConfidence}%`] : []),
    ...(d.allClear ? ['All debts are paid.'] : [`Current total balance: ${fmt(d.totalNow)}`]),
  ];

  const buildPrompt = (profileCtx, stageCtx) => [
    profileCtx || '',
    `DISTANCE TRAVELED — ${new Date().toLocaleDateString('en-US',{month:'long',year:'numeric'})}`,
    '',
    dataLines.join('\n'),
    stageCtx?.stageNote || '',
    '',
    'Rules:',
    '- Narrate the ground covered, not what remains. Lead with the single most meaningful win.',
    '- Translate wins into what they free up: name the monthly dollar amount and what it changes.',
    '- Use only the numbers above. No invented projections, no percentages not given.',
    '- Never shame slow months or below-plan payments — report the compliance numbers neutrally,',
    '  as fact, the same way a paid-down-balance number is reported. Being below plan sometimes',
    '  is not a failure worth narrating as one.',
    '- Do not give advice or suggest a next step of any kind — describe only what already',
    '  happened and what it freed up. No "consider", "should", "crucial", or similar.',
    '- 3 short paragraphs max. Plain prose. No headers, no bullets, no greeting.',
  ].filter(Boolean).join('\n').trim();

  _rcAnalyzeWithAI('distance_traveled', dataLines, buildPrompt, target);
}

async function _rcRenderDebtProgress() {
  const body = g('rcReportBody');
  if (!body) return;
  if (!Object.keys(_debtHistoryCache).length) {
    body.innerHTML = `<div style="font-size:13px;color:var(--slate);display:flex;align-items:center;gap:8px"><div class="spinner"></div>Loading...</div>`;
    await _budgetLoadDebtHistory();
  }
  const allDebts    = S.debtCards;
  const activeDebts = allDebts.filter(c => !c.paidInFull);
  const hasHistory  = Object.values(_debtHistoryCache).some(h => h.length > 0);
  if (!allDebts.length) { body.innerHTML = `<div style="color:var(--slate);font-size:13px">No debt accounts found.</div>`; return; }
  let totalInterestPaid = 0;
  let hasRealInterest = false;
  allDebts.forEach(card => {
    const history = [...(_debtHistoryCache[String(card._dbId)] || [])].reverse();
    // Prefer real interest_charged (B6a/B6b) over payment-minus-balance-drop estimate
    const realInterest = history
      .filter(h => h.interest_charged != null)
      .reduce((s, h) => s + h.interest_charged, 0);
    if (realInterest > 0) {
      totalInterestPaid += realInterest;
      hasRealInterest = true;
    } else {
      // Fallback estimate: payment - balance drop each month
      for (let i = 1; i < history.length; i++) {
        const balDrop = history[i-1].balance - history[i].balance;
        const pmt     = history[i].payment;
        if (pmt > 0 && balDrop < pmt) totalInterestPaid += Math.max(0, pmt - balDrop);
      }
    }
  });
  const freed        = _budgetFreedMinimumsThisYear(activeDebts);
  const totalBegin   = allDebts.reduce((s,c) => s+(parseFloat(c.beginBal)||0), 0);
  const totalCurrent = allDebts.reduce((s,c) => s+(_cardBal(c)), 0);
  const totalPaid    = Math.max(0, totalBegin - totalCurrent);
  const pctDone      = totalBegin > 0 ? Math.round((totalPaid/totalBegin)*100) : 0;
  body.innerHTML = `
    <div style="margin-bottom:24px">
      <h2 style="font-family:'Playfair Display',Georgia,serif;font-style:italic;font-size:22px;font-weight:600;color:var(--ink);margin-bottom:4px">Debt Progress</h2>
      <div style="font-size:13px;color:var(--slate)">Balance history, interest paid, and freed minimums across all debt accounts.</div>
    </div>
    <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:12px;margin-bottom:24px">
      <div class="card" style="padding:14px"><div style="font-size:10px;text-transform:uppercase;letter-spacing:.08em;color:var(--slate-2);margin-bottom:4px">Principal paid</div><div style="font-family:var(--font-mono);font-size:20px;font-weight:600;color:var(--pine)">${fmt(totalPaid)}</div><div style="font-size:11px;color:var(--slate);margin-top:2px">${pctDone}% of starting balance</div></div>
      <div class="card" style="padding:14px"><div style="font-size:10px;text-transform:uppercase;letter-spacing:.08em;color:var(--slate-2);margin-bottom:4px">Remaining</div><div style="font-family:var(--font-mono);font-size:20px;font-weight:600;color:var(--ember)">${fmt(totalCurrent)}</div></div>
      <div class="card" style="padding:14px"><div style="font-size:10px;text-transform:uppercase;letter-spacing:.08em;color:var(--slate-2);margin-bottom:4px">Interest paid</div><div style="font-family:var(--font-mono);font-size:20px;font-weight:600;color:var(--ember)">${totalInterestPaid>0?fmt(totalInterestPaid):'--'}</div><div style="font-size:11px;color:var(--slate-2);margin-top:2px">${totalInterestPaid>0?(hasRealInterest?'from imports':'estimated from history'):'link cards to track'}</div></div>
      ${freed!==null&&freed>0?`<div class="card" style="padding:14px;border-color:var(--pine-border);background:var(--pine-bg)"><div style="font-size:10px;text-transform:uppercase;letter-spacing:.08em;color:var(--pine);margin-bottom:4px">Freed minimums</div><div style="font-family:var(--font-mono);font-size:20px;font-weight:600;color:var(--pine)">+${fmt(freed)}/mo</div><div style="font-size:11px;color:var(--pine);opacity:.8;margin-top:2px">since January</div></div>`:''}
    </div>
    ${!hasHistory?`<div class="card" style="padding:16px;border-color:var(--gold-border);background:var(--gold-bg);margin-bottom:20px"><div style="font-size:13px;font-weight:500;color:#92400e;margin-bottom:6px">Balance history not yet available</div><div style="font-size:12px;color:var(--slate);line-height:1.6">Link each debt card to its imported bank account in the Budget page, then import monthly statements. Groundwork builds the history automatically.</div><button onclick="showView('budget')" style="margin-top:10px;font-size:12px;background:none;border:1px solid var(--gold-border);border-radius:var(--r-sm);padding:5px 12px;cursor:pointer;color:#92400e">Set up in Budget</button></div>`:''}
    <div style="display:flex;flex-direction:column;gap:12px">
      ${allDebts.map(card => {
        const bal   = _cardBal(card);
        const begin = parseFloat(card.beginBal)||bal;
        const pct   = begin>0?Math.min(100,Math.round(((begin-bal)/begin)*100)):0;
        const apr   = parseFloat(card.rate)||0;
        const min   = _payoffPayment(card)||0;   // V3
        const snaps = bal>0&&apr>0&&min>0?_projectPayoff(bal,apr,min):[];
        const barClr = pct>=75?'var(--pine)':pct>=40?'var(--gold)':'var(--ember)';
        const history = (_debtHistoryCache[String(card._dbId)]||[]).slice().reverse();

        // Reuse the Debt page's rich sparkline and trend stats
        const sparklineSvg = _debtCardSparkline(card, 120, 32);
        const stats = _debtCardTrendStats(card);
        const trendIcon  = stats?(stats.trending==='down'?'↓':stats.trending==='up'?'↑':'→'):'';
        const trendColor = stats?(stats.trending==='down'?'var(--pine)':stats.trending==='up'?'var(--ember)':'var(--slate)'):'';
        const fmtMo = mo => { if(!mo)return''; const[y,m]=mo.split('-'); return new Date(+y,+m-1,1).toLocaleDateString('en-US',{month:'short',year:'2-digit'}); };
        const firstMo = history[0]?.month||'';
        const lastMo  = history[history.length-1]?.month||'';
        const interestDisplay = stats&&stats.totalInterest>0
          ? `<span style="color:var(--slate-2)">Interest paid:</span> <span style="font-family:var(--font-mono);color:var(--ember)">${fmt(stats.totalInterest)}${stats.hasRealInterest?'':' est'}</span>`
          : '';

        return `<div class="card" style="padding:16px${card.paidInFull?';border-color:var(--pine-border);background:var(--pine-bg)':''}">
          <div style="display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:10px;gap:12px">
            <div>
              <div style="font-size:14px;font-weight:600;color:var(--ink)">${esc(card.name||'Debt')}</div>
              <div style="font-size:11px;color:var(--slate)">${apr>0?`${apr}% APR`:''}</div>
            </div>
            <div style="text-align:right;flex-shrink:0">
              ${sparklineSvg
                ? `<div>${sparklineSvg}<div style="display:flex;justify-content:space-between;font-family:var(--font-mono);font-size:9px;color:var(--slate-2);margin-top:2px;width:120px"><span>${fmtMo(firstMo)}</span><span>${fmtMo(lastMo)}</span></div></div>`
                : `<div style="font-family:var(--font-mono);font-size:16px;font-weight:600;color:${card.paidInFull?'var(--pine)':'var(--ember)'}">${card.paidInFull?'Paid off':fmt(bal)}</div>`}
            </div>
          </div>
          ${begin>0?`<div style="height:5px;background:var(--steel);border-radius:3px;overflow:hidden;margin-bottom:5px"><div style="height:100%;width:${pct}%;background:${barClr};border-radius:3px"></div></div><div style="display:flex;justify-content:space-between;font-size:11px;color:var(--slate-2);margin-bottom:8px"><span>${pct}% paid</span><span>${card.paidInFull?'Complete':fmt(bal)+' left'}</span></div>`:''}
          ${stats?`<div style="display:flex;gap:16px;flex-wrap:wrap;font-size:12px;color:var(--slate);margin-bottom:6px">
            <span style="font-family:var(--font-mono);color:${trendColor}">${trendIcon} ${stats.trending==='down'?`−${fmt(Math.abs(stats.monthlyRate))}/mo`:stats.trending==='up'?`+${fmt(Math.abs(stats.monthlyRate))}/mo`:'holding steady'}</span>
            ${stats.netReduction>0?`<span><span style="color:var(--slate-2)">Net paid:</span> <span style="font-family:var(--font-mono);color:var(--pine)">${fmt(stats.netReduction)}</span></span>`:''}
            ${stats.avgPayment>0?`<span><span style="color:var(--slate-2)">Avg pmt:</span> <span style="font-family:var(--font-mono)">${fmt(stats.avgPayment)}/mo</span></span>`:''}
            ${interestDisplay}
          </div>`:''}
          ${!card.paidInFull&&snaps.length?`<div style="display:flex;gap:20px;font-size:12px;flex-wrap:wrap"><span><span style="color:var(--slate-2)">Payoff:</span> <span style="font-family:var(--font-mono)">${_payoffDateLabel(snaps.length)}</span></span>${stats?.months?`<span style="color:var(--slate-2)">${stats.months} mo history</span>`:''}
          </div>`:''}
        </div>`;
      }).join('')}
    </div>`;
}

// ── §7.4 Income & Savings Rate ────────────────────────────────────────────────
function _rcRenderIncomeSavings() {
  const body = g('rcReportBody');
  if (!body) return;
  const now = new Date();
  const months = [];
  for (let i = 11; i >= 0; i--) {
    const d = new Date(now.getFullYear(), now.getMonth()-i, 1);
    months.push(`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`);
  }
  const budgetInc = S.incomes.reduce((s,i) => s+i.amount, 0);
  const moData = months.map(mo => {
    const inc  = S.transactions.filter(t=>t.type==='credit'&&(t.date||'').startsWith(mo)).reduce((s,t)=>s+t.amount,0);
    const effI = inc>0?inc:budgetInc;
    const exp  = S.transactions.filter(t=>t.type==='debit'&&(t.date||'').startsWith(mo)).reduce((s,t)=>s+t.amount,0);
    const saved = effI-exp, rate = effI>0?Math.round((saved/effI)*100):0;
    const [y,m] = mo.split('-').map(Number);
    return { mo, lbl:new Date(y,m-1,1).toLocaleDateString('en-US',{month:'short'}), inc:effI, exp, saved, rate };
  });
  const avgRate    = Math.round(moData.reduce((s,m)=>s+m.rate,0)/moData.length);
  const bestMonth  = moData.reduce((a,b)=>b.rate>a.rate?b:a);
  const worstMonth = moData.reduce((a,b)=>b.rate<a.rate?b:a);
  // Computed here (not just inside the AI block below) so the visible
  // "Lowest month"/"Best month" stat cards can also flag it when the
  // current in-progress month happens to land as a superlative — same
  // partial-month blind spot, same fix, applied to what a human reads too.
  const _today            = new Date();
  const _currentMonthKey  = `${_today.getFullYear()}-${String(_today.getMonth()+1).padStart(2,'0')}`;
  const _daysInMonth      = new Date(_today.getFullYear(), _today.getMonth()+1, 0).getDate();
  const _dayOfMonth       = _today.getDate();
  const _isPartialMonth   = (m) => m && m.mo === _currentMonthKey && _dayOfMonth < _daysInMonth;
  const worstIsPartial    = _isPartialMonth(worstMonth);
  const bestIsPartial     = _isPartialMonth(bestMonth);
  const improving  = moData.slice(-3).every((m,i,arr)=>i===0||m.rate>=arr[i-1].rate);
  const maxAbs = Math.max(...moData.map(m=>Math.abs(m.rate)),20), BAR_H=60;
  const bars = moData.map(m => {
    const h=Math.round((Math.abs(m.rate)/maxAbs)*BAR_H), neg=m.rate<0;
    const clr=m.rate>=20?'var(--pine)':m.rate>=0?'var(--gold)':'var(--ember)';
    return `<div style="display:flex;flex-direction:column;align-items:center;gap:2px;flex:1;min-width:18px">
      <div style="font-size:9px;color:var(--slate-2)">${m.rate}%</div>
      <div style="width:100%;height:${BAR_H}px;display:flex;flex-direction:column;justify-content:${neg?'flex-start':'flex-end'}"><div style="width:100%;height:${h}px;background:${clr};border-radius:${neg?'0 0 2px 2px':'2px 2px 0 0'}"></div></div>
      <div style="font-size:9px;color:var(--slate-2);writing-mode:vertical-rl;transform:rotate(180deg);height:22px">${m.lbl}</div>
    </div>`;
  }).join('');
  body.innerHTML = `
    <div style="margin-bottom:24px">
      <h2 style="font-family:'Playfair Display',Georgia,serif;font-style:italic;font-size:22px;font-weight:600;color:var(--ink);margin-bottom:4px">Income & Savings Rate</h2>
      <div style="font-size:13px;color:var(--slate)">How much you're saving as a percentage of income each month.</div>
    </div>
    <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(130px,1fr));gap:12px;margin-bottom:24px">
      <div class="card" style="padding:14px${avgRate>=15?';border-color:var(--pine-border)':''}"><div style="font-size:10px;text-transform:uppercase;letter-spacing:.08em;color:var(--slate-2);margin-bottom:4px">Avg savings rate</div><div style="font-family:var(--font-mono);font-size:22px;font-weight:600;color:${avgRate>=20?'var(--pine)':avgRate>=10?'var(--gold)':'var(--ember)'}">${avgRate}%</div><div style="font-size:11px;color:var(--slate);margin-top:2px">Target: 15-20%</div></div>
      <div class="card" style="padding:14px"><div style="font-size:10px;text-transform:uppercase;letter-spacing:.08em;color:var(--slate-2);margin-bottom:4px">Trend</div><div style="font-size:18px;font-weight:600;color:${improving?'var(--pine)':'var(--slate)'}">${improving?'Improving':'Mixed'}</div><div style="font-size:11px;color:var(--slate);margin-top:2px">last 3 months</div></div>
      <div class="card" style="padding:14px"><div style="font-size:10px;text-transform:uppercase;letter-spacing:.08em;color:var(--slate-2);margin-bottom:4px">Best month</div><div style="font-family:var(--font-mono);font-size:18px;font-weight:600;color:var(--pine)">${bestMonth.rate}%</div><div style="font-size:11px;color:var(--slate);margin-top:2px">${bestMonth.lbl}${bestIsPartial ? ' (so far)' : ''}</div></div>
      <div class="card" style="padding:14px"><div style="font-size:10px;text-transform:uppercase;letter-spacing:.08em;color:var(--slate-2);margin-bottom:4px">Lowest month</div><div style="font-family:var(--font-mono);font-size:18px;font-weight:600;color:${worstMonth.rate<0?'var(--ember)':'var(--gold)'}">${worstMonth.rate}%</div><div style="font-size:11px;color:var(--slate);margin-top:2px">${worstMonth.lbl}${worstIsPartial ? ' (so far)' : ''}</div></div>
    </div>
    <div class="card" style="margin-bottom:20px;padding:16px">
      <div style="font-size:11px;font-weight:600;letter-spacing:.08em;text-transform:uppercase;color:var(--slate-2);margin-bottom:8px">Savings rate - last 12 months</div>
      <div style="display:flex;align-items:flex-end;gap:3px">${bars}</div>
      <div style="display:flex;gap:16px;margin-top:8px;font-size:11px;color:var(--slate-2);flex-wrap:wrap">
        <span style="color:var(--pine)">20%+ solid</span><span style="color:var(--gold)">0-19% building</span><span style="color:var(--ember)">negative over-spent</span>
      </div>
    </div>
    <div class="card" style="padding:16px">
      <div style="font-size:11px;font-weight:600;letter-spacing:.08em;text-transform:uppercase;color:var(--slate-2);margin-bottom:12px">Month by month</div>
      <table style="width:100%;border-collapse:collapse;font-size:12px">
        <thead><tr style="border-bottom:1px solid var(--steel)"><th style="text-align:left;padding:5px 8px;color:var(--slate-2);font-weight:500">Month</th><th style="text-align:right;padding:5px 8px;color:var(--slate-2);font-weight:500">Income</th><th style="text-align:right;padding:5px 8px;color:var(--slate-2);font-weight:500">Expenses</th><th style="text-align:right;padding:5px 8px;color:var(--slate-2);font-weight:500">Saved</th><th style="text-align:right;padding:5px 8px;color:var(--slate-2);font-weight:500">Rate</th></tr></thead>
        <tbody>${moData.map(m=>`<tr style="border-bottom:1px solid var(--steel)"><td style="padding:6px 8px;color:var(--ink)">${m.lbl}</td><td style="padding:6px 8px;font-family:var(--font-mono);text-align:right;color:var(--pine)">${fmt(m.inc)}</td><td style="padding:6px 8px;font-family:var(--font-mono);text-align:right;color:var(--ember)">${fmt(m.exp)}</td><td style="padding:6px 8px;font-family:var(--font-mono);text-align:right;color:${m.saved>=0?'var(--pine)':'var(--ember)'}">${fmt(m.saved)}</td><td style="padding:6px 8px;font-family:var(--font-mono);text-align:right;font-weight:500;color:${m.rate>=20?'var(--pine)':m.rate>=0?'var(--gold)':'var(--ember)'}">${m.rate}%</td></tr>`).join('')}</tbody>
      </table>
    </div>`;

  // G1: AI analysis for income & savings rate (medium utility)
  const moWithData = moData.filter(m => m.inc > 0 || m.exp > 0);
  if (moWithData.length > 0) {
    const latest    = moWithData[moWithData.length - 1];
    const trendLast3 = moWithData.slice(-3).map(m => m.rate);
    const trendDir  = trendLast3.length >= 2
      ? (trendLast3[trendLast3.length-1] > trendLast3[0] ? 'improving' : trendLast3[trendLast3.length-1] < trendLast3[0] ? 'declining' : 'flat')
      : '';
    // BUG FIX (July 6): the current calendar month is included in moData
    // identically to the 11 fully-completed prior months — nothing here
    // ever told the AI (or the stat cards) that "latest month" might mean
    // 6 days of data, not a final result. Confirmed in the field: a report
    // on the 6th of July treated a partial-month -86% savings rate as a
    // completed "income cliff" crisis. Fixed by explicitly computing how
    // far into the current month today actually is (shared with the stat
    // cards above via _isPartialMonth), and telling the AI plainly when
    // the "latest" data point is still in progress.
    const latestIsPartial  = _isPartialMonth(latest);
    const dataLines = [
      `Months of data: ${moWithData.length}`,
      `Average savings rate (12-month): ${avgRate}% (target: 15–20%)`,
      `Best month: ${bestMonth.lbl} at ${bestMonth.rate}%`,
      `Lowest month: ${worstMonth.lbl} at ${worstMonth.rate}%`,
      ...(trendDir ? [`3-month trend: ${trendDir}`] : []),
      ...(latest ? [`Latest month: income ${fmt(latest.inc)}, expenses ${fmt(latest.exp)}, saved ${fmt(latest.saved)} (${latest.rate}%)`] : []),
      ...(latestIsPartial ? [`IMPORTANT: ${latest.lbl} is only ${_dayOfMonth} of ${_daysInMonth} days in — this month's numbers are partial, not final. Income in particular often lands later in the month. Do not describe this month's current rate as a completed trend, a crisis, or a "cliff" — treat it as still developing and say so plainly.`] : []),
    ];
    const buildPrompt = (profileCtx) => [
      profileCtx || '',
      'INCOME & SAVINGS RATE — last 12 months',
      '',
      dataLines.join('\n'),
      '',
      'Month-by-month (last 6):',
      ...moWithData.slice(-6).map(m => `  ${m.lbl}: income ${fmt(m.inc)}, expenses ${fmt(m.exp)}, rate ${m.rate}%`),
      '',
      latestIsPartial
        ? `In 2-3 short paragraphs: focus mainly on the completed months (everything before ${latest.lbl}) — state that savings rate against the 15-20% target plainly, with the actual numbers. Mention ${latest.lbl} only briefly, explicitly noting it's still in progress and too early to judge. Name the best and worst month above and their exact rates, stated as plain facts — not a command, and never calculate a new number yourself. No headers. Use only the numbers given above.`
        : 'In 2-3 short paragraphs: state this savings rate against the 15-20% target plainly, with the actual numbers. Name the best and worst month above and their exact rates, stated as plain facts — not a command, and never calculate a new number yourself. No headers. Use only the numbers given above.',
    ].filter(Boolean).join('\n');
    _rcAnalyzeWithAI('income_savings', dataLines, buildPrompt, body);
  }
}

// ── §7.5 Net Worth Timeline ───────────────────────────────────────────────────
async function _rcRenderNetWorthTimeline() {
  const body = g('rcReportBody');
  if (!body) return;
  if (!_nwHistory || !_nwHistory.length) {
    body.innerHTML = `<div style="font-size:13px;color:var(--slate)">Loading...</div>`;
    await loadNWHistory();
  }
  const history = _nwHistory || [];
  if (!history.length) {
    body.innerHTML = `<div style="color:var(--slate);font-size:13px">No net worth snapshots yet.</div><button onclick="showView('networth')" style="margin-top:12px;font-size:12px;background:none;border:1px solid var(--steel);border-radius:var(--r-sm);padding:5px 12px;cursor:pointer;color:var(--ink)">Go to Net Worth</button>`;
    return;
  }
  const sorted     = [...history].sort((a,b)=>(a.date||'').localeCompare(b.date||''));
  const first      = sorted[0], last = sorted[sorted.length-1];
  const totalGain  = last.net_worth - first.net_worth;
  const debtContrib = Math.max(0, (first.total_liabilities||0)-(last.total_liabilities||0));
  const thresholds = [-50000,-25000,-10000,0,10000,25000,50000,100000,250000];
  const milestones = [];
  thresholds.forEach(t => {
    const hit = sorted.find((s,i)=>i>0&&((sorted[i-1].net_worth<t&&s.net_worth>=t)||(t<0&&sorted[i-1].net_worth>t&&s.net_worth<=t)));
    if (hit) milestones.push({ threshold:t, label:hit.month_label||hit.date });
  });
  const W=560,H=140,PAD=8;
  const vals=sorted.map(s=>s.net_worth), maxV=Math.max(...vals,0), minV=Math.min(...vals,0), range=maxV-minV||1;
  const toX=i=>PAD+Math.round((i/Math.max(sorted.length-1,1))*(W-PAD*2));
  const toY=v=>PAD+Math.round((H-PAD*2)-(((v-minV)/range)*(H-PAD*2)));
  const zero=toY(0), pts=sorted.map((s,i)=>`${toX(i)},${toY(s.net_worth)}`).join(' ');
  const areaD=`M${toX(0)},${zero} ${sorted.map((s,i)=>`L${toX(i)},${toY(s.net_worth)}`).join(' ')} L${toX(sorted.length-1)},${zero} Z`;
  const clr=last.net_worth>=0?'var(--pine)':'var(--ember)';
  body.innerHTML = `
    <div style="margin-bottom:24px">
      <h2 style="font-family:'Playfair Display',Georgia,serif;font-style:italic;font-size:22px;font-weight:600;color:var(--ink);margin-bottom:4px">Net Worth Timeline</h2>
      <div style="font-size:13px;color:var(--slate)">All-time trajectory from first snapshot to today.</div>
    </div>
    <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(130px,1fr));gap:12px;margin-bottom:24px">
      <div class="card" style="padding:14px"><div style="font-size:10px;text-transform:uppercase;letter-spacing:.08em;color:var(--slate-2);margin-bottom:4px">Current</div><div style="font-family:var(--font-mono);font-size:20px;font-weight:600;color:${last.net_worth>=0?'var(--pine)':'var(--ember)'}">${fmt(last.net_worth)}</div></div>
      <div class="card" style="padding:14px"><div style="font-size:10px;text-transform:uppercase;letter-spacing:.08em;color:var(--slate-2);margin-bottom:4px">Total change</div><div style="font-family:var(--font-mono);font-size:20px;font-weight:600;color:${totalGain>=0?'var(--pine)':'var(--ember)'}">${totalGain>=0?'+':''}${fmt(totalGain)}</div><div style="font-size:11px;color:var(--slate);margin-top:2px">since ${first.month_label||first.date}</div></div>
      ${debtContrib>0?`<div class="card" style="padding:14px"><div style="font-size:10px;text-transform:uppercase;letter-spacing:.08em;color:var(--slate-2);margin-bottom:4px">From debt paydown</div><div style="font-family:var(--font-mono);font-size:20px;font-weight:600;color:var(--pine)">+${fmt(debtContrib)}</div></div>`:''}
    </div>
    <div class="card" style="margin-bottom:20px;padding:16px">
      <svg viewBox="0 0 ${W} ${H}" style="width:100%;height:auto;display:block">
        ${zero>PAD&&zero<H-PAD?`<line x1="${PAD}" y1="${zero}" x2="${W-PAD}" y2="${zero}" stroke="var(--steel)" stroke-width="1" stroke-dasharray="4,3"/>`:''}
        <path d="${areaD}" fill="${clr}" opacity=".08"/>
        <polyline points="${pts}" fill="none" stroke="${clr}" stroke-width="2" stroke-linejoin="round"/>
      </svg>
      <div style="display:flex;justify-content:space-between;font-size:11px;color:var(--slate-2);margin-top:4px"><span>${first.month_label||first.date}</span><span>${last.month_label||last.date}</span></div>
    </div>
    ${milestones.length?`<div class="card" style="margin-bottom:20px;padding:16px"><div style="font-size:11px;font-weight:600;letter-spacing:.08em;text-transform:uppercase;color:var(--slate-2);margin-bottom:12px">Milestones</div>${milestones.map(m=>`<div style="display:flex;justify-content:space-between;padding:7px 0;border-bottom:1px solid var(--steel);font-size:12px"><span style="color:var(--ink)">Net worth crossed ${m.threshold>=0?'+':''}${fmt(m.threshold)}</span><span style="font-family:var(--font-mono);color:var(--slate)">${m.label}</span></div>`).join('')}</div>`:''}
    <div class="card" style="padding:16px">
      <div style="font-size:11px;font-weight:600;letter-spacing:.08em;text-transform:uppercase;color:var(--slate-2);margin-bottom:12px">All snapshots</div>
      <table style="width:100%;border-collapse:collapse;font-size:12px">
        <thead><tr style="border-bottom:1px solid var(--steel)"><th style="text-align:left;padding:5px 8px;color:var(--slate-2);font-weight:500">Date</th><th style="text-align:right;padding:5px 8px;color:var(--slate-2);font-weight:500">Assets</th><th style="text-align:right;padding:5px 8px;color:var(--slate-2);font-weight:500">Liabilities</th><th style="text-align:right;padding:5px 8px;color:var(--slate-2);font-weight:500">Net Worth</th></tr></thead>
        <tbody>${[...sorted].reverse().map(s=>`<tr style="border-bottom:1px solid var(--steel)"><td style="padding:6px 8px;color:var(--ink)">${s.month_label||s.date}</td><td style="padding:6px 8px;font-family:var(--font-mono);text-align:right;color:var(--pine)">${fmt(s.total_assets)}</td><td style="padding:6px 8px;font-family:var(--font-mono);text-align:right;color:var(--ember)">${fmt(s.total_liabilities)}</td><td style="padding:6px 8px;font-family:var(--font-mono);text-align:right;font-weight:600;color:${s.net_worth>=0?'var(--pine)':'var(--ember)'}">${fmt(s.net_worth)}</td></tr>`).join('')}</tbody>
      </table>
    </div>`;
}

// ── §7.8 Spending vs. Budget ──────────────────────────────────────────────────
function _rcRenderBudgetVsActual() {
  const body = g('rcReportBody');
  if (!body) return;
  if (!S.expenses.length) {
    body.innerHTML = `<div style="color:var(--slate);font-size:13px">No budget set yet.</div><button onclick="showView('budget')" style="margin-top:12px;font-size:12px;background:none;border:1px solid var(--steel);border-radius:var(--r-sm);padding:5px 12px;cursor:pointer;color:var(--ink)">Set up budget</button>`;
    return;
  }
  const now    = new Date();
  const months = [...new Set(S.transactions.map(t=>(t.date||'').slice(0,7)).filter(Boolean))].sort().reverse();
  const curMo  = `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}`;
  body.innerHTML = `
    <div style="margin-bottom:24px">
      <h2 style="font-family:'Playfair Display',Georgia,serif;font-style:italic;font-size:22px;font-weight:600;color:var(--ink);margin-bottom:4px">Spending vs. Budget</h2>
      <div style="font-size:13px;color:var(--slate)">How actual spending compares to budgeted amounts for any month.</div>
    </div>
    <div style="margin-bottom:24px">
      <label style="font-size:11px;font-weight:600;letter-spacing:.06em;text-transform:uppercase;color:var(--slate);display:block;margin-bottom:4px">Month</label>
      <select id="rcBVAMonth" onchange="_rcUpdateBudgetVsActual()" style="font-size:13px;border:1px solid var(--steel);border-radius:var(--r-sm);padding:6px 10px;background:var(--paper);color:var(--ink)">
        ${months.map(m=>{const [y,mo]=m.split('-').map(Number);return`<option value="${m}"${m===curMo?' selected':''}>${new Date(y,mo-1,1).toLocaleDateString('en-US',{month:'long',year:'numeric'})}</option>`;}).join('')}
      </select>
    </div>
    <div id="rcBVAResult"></div>`;
  _rcUpdateBudgetVsActual();
}

function _rcUpdateBudgetVsActual() {
  const mo  = g('rcBVAMonth')?.value;
  const res = g('rcBVAResult');
  if (!mo || !res) return;
  const prevMoKey = _budgetMonthKey; _budgetMonthKey = mo;
  let totalBudget=0, totalActual=0, totalOver=0, totalUnder=0;
  const rows = S.expenses.map(exp => {
    const catName=exp.cat||exp.name||'Other', budget=parseFloat(exp.amount)||0;
    const actual=_budgetSpentForCat(catName), diff=actual-budget, pct=budget>0?Math.round((actual/budget)*100):0;
    const cs=_categoryStyle(catName);
    totalBudget+=budget; totalActual+=actual;
    if(diff>0) totalOver+=diff; else totalUnder+=Math.abs(diff);
    return { exp, catName, budget, actual, diff, pct, cs, barClr:pct>=100?'var(--ember)':pct>=85?'var(--gold)':'var(--pine)' };
  }).sort((a,b)=>b.pct-a.pct);
  _budgetMonthKey = prevMoKey;
  const netDiff = totalActual - totalBudget;
  res.innerHTML = `
    <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(130px,1fr));gap:12px;margin-bottom:24px">
      <div class="card" style="padding:14px"><div style="font-size:10px;text-transform:uppercase;letter-spacing:.08em;color:var(--slate-2);margin-bottom:4px">Budgeted</div><div style="font-family:var(--font-mono);font-size:20px;font-weight:600;color:var(--ink)">${fmt(totalBudget)}</div></div>
      <div class="card" style="padding:14px"><div style="font-size:10px;text-transform:uppercase;letter-spacing:.08em;color:var(--slate-2);margin-bottom:4px">Actual</div><div style="font-family:var(--font-mono);font-size:20px;font-weight:600;color:var(--ink)">${fmt(totalActual)}</div></div>
      <div class="card" style="padding:14px${totalOver>0?';border-color:var(--ember-border);background:var(--ember-bg)':''}"><div style="font-size:10px;text-transform:uppercase;letter-spacing:.08em;color:var(--slate-2);margin-bottom:4px">Over budget</div><div style="font-family:var(--font-mono);font-size:20px;font-weight:600;color:var(--ember)">${totalOver>0?fmt(totalOver):'--'}</div></div>
      <div class="card" style="padding:14px${totalUnder>0?';border-color:var(--pine-border)':''}"><div style="font-size:10px;text-transform:uppercase;letter-spacing:.08em;color:var(--slate-2);margin-bottom:4px">Under budget</div><div style="font-family:var(--font-mono);font-size:20px;font-weight:600;color:var(--pine)">${totalUnder>0?fmt(totalUnder):'--'}</div></div>
    </div>
    <div class="card" style="padding:16px">
      <div style="font-size:11px;font-weight:600;letter-spacing:.08em;text-transform:uppercase;color:var(--slate-2);margin-bottom:12px">By category</div>
      ${rows.map(r=>{const iconBg=_catTint(r.cs.color),iconBr=_catTintBorder(r.cs.color);return`<div style="padding:10px 0;border-bottom:1px solid var(--steel)"><div style="display:flex;align-items:center;gap:10px;margin-bottom:6px"><div><div class="cat-icon" style="background:${iconBg};border-color:${iconBr};color:${r.cs.color}">${_renderCatIcon(r.cs.icon,r.cs.color,18)}</div></div><div style="flex:1;min-width:0"><div style="font-size:13px;font-weight:500;color:var(--ink)">${esc(r.exp.name||r.catName)}</div></div><div style="text-align:right;flex-shrink:0"><div style="font-family:var(--font-mono);font-size:13px;color:${r.diff>0?'var(--ember)':'var(--ink)'}">${fmt(r.actual)}</div><div style="font-size:11px;color:var(--slate-2)">of ${fmt(r.budget)}</div></div><div style="width:40px;text-align:right;flex-shrink:0"><span style="font-family:var(--font-mono);font-size:11px;font-weight:600;color:${r.pct>=100?'var(--ember)':r.pct>=85?'var(--gold)':'var(--pine)'}">${r.pct}%</span></div></div><div style="height:4px;background:var(--steel);border-radius:2px;overflow:hidden"><div style="width:${Math.min(100,r.pct)}%;height:100%;background:${r.barClr};border-radius:2px"></div></div>${r.diff>0?`<div style="font-size:11px;color:var(--ember);margin-top:3px">${fmt(r.diff)} over</div>`:r.diff<-1?`<div style="font-size:11px;color:var(--pine);margin-top:3px">${fmt(Math.abs(r.diff))} remaining</div>`:''}</div>`;}).join('')}
      <div style="display:flex;justify-content:space-between;padding:10px 0;font-size:13px;font-weight:600"><span style="color:var(--ink)">Net</span><span style="font-family:var(--font-mono);color:${netDiff<=0?'var(--pine)':'var(--ember)'}">${netDiff>0?'+':''}${fmt(netDiff)}</span></div>
    </div>`;
}


// ── §7.9 Debt Payoff Analysis (Phase F) ──────────────────────────────────────
async function _rcRenderDebtPayoff() {
  const body = g('rcReportBody');
  if (!body) return;

  if (!Object.keys(_debtHistoryCache).length) {
    await _budgetLoadDebtHistory().catch(_gwErr('_rcRenderDebtPayoff'));
  }

  const activeDebts = _activeDebtCards();

  if (!activeDebts.length) {
    body.innerHTML = `<div style="color:var(--slate);font-size:13px;padding:20px 0">No active debt accounts found.</div>
      <button onclick="showView('debt')" style="font-size:12px;background:none;border:1px solid var(--steel);border-radius:var(--r-sm);padding:5px 12px;cursor:pointer;color:var(--ink)">Go to Debt Payoff</button>`;
    return;
  }

  // F1: Per-card projections
  const cardData = activeDebts.map(card => {
    const bal   = _cardBal(card);
    const apr   = parseFloat(card.rate)||0;
    const pmt   = _payoffPayment(card)||0;   // V3
    const calcMin = bal > 0 && apr > 0 ? _calcMinPayment(bal, apr) : pmt;
    const snaps   = bal > 0 && pmt > 0 ? _projectPayoff(bal, apr, pmt) : [];
    const totalInt    = snaps.reduce((s,r)=>s+r.interest,0);
    // V11: this debt at minimums only, as everywhere else (_minimumsOnly) - not
    // today's minimum frozen for its life. Claimed only when both runs finish.
    const minOnly     = bal > 0 ? _minimumsOnly([{ balance: bal, rate: apr, minimum: pmt, debtType: card.debtType || 'credit' }]) : null;
    const provable    = minOnly && !minOnly.capped && snaps.length && !snaps[snaps.length - 1].noPayoff;
    const minTotalInt = provable ? minOnly.totalInterest : 0;
    const intSaved    = provable ? Math.max(0, minOnly.totalInterest - totalInt) : 0;
    const mosSooner   = provable ? Math.max(0, minOnly.months - snaps.length) : 0;
    // APR history
    const history = (_debtHistoryCache[String(card._dbId)]||[]).slice().reverse();
    const aprHistory = [];
    for (let i=1; i<history.length; i++) {
      if (history[i].apr && history[i-1].apr && Math.abs(history[i].apr - history[i-1].apr) > 0.5) {
        aprHistory.push({ month: history[i].month, from: history[i-1].apr, to: history[i].apr });
      }
    }
    return { card, bal, apr, pmt, calcMin, payoffMos: snaps.length,
             payoffLabel: `${_payoffDateLabel(snaps.length)} at its own payment`, totalInt, minTotalInt,   // V4: not the plan
             intSaved, mosSooner, aprHistory, linked: !!card.linkedAccountId };
  });

  // V10: the plan's own engine run (the Debt page's), not an avalanche of the report's own.
  const plan          = await _planAwait();
  const sortedByApr   = [...cardData].sort((a,b)=>(parseFloat(b.card.rate)||0)-(parseFloat(a.card.rate)||0));
  // The plan's first debt, as the Debt page marks it: highest APR, or smallest balance for snowball.
  const targetData    = (_planName() === 'snowball' ? [...cardData].sort((a,b)=>a.bal-b.bal) : sortedByApr)[0];
  // Each debt's month in the plan, in the order the plan clears them.
  const planSeq       = cardData.map(d => ({ d, month: _planClearedMonth(d.card, plan) }))
                                .filter(x => x.month).sort((a,b) => a.month - b.month);
  const totalDebt     = activeDebts.reduce((s,c)=>s+(_cardBal(c)),0);
  const beginDebt     = S.debtCards.reduce((s,c)=>s+(parseFloat(c.beginBal)||0),0);
  const eliminated    = Math.max(0, beginDebt - totalDebt);
  const pctElim       = beginDebt > 0 ? Math.round((eliminated/beginDebt)*100) : 0;
  const totalRemInt   = cardData.reduce((s,d)=>s+d.totalInt,0);
  // V11: the plan against minimums only - the Debt page's own pair of figures. The
  // old card summed each debt's gains against a frozen minimum and dropped its
  // losses ($297.52 "saved" where the net was -$2,642), under "your strategy is
  // working". Shown only when both runs finish and the plan is ahead.
  const minsOnly      = (() => { const d = getCardData(); return d.length ? _minimumsOnly(d) : null; })();
  const planSaves     = plan && minsOnly && !minsOnly.capped ? Math.max(0, minsOnly.totalInterest - plan.totalInterest) : 0;
  const debtFreeDate  = plan?.months ? _payoffDateLabel(plan.months) : '—';
  const freed         = _budgetFreedMinimumsThisYear(activeDebts);

  // Payoff impact scenarios on the plan's first debt
  let scenario50 = null, scenario100 = null;
  if (targetData) {
    const { bal:tBal, apr:tApr, pmt:tPmt } = targetData;
    if (tBal > 0 && tPmt > 0) {
      const base    = _projectPayoff(tBal, tApr, tPmt);
      const plus50  = _projectPayoff(tBal, tApr, tPmt+50);
      const plus100 = _projectPayoff(tBal, tApr, tPmt+100);
      const bInt=base.reduce((s,r)=>s+r.interest,0);
      scenario50  = { extra:50,  mosSooner:Math.max(0,base.length-plus50.length),  intSaved:Math.max(0,bInt-plus50.reduce((s,r)=>s+r.interest,0)) };
      scenario100 = { extra:100, mosSooner:Math.max(0,base.length-plus100.length), intSaved:Math.max(0,bInt-plus100.reduce((s,r)=>s+r.interest,0)) };
    }
  }

  body.innerHTML = `
    <div style="margin-bottom:24px">
      <h2 style="font-family:'Playfair Display',Georgia,serif;font-style:italic;font-size:22px;font-weight:600;color:var(--ink);margin-bottom:4px">Debt Payoff Analysis</h2>
      <div style="font-size:13px;color:var(--slate)">Your complete debt picture — balances, sequence, interest cost, and what the math says about your trajectory.</div>
    </div>

    <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:12px;margin-bottom:24px">
      <div class="card" style="padding:14px">
        <div style="font-size:10px;text-transform:uppercase;letter-spacing:.08em;color:var(--slate-2);margin-bottom:4px">Total remaining</div>
        <div style="font-family:var(--font-mono);font-size:20px;font-weight:600;color:var(--ember)">${fmt(totalDebt)}</div>
        ${eliminated>0?`<div style="font-size:11px;color:var(--pine);margin-top:2px">${pctElim}% eliminated (${fmt(eliminated)} paid)</div>`:''}
      </div>
      <div class="card" style="padding:14px">
        <div style="font-size:10px;text-transform:uppercase;letter-spacing:.08em;color:var(--slate-2);margin-bottom:4px">Debt-free date</div>
        <div style="font-family:var(--font-mono);font-size:16px;font-weight:600;color:var(--pine)">${debtFreeDate}</div>
        <div style="font-size:11px;color:var(--slate);margin-top:2px">your ${_planName()} plan, ${fmt(_getMonthlyBudget())}/mo</div>
      </div>
      <div class="card" style="padding:14px">
        <div style="font-size:10px;text-transform:uppercase;letter-spacing:.08em;color:var(--slate-2);margin-bottom:4px">Remaining interest</div>
        <div style="font-family:var(--font-mono);font-size:20px;font-weight:600;color:var(--ember)">${fmt(totalRemInt)}</div>
        <div style="font-size:11px;color:var(--slate);margin-top:2px">at current rates</div>
      </div>
      ${planSaves>0?`<div class="card" style="padding:14px;border-color:var(--pine-border);background:var(--pine-bg)"><div style="font-size:10px;text-transform:uppercase;letter-spacing:.08em;color:var(--pine);margin-bottom:4px">Less interest than minimums only</div><div style="font-family:var(--font-mono);font-size:20px;font-weight:600;color:var(--pine)">${fmt(planSaves)}</div><div style="font-size:11px;color:var(--pine);opacity:.8;margin-top:2px">your ${_planName()} plan at ${fmt(_getMonthlyBudget())}/mo, against paying only each minimum as issuers calculate it</div></div>`:''}
      ${freed>0?`<div class="card" style="padding:14px;border-color:var(--pine-border);background:var(--pine-bg)"><div style="font-size:10px;text-transform:uppercase;letter-spacing:.08em;color:var(--pine);margin-bottom:4px">Freed minimums</div><div style="font-family:var(--font-mono);font-size:20px;font-weight:600;color:var(--pine)">+${fmt(freed)}/mo</div><div style="font-size:11px;color:var(--pine);opacity:.8;margin-top:2px">since January</div></div>`:''}
    </div>

    <div class="card" style="margin-bottom:20px;padding:16px">
      <div style="font-size:11px;font-weight:600;letter-spacing:.08em;text-transform:uppercase;color:var(--slate-2);margin-bottom:14px">Per-card breakdown</div>
      ${cardData.map(d => {
        const isTarget = d.card.id === targetData?.card.id;
        const aprNote  = d.aprHistory.length ? `<div style="font-size:11px;color:var(--gold);margin-top:3px">APR changed: ${d.aprHistory.map(h=>`${h.from}% to ${h.to}% in ${h.month}`).join(', ')}</div>` : '';
        return `<div style="padding:12px 0;border-bottom:1px solid var(--steel)">
          <div style="display:flex;align-items:flex-start;justify-content:space-between;gap:12px;margin-bottom:6px">
            <div style="flex:1;min-width:0">
              <div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap">
                <span style="font-size:13px;font-weight:600;color:var(--ink)">${esc(d.card.name||'Card')}</span>
                ${isTarget?`<span style="font-size:10px;padding:1px 7px;border-radius:10px;background:var(--gold-bg);color:#92400e;border:1px solid var(--gold-border)">${_planName()} target</span>`:''}
                ${d.linked?`<span style="font-size:10px;color:var(--pine)">from imports</span>`:`<span style="font-size:10px;color:var(--slate-2)">manual</span>`}
              </div>
              <div style="font-size:11px;color:var(--slate);margin-top:2px">${d.apr>0?`${d.apr}% APR · `:''}${fmt(d.pmt)}/mo${d.calcMin>0&&Math.abs(d.pmt-d.calcMin)>1?` (min ${fmt(d.calcMin)})`:''}</div>
              ${aprNote}
            </div>
            <div style="text-align:right;flex-shrink:0">
              <div style="font-family:var(--font-mono);font-size:15px;font-weight:600;color:var(--ember)">${fmt(d.bal)}</div>
              <div style="font-size:11px;color:var(--slate)">${d.payoffLabel}</div>
            </div>
          </div>
          ${d.totalInt>0?`<div style="font-size:11px;color:var(--slate-2);flex-wrap:wrap;display:flex;gap:16px">
            <span>Interest: <span style="font-family:var(--font-mono);color:var(--ember)">${fmt(d.totalInt)}</span></span>
            ${d.intSaved>0?`<span style="color:var(--pine)">${fmt(d.intSaved)} less interest than minimums only · ${d.mosSooner} months sooner</span>`:''}
          </div>`:''}
        </div>`;
      }).join('')}
    </div>

    ${planSeq.length ? `<div class="card" style="margin-bottom:20px;padding:16px">
      <div style="font-size:11px;font-weight:600;letter-spacing:.08em;text-transform:uppercase;color:var(--slate-2);margin-bottom:4px">Payoff sequence — your ${_planName()} plan</div>
      <div style="font-size:12px;color:var(--slate);margin-bottom:12px">${_planName() === 'snowball' ? 'Smallest balance first' : 'Highest APR first'}, ${fmt(_getMonthlyBudget())}/mo. Each payoff rolls its payment to the next debt.</div>
      ${planSeq.map(({d, month},i)=>`<div style="display:flex;align-items:center;gap:12px;padding:8px 0;border-bottom:1px solid var(--steel)">
        <div style="width:20px;height:20px;border-radius:50%;background:${i===0?'var(--gold)':'var(--steel)'};color:${i===0?'#92400e':'var(--slate)'};font-size:11px;font-weight:600;display:flex;align-items:center;justify-content:center;flex-shrink:0">${i+1}</div>
        <div style="flex:1"><div style="font-size:13px;font-weight:500;color:var(--ink)">${esc(d.card.name||'Card')}</div><div style="font-size:11px;color:var(--slate)">${d.apr}% APR · ${fmt(d.bal)}</div></div>
        <div style="font-family:var(--font-mono);font-size:12px;color:var(--slate)">${_payoffDateLabel(month)}</div>
      </div>`).join('')}
    </div>` : ''}

    ${scenario50||scenario100 ? `<div class="card" style="margin-bottom:20px;padding:16px">
      <div style="font-size:11px;font-weight:600;letter-spacing:.08em;text-transform:uppercase;color:var(--slate-2);margin-bottom:4px">What if you paid more?</div>
      <div style="font-size:12px;color:var(--slate);margin-bottom:12px">Applied to ${esc(targetData?.card.name||'highest-APR card')}.</div>
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:12px">
        ${scenario50?`<div style="padding:12px;background:var(--mist);border-radius:var(--r-sm)"><div style="font-size:12px;font-weight:600;color:var(--ink);margin-bottom:6px">+$50/month extra</div><div style="font-size:12px;color:var(--pine)">${scenario50.mosSooner} months sooner</div><div style="font-size:11px;color:var(--slate)">${fmt(scenario50.intSaved)} less interest</div></div>`:''}
        ${scenario100?`<div style="padding:12px;background:var(--mist);border-radius:var(--r-sm)"><div style="font-size:12px;font-weight:600;color:var(--ink);margin-bottom:6px">+$100/month extra</div><div style="font-size:12px;color:var(--pine)">${scenario100.mosSooner} months sooner</div><div style="font-size:11px;color:var(--slate)">${fmt(scenario100.intSaved)} less interest</div></div>`:''}
      </div>
    </div>` : ''}

    <div class="card" id="rcDebtPayoffAICard" style="padding:16px">
      <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:12px">
        <div>
          <div style="font-size:11px;font-weight:600;letter-spacing:.08em;text-transform:uppercase;color:var(--slate-2)">Groundwork's analysis</div>
          <div style="font-size:12px;color:var(--slate);margin-top:2px">What the math means for your specific situation right now.</div>
        </div>
      </div>
      <div id="rcDebtPayoffAIContent">
        ${aiEnabled()
          ? `<button onclick="_rcRunDebtPayoffAI()" class="btn btn-primary" style="font-size:13px">Generate analysis</button>
             <div style="font-size:11px;color:var(--slate-2);margin-top:8px">Runs on your own machine — debt balances, APRs, payoff sequence, and interest data never leave your computer.</div>`
          : `<div style="font-size:13px;color:var(--slate)">${S.prefs?.aiEnabled === false
                ? 'Turn AI on in Settings to enable Groundwork\'s analysis.'
                : 'Add an API key in Settings to enable Groundwork\'s analysis, or switch to local AI (free, no key needed).'}</div>`}
      </div>
    </div>
  `;

  const aiCard = g('rcDebtPayoffAICard');
  if (aiCard) aiCard._debtData = { cardData, sortedByApr, planSeq, totalDebt, beginDebt,
    eliminated, pctElim, totalRemInt, planSaves, freed, debtFreeDate,
    scenario50, scenario100, targetData };
}

async function _rcRunDebtPayoffAI() {
  const d = g('rcDebtPayoffAICard')?._debtData;
  if (!d) return;

  const cardLines = d.cardData.map(cd =>
    `${cd.card.name||'Card'}: ${fmt(cd.bal)}, ${cd.apr}% APR, ${fmt(cd.pmt)}/mo, payoff ${cd.payoffLabel}, ${fmt(cd.totalInt)} interest remaining` +
    (cd.intSaved > 0 ? `, ${fmt(cd.intSaved)} less interest than minimums only (issuer-style falling minimum)` : '') +
    (cd.aprHistory.length ? `, APR changed: ${cd.aprHistory.map(h=>`${h.from}%→${h.to}% in ${h.month}`).join(', ')}` : '')
  );

  const seqLines = d.planSeq
    .map(({d: cd, month},i) => `  ${i+1}. ${cd.card.name||'Card'} (${cd.apr}% APR) — payoff ${_payoffDateLabel(month)}`);   // V10

  const dataLines = [
    `Total remaining: ${fmt(d.totalDebt)}`,
    ...(d.eliminated > 0 ? [`Eliminated: ${fmt(d.eliminated)} (${d.pctElim}% of starting balance)`] : []),
    `Debt-free date: ${d.debtFreeDate}`,
    `Remaining interest at current rates: ${fmt(d.totalRemInt)}`,
    ...(d.planSaves > 0 ? [`Less interest than paying only the minimums (issuer-style falling minimums, nothing rolled over), under the ${_planName()} plan: ${fmt(d.planSaves)}`] : []),
    ...(d.freed > 0 ? [`Freed minimums since January: +${fmt(d.freed)}/month`] : []),
    '---',
    'Per-card:', ...cardLines,
    '---',
    `Payoff sequence (${_planName()} plan):`, ...seqLines,
    ...(d.scenario50 ? [
      '---',
      `What if you paid more? (on ${d.targetData?.card.name||'highest-APR card'})`,
      `+$50/month: ${d.scenario50.mosSooner} months sooner, ${fmt(d.scenario50.intSaved)} less interest`,
      ...(d.scenario100 ? [`+$100/month: ${d.scenario100.mosSooner} months sooner, ${fmt(d.scenario100.intSaved)} less interest`] : []),
    ] : []),
  ];

  const buildPrompt = (profileCtx, stageCtx) => {
    const aprAlerts = d.cardData.filter(cd => cd.aprHistory.length > 0)
      .map(cd => `${cd.card.name}: APR ${cd.aprHistory[0].from}%→${cd.aprHistory[0].to}% in ${cd.aprHistory[0].month}`).join('. ');
    return [
      profileCtx || '',
      `DEBT PICTURE — ${new Date().toLocaleDateString('en-US',{month:'long',year:'numeric'})}`,
      '',
      dataLines.join('\n'),
      aprAlerts ? `\nAPR CHANGES:\n${aprAlerts}` : '',
      stageCtx?.stageNote || '',
      stageCtx?.leanContext || '',
      '',
      'Rules:',
      '- Lead with the number that matters most right now for this specific user',
      '- Name dollar amounts; never recommend balance transfers or specific products',
      '- PSLF loans: never suggest accelerating payoff',
      '- Name one concrete option only, stated as a plain fact about its result — not a command',
      '  or suggestion. Write "Paying $50 more finishes this 6 months sooner," never "Consider',
      '  paying $50 more" or "You should redirect...". Not a list.',
      '- 3 short paragraphs. Plain prose. No headers, no bullets.',
    ].filter(Boolean).join('\n').trim();
  };

  const target = g('rcDebtPayoffAICard');
  if (target) {
    const contentEl = g('rcDebtPayoffAIContent');
    if (contentEl) contentEl.innerHTML = '';
    await _rcAnalyzeWithAI('debt_payoff', dataLines, buildPrompt, target);
  }
}


function splashMsg(msg) {
  const el = g('splashStatus');
  if (el) el.textContent = msg;
}

async function boot() {
  try {
    setText('topbarDate', new Date().toLocaleDateString('en-US',{weekday:'short',month:'short',day:'numeric',year:'numeric'}));
    splashMsg('Loading your data…');
    try {
      await bootFromDB();
      splashMsg('Building dashboard…');
    } catch(e) {
      console.error('bootFromDB failed:', e);
      splashMsg('Ready');
      // Show a visible error in the content area so we can see what failed
      const content = document.querySelector('.content');
      if (content) {
        content.innerHTML = `<div style="padding:32px;font-family:monospace;font-size:13px;color:#dc2626;background:#fff;border:2px solid #dc2626;border-radius:8px;margin:24px">
          <strong>Boot error in bootFromDB:</strong><br><br>${e?.message || e}<br><br>
          <span style="color:#666">Check the browser console (F12) for details.</span>
        </div>`;
      }
      loadSnapshot();
      // bootFromDB failed, so restoreFromBootstrap() never ran — that's the
      // only place that normally populates the import-rules cache. Load it
      // separately here so import rules still work in this fallback path.
      loadImportIntelligence().catch(_gwErr('boot'));
    }
    _loadAchievementDates().catch(_gwErr('boot'));
    restoreLedgerFilters();
    _restoreLedgerColWidths();
    _initLedgerColResize();
    try {
      showView('dashboard');
    } catch(e) {
      console.error('showView/renderDashboard failed:', e);
      const content = document.querySelector('.content');
      if (content && !content.querySelector('[style*="dc2626"]')) {
        content.innerHTML = `<div style="padding:32px;font-family:monospace;font-size:13px;color:#dc2626;background:#fff;border:2px solid #dc2626;border-radius:8px;margin:24px">
          <strong>Render error in renderDashboard:</strong><br><br>${e?.message || e}<br><br>
          <span style="color:#666">Stack: ${(e?.stack||'').slice(0,300)}</span>
        </div>`;
      }
    }
    setSaveDot('saved');
    // Historian: app close. pagehide is the reliable "leaving" signal (fires
    // where beforeunload can be skipped, and is bfcache-friendly); keepalive
    // lets the POST outlive teardown, and _gwFetch still attaches the session
    // token that navigator.sendBeacon can't send. Best-effort, one-shot.
    let _sessionEndSent = false;
    window.addEventListener('pagehide', () => {
      if (_sessionEndSent) return;
      _sessionEndSent = true;
      try {
        _gwFetch('/api/historian/engagement', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ event: 'session_end' }),
          keepalive: true,
        });
      } catch (e) { /* never block unload on telemetry */ }
    });
    _startHeartbeat(); // detect server restarts → auto-reload for fresh token
    _startAutoImportPolling(); // Downloads watcher bridge — offer detected bank files
    setTimeout(_checkForUpdates, 4000);             // update banner, off the boot path
    setInterval(_checkForUpdates, 6 * 3600 * 1000); // re-check twice a day
    if (typeof checkFirstRun === 'function') checkFirstRun().catch(_gwErr('boot'));
    if (typeof checkTermsAcceptance === 'function') checkTermsAcceptance().catch(_gwErr('boot'));
  } catch(e) {
    console.error('Boot error:', e);
  } finally {
    hideSplash();
  }
}

function hideSplash() {
  const splash = g('splashScreen');
  if (!splash) return;
  splash.classList.add('fade-out');
  setTimeout(() => { try { splash.remove(); } catch(e){ _gwErr('hideSplash')(e); } }, 520);
}

// Safety net — splash always clears after 6s no matter what
setTimeout(() => hideSplash(), 6000);

document.addEventListener('DOMContentLoaded', boot);
// Topbar date refresh
setInterval(() => {
  setText('topbarDate', new Date().toLocaleDateString('en-US',{weekday:'short',month:'short',day:'numeric',year:'numeric'}));
}, 10000);


// ─── Investment view stubs & BYB/Tracker fixes ────────────────────────────────

// Entry point called by showView('investments'). Populates the account
// filter dropdown, then loads and renders positions/analytics/transactions.

// ── Investment account helpers ─────────────────────────────────────────────────
let _invAccountsCache = null;

async function _ensureInvAccountsLoaded(force = false) {
  if (!force && _invAccountsCache?.length) { _populateInvDropdownsFromCache(); return; }
  try {
    const res = await API.get('/api/investments/accounts');
    _invAccountsCache = res.data || res || [];
    _populateInvDropdownsFromCache();
  } catch(e) { _invAccountsCache = []; }
}

function _populateInvDropdownsFromCache() {
  const accts = _invAccountsCache || [];
  const noOpt = '<option value="">No accounts yet</option>';
  const optsHtml = accts.length ? accts.map(a=>`<option value="${a.id}">${esc(a.name)}</option>`).join('') : noOpt;
  const filter = g('invAccountFilter');
  if (filter) { const cur=filter.value; filter.innerHTML='<option value="">All accounts</option>'+optsHtml; if(cur&&accts.some(a=>String(a.id)===cur)) filter.value=cur; }
  const holdAcct = g('holdingAccount');
  if (holdAcct) { const cur=holdAcct.value; holdAcct.innerHTML='<option value="">Select account…</option>'+optsHtml; if(cur) holdAcct.value=cur; else if(accts.length===1) holdAcct.value=accts[0].id; }
  const txnAcct = g('invTxnAccount');
  if (txnAcct) { const cur=txnAcct.value; txnAcct.innerHTML='<option value="">Select account…</option>'+optsHtml; if(cur) txnAcct.value=cur; else if(accts.length===1) txnAcct.value=accts[0].id; }
}

function createInvestmentAccount() { _showInvAcctModal(); }

function _showInvAcctModal() {
  document.getElementById('invAcctModal')?.remove();
  const el = document.createElement('div');
  el.id = 'invAcctModal';
  el.className = 'modal-overlay';
  el.innerHTML = `
    <div class="modal" style="max-width:380px">
      <div class="modal-header">
        <div class="modal-title">New investment account</div>
        <button class="modal-close" onclick="document.getElementById('invAcctModal')?.remove()">×</button>
      </div>
      <div class="modal-body">
        <div class="field mb-4">
          <label>Account name</label>
          <input class="field-input" type="text" id="invAcctName" placeholder="e.g. Fidelity Brokerage, Roth IRA">
        </div>
        <div class="field">
          <label>Institution (optional)</label>
          <input class="field-input" type="text" id="invAcctInst" placeholder="e.g. Fidelity">
        </div>
      </div>
      <div class="modal-footer">
        <button class="btn btn-secondary" onclick="document.getElementById('invAcctModal')?.remove()">Cancel</button>
        <button class="btn btn-primary" onclick="_saveInvAcct()">Create account</button>
      </div>
    </div>`;
  document.body.appendChild(el);
  setTimeout(() => g('invAcctName')?.focus(), 60);
}

async function _saveInvAcct() {
  const name = g('invAcctName')?.value?.trim();
  const institution = g('invAcctInst')?.value?.trim() || '';
  if (!name) { showToast('Name required', 'Give the account a name', 'error'); return; }
  document.getElementById('invAcctModal')?.remove();
  try {
    const created = await API.post('/api/accounts', { name, type:'investment', institution, sort_order:99 });
    await loadAccounts();
    await _ensureInvAccountsLoaded(true);
    // If the Record-transaction modal is open, select the new account there
    const sel = g('invTxnAccount');
    if (sel && created?.id) sel.value = String(created.id);
    showToast('Account created', name, 'success');
  } catch(e) { showToast('Could not create account', e.message || '', 'error'); }
}

async function initInvestments() {
  try {
    const res = await API.get('/api/investments/accounts');
    const accounts = res.data || res || [];
    const sel = g('invAccountFilter');
    if (sel) {
      const current = sel.value;
      sel.innerHTML = '<option value="">All accounts</option>' +
        accounts.map(a => `<option value="${a.id}">${a.name}</option>`).join('');
      if (current && accounts.some(a => String(a.id) === current)) {
        sel.value = current;
      }
    }
  } catch (e) {
    // No investment accounts yet, or request failed — positions view will
    // show its own empty state.
  }

  await loadInvestments();
  _loadRealizedGains().catch(_gwErr('initInvestments'));
}

// Investments — full implementation is complex; stubs satisfy onclick handlers
// while the basic _loadInvPositions above handles the simple case
function loadInvestments() { renderInvestments(); }

// ── Investment interaction functions ──────────────────────────────────────────

function filterInvTransactions() {
  // Filter the investment transaction list by selected ticker
  const filter = g('invTxnTickerFilter')?.value || '';
  document.querySelectorAll('.inv-txn-row').forEach(row => {
    const ticker = row.dataset.ticker || '';
    row.style.display = (!filter || ticker === filter) ? '' : 'none';
  });
}

// Audit 2a (d21): /api/investments/prices/validate had no client caller.
// Wired here as advisory add-holding validation. Never blocks the add —
// valid:false can also mean the price lookup is offline, and manual-price
// entry is a supported path.
let _tickerValidateTimer = null;
let _tickerValidateSeq   = 0;
function onHoldingTickerInput() {
  // Auto-uppercase the ticker input as user types
  const el = g('holdingTicker');
  if (el) el.value = el.value.toUpperCase();

  const hint = g('holdingTickerHint');
  if (!hint) return;
  const sym = el?.value?.trim() || '';
  clearTimeout(_tickerValidateTimer);
  if (!sym) { hint.textContent = ''; return; }
  hint.textContent = '…';
  hint.style.color = 'var(--slate-2)';
  const seq = ++_tickerValidateSeq;   // guard against stale responses landing after more typing
  _tickerValidateTimer = setTimeout(async () => {
    try {
      const res = await API.get(`/api/investments/prices/validate?ticker=${encodeURIComponent(sym)}`);
      const v   = res.data || res;
      if (seq !== _tickerValidateSeq) return;
      if (v.valid) {
        hint.textContent = `✓ ${v.name || sym}${v.price ? ` · ${fmt(v.price)}` : ''}`;
        hint.style.color = 'var(--pine)';
      } else {
        hint.textContent = 'Not found — check the symbol, or add it anyway and set the price manually';
        hint.style.color = 'var(--gold)';
      }
    } catch(e) {
      if (seq !== _tickerValidateSeq) return;
      hint.textContent = '';   // lookup unavailable — stay quiet, never block the add
    }
  }, 450);
}

function updateInvTxnTotal() {
  // Live-calculate total cost when shares or price changes
  const shares = parseFloat(g('invTxnShares')?.value) || 0;
  const price  = parseFloat(g('invTxnPrice')?.value)  || 0;
  const total  = shares * price;
  const el     = g('invTxnTotal');
  if (el) el.textContent = total > 0 ? fmt(total) : '';
}
function refreshPrices() {
  const btn = g('invRefreshBtn');
  if (btn) { btn.disabled = true; btn.textContent = '↺ Refreshing…'; }
  API.post('/api/investments/prices/refresh', { force: true }).then(result => {
    renderInvestments();
    const refreshed = result?.refreshed || [];
    const errors     = result?.errors || 0;
    if (!refreshed.length && !errors) {
      showToast('No holdings to price', 'Add a position first', 'info');
    } else if (errors > 0 && refreshed.length === 0) {
      showToast('Could not fetch prices', `${errors} ticker${errors!==1?'s':''} failed — try setting it manually`, 'warning');
    } else if (errors > 0) {
      showToast(`${refreshed.length} price${refreshed.length!==1?'s':''} updated`, `${errors} failed — try manual entry for those`, 'warning');
    } else {
      showToast(`${refreshed.length} price${refreshed.length!==1?'s':''} updated`, '', 'success');
    }
  }).catch(e => showToast('Refresh failed', e.message || 'Check your connection', 'error'))
    .finally(() => { if (btn) { btn.disabled = false; btn.textContent = '↺ Refresh prices'; } });
}
function openRecordTransactionModal() {
  g('recordTxnModal')?.classList.remove('hidden');
  setInvTxnType('buy');
  _ensureInvAccountsLoaded(); // the dropdown was never populated on open
  const d = g('invTxnDate'); if (d && !d.value) d.value = new Date().toISOString().slice(0,10);
}
function closeRecordTransactionModal() { g('recordTxnModal')?.classList.add('hidden'); }
let _invTxnType = 'buy';
function setInvTxnType(type) {
  _invTxnType = type;
  // The toggle buttons use ids, not data attributes — the old selector
  // matched nothing, which is why the highlight never moved.
  const ids = { buy:'invTxnTypeBuy', sell:'invTxnTypeSell', dividend:'invTxnTypeDiv', split:'invTxnTypeSplit' };
  Object.values(ids).forEach(id => g(id)?.classList.remove('active'));
  g(ids[type])?.classList.add('active');
  // Field labels/visibility per type
  const sharesLbl = g('invTxnSharesLabel'), totalLbl = g('invTxnTotalLabel');
  const priceField = g('invTxnPriceField'), totalRow = g('invTxnTotalRow');
  if (type === 'split') {
    if (sharesLbl) sharesLbl.textContent = 'Split ratio (2 = 2-for-1)';
    if (priceField) priceField.style.display = 'none';
    if (totalRow)  totalRow.style.display  = 'none';
  } else if (type === 'dividend') {
    if (sharesLbl) sharesLbl.textContent = 'Shares (optional)';
    if (totalLbl)  totalLbl.textContent  = 'Dividend amount ($)';
    if (priceField) priceField.style.display = 'none';
    if (totalRow)  totalRow.style.display  = '';
  } else {
    if (sharesLbl) sharesLbl.textContent = 'Shares';
    if (totalLbl)  totalLbl.textContent  = 'Total amount ($)';
    if (priceField) priceField.style.display = '';
    if (totalRow)  totalRow.style.display  = '';
  }
}
function saveHolding() { addHolding(); }
async function saveInvTransaction() {
  const ticker  = g('invTxnTicker')?.value?.trim()?.toUpperCase();
  const acctId  = parseInt(g('invTxnAccount')?.value) || 0;
  const shares  = parseFloat(g('invTxnShares')?.value) || 0;
  const price   = parseFloat(g('invTxnPrice')?.value)  || 0;
  const total   = parseFloat(g('invTxnTotal')?.value)  || 0;
  const fees    = parseFloat(g('invTxnFees')?.value)   || 0;
  const note    = g('invTxnNote')?.value?.trim() || '';
  const date    = g('invTxnDate')?.value || new Date().toISOString().slice(0,10);
  const type    = _invTxnType;

  if (!ticker) { showToast('Missing ticker', 'Enter the ticker symbol', 'error'); return; }
  if (!acctId) { showToast('Pick an account', 'Choose an account, or create one with + New', 'error'); return; }
  if (type === 'split' && !(shares > 0)) { showToast('Missing ratio', 'Enter the split ratio (2 = 2-for-1)', 'error'); return; }
  if ((type === 'buy' || type === 'sell') && !(shares > 0)) { showToast('Missing shares', 'Enter the number of shares', 'error'); return; }
  if (type === 'dividend' && !(total > 0)) { showToast('Missing amount', 'Enter the dividend amount', 'error'); return; }

  const body = {
    type, ticker, account_id: acctId, date,
    shares: type === 'split' ? 0 : shares,
    price_per_share: price,
    total_amount: total,
    fees, note,
  };
  if (type === 'split') body.meta = { ratio: shares };

  try {
    await API.post('/api/investments/transactions', body);
    closeRecordTransactionModal();
    await renderInvestments();
    if (type === 'sell') _loadRealizedGains().catch(_gwErr('saveInvTransaction'));
    showToast('Transaction recorded', `${type} · ${ticker}`, 'success');
  } catch(e) { showToast('Could not record transaction', e.message || '', 'error'); }
}

// ── Realized gains & tax summary ──────────────────────────────────────────────
// Server side (/api/investments/realized-gains, /api/investments/tax-summary)
// was already complete — this wires a UI to it for the first time.
let _realizedGainsYear = '';

async function _loadRealizedGains() {
  const content = g('realizedGainsContent');
  if (!content) return;

  try {
    const yearQS = _realizedGainsYear ? `?year=${encodeURIComponent(_realizedGainsYear)}` : '';
    const [taxRes, gainsRes] = await Promise.all([
      API.get('/api/investments/tax-summary'),
      API.get(`/api/investments/realized-gains${yearQS}`),
    ]);
    const taxRows = taxRes.data || taxRes || [];
    const gains   = gainsRes.data || gainsRes || { lots: [], summary: {} };

    // Populate/refresh the year dropdown — years come from tax-summary,
    // which is grouped server-side by lot.closed_date.year.
    const yearSel = g('realizedGainsYear');
    if (yearSel) {
      const years = taxRows.map(r => String(r.year));
      const have  = [...yearSel.options].map(o => o.value).filter(Boolean);
      const stale = years.length !== have.length || years.some(y => !have.includes(y));
      if (stale) {
        yearSel.innerHTML = '<option value="">All years</option>' +
          years.map(y => `<option value="${y}">${y}</option>`).join('');
        yearSel.value = _realizedGainsYear;
      }
    }

    _renderRealizedGains(taxRows, gains);
  } catch (e) {
    content.innerHTML = `<div style="font-size:12px;color:var(--slate-2)">Could not load realized gains.</div>`;
    _gwErr('_loadRealizedGains')(e);
  }
}

function _onRealizedGainsYearChange() {
  _realizedGainsYear = g('realizedGainsYear')?.value || '';
  _loadRealizedGains();
}

function _renderRealizedGains(taxRows, gains) {
  const content = g('realizedGainsContent');
  if (!content) return;

  const lots    = gains.lots || [];
  const summary = gains.summary || { total_gain: 0, short_term: 0, long_term: 0, count: 0 };

  if (!taxRows.length && !lots.length) {
    content.innerHTML = `
      <div class="empty-state" style="padding:20px 0">
        <div class="empty-state-icon">📊</div>
        <div class="empty-state-title">No sales yet</div>
        <div class="empty-state-sub">Realized gains and tax summaries appear here once you record a sell transaction.</div>
      </div>`;
    return;
  }

  const gainColor = v => (v || 0) >= 0 ? 'var(--pine)' : 'var(--ember)';

  const statsRow = `
    <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(130px,1fr));gap:12px;margin-bottom:20px">
      <div class="stat-card">
        <div class="stat-label">Total realized${_realizedGainsYear ? ` (${_realizedGainsYear})` : ''}</div>
        <div class="stat-value" style="color:${gainColor(summary.total_gain)}">${fmt(summary.total_gain||0)}</div>
      </div>
      <div class="stat-card">
        <div class="stat-label">Short-term</div>
        <div class="stat-value" style="color:${gainColor(summary.short_term)};font-size:20px">${fmt(summary.short_term||0)}</div>
        <div class="stat-delta">held under 1 year</div>
      </div>
      <div class="stat-card">
        <div class="stat-label">Long-term</div>
        <div class="stat-value" style="color:${gainColor(summary.long_term)};font-size:20px">${fmt(summary.long_term||0)}</div>
        <div class="stat-delta">held 1 year or more</div>
      </div>
      <div class="stat-card">
        <div class="stat-label">Closed lots</div>
        <div class="stat-value" style="font-size:20px">${summary.count||0}</div>
      </div>
    </div>`;

  const yearRows = taxRows.map(r => `
    <tr style="cursor:pointer" onclick="g('realizedGainsYear').value='${r.year}';_onRealizedGainsYearChange()">
      <td style="padding:8px 12px">${r.year}</td>
      <td style="padding:8px 12px;text-align:right;font-family:var(--font-mono);color:${gainColor(r.short_term)}">${fmt(r.short_term)}</td>
      <td style="padding:8px 12px;text-align:right;font-family:var(--font-mono);color:${gainColor(r.long_term)}">${fmt(r.long_term)}</td>
      <td style="padding:8px 12px;text-align:right;font-family:var(--font-mono);font-weight:600;color:${gainColor(r.total)}">${fmt(r.total)}</td>
      <td style="padding:8px 12px;text-align:right;color:var(--slate-2);font-size:11px">${r.lots}</td>
    </tr>`).join('');

  const yearTable = taxRows.length ? `
    <div style="margin-bottom:20px">
      <div style="font-size:11px;font-weight:600;letter-spacing:.06em;text-transform:uppercase;color:var(--slate-2);margin-bottom:8px">By tax year</div>
      <div style="overflow-x:auto">
        <table class="data-table" style="width:100%">
          <thead><tr>
            <th style="padding:8px 12px;text-align:left">Year</th>
            <th style="padding:8px 12px;text-align:right">Short-term</th>
            <th style="padding:8px 12px;text-align:right">Long-term</th>
            <th style="padding:8px 12px;text-align:right">Total</th>
            <th style="padding:8px 12px;text-align:right">Lots</th>
          </tr></thead>
          <tbody>${yearRows}</tbody>
        </table>
      </div>
    </div>` : '';

  const lotRows = lots.map(l => {
    const sharesDisp = (l.shares_sold || 0).toFixed(4).replace(/\.?0+$/, '');
    return `
    <tr>
      <td style="padding:8px 12px;font-family:var(--font-mono);font-weight:600">${esc(l.ticker||'')}</td>
      <td style="padding:8px 12px;text-align:right;font-family:var(--font-mono)">${sharesDisp}</td>
      <td style="padding:8px 12px;text-align:right;font-family:var(--font-mono)">${fmt(l.cost_basis_per_share||0)}</td>
      <td style="padding:8px 12px;text-align:right;font-family:var(--font-mono)">${fmt(l.sell_price_per_share||0)}</td>
      <td style="padding:8px 12px;text-align:right;font-family:var(--font-mono);font-weight:600;color:${gainColor(l.realized_gain)}">${fmt(l.realized_gain||0)}</td>
      <td style="padding:8px 12px;text-align:right;font-size:11px;color:${gainColor(l.realized_gain_pct)}">${(l.realized_gain_pct||0)>=0?'+':''}${(l.realized_gain_pct||0).toFixed(1)}%</td>
      <td style="padding:8px 12px;text-align:center">
        <span style="font-size:10px;padding:2px 8px;border-radius:20px;
                     background:${l.is_long_term?'var(--pine-bg)':'var(--gold-bg)'};
                     color:${l.is_long_term?'var(--pine)':'#92400e'};
                     border:1px solid ${l.is_long_term?'var(--pine-border)':'var(--gold-border)'}">${esc(l.term_label||'')}</span>
      </td>
      <td style="padding:8px 12px;color:var(--slate-2);font-size:11px;white-space:nowrap">${esc(l.sell_date||'')}</td>
    </tr>`;
  }).join('');

  const lotsTable = lots.length ? `
    <div>
      <div style="font-size:11px;font-weight:600;letter-spacing:.06em;text-transform:uppercase;color:var(--slate-2);margin-bottom:8px">
        Closed lots${_realizedGainsYear ? ` — ${_realizedGainsYear}` : ''}
      </div>
      <div style="overflow-x:auto">
        <table class="data-table" style="width:100%">
          <thead><tr>
            <th style="padding:8px 12px;text-align:left">Ticker</th>
            <th style="padding:8px 12px;text-align:right">Shares</th>
            <th style="padding:8px 12px;text-align:right">Cost basis</th>
            <th style="padding:8px 12px;text-align:right">Sell price</th>
            <th style="padding:8px 12px;text-align:right">Gain / loss</th>
            <th style="padding:8px 12px;text-align:right">%</th>
            <th style="padding:8px 12px;text-align:center">Term</th>
            <th style="padding:8px 12px;text-align:left">Sold</th>
          </tr></thead>
          <tbody>${lotRows}</tbody>
        </table>
      </div>
    </div>` : `<div style="font-size:12px;color:var(--slate-2)">No closed lots${_realizedGainsYear ? ` in ${_realizedGainsYear}` : ''}.</div>`;

  content.innerHTML = statsRow + yearTable + lotsTable + `
    <div style="margin-top:16px;font-size:11px;color:var(--slate-2);line-height:1.6">
      Short-term = held under a year, generally taxed as ordinary income. Long-term = held a year
      or more, usually taxed at a lower rate. This is informational, not tax advice — check with a
      tax professional for your specific situation.
    </div>`;
}
function setMethod(m) {
  S.debtMethod = m;
  g('btnAvalanche')?.classList.toggle('active', m==='avalanche');
  g('btnSnowball')?.classList.toggle('active', m==='snowball');
  const tip = g('strategyTip');
  if (tip) tip.textContent = m==='avalanche'
    ? 'Highest interest rate first — saves the most money'
    : 'Smallest balance first — fastest to see a payoff';
  const helpSlot = g('strategyHelpIcon');
  if (helpSlot) helpSlot.innerHTML = helpIcon(m==='avalanche' ? 'avalanche' : 'snowball');
  API.patch('/api/settings', { debt_method: m }).catch(_gwErr('setMethod'));
  calculate();
}

// BYB — adapt to bybContent ID in HTML
function renderBYB() {
  const cont = g('bybContent');
  if (!cont) return;
  _loadBYBItems();
}

async function _loadBYBItems() {
  // This used to drop decision/dti_before/dti_after/payoff_impact/
  // whats_left_before/after/replacing/actual_cost/decided_at on the floor
  // here — the exact fields the wizard computes and the server now
  // persists (see BYBItem's docstring) — which meant every item rendered
  // as undecided/"walked away" no matter what was actually saved.
  try {
    const res  = await API.get('/api/byb');
    const data = res.data || res || [];
    S.bybItems = Array.isArray(data) ? data.map(b => ({
      ...b,
      id:       b.id,
      _dbId:    b.id,
      name:     b.name     || '',
      category: b.category || b.type || '',
      type:     b.type     || 'subscription',
      monthly:  parseFloat(b.monthly || b.monthly_cost || 0),
      replacing_name: b.replacing?.name || null,
    })) : [];
  } catch(e) {
    if (!Array.isArray(S.bybItems)) S.bybItems = [];
  }
  _renderBYBList();
}
function _renderBYBList() {
  const cont = g('bybContent');
  if (!cont) return;

  if (!S.bybItems.length) {
    cont.innerHTML = `
      <div class="empty-guide">
        <div class="empty-guide-icon">◷</div>
        <div class="empty-guide-title">Nothing evaluated yet</div>
        <div class="empty-guide-text">Open Before You Buy before making a major purchase. See exactly what it costs your budget, your DTI, and your debt-free date.</div>
        <button class="btn btn-secondary btn-sm" onclick="openBYBWizard()">Evaluate a purchase →</button>
      </div>`;
    return;
  }

  const committed   = S.bybItems.filter(b => b.decision === 'commit');
  const tracked     = S.bybItems.filter(b => b.decision === 'track');
  // An item with NO decision is not a walkaway. It is a purchase still being
  // thought about, or one nobody came back to, and counting it as a decision
  // reads a choice out of an absence — the one inference this app refuses.
  const walkedAway  = S.bybItems.filter(b => b.decision === 'walkaway');
  const undecided   = S.bybItems.filter(b => !b.decision);
  const totalMonthly     = committed.reduce((s,b) => s+(b.monthly||0), 0);
  const totalPayoffShift = committed.reduce((s,b) => s+(b.payoff_impact||0), 0);
  const dtiNow           = calcDTI() || 0;

  const decisionBadge = d => {
    if (d === 'commit')   return `<span style="font-size:10px;background:var(--pine-bg);color:var(--pine);border:1px solid var(--pine-border);border-radius:20px;padding:2px 8px;font-weight:600">Committed</span>`;
    if (d === 'track')    return `<span style="font-size:10px;background:var(--mist);color:var(--slate);border:1px solid var(--steel);border-radius:20px;padding:2px 8px">Tracking</span>`;
    if (d === 'walkaway') return `<span style="font-size:10px;background:var(--ember-bg);color:var(--ember);border:1px solid var(--ember-border);border-radius:20px;padding:2px 8px">Walked away</span>`;
    return '';
  };

  const itemCard = b => {
    const dtiDelta     = (b.dti_after != null && b.dti_before != null) ? (b.dti_after - b.dti_before).toFixed(1) : null;
    const payoffImpact = b.payoff_impact != null ? parseInt(b.payoff_impact) : null;
    // decided_at from the server is already a full ISO datetime
    // (item.decided_at.isoformat()), not a bare date — appending
    // 'T00:00:00' the way other plain-date fields in this app need to
    // produced "Invalid Date" here.
    const decidedAt    = b.decided_at ? new Date(b.decided_at).toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'}) : '';
    const safeJson     = JSON.stringify(b).replace(/\x22/g, '&quot;');
    return `
      <div class="card mb-3" style="${b.decision==='commit'?'border-color:var(--pine-border)':b.decision==='walkaway'?'opacity:.75':''}">
        <div style="display:flex;justify-content:space-between;align-items:flex-start;gap:8px;margin-bottom:8px">
          <div style="flex:1">
            <div style="font-weight:600;font-size:13px;color:var(--ink);margin-bottom:3px">${esc(b.name||'')}</div>
            <div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap">
              ${decisionBadge(b.decision)}
              ${decidedAt ? `<span style="font-size:11px;color:var(--slate-2)">${decidedAt}</span>` : ''}
            </div>
          </div>
          <div style="text-align:right;flex-shrink:0">
            <div style="font-family:var(--font-mono);font-size:14px;font-weight:600;color:${b.decision==='commit'?'var(--ember)':'var(--slate)'}">
              ${b.monthly>0?fmt(b.monthly)+'/mo':''}
            </div>
            ${b.replacing?.name ? `<div style="font-size:10px;color:var(--slate-2)">replacing ${esc(b.replacing.name)}</div>` : ''}
          </div>
        </div>
        ${(dtiDelta !== null || payoffImpact !== null) ? `
        <div style="display:flex;gap:16px;font-size:11px;color:var(--slate);padding-top:8px;border-top:0.5px solid var(--steel-2);flex-wrap:wrap">
          ${dtiDelta !== null ? `<span>DTI: <span style="font-family:var(--font-mono);color:${parseFloat(dtiDelta)>0?'var(--ember)':'var(--pine)'}">${parseFloat(dtiDelta)>0?'+':''}${dtiDelta}%</span></span>` : ''}
          ${payoffImpact !== null
            ? `<span>Payoff: <span style="font-family:var(--font-mono);color:${payoffImpact>0?'var(--ember)':'var(--pine)'}">${payoffImpact>0?'+':''}${payoffImpact} mo</span></span>`
            : `<span>Payoff: <span style="font-family:var(--font-mono);color:var(--ember)">not affordable</span></span>`}
          ${b.whats_left_after != null ? `<span>Left: <span style="font-family:var(--font-mono);color:${b.whats_left_after>=0?'var(--pine)':'var(--ember)'}">${fmt(b.whats_left_after)}</span></span>` : ''}
        </div>` : ''}
        <div style="display:flex;justify-content:flex-end;gap:8px;margin-top:8px">
          ${b.decision === 'track' ? `
          <button class="btn btn-secondary btn-sm" onclick="_bybResolveTracked(${b._dbId}, '${esc(b.name).replace(/'/g,"\\'")}', ${b.monthly||0})" style="font-size:11px">Decide now</button>
          ` : ''}
          <button class="btn btn-ghost btn-sm" onclick="_bybReEvaluate(${safeJson})" style="font-size:11px">Re-evaluate</button>
          <button class="btn btn-ghost btn-sm" onclick="removeBYBItem(${b._dbId})" style="color:var(--slate-2);font-size:11px">Remove</button>
        </div>
      </div>`;
  };

  const summaryBar = committed.length ? `
    <div style="background:var(--mist);border-radius:var(--r-md);padding:12px 14px;margin-bottom:18px">
      <div style="font-size:10px;font-weight:600;text-transform:uppercase;letter-spacing:.08em;color:var(--slate-2);margin-bottom:8px">Committed purchases — cumulative impact</div>
      <div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:8px;text-align:center">
        <div><div style="font-family:var(--font-mono);font-size:16px;font-weight:600;color:var(--ember)">${fmt(totalMonthly)}/mo</div><div style="font-size:10px;color:var(--slate-2)">added</div></div>
        <div><div style="font-family:var(--font-mono);font-size:16px;font-weight:600;color:${dtiNow>20?'var(--ember)':dtiNow>15?'var(--gold)':'var(--pine)'}">${dtiNow.toFixed(1)}%</div><div style="font-size:10px;color:var(--slate-2)">DTI now</div></div>
        <div><div style="font-family:var(--font-mono);font-size:16px;font-weight:600;color:${totalPayoffShift>0?'var(--ember)':'var(--pine)'}">${totalPayoffShift>0?'+':''}${totalPayoffShift} mo</div><div style="font-size:10px;color:var(--slate-2)">payoff shift</div></div>
      </div>
    </div>` : '';

  const section = (label, items) => items.length ? `
    <div style="font-size:10px;font-weight:600;text-transform:uppercase;letter-spacing:.08em;color:var(--slate-2);margin-bottom:8px;margin-top:14px">${label}</div>
    ${items.map(itemCard).join('')}` : '';

  cont.innerHTML = `
    <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:16px">
      <div style="font-size:13px;color:var(--slate)">${S.bybItems.length} evaluation${S.bybItems.length!==1?'s':''}</div>
      <button class="btn btn-secondary btn-sm" onclick="openBYBWizard()">+ Evaluate purchase</button>
    </div>
    ${summaryBar}
    ${section('Committed', committed)}
    ${section('Tracking', tracked)}
    ${section('Walked away', walkedAway)}`;
}

// Tracker — adapt to existing HTML IDs (monthSelect, trackerProgress etc)


